DECLARE
  CURSOR c_tipos IS
    SELECT type_name FROM (
      SELECT 'EXTORNO_LIST' AS type_name FROM dual UNION ALL
      SELECT 'EXTORNO_TYPE' FROM dual UNION ALL
      SELECT 'NUMERO_DOCUMENTO_LIST' FROM dual UNION ALL
      SELECT 'NUMERO_DOCUMENTO_TYPE' FROM dual UNION ALL
      SELECT 'SOLICITUD_HONRAS_LIST' FROM dual UNION ALL
      SELECT 'SOLICITUD_HONRAS_TYPE' FROM dual
    );

  v_exists NUMBER;
BEGIN
  FOR t IN c_tipos LOOP
    SELECT COUNT(*) INTO v_exists
    FROM ALL_OBJECTS
    WHERE OBJECT_TYPE = 'TYPE'
      AND OBJECT_NAME = t.type_name
      AND OWNER = 'US_BASE_MODULAR';

    IF v_exists > 0 THEN
      EXECUTE IMMEDIATE 'DROP TYPE US_BASE_MODULAR.' || t.type_name || ' FORCE';
    END IF;
  END LOOP;
END;


/


--------------------------------------------------------
--  DDL for Type EXTORNO_TYPE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TYPE "US_BASE_MODULAR"."EXTORNO_TYPE" 
  AS
