/

  CREATE OR REPLACE EDITIONABLE TYPE "US_BASE_MODULAR"."SOLICITUD_HONRAS_LIST" AS
TABLE OF SOLICITUD_HONRAS_TYPE;


/

--------------------------------------------------------
--  DDL SEQUENCE
--------------------------------------------------------

DECLARE
  CURSOR c_secuencias IS
    SELECT sequence_name, start_with FROM (
      SELECT 'EXTORNO_ER_SEQ' AS sequence_name, 1 AS start_with FROM dual UNION ALL
      SELECT 'EXTORNO_GRUPO_SEQ', 1 FROM dual UNION ALL
      SELECT 'EXTORNO_SEQ', 1 FROM dual UNION ALL
      SELECT 'LOG_ERROR_SEQ', 1 FROM dual UNION ALL
      SELECT 'PRODUCTO_IFI_SEQ', 1 FROM dual UNION ALL
      SELECT 'SOLICITUD_DET_SEQ', 1 FROM dual UNION ALL
      SELECT 'SOLICITUD_NOMBRE_ARCHIVO_SEQ', 1 FROM dual UNION ALL
      SELECT 'SOLICITUD_SEQ', 1 FROM dual UNION ALL
	  SELECT 'HISTORIAL_CREDITO_SEQ', 1 FROM dual UNION ALL
      SELECT 'COBERTURA_SEQ', 1 FROM dual UNION ALL
	  SELECT 'EXTORNO_NOMBRE_ARCHIVO_SEQ', 1 FROM dual
    );

  v_count NUMBER;
BEGIN
  FOR r IN c_secuencias LOOP
    SELECT COUNT(*) INTO v_count 
    FROM user_sequences 
    WHERE sequence_name = r.sequence_name;

    IF v_count > 0 THEN
      EXECUTE IMMEDIATE 'DROP SEQUENCE US_BASE_MODULAR.' || r.sequence_name;
    END IF;

    EXECUTE IMMEDIATE '
      CREATE SEQUENCE US_BASE_MODULAR.' || r.sequence_name || '
      MINVALUE 1 MAXVALUE 9999999999999999999999999999 
      INCREMENT BY 1 START WITH ' || r.start_with || '
      NOCACHE NOORDER NOCYCLE NOKEEP NOSCALE GLOBAL';
  END LOOP;
END;
/

DECLARE
  CURSOR c_tablas IS
    SELECT table_name FROM (
      SELECT 'COBERTURA' AS table_name FROM dual UNION ALL      
      SELECT 'ETL_RCC_IDCLI_TMP' FROM dual UNION ALL      
      SELECT 'ETL_RCC_MVCLI_TMP' FROM dual UNION ALL      
      SELECT 'ETL_RCC_RSCLI_TMP' FROM dual UNION ALL  
	  SELECT 'EXTORNO_NOMBRE_ARCHIVO' FROM dual	UNION ALL    
      SELECT 'EXTORNO' FROM dual UNION ALL
      SELECT 'EXTORNO_ERROR' FROM dual UNION ALL
      SELECT 'LOG_ERROR' FROM dual UNION ALL
      SELECT 'PRODUCTO_IFI' FROM dual UNION ALL
      SELECT 'SOLICITUD' FROM dual UNION ALL
      SELECT 'SOLICITUD_ARCHIVOS' FROM dual UNION ALL
      SELECT 'SOLICITUD_DETALLE' FROM dual UNION ALL
      SELECT 'SOLICITUD_DETALLE_CLASIFICACION_DEUDOR' FROM dual UNION ALL
      SELECT 'SOLICITUD_DETALLE_TEXTO' FROM dual UNION ALL
      SELECT 'SOLICITUD_HISTORICO' FROM dual UNION ALL
	  SELECT 'HISTORIAL_CREDITO' FROM dual UNION ALL
      SELECT 'SOLICITUD_HONRAS' FROM dual UNION ALL
      SELECT 'SOLICITUD_NOMBRE_ARCHIVO' FROM dual UNION ALL
      SELECT 'SOLICITUD_REPLEG' FROM dual UNION ALL
      SELECT 'SOLICITUD_REPLEG_TEXTO' FROM dual UNION ALL
      SELECT 'SOLICITUD_RESULTADOS' FROM dual
	  
    );

  v_exists NUMBER;
BEGIN
  FOR t IN c_tablas LOOP
    SELECT COUNT(*) INTO v_exists
    FROM ALL_OBJECTS
    WHERE OBJECT_TYPE = 'TABLE'
      AND OBJECT_NAME = t.table_name
      AND OWNER = 'US_BASE_MODULAR';

    IF v_exists > 0 THEN
      EXECUTE IMMEDIATE 'DROP TABLE US_BASE_MODULAR.' || t.table_name || ' CASCADE CONSTRAINTS';
    END IF;
  END LOOP;
END;
/
   
