--  DDL for Table SOLICITUD
--------------------------------------------------------

  CREATE TABLE "US_BASE_MODULAR"."SOLICITUD" 
   (	"INT_IDSOLICITUD" NUMBER(20,0), 
	"INT_IDPRODUCTO" NUMBER(10,0), 
	"VC_CODIGO" VARCHAR2(20 BYTE), 
	"INT_IDIFI" NUMBER(10,0), 
	"VC_NOMBRE_IFI" VARCHAR2(200 BYTE), 
	"INT_REGISTROS" NUMBER(10,0), 
	"INT_APROBADOS" NUMBER(10,0), 
	"INT_RECHAZADOS" NUMBER(10,0), 
	"INT_IDESTADO" NUMBER(10,0), 
	"INT_IDTIPO_OPERACION" NUMBER(10,0), 
	"INT_IDMONEDA" NUMBER(10,0), 
	"DEC_TOTAL_COBERTURADO_INICIAL" NUMBER(20,4), 
	"DEC_TOTAL_DESEMBOLSADO" NUMBER(20,4), 
	"DEC_TOTAL_MONTO_PRESTAMO" NUMBER(20,4), 
	"DT_FECHA" DATE, 
	"VC_USUARIO_CREACION" VARCHAR2(20 BYTE), 
	"DT_FECHA_CREACION" DATE, 
	"VC_TERMINAL_CREACION" VARCHAR2(20 BYTE), 
	"VC_USUARIO_MODIFICACION" VARCHAR2(20 BYTE), 
	"DT_FECHA_MODIFICACION" DATE, 
	"VC_TERMINAL_MODIFICACION" VARCHAR2(20 BYTE), 
	"OBSERVACIONES" VARCHAR2(4000 BYTE),
	"JSON_UI_DECORADORES"           CLOB,
	
	CONSTRAINT "SOL_UIDECOR_IS_JSON"  CHECK ("JSON_UI_DECORADORES" IS JSON),

	CONSTRAINT "CK_SOL_UIDECOR_KEYS"
		CHECK (
		  JSON_EXISTS("JSON_UI_DECORADORES", '$.field')
		  AND JSON_EXISTS("JSON_UI_DECORADORES", '$.textcolor')
		  AND JSON_EXISTS("JSON_UI_DECORADORES", '$.bgcolor')
		)
   ) ;

   COMMENT ON COLUMN "US_BASE_MODULAR"."SOLICITUD"."INT_IDSOLICITUD" IS 'Id de Solicitud';
   COMMENT ON COLUMN "US_BASE_MODULAR"."SOLICITUD"."INT_IDPRODUCTO" IS 'Identificador de la tabla producto';
   COMMENT ON COLUMN "US_BASE_MODULAR"."SOLICITUD"."VC_CODIGO" IS 'Codigo de Solicitud';
   COMMENT ON COLUMN "US_BASE_MODULAR"."SOLICITUD"."INT_IDIFI" IS 'Id de Institucion Financiera';
   COMMENT ON COLUMN "US_BASE_MODULAR"."SOLICITUD"."VC_NOMBRE_IFI" IS 'Nombre de Institucion Financiera';
   COMMENT ON COLUMN "US_BASE_MODULAR"."SOLICITUD"."INT_REGISTROS" IS 'Total de Registros';
   COMMENT ON COLUMN "US_BASE_MODULAR"."SOLICITUD"."INT_APROBADOS" IS 'Registros aprobados';
   COMMENT ON COLUMN "US_BASE_MODULAR"."SOLICITUD"."INT_RECHAZADOS" IS 'Registros Rechazados';
   COMMENT ON COLUMN "US_BASE_MODULAR"."SOLICITUD"."INT_IDESTADO" IS 'Id de Estado de Solcitud';
   COMMENT ON COLUMN "US_BASE_MODULAR"."SOLICITUD"."INT_IDTIPO_OPERACION" IS 'Id Tipo de Operacion';
   COMMENT ON COLUMN "US_BASE_MODULAR"."SOLICITUD"."INT_IDMONEDA" IS 'Id Moneda';
   COMMENT ON COLUMN "US_BASE_MODULAR"."SOLICITUD"."DEC_TOTAL_COBERTURADO_INICIAL" IS 'Monto Total Coberturado Inicial';
   COMMENT ON COLUMN "US_BASE_MODULAR"."SOLICITUD"."DEC_TOTAL_DESEMBOLSADO" IS 'Monto Total Desembolsado';
   COMMENT ON COLUMN "US_BASE_MODULAR"."SOLICITUD"."DEC_TOTAL_MONTO_PRESTAMO" IS 'Monto Total de Préstamo';
   COMMENT ON COLUMN "US_BASE_MODULAR"."SOLICITUD"."DT_FECHA" IS 'Fecha de Registro de Solicitud';
