	"VC_COD_CERTIFICA" VARCHAR2(40 BYTE), 
	"DT_FECHA_DESEMBOLSADO" DATE, 
	"DT_FECHA_CERTIFICA" DATE,
	"JSON_UI_DECORADORES"           CLOB,
	
	CONSTRAINT "SOL_DET_UIDECOR_IS_JSON"  CHECK ("JSON_UI_DECORADORES" IS JSON),

	CONSTRAINT "CK_SOL_DET_UIDECOR_KEYS"
		CHECK (
		  JSON_EXISTS("JSON_UI_DECORADORES", '$.field')
		  AND JSON_EXISTS("JSON_UI_DECORADORES", '$.textcolor')
		  AND JSON_EXISTS("JSON_UI_DECORADORES", '$.bgcolor')
		)
   ) ;
   
 

