  BEFORE INSERT
  ON COBERTURA
  FOR EACH ROW
BEGIN

<< COLUMN_SEQUENCES >>
  BEGIN
    IF INSERTING
      AND :NEW.INT_IDCOBERTURA IS NULL
    THEN
      SELECT COBERTURA_SEQ.NEXTVAL
        INTO :NEW.INT_IDCOBERTURA
        FROM SYS.DUAL;
    END IF;
  END COLUMN_SEQUENCES;

END;

