  BEFORE INSERT
  ON SOLICITUD
  FOR EACH ROW
BEGIN

<< COLUMN_SEQUENCES >>
  BEGIN
    IF INSERTING
      AND :NEW.INT_IDSOLICITUD IS NULL
    THEN
      SELECT SOLICITUD_SEQ.NEXTVAL
        INTO :NEW.INT_IDSOLICITUD
        FROM SYS.DUAL;
    END IF;
  END COLUMN_SEQUENCES;

END;

/
ALTER TRIGGER "US_BASE_MODULAR"."SOLICITUD_TRG_BEF_INS" ENABLE;
--------------------------------------------------------
--  DDL for Trigger SOLICITUD_TRG_AFT_INS_UPD
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "US_BASE_MODULAR"."SOLICITUD_TRG_AFT_INS_UPD" 
  AFTER INSERT OR UPDATE
  ON SOLICITUD
  FOR EACH ROW
DECLARE
  V_INT_FILA SOLICITUD_HISTORICO.INT_FILA % TYPE;
BEGIN

  IF NVL(:OLD.INT_IDESTADO, 0) <> NVL(:NEW.INT_IDESTADO, 0)
  THEN

    SELECT COUNT(1)
      INTO V_INT_FILA
      FROM SOLICITUD_HISTORICO
      WHERE INT_IDSOLICITUD = :NEW.INT_IDSOLICITUD;

    V_INT_FILA := V_INT_FILA + 1;

    INSERT INTO SOLICITUD_HISTORICO (
      INT_IDSOLICITUD, INT_FILA, INT_IDPRODUCTO, VC_CODIGO, INT_IDIFI, VC_NOMBRE_IFI, INT_REGISTROS, INT_APROBADOS, INT_RECHAZADOS, INT_IDESTADO_ANT, INT_IDESTADO, INT_IDTIPO_OPERACION, INT_IDMONEDA, DEC_TOTAL_COBERTURADO_INICIAL, DEC_TOTAL_DESEMBOLSADO, DT_FECHA, VC_USUARIO_CREACION, DT_FECHA_CREACION, VC_TERMINAL_CREACION, VC_USUARIO_MODIFICACION, DT_FECHA_MODIFICACION, VC_TERMINAL_MODIFICACION
    )
    VALUES (:NEW.INT_IDSOLICITUD, V_INT_FILA, :NEW.INT_IDPRODUCTO, :NEW.VC_CODIGO, :NEW.INT_IDIFI, :NEW.VC_NOMBRE_IFI, :NEW.INT_REGISTROS, :NEW.INT_APROBADOS, :NEW.INT_RECHAZADOS, :OLD.INT_IDESTADO, :NEW.INT_IDESTADO, :NEW.INT_IDTIPO_OPERACION, :NEW.INT_IDMONEDA, :NEW.DEC_TOTAL_COBERTURADO_INICIAL, :NEW.DEC_TOTAL_DESEMBOLSADO, :NEW.DT_FECHA, :NEW.VC_USUARIO_CREACION, :NEW.DT_FECHA_CREACION, :NEW.VC_TERMINAL_CREACION, :NEW.VC_USUARIO_MODIFICACION, :NEW.DT_FECHA_MODIFICACION, :NEW.VC_TERMINAL_MODIFICACION);
  END IF;
END;

/
ALTER TRIGGER "US_BASE_MODULAR"."SOLICITUD_TRG_AFT_INS_UPD" ENABLE;
