--------------------------------------------------------
--  DDL for Package Body PKG_TABLA_DETALLE
--------------------------------------------------------

create or replace PACKAGE BODY                  "PKG_TABLA_DETALLE" AS

  PROCEDURE S_LISTARXCODIGO(p_vchCodigo IN US_BASE.BASE_TABLA.VC_CODTABLA%TYPE,
                            p_curTabla  OUT SYS_REFCURSOR) AS
  BEGIN
    OPEN p_curTabla FOR
      SELECT TABDET.INT_IDTABLA_DETALLE,
             TABDET.INT_IDTABLA,
             TABDET.VC_CODTABLA_DETALLE,
             TABDET.VC_NOMBRE,
             TABDET.VC_ADICIONAL1,
             TABDET.VC_ADICIONAL2,
             TABDET.VC_ADICIONAL3,
             TABDET.CH_FLAG_ESTADO,
             TABDET.VC_USUARIO_CREACION,
             TABDET.DT_FECHA_CREACION,
             TABDET.VC_USUARIO_MODIFICACION,
             TABDET.DT_FECHA_MODIFICACION
        FROM US_BASE.BASE_TABLA_DETALLE TABDET
       INNER JOIN US_BASE.BASE_TABLA TAB
          ON TAB.INT_IDTABLA = TABDET.INT_IDTABLA
         AND TABDET.CH_FLAG_ESTADO = 'A'
       WHERE (p_vchCodigo IS NULL OR TAB.VC_CODTABLA = p_vchCodigo)
         AND TABDET.CH_FLAG_ESTADO = 'A'
       ORDER BY TABDET.INT_IDTABLA_DETALLE;

  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_TABLA_DETALLE', 'S_LISTARXCODIGO', vcErrorStack, vcErrorBacktace, 'VC_CODTABLA:' || TO_CHAR(p_vchCodigo));
      RAISE_APPLICATION_ERROR(-20231, 'PKG_TABLA_DETALLE.S_LISTARXCODIGO:' || vcErrorStack || '; ' || vcErrorBacktace || '; VC_CODTABLA:' || TO_CHAR(p_vchCodigo));
  END S_LISTARXCODIGO;

  FUNCTION F_OBT_NOMBRE_TABLADETALLE(INT_CODIGO IN US_BASE.BASE_TABLA_DETALLE.INT_IDTABLA_DETALLE%TYPE)
    RETURN VARCHAR2 IS
    VNOMBRE US_BASE.BASE_TABLA_DETALLE.VC_NOMBRE%TYPE;
    VCOUNT  NUMBER;
  BEGIN

    SELECT COUNT(1)
      INTO VCOUNT
      FROM US_BASE.BASE_TABLA_DETALLE
     WHERE INT_IDTABLA_DETALLE = INT_CODIGO;
    IF VCOUNT > 0 THEN
      SELECT VC_NOMBRE
        INTO VNOMBRE
        FROM US_BASE.BASE_TABLA_DETALLE
       WHERE INT_IDTABLA_DETALLE = INT_CODIGO;
    ELSE
      VNOMBRE := ' ';
    END IF;
    RETURN VNOMBRE;
  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_TABLA_DETALLE', 'F_OBT_NOMBRE_TABLADETALLE', vcErrorStack, vcErrorBacktace, 'INT_IDTABLA_DETALLE:' || TO_CHAR(INT_CODIGO));
      RAISE_APPLICATION_ERROR(-20232, 'PKG_TABLA_DETALLE.F_OBT_NOMBRE_TABLADETALLE:' || vcErrorStack || '; ' || vcErrorBacktace || '; INT_IDTABLA_DETALLE:' || TO_CHAR(INT_CODIGO));
  END F_OBT_NOMBRE_TABLADETALLE;

  FUNCTION F_OBT_CODIGO_TABLADETALLE(INT_CODIGO IN US_BASE.BASE_TABLA_DETALLE.INT_IDTABLA_DETALLE%TYPE)
    RETURN VARCHAR2 IS
    VCCODTABLA_DETALLE US_BASE.BASE_TABLA_DETALLE.VC_CODTABLA_DETALLE %TYPE;
    VCOUNT             NUMBER;
  BEGIN
    SELECT COUNT(1)
      INTO VCOUNT
      FROM US_BASE.BASE_TABLA_DETALLE
     WHERE INT_IDTABLA_DETALLE = INT_CODIGO;
    IF VCOUNT > 0 THEN
      SELECT VC_CODTABLA_DETALLE
        INTO VCCODTABLA_DETALLE
        FROM US_BASE.BASE_TABLA_DETALLE
       WHERE INT_IDTABLA_DETALLE = INT_CODIGO;
    ELSE
      VCCODTABLA_DETALLE := ' ';
    END IF;
    RETURN VCCODTABLA_DETALLE;
  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_TABLA_DETALLE', 'F_OBT_CODIGO_TABLADETALLE', vcErrorStack, vcErrorBacktace, 'INT_IDTABLA_DETALLE:' || TO_CHAR(INT_CODIGO));
      RAISE_APPLICATION_ERROR(-20233, 'PKG_TABLA_DETALLE.F_OBT_CODIGO_TABLADETALLE:' || vcErrorStack || '; ' || vcErrorBacktace || '; INT_IDTABLA_DETALLE:' ||  TO_CHAR(INT_CODIGO));
  END F_OBT_CODIGO_TABLADETALLE;

  FUNCTION F_OBT_VALOR_TABLADETALLE(VC_TABLA         IN US_BASE.BASE_TABLA.VC_CODTABLA%TYPE,
                                    VC_TABLA_DETALLE IN US_BASE.BASE_TABLA_DETALLE.VC_CODTABLA_DETALLE%TYPE,
                                    INT_ADICIONAL    IN NUMBER)
    RETURN VARCHAR2 IS
    pVC_NOMBRE     US_BASE.BASE_TABLA_DETALLE.VC_NOMBRE%TYPE;
    pVC_ADICIONAL  US_BASE.BASE_TABLA_DETALLE.VC_ADICIONAL4%TYPE;
    pVC_ADICIONAL1 US_BASE.BASE_TABLA_DETALLE.VC_ADICIONAL1%TYPE;
    pVC_ADICIONAL2 US_BASE.BASE_TABLA_DETALLE.VC_ADICIONAL2%TYPE;
    pVC_ADICIONAL3 US_BASE.BASE_TABLA_DETALLE.VC_ADICIONAL3%TYPE;
    pVC_ADICIONAL4 US_BASE.BASE_TABLA_DETALLE.VC_ADICIONAL4%TYPE;
    VCOUNT         NUMBER;
  BEGIN
    SELECT COUNT(1)
      INTO VCOUNT
      FROM US_BASE.BASE_TABLA_DETALLE BTD
     WHERE BTD.INT_IDTABLA IN
           (SELECT BT.INT_IDTABLA
              FROM US_BASE.BASE_TABLA BT
             WHERE BT.VC_CODTABLA = VC_TABLA)
       AND BTD.VC_CODTABLA_DETALLE = VC_TABLA_DETALLE;
    IF VCOUNT > 0 THEN
      SELECT BTD.VC_NOMBRE,
             BTD.VC_ADICIONAL1,
             BTD.VC_ADICIONAL2,
             BTD.VC_ADICIONAL3,
             BTD.VC_ADICIONAL4
        INTO pVC_NOMBRE,
             pVC_ADICIONAL1,
             pVC_ADICIONAL2,
             pVC_ADICIONAL3,
             pVC_ADICIONAL4
        FROM US_BASE.BASE_TABLA_DETALLE BTD
       WHERE BTD.INT_IDTABLA IN
             (SELECT BT.INT_IDTABLA
                FROM US_BASE.BASE_TABLA BT
               WHERE BT.VC_CODTABLA = VC_TABLA)
         AND BTD.VC_CODTABLA_DETALLE = VC_TABLA_DETALLE
         AND ROWNUM <= 1;

      CASE INT_ADICIONAL
        WHEN 0 THEN
          pVC_ADICIONAL := pVC_NOMBRE;
        WHEN 1 THEN
          pVC_ADICIONAL := pVC_ADICIONAL1;
        WHEN 2 THEN
          pVC_ADICIONAL := pVC_ADICIONAL2;
        WHEN 3 THEN
          pVC_ADICIONAL := pVC_ADICIONAL3;
        WHEN 4 THEN
          pVC_ADICIONAL := pVC_ADICIONAL4;
        ELSE
          pVC_ADICIONAL := ' ';
      END CASE;
    ELSE
      pVC_ADICIONAL := ' ';
    END IF;

    RETURN TRIM(pVC_ADICIONAL);

  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_TABLA_DETALLE', 'F_OBT_VALOR_TABLADETALLE', vcErrorStack, vcErrorBacktace, 'VC_CODTABLA:' || TO_CHAR(VC_TABLA) || ', VC_CODTABLA_DETALLE:' || TO_CHAR(VC_TABLA_DETALLE) || ', INT_ADICIONAL:' || TO_CHAR(INT_ADICIONAL));
      RAISE_APPLICATION_ERROR(-20234, 'PKG_TABLA_DETALLE.F_OBT_VALOR_TABLADETALLE:' || vcErrorStack || '; ' || vcErrorBacktace || 'VC_CODTABLA:' || TO_CHAR(VC_TABLA) || ', VC_CODTABLA_DETALLE:' || TO_CHAR(VC_TABLA_DETALLE) || ', INT_ADICIONAL:' || TO_CHAR(INT_ADICIONAL));
  END F_OBT_VALOR_TABLADETALLE;

    FUNCTION F_OBT_VALOR_ADICIONAL_TABLADETALLE(VC_TABLA         IN US_BASE.BASE_TABLA.VC_CODTABLA%TYPE,
                                                VC_TABLA_DETALLE IN US_BASE.BASE_TABLA_DETALLE.VC_CODTABLA_DETALLE%TYPE,
                                                INT_ADICIONAL    IN NUMBER)
    RETURN VARCHAR2 IS
    pVC_NOMBRE     US_BASE.BASE_TABLA_DETALLE.VC_NOMBRE%TYPE;
    pVC_ADICIONAL  US_BASE.BASE_TABLA_DETALLE.VC_ADICIONAL4%TYPE;
    pVC_ADICIONAL1 US_BASE.BASE_TABLA_DETALLE.VC_ADICIONAL1%TYPE;
    pVC_ADICIONAL2 US_BASE.BASE_TABLA_DETALLE.VC_ADICIONAL2%TYPE;
    pVC_ADICIONAL3 US_BASE.BASE_TABLA_DETALLE.VC_ADICIONAL3%TYPE;
    pVC_ADICIONAL4 US_BASE.BASE_TABLA_DETALLE.VC_ADICIONAL4%TYPE;
    VCOUNT         NUMBER;
  BEGIN
    SELECT COUNT(1)
      INTO VCOUNT
      FROM US_BASE.BASE_TABLA_DETALLE BTD
     WHERE BTD.INT_IDTABLA IN
           (SELECT BT.INT_IDTABLA
              FROM US_BASE.BASE_TABLA BT
             WHERE BT.VC_CODTABLA = VC_TABLA)
       AND BTD.VC_ADICIONAL1 = VC_TABLA_DETALLE;
    IF VCOUNT > 0 THEN
      SELECT BTD.VC_NOMBRE,
             BTD.VC_ADICIONAL1,
             BTD.VC_ADICIONAL2,
             BTD.VC_ADICIONAL3,
             BTD.VC_ADICIONAL4
        INTO pVC_NOMBRE,
             pVC_ADICIONAL1,
             pVC_ADICIONAL2,
             pVC_ADICIONAL3,
             pVC_ADICIONAL4
        FROM US_BASE.BASE_TABLA_DETALLE BTD
       WHERE BTD.INT_IDTABLA IN
             (SELECT BT.INT_IDTABLA
                FROM US_BASE.BASE_TABLA BT
               WHERE BT.VC_CODTABLA = VC_TABLA)
         AND BTD.VC_ADICIONAL1 = VC_TABLA_DETALLE
         AND ROWNUM <= 1;

      CASE INT_ADICIONAL
        WHEN 0 THEN
          pVC_ADICIONAL := pVC_NOMBRE;
        WHEN 1 THEN
          pVC_ADICIONAL := pVC_ADICIONAL1;
        WHEN 2 THEN
          pVC_ADICIONAL := pVC_ADICIONAL2;
        WHEN 3 THEN
          pVC_ADICIONAL := pVC_ADICIONAL3;
        WHEN 4 THEN
          pVC_ADICIONAL := pVC_ADICIONAL4;
        ELSE
          pVC_ADICIONAL := ' ';
      END CASE;
    ELSE
      pVC_ADICIONAL := ' ';
    END IF;

    RETURN TRIM(pVC_ADICIONAL);

  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_TABLA_DETALLE', 'F_OBT_VALOR_ADICIONAL_TABLADETALLE', vcErrorStack, vcErrorBacktace, 'VC_CODTABLA:' || TO_CHAR(VC_TABLA) || ', VC_CODTABLA_DETALLE:' || TO_CHAR(VC_TABLA_DETALLE) || ', INT_ADICIONAL:' || TO_CHAR(INT_ADICIONAL));
      RAISE_APPLICATION_ERROR(-20234, 'PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE:' || vcErrorStack || '; ' || vcErrorBacktace || 'VC_CODTABLA:' || TO_CHAR(VC_TABLA) || ', VC_CODTABLA_DETALLE:' || TO_CHAR(VC_TABLA_DETALLE) || ', INT_ADICIONAL:' || TO_CHAR(INT_ADICIONAL));
  END F_OBT_VALOR_ADICIONAL_TABLADETALLE;

  PROCEDURE S_LISTARTIPOARCHIVO(p_vchCodigo IN US_BASE.BASE_TABLA.VC_CODTABLA%TYPE,
                                p_curTabla  OUT SYS_REFCURSOR) AS
  BEGIN
    OPEN p_curTabla FOR
      SELECT TABDET.INT_IDTABLA_DETALLE,
             TABDET.INT_IDTABLA,
             TABDET.VC_CODTABLA_DETALLE,
             TABDET.VC_NOMBRE,
             TABDET.VC_ADICIONAL1,
             TABDET.VC_ADICIONAL2,
             TABDET.VC_ADICIONAL3,
             TABDET.CH_FLAG_ESTADO,
             TABDET.VC_USUARIO_CREACION,
             TABDET.DT_FECHA_CREACION,
             TABDET.VC_USUARIO_MODIFICACION,
             TABDET.DT_FECHA_MODIFICACION
        FROM US_BASE.BASE_TABLA_DETALLE TABDET
       INNER JOIN US_BASE.BASE_TABLA TAB
          ON TAB.INT_IDTABLA = TABDET.INT_IDTABLA
         AND TABDET.CH_FLAG_ESTADO = 'A'
       WHERE (p_vchCodigo is null OR TABDET.VC_ADICIONAL2 = p_vchCodigo) --DERM
         AND TABDET.CH_FLAG_ESTADO = 'A'
       ORDER BY TABDET.INT_IDTABLA_DETALLE;

  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_TABLA_DETALLE', 'S_LISTARTIPOARCHIVO', vcErrorStack, vcErrorBacktace, 'VC_ADICIONAL2:' || TO_CHAR(p_vchCodigo));
      RAISE_APPLICATION_ERROR(-20235, 'PKG_TABLA_DETALLE.F_OBT_VALOR_TABLADETALLE:' || vcErrorStack || '; ' || vcErrorBacktace || 'VC_ADICIONAL2:' || TO_CHAR(p_vchCodigo));
  END S_LISTARTIPOARCHIVO;

END PKG_TABLA_DETALLE;


