--------------------------------------------------------
--  DDL for Package Body PKG_ARCHIVO
--------------------------------------------------------

 create or replace PACKAGE BODY                  "PKG_ARCHIVO" 
  AS

  PROCEDURE I_INSERTAR(p_intIdTipoArchivo    IN  SOLICITUD_NOMBRE_ARCHIVO.INT_IDTIPO_ARCHIVO % TYPE,
                       p_vchNombreArchivo    IN  SOLICITUD_NOMBRE_ARCHIVO.VC_NOMBRE_ARCHIVO % TYPE,
                       p_vchDescripcion      IN  SOLICITUD_NOMBRE_ARCHIVO.VC_DESCRIPCION % TYPE,
                       p_intIdOrigen         IN  SOLICITUD_NOMBRE_ARCHIVO.INT_IDPRODUCTO % TYPE,
                       p_intIdTabla          IN  SOLICITUD_NOMBRE_ARCHIVO.INT_IDSOLICITUD % TYPE,
                       p_chrFlagEstado       IN  SOLICITUD_NOMBRE_ARCHIVO.CH_FLAG_ESTADO % TYPE,
                       p_vchUsuarioCreacion  IN  SOLICITUD_NOMBRE_ARCHIVO.VC_USUARIO_CREACION % TYPE,
                       p_datFechaCreacion    IN  SOLICITUD_NOMBRE_ARCHIVO.DT_FECHA_CREACION % TYPE,
                       p_vchTerminalCreacion IN  SOLICITUD_NOMBRE_ARCHIVO.VC_TERMINAL_CREACION % TYPE,
                       p_intIdArchivo        OUT INT,
                       p_vchMsg              OUT VARCHAR2)
    AS
    BEGIN

      INSERT INTO SOLICITUD_NOMBRE_ARCHIVO (
        INT_IDTIPO_ARCHIVO, VC_NOMBRE_ARCHIVO, VC_DESCRIPCION, INT_IDPRODUCTO, INT_IDSOLICITUD, CH_FLAG_ESTADO, VC_USUARIO_CREACION, DT_FECHA_CREACION, VC_TERMINAL_CREACION
      )
      VALUES (p_intIdTipoArchivo, p_vchNombreArchivo, p_vchDescripcion, p_intIdOrigen, p_intIdTabla, p_chrFlagEstado, p_vchUsuarioCreacion, p_datFechaCreacion, p_vchTerminalCreacion) RETURNING INT_IDARCHIVO INTO p_intIdArchivo;

      p_vchMsg := 'OK';

    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          p_vchMsg := 'PKG_ARCHIVO.I_INSERTAR---> Nro Linea Error: ' || vcErrorStack || '; ' || vcErrorBacktace;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_ARCHIVO', 'I_INSERTAR', vcErrorStack, vcErrorBacktace);
          RAISE_APPLICATION_ERROR(-20101, 'PKG_ARCHIVO.I_INSERTAR:' || vcErrorStack || '; ' || vcErrorBacktace);
    END I_INSERTAR;

  PROCEDURE S_LISTAPAGINACION(p_intIdArchivo     IN  SOLICITUD_NOMBRE_ARCHIVO.INT_IDARCHIVO % TYPE,
                              p_intIdTipoArchivo IN  SOLICITUD_NOMBRE_ARCHIVO.INT_IDTIPO_ARCHIVO % TYPE,
                              p_intIdOrigen      IN  SOLICITUD_NOMBRE_ARCHIVO.INT_IDPRODUCTO % TYPE,
                              p_intIdTabla       IN  SOLICITUD_NOMBRE_ARCHIVO.INT_IDSOLICITUD % TYPE,
                              p_intStartIndex    IN  NUMBER,
                              p_intPageSize      IN  NUMBER,
                              p_curTabla         OUT sys_refcursor)
    AS
    BEGIN
      OPEN p_curTabla FOR

      SELECT *
        FROM (SELECT COUNT(1) OVER () AS CANTIDAD,
                     ROW_NUMBER() OVER (ORDER BY A.INT_IDARCHIVO) AS ROWNUMBER,
                     A.INT_IDARCHIVO,
                     A.INT_IDTIPO_ARCHIVO,
                     TDTAR.VC_NOMBRE AS VC_NOMBRE_TIPO_ARCHIVO,
                     A.VC_NOMBRE_ARCHIVO AS VC_NOMBRE_ARCHIVO,
                     A.VC_DESCRIPCION,
                     A.INT_IDPRODUCTO,
                     A.INT_IDSOLICITUD,
                     A.CH_FLAG_ESTADO,
                     NVL(A.VC_RUTA_SFTP, ' ') AS VC_RUTA_SFTP,
                     NVL(A.INT_PROCESO_SFTP, 0) AS INT_PROCESO_SFTP
            FROM SOLICITUD_NOMBRE_ARCHIVO A
              LEFT JOIN US_BASE.BASE_TABLA_DETALLE TDTAR
                ON (TDTAR.INT_IDTABLA_DETALLE = A.INT_IDTIPO_ARCHIVO
                AND TDTAR.CH_FLAG_ESTADO = 'A')
            WHERE (p_intIdArchivo = 0
              OR A.INT_IDARCHIVO = p_intIdArchivo)
              AND (p_intIdTipoArchivo = 0
              OR A.INT_IDTIPO_ARCHIVO = p_intIdTipoArchivo)
              AND (A.INT_IDPRODUCTO = DECODE(p_intIdArchivo, 0, p_intIdOrigen, A.INT_IDPRODUCTO))
              AND (A.INT_IDSOLICITUD = DECODE(p_intIdArchivo, 0, p_intIdTabla, A.INT_IDSOLICITUD))
              AND (A.CH_FLAG_ESTADO = 'A'))
        WHERE (ROWNUMBER BETWEEN ((p_intStartIndex) * p_intPageSize + 1) AND (p_intStartIndex + 1) * p_intPageSize);
    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_ARCHIVO', 'S_LISTAPAGINACION', vcErrorStack, vcErrorBacktace);
          RAISE_APPLICATION_ERROR(-20102, 'PKG_ARCHIVO.S_LISTAPAGINACION:' || vcErrorStack || '; ' || vcErrorBacktace);
    END S_LISTAPAGINACION;

  PROCEDURE S_LISTAR_ARCHIVOS_X_SOLICITUD(p_intIdSolicitud IN  SOLICITUD.INT_IDSOLICITUD % TYPE,
                                          p_intStartIndex  IN  NUMBER,
                                          p_intPageSize    IN  NUMBER,
                                          p_curTabla       OUT SYS_REFCURSOR)
    AS
    BEGIN
      OPEN p_curTabla FOR

      SELECT D.INT_NUMERO_TOTAL_REGISTRO,
             D.INT_ROW_NUMBER,
             D.VC_NOMBRE_ARCHIVO,
             D.VC_USUARIO_CREACION,
             D.DT_FECHA_CREACION,
             D.VC_TIPODOCUM,
             D.VC_DESCRIPCIONDOCUM,
             D.INT_IDIFI,
             D.INT_IDARCHIVO
        FROM (SELECT COUNT(1) OVER () AS INT_NUMERO_TOTAL_REGISTRO,
                     ROW_NUMBER() OVER (ORDER BY B.INT_IDSOLICITUD DESC) AS INT_ROW_NUMBER,
                     B.VC_NOMBRE_ARCHIVO AS VC_NOMBRE_ARCHIVO,
                     B.VC_USUARIO_CREACION,
                     B.DT_FECHA_CREACION,
                     D.VC_CODTABLA_DETALLE AS VC_TIPODOCUM,
                     B.VC_DESCRIPCION AS VC_DESCRIPCIONDOCUM,
                     S.INT_IDIFI,
                     B.INT_IDARCHIVO
            FROM SOLICITUD_NOMBRE_ARCHIVO B
              LEFT JOIN US_BASE.BASE_TABLA_DETALLE D
                ON (B.INT_IDTIPO_ARCHIVO = D.INT_IDTABLA_DETALLE)
              LEFT JOIN SOLICITUD S
                ON (B.INT_IDSOLICITUD = S.INT_IDSOLICITUD)
            WHERE B.INT_IDSOLICITUD = P_INTIDSOLICITUD) D
        WHERE (D.INT_ROW_NUMBER BETWEEN ((p_intStartIndex) * p_intPageSize + 1) AND (p_intStartIndex + 1) * p_intPageSize);

    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_ARCHIVO', 'S_LISTAR_ARCHIVOS_X_SOLICITUD', vcErrorStack, vcErrorBacktace, 'INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
          RAISE_APPLICATION_ERROR(-20103, 'PKG_ARCHIVO.S_LISTAR_ARCHIVOS_X_SOLICITUD:' || vcErrorStack || '; ' || vcErrorBacktace || '; INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
    END S_LISTAR_ARCHIVOS_X_SOLICITUD;

   PROCEDURE I_INSERTAR_EXTORNO(
					   p_intIdTipoArchivo    IN  EXTORNO_NOMBRE_ARCHIVO.INT_IDTIPO_ARCHIVO % TYPE,
                       p_vchNombreArchivo    IN  EXTORNO_NOMBRE_ARCHIVO.VC_NOMBRE_ARCHIVO % TYPE,
                       p_vchDescripcion      IN  EXTORNO_NOMBRE_ARCHIVO.VC_DESCRIPCION % TYPE,                       
                       p_intIdTabla          IN  EXTORNO_NOMBRE_ARCHIVO.INT_IDEXTORNO % TYPE,
                       p_chrFlagEstado       IN  EXTORNO_NOMBRE_ARCHIVO.CH_FLAG_ESTADO % TYPE,
                       p_vchUsuarioCreacion  IN  EXTORNO_NOMBRE_ARCHIVO.VC_USUARIO_CREACION % TYPE,
                       p_datFechaCreacion    IN  EXTORNO_NOMBRE_ARCHIVO.DT_FECHA_CREACION % TYPE,
                       p_vchTerminalCreacion IN  EXTORNO_NOMBRE_ARCHIVO.VC_TERMINAL_CREACION % TYPE,
					   p_vchRutaSFTP         IN  EXTORNO_NOMBRE_ARCHIVO.VC_RUTA_SFTP % TYPE,
                       p_intIdArchivo        OUT INT,
                       p_vchMsg              OUT VARCHAR2)
    AS
    BEGIN

      INSERT INTO EXTORNO_NOMBRE_ARCHIVO (
       INT_IDTIPO_ARCHIVO, VC_NOMBRE_ARCHIVO, VC_DESCRIPCION, INT_IDEXTORNO, CH_FLAG_ESTADO, VC_USUARIO_CREACION, DT_FECHA_CREACION, VC_TERMINAL_CREACION, VC_RUTA_SFTP
      )
      VALUES (p_intIdTipoArchivo, p_vchNombreArchivo, p_vchDescripcion, p_intIdTabla, p_chrFlagEstado, p_vchUsuarioCreacion, p_datFechaCreacion, p_vchTerminalCreacion, p_vchRutaSFTP) RETURNING INT_IDARCHIVO INTO p_intIdArchivo;


      p_vchMsg := 'OK';

    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          p_vchMsg := 'PKG_ARCHIVO.I_INSERTAR_EXTORNO---> Nro Linea Error: ' || vcErrorStack || '; ' || vcErrorBacktace;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_ARCHIVO', 'I_INSERTAR_EXTORNO', vcErrorStack, vcErrorBacktace);
          RAISE_APPLICATION_ERROR(-20101, 'PKG_ARCHIVO.I_INSERTAR_EXTORNO:' || vcErrorStack || '; ' || vcErrorBacktace);
    END I_INSERTAR_EXTORNO;	

END PKG_ARCHIVO;


/
--------------------------------------------------------
--  DDL for Package Body PKG_BASE
--------------------------------------------------------
create or replace PACKAGE BODY      "US_BASE_MODULAR"."PKG_BASE" AS

  FUNCTION F_CLOB_A_FILAS(P_CLOB        IN CLOB,
                          P_DELIMITADOR IN VARCHAR2 DEFAULT CHR(13) || CHR(10))
    RETURN PKG_BASE.VC_TAB
    PIPELINED IS

    INT_LIMITE_FILA       CONSTANT INTEGER := 4000; -- FOR SINGLE BYTE CHARACTERS
    INT_CANTIDAD_LIMITE   CONSTANT INTEGER := 8 * INT_LIMITE_FILA;
    INT_CLOB_LONGITUD     INTEGER;
    INT_CLOB_INDICE       INTEGER;
    VC_FILA               VARCHAR2(32767);
    INT_FILA_FINAL        INTEGER;
    INT_FILA_LONGITUD     INTEGER;
    INT_FILA_INDICE       INTEGER;
    INT_LARGO_DELIMITADOR INTEGER := LENGTH(P_DELIMITADOR);
    INT_LINEA_FINAL       INTEGER;
  BEGIN
    INT_CLOB_LONGITUD := DBMS_LOB.GETLENGTH(P_CLOB);
    INT_CLOB_INDICE   := 1;

    WHILE INT_CLOB_INDICE <= INT_CLOB_LONGITUD LOOP
      VC_FILA := DBMS_LOB.SUBSTR(P_CLOB, INT_CANTIDAD_LIMITE, INT_CLOB_INDICE);

      --IF INT_CLOB_INDICE > INT_CLOB_LONGITUD - LENGTH(VC_FILA) -- PARA MULTIBYTE
      IF INT_CLOB_INDICE > INT_CLOB_LONGITUD - INT_CANTIDAD_LIMITE THEN
        -- PARA SINGLE BYTE
        INT_CLOB_INDICE := INT_CLOB_LONGITUD + 1;
      ELSE
        INT_FILA_FINAL := INSTR(VC_FILA, P_DELIMITADOR, -1);

        IF INT_FILA_FINAL = 0 THEN
          VC_FILA         := SUBSTR(VC_FILA, 1, INT_CANTIDAD_LIMITE - INT_LIMITE_FILA);
          INT_CLOB_INDICE := INT_CLOB_INDICE + INT_CANTIDAD_LIMITE - INT_LIMITE_FILA;
        ELSE
          VC_FILA         := SUBSTR(VC_FILA, 1, INT_FILA_FINAL + INT_LARGO_DELIMITADOR - 1);
          INT_CLOB_INDICE := INT_CLOB_INDICE + INT_FILA_FINAL + INT_LARGO_DELIMITADOR - 1;
        END IF;
      END IF;

      INT_FILA_INDICE   := 1;
      INT_FILA_LONGITUD := LENGTH(VC_FILA);

      WHILE INT_FILA_INDICE <= INT_FILA_LONGITUD LOOP
        INT_LINEA_FINAL := INSTR(VC_FILA, P_DELIMITADOR, INT_FILA_INDICE);

        IF INT_LINEA_FINAL = 0 OR (INT_LINEA_FINAL - INT_FILA_INDICE) > INT_LIMITE_FILA THEN
          PIPE ROW(SUBSTR(VC_FILA, INT_FILA_INDICE, INT_LIMITE_FILA));
          INT_FILA_INDICE := INT_FILA_INDICE + INT_LIMITE_FILA;
        ELSE
          PIPE ROW(SUBSTR(VC_FILA, INT_FILA_INDICE, INT_LINEA_FINAL - INT_FILA_INDICE));
          INT_FILA_INDICE := INT_LINEA_FINAL + INT_LARGO_DELIMITADOR;
        END IF;
      END LOOP;
    END LOOP;

    RETURN;
  EXCEPTION
    WHEN NO_DATA_NEEDED THEN
      NULL;
  END F_CLOB_A_FILAS;

  FUNCTION F_NUMEROS(P_NUMEROS IN VARCHAR2, P_MAYOR_O_IGUAL IN NUMBER DEFAULT 0) RETURN NUMBER IS
    INT_NUMEROS NUMBER;
  BEGIN
    INT_NUMEROS := TO_NUMBER(TRIM(P_NUMEROS));
    IF INT_NUMEROS >= P_MAYOR_O_IGUAL THEN
      RETURN 1;
    ELSE
      RETURN - 1;
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN 0;
  END F_NUMEROS;

  FUNCTION F_LETRAS(P_LETRAS IN VARCHAR2) RETURN NUMBER IS
    INT_LETRAS NUMBER;
  BEGIN

    SELECT COUNT(1)
      INTO INT_LETRAS
      FROM DUAL
     WHERE REGEXP_LIKE(P_LETRAS, '^\w+$')
       AND REGEXP_LIKE(P_LETRAS, '^[^[:digit:]]+$');

    IF INT_LETRAS > 0 THEN
      RETURN 1;
    ELSE
      RETURN - 1;
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN 0;
  END F_LETRAS;

  FUNCTION F_LETRAS_CON_ESPACIO(P_LETRAS IN VARCHAR2) RETURN NUMBER IS
    INT_LETRAS NUMBER;
  BEGIN

    SELECT COUNT(1)
      INTO INT_LETRAS
      FROM DUAL
     WHERE REGEXP_LIKE(REPLACE(P_LETRAS, ' ', ''), '^\w+$')
       AND REGEXP_LIKE(REPLACE(P_LETRAS, ' ', ''), '^[^[:digit:]]+$');

    IF INT_LETRAS > 0 THEN
      RETURN 1;
    ELSE
      RETURN - 1;
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN 0;
  END F_LETRAS_CON_ESPACIO;

  FUNCTION F_EXPRESSION_COUNT(p_CADENA VARCHAR2, p_VALOR VARCHAR2)
    RETURN NUMBER AS
    intEncontrados  NUMBER := 0;
    vcLongitudValor NUMBER := 0;
    intContador     NUMBER := 0;
    vcExpresion     VARCHAR2(4000);
    vcTemporal      VARCHAR2(4000);
  BEGIN
    vcExpresion     := p_CADENA;
    vcLongitudValor := LENGTH(p_VALOR);
    LOOP
      intContador := intContador + 1;
      vcTemporal  := SUBSTR(vcExpresion, 1, vcLongitudValor);
      IF (vcTemporal = p_VALOR) THEN
        intEncontrados := intEncontrados + 1;
      END IF;
      vcExpresion := SUBSTR(vcExpresion, 2, LENGTH(vcExpresion) - 1);
      EXIT WHEN(LENGTH(vcExpresion) = 0) OR(vcExpresion IS NULL);
    END LOOP;
    RETURN intEncontrados;
  END;

  FUNCTION F_VALIDA_CONDICION(p_intCondicion IN NUMBER,
                              p_vcTipoDoc    IN VARCHAR2,
                              p_vcNumeroDoc  IN VARCHAR2,
                              p_intProducto  IN NUMBER DEFAULT 0)
    RETURN NUMBER IS
    intResultado       NUMBER;
    vcIniDoc           NUMBER;
    intCount           NUMBER;
    intIdClaseProducto NUMBER;
    intNAP             NUMBER;
  BEGIN

    vcIniDoc := SUBSTR(p_vcNumeroDoc, 1, 2);

    IF p_intCondicion IN (1,6) THEN -- OBLIGATORIO SI ES RUC 20
      IF (p_vcTipoDoc = 'RUC' AND vcIniDoc = '20') THEN
        intResultado := 1;
      ELSE
        intResultado := 0;
      END IF;
    ELSIF p_intCondicion = 2 THEN -- OBLIGATORIO SI ES DISTINTO A RUC 20
      IF (p_vcTipoDoc = 'RUC' AND vcIniDoc = '20') THEN
        intResultado := 0;
      ELSE
        intResultado := 1;
      END IF;
    ELSIF p_intCondicion = 3 THEN -- OBLIGATORIO SI ES RUC 10,15,17,20
      IF (p_vcTipoDoc = 'RUC' AND vcIniDoc IN ('10', '15', '17', '20')) THEN
        intResultado := 1;
      ELSE
        intResultado := 0;
      END IF;
    ELSIF p_intCondicion = 4 THEN --OBLIGATORIO SI CLASE COBERTURA CON INTERMEDIACION
      SELECT Count(1)
        INTO intCount
        FROM US_BASE.BASE_PRODUCTO_CONFIG B
       WHERE B.INT_IDPRODUCTO = p_intProducto;

      IF intCount > 0 THEN
        SELECT B.INT_IDCLASE_PRODUCTO
          INTO intIdClaseProducto
          FROM US_BASE.BASE_PRODUCTO_CONFIG B
         WHERE B.INT_IDPRODUCTO = p_intProducto;
        IF intIdClaseProducto = 3 THEN
          intResultado := 1;
        ELSE
          intResultado := 0;
        END IF;
      ELSE
        intResultado := 1;
      END IF;
    ELSIF p_intCondicion = 5 THEN --SI REGLA NTC ESTA EN OFF
      SELECT Count(1)
        INTO intCount
        FROM US_BASE.BASE_REGLA_PRODUCTO B
       WHERE B.INT_IDPROD = p_intProducto;

      IF intCount > 0 THEN
        SELECT B.CH_ES_CREDITO_MONTO_COLATERAL_CODIGO_NAP
          INTO intNAP
          FROM US_BASE.BASE_REGLA_PRODUCTO B
         WHERE B.INT_IDPROD = p_intProducto;
        IF intNAP = 1 THEN
          intResultado := 1;
        ELSE
          intResultado := 0;
        END IF;
      ELSE
        intResultado := 0;
      END IF;
    ELSE
      intResultado := 1;
    END IF;

    RETURN intResultado;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN 0;
  END F_VALIDA_CONDICION;

  FUNCTION F_VALIDA_RUC(P_RUC IN VARCHAR2) RETURN NUMBER IS
    V_RESULTADO NUMBER;
    LI_SUMA     NUMBER;
    LI_I        NUMBER;
    LI_RESTO    NUMBER;
    LI_DIGITO   NUMBER;
    LI_X        NUMBER;
    V_RUC       VARCHAR2(20);
    LI_LARGORUC NUMBER;

  BEGIN
    V_RESULTADO := 0;
    V_RUC       := TRIM(P_RUC);

    IF (F_NUMEROS(V_RUC) = 1) THEN
      IF (LENGTH(V_RUC) = 11) THEN
        LI_SUMA     := 0;
        LI_X        := 6;
        LI_LARGORUC := LENGTH(V_RUC) - 1;

        FOR LI_I IN 1 .. LI_LARGORUC LOOP
          IF LI_I = 5 THEN
            LI_X := 8;
          END IF;

          LI_DIGITO := TO_NUMBER(SUBSTR(V_RUC, LI_I, 1));
          LI_X      := LI_X - 1;
          LI_SUMA   := LI_SUMA + (LI_DIGITO * LI_X);
        END LOOP;

        LI_RESTO := MOD(LI_SUMA, 11);
        LI_RESTO := 11 - LI_RESTO;

        IF LI_RESTO >= 10 THEN
          LI_RESTO := LI_RESTO - 10;
        END IF;

        IF LI_RESTO = TO_NUMBER(SUBSTR(V_RUC, LENGTH(V_RUC), 1)) THEN
          V_RESULTADO := 1;
        END IF;
      ELSE
        V_RESULTADO := 0;
      END IF;
    END IF;

    RETURN V_RESULTADO;

  END F_VALIDA_RUC;

  FUNCTION F_VALIDA_FECHA(P_FECHA IN VARCHAR2, P_FORMATO IN VARCHAR2)
    RETURN NUMBER IS
    DT_FECHA   DATE;
    INT_VALIDO NUMBER;
  BEGIN
    INT_VALIDO := 0;
    DT_FECHA   := TO_DATE(TRIM(P_FECHA), P_FORMATO);
    IF DT_FECHA >= TO_DATE('19000101', 'YYYYDDMM') THEN
      INT_VALIDO := 1;
    END IF;
    RETURN INT_VALIDO;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN 0;
  END F_VALIDA_FECHA;

  FUNCTION F_CONVERTIR_DNI_A_RUC(P_DNI IN VARCHAR2) RETURN VARCHAR2 DETERMINISTIC IS
    LI_SUMA     NUMBER;
    LI_I        NUMBER;
    LI_RESTO    NUMBER;
    LI_DIGITO   NUMBER;
    LI_X        NUMBER;
    V_DNI       VARCHAR2(20);
    V_RUC       VARCHAR2(20);
    LI_LARGORUC NUMBER;

  BEGIN
    V_RUC := '';

    IF (LENGTH(TRIM(P_DNI)) <> 8) THEN
      RETURN V_RUC;
    END IF;

    IF (F_NUMEROS(TRIM(P_DNI)) = 1) THEN
      V_DNI       := '10' || TRIM(P_DNI) || '0';
      LI_SUMA     := 0;
      LI_X        := 6;
      LI_LARGORUC := LENGTH(V_DNI) - 1;

      FOR LI_I IN 1 .. LI_LARGORUC LOOP
        IF LI_I = 5 THEN
          LI_X := 8;
        END IF;

        LI_DIGITO := TO_NUMBER(SUBSTR(V_DNI, LI_I, 1));
        LI_X      := LI_X - 1;
        LI_SUMA   := LI_SUMA + (LI_DIGITO * LI_X);
      END LOOP;

      LI_RESTO := MOD(LI_SUMA, 11);
      LI_RESTO := 11 - LI_RESTO;

      IF LI_RESTO >= 10 THEN
        LI_RESTO := LI_RESTO - 10;
      END IF;

      V_RUC := '10' || TRIM(P_DNI) || TRIM(TO_CHAR(LI_RESTO));
    END IF;

    RETURN V_RUC;

  END F_CONVERTIR_DNI_A_RUC;

  FUNCTION F_CONVERTIR_RUC_A_DNI(P_RUC IN VARCHAR2) RETURN VARCHAR2 DETERMINISTIC IS

    V_DNI     VARCHAR2(20);
    V_RUC     VARCHAR2(20);
    V_INI_RUC VARCHAR2(10);

  BEGIN
    V_DNI := '';
    V_RUC := TRIM(P_RUC);

    IF V_RUC IS NOT NULL THEN
      V_INI_RUC := SUBSTR(V_RUC, 1, 2);
      IF V_INI_RUC = '10' AND LENGTH(V_RUC) = 11 THEN
        V_DNI := SUBSTR(V_RUC, 3, 8);
      END IF;
    END IF;

    RETURN V_DNI;

  END F_CONVERTIR_RUC_A_DNI;

 FUNCTION F_SIGUIENTE_DIA_HABIL(p_Fecha IN DATE, p_DiaHabil IN NUMBER)
    RETURN DATE IS
    pFechaFinal DATE;
  BEGIN
    SELECT FECHA_FINAL
      INTO pFechaFinal
      FROM (SELECT ROWNUM AS DIA, D1.FECHA_FINAL
              FROM (SELECT D0.FECHA_FINAL
                      FROM (SELECT TRUNC(p_Fecha) + LEVEL AS FECHA_FINAL
                              FROM DUAL
                             WHERE TO_NUMBER(TO_CHAR(TRUNC(p_Fecha) + LEVEL, 'D')) NOT IN (1, 7)
                            CONNECT BY LEVEL <= p_DiaHabil + 7) D0
                     WHERE TRIM(TO_CHAR(D0.FECHA_FINAL, 'YYYYMMDD')) NOT IN
                           (SELECT F.VC_FERIADOS
                              FROM US_BASE.V_SCP_FERIADO F
                             WHERE F.VC_FERIADOS >= TRIM(TO_CHAR(TRUNC(p_Fecha), 'YYYYMMDD')))
                     ORDER BY D0.FECHA_FINAL) D1)
     WHERE DIA = p_DiaHabil;
    RETURN pFechaFinal;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN p_Fecha + p_DiaHabil;
  END F_SIGUIENTE_DIA_HABIL;

  PROCEDURE I_EXTRAER_ESTRUCTURA(p_Producto  IN NUMBER,
                                 p_Tipo      IN VARCHAR2,
                                 p_Registros IN OUT T_TAB_ESTRUCTURA) AS
    CANT NUMBER;
  BEGIN
    p_Registros := T_TAB_ESTRUCTURA();

    IF p_Tipo = 'SOLBENE' THEN
      SELECT COUNT(1)
        INTO CANT
        FROM US_BASE.V_BASE_ESTRUCTURA_CONFIG_SOL_BENEFICIARIO B
       WHERE B.INT_IDPRODUCTO = p_Producto;

      IF CANT > 0 THEN
        p_Registros.EXTEND(CANT);

        FOR REC_CRO IN (SELECT B.INT_CODIGO,
                               TRIM(B.VC_DESCRIPCION) AS VC_DESCRIPCION,
                               B.INT_REQUERIDO,
                               B.INT_IDCONDICION
                          FROM US_BASE.V_BASE_ESTRUCTURA_CONFIG_SOL_BENEFICIARIO B
                         WHERE B.INT_IDPRODUCTO = p_Producto
                         ORDER BY B.INT_CODIGO) LOOP

          p_Registros(REC_CRO.INT_CODIGO).INT_CODIGO := REC_CRO.INT_CODIGO;
          p_Registros(REC_CRO.INT_CODIGO).VC_DESCRIPCION := REC_CRO.VC_DESCRIPCION;
          p_Registros(REC_CRO.INT_CODIGO).INT_REQUERIDO := REC_CRO.INT_REQUERIDO;
          p_Registros(REC_CRO.INT_CODIGO).INT_IDCONDICION := REC_CRO.INT_IDCONDICION;

        END LOOP;
      END IF;
    END IF;

    IF p_Tipo = 'SOLCRED' THEN
      SELECT COUNT(1)
        INTO CANT
        FROM US_BASE.V_BASE_ESTRUCTURA_CONFIG_SOL_CREDITO B
       WHERE B.INT_IDPRODUCTO = p_Producto;

      IF CANT > 0 THEN
        p_Registros.EXTEND(CANT);

        FOR REC_CRO IN (SELECT B.INT_CODIGO,
                               TRIM(B.VC_DESCRIPCION) AS VC_DESCRIPCION,
                               B.INT_REQUERIDO,
                               B.INT_IDCONDICION
                          FROM US_BASE.V_BASE_ESTRUCTURA_CONFIG_SOL_CREDITO B
                         WHERE B.INT_IDPRODUCTO = p_Producto
                         ORDER BY B.INT_CODIGO) LOOP

          p_Registros(REC_CRO.INT_CODIGO).INT_CODIGO := REC_CRO.INT_CODIGO;
          p_Registros(REC_CRO.INT_CODIGO).VC_DESCRIPCION := REC_CRO.VC_DESCRIPCION;
          p_Registros(REC_CRO.INT_CODIGO).INT_REQUERIDO := REC_CRO.INT_REQUERIDO;
          p_Registros(REC_CRO.INT_CODIGO).INT_IDCONDICION := REC_CRO.INT_IDCONDICION;

        END LOOP;
      END IF;
    END IF;

    IF p_Tipo = 'SOLREPL' THEN
      SELECT COUNT(1)
        INTO CANT
        FROM US_BASE.V_BASE_ESTRUCTURA_CONFIG_SOL_REP_LEGAL B
       WHERE B.INT_IDPRODUCTO = p_Producto;

      IF CANT > 0 THEN
        p_Registros.EXTEND(CANT);

        FOR REC_CRO IN (SELECT B.INT_CODIGO,
                               TRIM(B.VC_DESCRIPCION) AS VC_DESCRIPCION,
                               B.INT_REQUERIDO,
                               B.INT_IDCONDICION
                          FROM US_BASE.V_BASE_ESTRUCTURA_CONFIG_SOL_REP_LEGAL B
                         WHERE B.INT_IDPRODUCTO = p_Producto
                         ORDER BY B.INT_CODIGO) LOOP

          p_Registros(REC_CRO.INT_CODIGO).INT_CODIGO := REC_CRO.INT_CODIGO;
          p_Registros(REC_CRO.INT_CODIGO).VC_DESCRIPCION := REC_CRO.VC_DESCRIPCION;
          p_Registros(REC_CRO.INT_CODIGO).INT_REQUERIDO := REC_CRO.INT_REQUERIDO;
          p_Registros(REC_CRO.INT_CODIGO).INT_IDCONDICION := REC_CRO.INT_IDCONDICION;

        END LOOP;
      END IF;
    END IF;

    IF p_Tipo = 'REPLEGA' THEN
      SELECT COUNT(1)
        INTO CANT
        FROM US_BASE.V_BASE_ESTRUCTURA_CONFIG_REP_LEGAL B
       WHERE B.INT_IDPRODUCTO = p_Producto;

      IF CANT > 0 THEN
        p_Registros.EXTEND(CANT);

        FOR REC_CRO IN (SELECT B.INT_CODIGO,
                               TRIM(B.VC_DESCRIPCION) AS VC_DESCRIPCION,
                               B.INT_REQUERIDO,
                               B.INT_IDCONDICION
                          FROM US_BASE.V_BASE_ESTRUCTURA_CONFIG_REP_LEGAL B
                         WHERE B.INT_IDPRODUCTO = p_Producto
                         ORDER BY B.INT_CODIGO) LOOP

          p_Registros(REC_CRO.INT_CODIGO).INT_CODIGO := REC_CRO.INT_CODIGO;
          p_Registros(REC_CRO.INT_CODIGO).VC_DESCRIPCION := REC_CRO.VC_DESCRIPCION;
          p_Registros(REC_CRO.INT_CODIGO).INT_REQUERIDO := REC_CRO.INT_REQUERIDO;
          p_Registros(REC_CRO.INT_CODIGO).INT_IDCONDICION := REC_CRO.INT_IDCONDICION;

        END LOOP;
      END IF;
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_BASE', 'I_EXTRAER_ESTRUCTURA', vcErrorStack, vcErrorBacktace);
      RAISE_APPLICATION_ERROR(-20110, 'PKG_BASE.I_EXTRAER_ESTRUCTURA:'|| vcErrorStack||'; '||vcErrorBacktace);
  END I_EXTRAER_ESTRUCTURA;

  PROCEDURE I_PROCESAR_CLOB(p_intIdSolicitud IN SOLICITUD.INT_IDSOLICITUD%TYPE) AS
    PRAGMA AUTONOMOUS_TRANSACTION;
    intCount      NUMBER;
    intLargoFile1 NUMBER;
    intLargoFile2 NUMBER;
    L_TAB_SDT     T_TAB_SDT := T_TAB_SDT();
    L_TAB_SRT     T_TAB_SRT := T_TAB_SRT();
    start_time    NUMBER;
    end_time      NUMBER;
  BEGIN

    SELECT COUNT(1)
      INTO intCount
      FROM SOLICITUD_ARCHIVOS A
     WHERE A.INT_IDSOLICITUD = p_intIdSolicitud
       AND A.VC_ESTADO = 'RE';

    IF intCount > 0 THEN
      SELECT NVL(DBMS_LOB.GETLENGTH(A.CL_FILE1), -1),
             NVL(DBMS_LOB.GETLENGTH(A.CL_FILE2), -1)
        INTO intLargoFile1, intLargoFile2
        FROM SOLICITUD_ARCHIVOS A
       WHERE A.INT_IDSOLICITUD = p_intIdSolicitud
         AND A.VC_ESTADO = 'RE';

      IF intLargoFile1 > 0 THEN
        Start_time := DBMS_UTILITY.get_time;
        SELECT p_intIdSolicitud AS INT_IDSOLICITUD,
               ROWNUM AS INT_FILA,
               0 AS INT_IDSOLICITUD_DET,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 01)) AS C01,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 02)) AS C02,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 03)) AS C03,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 04)) AS C04,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 05)) AS C05,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 06)) AS C06,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 07)) AS C07,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 08)) AS C08,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 09)) AS C09,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 10)) AS C10,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 11)) AS C11,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 12)) AS C12,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 13)) AS C13,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 14)) AS C14,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 15)) AS C15,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 16)) AS C16,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 17)) AS C17,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 18)) AS C18,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 19)) AS C19,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 20)) AS C20,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 21)) AS C21,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 22)) AS C22,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 23)) AS C23,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 24)) AS C24,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 25)) AS C25,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 26)) AS C26,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 27)) AS C27,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 28)) AS C28,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 29)) AS C29,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 30)) AS C30,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 31)) AS C31,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 32)) AS C32,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 33)) AS C33,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 34)) AS C34,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 35)) AS C35,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 36)) AS C36,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 37)) AS C37,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 38)) AS C38,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 39)) AS C39,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 40)) AS C40,
               NULL AS OBSERVACIONES
          BULK COLLECT
          INTO L_TAB_SDT
          FROM (SELECT REGEXP_REPLACE(REPLACE(T.COLUMN_VALUE, '|', '| '), '^\|', ' |') AS FILA
                  FROM TABLE (SELECT PKG_BASE.F_CLOB_A_FILAS(A.CL_FILE1)
                                FROM SOLICITUD_ARCHIVOS A
                               WHERE A.INT_IDSOLICITUD = p_intIdSolicitud) T
                 WHERE TRIM(T.COLUMN_VALUE) IS NOT NULL);
        end_time := DBMS_UTILITY.get_time;
        DBMS_OUTPUT.PUT_LINE('Bulk select 1: ' || TO_CHAR(end_time - start_time));

        Start_time := DBMS_UTILITY.get_time;
        FORALL i in L_TAB_SDT.first .. L_TAB_SDT.last
          INSERT /*+APPEND*/ INTO SOLICITUD_DETALLE_TEXTO VALUES L_TAB_SDT (i);
        end_time := DBMS_UTILITY.get_time;
        DBMS_OUTPUT.PUT_LINE('Bulk Insert 1: ' || TO_CHAR(end_time - start_time));



        COMMIT;
      END IF;

      IF intLargoFile2 > 0 THEN
        Start_time := DBMS_UTILITY.get_time;
        SELECT p_intIdSolicitud AS INT_IDSOLICITUD,
               ROWNUM AS INT_FILA,
               0 AS INT_IDSOLICITUD_DET,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 01)) AS C01,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 02)) AS C02,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 03)) AS C03,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 04)) AS C04,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 05)) AS C05,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 06)) AS C06,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 07)) AS C07,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 08)) AS C08,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 09)) AS C09,
               TRIM(REGEXP_SUBSTR(FILA, '[^|]+', 1, 10)) AS C10,
               NULL AS OBSERVACIONES
          BULK COLLECT
          INTO L_TAB_SRT
          FROM (SELECT REGEXP_REPLACE(REPLACE(T.COLUMN_VALUE, '|', '| '), '^\|', ' |') AS FILA
                  FROM TABLE (SELECT PKG_BASE.F_CLOB_A_FILAS(A.CL_FILE2)
                                FROM SOLICITUD_ARCHIVOS A
                               WHERE A.INT_IDSOLICITUD = p_intIdSolicitud) T
                 WHERE TRIM(T.COLUMN_VALUE) IS NOT NULL);
        end_time := DBMS_UTILITY.get_time;
        DBMS_OUTPUT.PUT_LINE('Bulk select 2: ' || TO_CHAR(end_time - start_time));

        Start_time := DBMS_UTILITY.get_time;
        FORALL i in L_TAB_SRT.first .. L_TAB_SRT.last
          INSERT /*+APPEND*/ INTO SOLICITUD_REPLEG_TEXTO VALUES L_TAB_SRT(i);
        end_time := DBMS_UTILITY.get_time;
        DBMS_OUTPUT.PUT_LINE('Bulk Insert 2: ' || TO_CHAR(end_time - start_time));

        COMMIT;
      END IF;

      UPDATE SOLICITUD_ARCHIVOS A
         SET A.VC_ESTADO = 'PR'
       WHERE A.INT_IDSOLICITUD = p_intIdSolicitud
         AND A.VC_ESTADO = 'RE';

      UPDATE SOLICITUD_RESULTADOS A
         SET A.VC_ESTADO                = 'PROCESAR_CLOB',
             A.VC_USUARIO_MODIFICACION  = USER,
             A.DT_FECHA_MODIFICACION    = SYSDATE,
             A.VC_TERMINAL_MODIFICACION = SYS_CONTEXT('USERENV', 'IP_ADDRESS')
       WHERE A.INT_IDSOLICITUD = p_intIdSolicitud
         AND A.VC_ESTADO = 'REGISTRO';

      COMMIT;
    END IF;

  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      ROLLBACK;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_BASE', 'I_PROCESAR_CLOB', vcErrorStack, vcErrorBacktace, 'INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
      RAISE_APPLICATION_ERROR(-20111, 'PKG_BASE.I_PROCESAR_CLOB:'|| vcErrorStack||'; '||vcErrorBacktace||'; INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
  END I_PROCESAR_CLOB;

  PROCEDURE I_PROCESAR_ESTRUCTURA(p_intIdSolicitud IN SOLICITUD.INT_IDSOLICITUD%TYPE) AS
    PRAGMA AUTONOMOUS_TRANSACTION;
  BEGIN
    I_PROCESAR_ESTRUCTURA_SOLICITUD(p_intIdSolicitud);
    I_PROCESAR_ESTRUCTURA_REPLEGAL(p_intIdSolicitud);

    UPDATE SOLICITUD_RESULTADOS A
       SET A.VC_ESTADO                = 'PROCESAR_STRUC',
           A.VC_USUARIO_MODIFICACION  = USER,
           A.DT_FECHA_MODIFICACION    = SYSDATE,
           A.VC_TERMINAL_MODIFICACION = SYS_CONTEXT('USERENV', 'IP_ADDRESS')
     WHERE A.INT_IDSOLICITUD = p_intIdSolicitud
       AND A.VC_ESTADO = 'PROCESAR_CLOB';
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      ROLLBACK;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_BASE', 'I_PROCESAR_ESTRUCTURA', vcErrorStack, vcErrorBacktace, 'INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
      RAISE_APPLICATION_ERROR(-20112, 'PKG_BASE.I_PROCESAR_ESTRUCTURA:'|| vcErrorStack||'; '||vcErrorBacktace||'; INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
  END I_PROCESAR_ESTRUCTURA;

  PROCEDURE I_PROCESAR_ESTRUCTURA_SOLICITUD(p_intIdSolicitud IN SOLICITUD.INT_IDSOLICITUD%TYPE) AS
    PRAGMA AUTONOMOUS_TRANSACTION;
    intCount         NUMBER;
    intLargoFile1    NUMBER;
    intIdSolicituDet SOLICITUD_DETALLE.INT_IDSOLICITUD_DET%TYPE;
    L_TAB_SD0        T_TAB_SD := T_TAB_SD();
    L_TAB_SD_VAL     T_TAB_SD := T_TAB_SD();
    vcErrores        VARCHAR2(4000);
    intErrores       NUMBER;
    start_time       NUMBER;
    end_time         NUMBER;
    stSolBene        PKG_BASE.T_TAB_ESTRUCTURA;
    stSolRepL        PKG_BASE.T_TAB_ESTRUCTURA;
    stSolCred        PKG_BASE.T_TAB_ESTRUCTURA;
    blValidacion     Boolean;
    intPunto         NUMBER(10);
    intEntero        NUMBER(10);
    intDecimal       NUMBER(10);
    intIdProducto    SOLICITUD.INT_IDPRODUCTO%TYPE;
    REG_SDT          SOLICITUD_DETALLE_TEXTO%ROWTYPE;
    REG_SD           SOLICITUD_DETALLE%ROWTYPE;
    REG_SD_NULL      SOLICITUD_DETALLE%ROWTYPE;
  BEGIN

    intIdProducto := 0;

    SELECT A.INT_IDPRODUCTO
      INTO intIdProducto
      FROM SOLICITUD A
     WHERE A.INT_IDSOLICITUD = p_intIdSolicitud;

    SELECT COUNT(1)
      INTO intCount
      FROM SOLICITUD_ARCHIVOS A
     WHERE A.INT_IDSOLICITUD = p_intIdSolicitud
       AND A.VC_ESTADO = 'PR';

    IF intCount > 0 THEN
      SELECT COUNT(1)
        INTO intLargoFile1
        FROM SOLICITUD_DETALLE_TEXTO A
       WHERE A.INT_IDSOLICITUD = p_intIdSolicitud;
    END IF;

    IF intLargoFile1 > 0 THEN
      PKG_BASE.I_EXTRAER_ESTRUCTURA(intIdProducto, 'SOLBENE', stSolBene);
      PKG_BASE.I_EXTRAER_ESTRUCTURA(intIdProducto, 'SOLCRED', stSolCred);
      PKG_BASE.I_EXTRAER_ESTRUCTURA(intIdProducto, 'SOLREPL', stSolRepL);

      BEGIN
        Start_time := DBMS_UTILITY.get_time;
        FOR CURSOR_SDT IN (SELECT INT_IDSOLICITUD, INT_FILA, INT_IDSOLICITUD_DET,
                                  C01, C02, C03, C04, C05, C06, C07, C08, C09, C10,
                                  C11, C12, C13, C14, C15, C16, C17, C18, C19, C20,
                                  C21, C22, C23, C24, C25, C26, C27, C28, C29, C30,
                                  C31, C32, C33, C34, C35, C36, C37, C38, C39, C40,
                                  OBSERVACIONES
                             FROM SOLICITUD_DETALLE_TEXTO
                            WHERE INT_IDSOLICITUD = p_intIdSolicitud
                            ORDER BY INT_IDSOLICITUD, INT_FILA) LOOP
          vcErrores  := 'Errores en Solicitud : ' ||TRIM(TO_CHAR(p_intIdSolicitud))|| vcEnter;
          intErrores := 0;
          REG_SDT    := CURSOR_SDT;
          REG_SD     := REG_SD_NULL;

          REG_SD.INT_IDSOLICITUD := REG_SDT.INT_IDSOLICITUD;
          --Tipo de documento
          BEGIN
            blValidacion := FALSE;
            IF stSolBene(01).INT_REQUERIDO = 1 THEN
              IF TRIM(REG_SDT.C01) IS NULL THEN
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 01 : ' || stSolBene(01).VC_DESCRIPCION || ', > Es obligatorio.' || vcEnter;
              ELSE
                IF LENGTH(TRIM(REG_SDT.C01)) = 3 AND PKG_BASE.F_LETRAS(TRIM(REG_SDT.C01)) = 1 THEN
                  blValidacion := TRUE;
                ELSE
                  intErrores := intErrores + 1;
                  vcErrores  := vcErrores || 'en Campo 01 : ' || stSolBene(01).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C01) || ', > Debe se letras de longitud 3.' || vcEnter;
                END IF;
              END IF;
            ELSE
              IF (LENGTH(TRIM(REG_SDT.C01)) = 3 AND PKG_BASE.F_LETRAS(TRIM(REG_SDT.C01)) = 1) OR TRIM(REG_SDT.C01) IS NULL THEN
                blValidacion := TRUE;
              ELSE
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 01 : ' || stSolBene(01).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C01) || ', > Debe se letras de longitud 3.' || vcEnter;
              END IF;
            END IF;
            IF blValidacion THEN
              REG_SD.VC_TIPO_DOCUMENTO := TRIM(REG_SDT.C01);
            END IF;
          EXCEPTION
            WHEN OTHERS THEN
              intErrores := intErrores + 1;
              vcErrores  := vcErrores || 'en Campo 01 : ' || stSolBene(01).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C01) || ', > ' || SQLERRM || '.' || vcEnter;
          END;

          --Numero de documento
          BEGIN
            blValidacion := FALSE;
            IF stSolBene(02).INT_REQUERIDO = 1 THEN
              IF TRIM(REG_SDT.C02) IS NULL THEN
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', > Es requerido.' || vcEnter;
              ELSE
                IF ( (PKG_BASE.F_NUMEROS(TRIM(REG_SDT.C02)) = 1 AND LENGTH(TRIM(REG_SDT.C02)) >= 8) OR
                   ( ( TRIM(REG_SDT.C01)='RUC' AND LENGTH(TRIM(REG_SDT.C02)) =11 ) OR
                     ( TRIM(REG_SDT.C01)='DNI' AND LENGTH(TRIM(REG_SDT.C02)) =8  ) OR
                     ( TRIM(REG_SDT.C01)='CET' AND LENGTH(TRIM(REG_SDT.C02))>=9 AND LENGTH(TRIM(REG_SDT.C02))<=12 ) ) ) THEN
                  blValidacion := TRUE;
                ELSE
                  intErrores := intErrores + 1;
                  vcErrores  := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C02) || ', > Deben ser caracteres numéricos positivos y mínimo 8 caracteres' || vcEnter;
                END IF;
              END IF;
            ELSE
              IF ( (PKG_BASE.F_NUMEROS(TRIM(REG_SDT.C02)) = 1 AND LENGTH(TRIM(REG_SDT.C02)) >= 8) OR
                 ( ( TRIM(REG_SDT.C01)='RUC' AND LENGTH(TRIM(REG_SDT.C02)) =11 ) OR
                   ( TRIM(REG_SDT.C01)='DNI' AND LENGTH(TRIM(REG_SDT.C02)) =8  ) OR
                   ( TRIM(REG_SDT.C01)='CET' AND LENGTH(TRIM(REG_SDT.C02))>=9 AND LENGTH(TRIM(REG_SDT.C02))<=12 ) ) ) OR TRIM(REG_SDT.C02) IS NULL THEN
                blValidacion := TRUE;
              ELSE
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C02) || ', > Deben ser caracteres numéricos positivos y mínimo 8 caracteres' || vcEnter;
              END IF;
            END IF;
            IF blValidacion THEN
              REG_SD.VC_NUMERO_DOCUMENTO := TRIM(REG_SDT.C02);
              /*
              IF REG_SD.VC_TIPO_DOCUMENTO = 'DNI' THEN
                REG_SD.VC_TIPO_DOCUMENTO_CON   := 'RUC';
                REG_SD.VC_NUMERO_DOCUMENTO_CON := PKG_BASE.F_CONVERTIR_DNI_A_RUC(REG_SD.VC_NUMERO_DOCUMENTO);
                REG_SD.VC_NUMERO_DOCUMENTO_RUC := PKG_BASE.F_CONVERTIR_DNI_A_RUC(REG_SD.VC_NUMERO_DOCUMENTO);
              END IF;
              IF REG_SD.VC_TIPO_DOCUMENTO = 'RUC' AND LENGTH(REG_SD.VC_NUMERO_DOCUMENTO) = 11 THEN
                IF SUBSTR(REG_SD.VC_NUMERO_DOCUMENTO, 1, 2) = '10' THEN
                  REG_SD.VC_TIPO_DOCUMENTO_CON   := 'DNI';
                  REG_SD.VC_NUMERO_DOCUMENTO_CON := PKG_BASE.F_CONVERTIR_RUC_A_DNI(REG_SD.VC_NUMERO_DOCUMENTO);
                END IF;
                REG_SD.VC_NUMERO_DOCUMENTO_RUC := REG_SD.VC_NUMERO_DOCUMENTO;
              END IF;
              */
            END IF;
          EXCEPTION
            WHEN OTHERS THEN
              intErrores := intErrores + 1;
              vcErrores  := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', ' ||  TRIM(REG_SDT.C02) || ', > ' || SQLERRM || '.' || vcEnter;
          END;

          --Razon Social
          BEGIN
            blValidacion := FALSE;
            IF stSolBene(03).INT_REQUERIDO = 1 AND PKG_BASE.F_VALIDA_CONDICION(stSolBene(03).INT_IDCONDICION, TRIM(REG_SDT.C01), TRIM(REG_SDT.C02), intIdProducto) = 1 THEN
              IF TRIM(REG_SDT.C03) IS NULL THEN
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 03 : ' || stSolBene(03).VC_DESCRIPCION || ', > Es obligatorio.' || vcEnter;
              ELSE
                IF LENGTH(TRIM(REG_SDT.C03)) <= 300 THEN
                  blValidacion := TRUE;
                ELSE
                  intErrores := intErrores + 1;
                  vcErrores  := vcErrores || 'en Campo 03 : ' || stSolBene(03).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C03) || ', > Longitud excede de 300.' || vcEnter;
                END IF;
              END IF;
            ELSE
              IF LENGTH(TRIM(REG_SDT.C03)) <= 300 OR TRIM(REG_SDT.C03) IS NULL THEN
                blValidacion := TRUE;
              ELSE
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 03 : ' || stSolBene(03).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C03) || ', > Longitud excede de 300.' || vcEnter;
              END IF;
            END IF;
            IF blValidacion THEN
              REG_SD.VC_RAZON_SOCIAL := TRIM(REG_SDT.C03);
            END IF;
          EXCEPTION
            WHEN OTHERS THEN
              intErrores := intErrores + 1;
              vcErrores  := vcErrores || 'en Campo 03 : ' || stSolBene(03).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C03) || ', > ' || SQLERRM || '.' || vcEnter;
          END;

          --Apellido Paterno
          BEGIN
            blValidacion := FALSE;
            IF stSolBene(04).INT_REQUERIDO = 1 AND PKG_BASE.F_VALIDA_CONDICION(stSolBene(04).INT_IDCONDICION, TRIM(REG_SDT.C01), TRIM(REG_SDT.C02), intIdProducto) = 1 THEN
              IF TRIM(REG_SDT.C04) IS NULL THEN
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 04 : ' || stSolBene(04).VC_DESCRIPCION || ', > Es obligatorio.' || vcEnter;
              ELSE
                IF LENGTH(TRIM(REG_SDT.C04)) <= 80 THEN
                  IF PKG_BASE.F_LETRAS_CON_ESPACIO(TRIM(REG_SDT.C04)) = 1 THEN
                    blValidacion := TRUE;
                  ELSE
                    intErrores := intErrores + 1;
                    vcErrores  := vcErrores || 'en Campo 04 : ' || stSolBene(04).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C04) || ', > Solo debe contener caracteres Alfabeticos.' || vcEnter;
                  END IF;
                ELSE
                  intErrores := intErrores + 1;
                  vcErrores  := vcErrores || 'en Campo 04 : ' || stSolBene(04).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C04) || ', > Longitud excede de 80.' || vcEnter;
                END IF;
              END IF;
            ELSE
              IF ( LENGTH(TRIM(REG_SDT.C04)) <= 80 OR TRIM(REG_SDT.C04) IS NULL ) THEN
                IF PKG_BASE.F_LETRAS_CON_ESPACIO( TRIM(REG_SDT.C04) ) = 1 OR TRIM(REG_SDT.C04) IS NULL THEN
                  blValidacion := TRUE;
                ELSE
                  intErrores := intErrores + 1;
                  vcErrores  := vcErrores || 'en Campo 04 : ' || stSolBene(04).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C04) || ', > Solo debe contener caracteres Alfabeticos.' || vcEnter;
                END IF;
              ELSE
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 04 : ' || stSolBene(04).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C04) || ', > Longitud excede de 80.' || vcEnter;
              END IF;
            END IF;
            IF blValidacion THEN
              REG_SD.VC_APELLIDO_PATERNO := TRIM(REG_SDT.C04);
            END IF;
          EXCEPTION
            WHEN OTHERS THEN
              intErrores := intErrores + 1;
              vcErrores  := vcErrores || 'en Campo 04 : ' || stSolBene(04).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C04) || ', > ' || SQLERRM || '.' || vcEnter;
          END;

          --Apellido Materno
          BEGIN
            blValidacion := FALSE;
            IF stSolBene(05).INT_REQUERIDO = 1 AND PKG_BASE.F_VALIDA_CONDICION(stSolBene(05).INT_IDCONDICION, TRIM(REG_SDT.C01), TRIM(REG_SDT.C02), intIdProducto) = 1 THEN
              IF TRIM(REG_SDT.C05) IS NULL THEN
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 05 : ' || stSolBene(05).VC_DESCRIPCION || ', > Es obligatorio.' || vcEnter;
              ELSE
                IF LENGTH(TRIM(REG_SDT.C05)) <= 80 THEN
                  IF PKG_BASE.F_LETRAS_CON_ESPACIO(TRIM(REG_SDT.C05)) = 1 THEN
                    blValidacion := TRUE;
                  ELSE
                    intErrores := intErrores + 1;
                    vcErrores  := vcErrores || 'en Campo 05 : ' || stSolBene(05).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C05) || ', > Solo debe contener caracteres Alfabeticos.' || vcEnter;
                  END IF;
                ELSE
                  intErrores := intErrores + 1;
                  vcErrores  := vcErrores || 'en Campo 05 : ' || stSolBene(05).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C05) || ', > Longitud excede de 80.' || vcEnter;
                END IF;
              END IF;
            ELSE
              IF (LENGTH(TRIM(REG_SDT.C05)) <= 80 OR TRIM(REG_SDT.C05) IS NULL) THEN
                IF PKG_BASE.F_LETRAS_CON_ESPACIO(TRIM(REG_SDT.C05)) = 1 OR TRIM(REG_SDT.C05) IS NULL THEN
                  blValidacion := TRUE;
                ELSE
                  intErrores := intErrores + 1;
