                ELSE
                  intErrores := intErrores + 1;
                  vcErrores  := vcErrores || 'en Campo 25 : ' || stSolCred(10).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C25) || ', > Debe tener entre 10 y 12 caractéres.' || vcEnter;
                END IF;
              END IF;
            ELSE
              IF (LENGTH(TRIM(REG_SDT.C25)) >= 10 AND LENGTH(TRIM(REG_SDT.C25)) <= 12 AND PKG_BASE.F_NUMEROS(TRIM(REG_SDT.C25)) = 1) OR TRIM(REG_SDT.C25) IS NULL THEN
                blValidacion := TRUE;
              ELSE
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 25 : ' || stSolCred(10).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C25) || ', > Debe tener entre 10 y 12 carateres.' || vcEnter;
              END IF;
            END IF;
            IF blValidacion THEN
              REG_SD.VC_CODIGO_SUBASTA := TRIM(REG_SDT.C25);
            END IF;
          EXCEPTION
            WHEN OTHERS THEN
              intErrores := intErrores + 1;
              vcErrores  := vcErrores || 'en Campo 25 : ' || stSolCred(10).VC_DESCRIPCION || ', ' || TRIM(REG_SDT.C25) || ', > ' || SQLERRM || '.' || vcEnter;
          END;


          PKG_PRODUCTO.I_PROCESAR_ESTRUCTURA_SOLICITUD(REG_SD, REG_SDT, intErrores, vcErrores);

          REG_SD.VC_USUARIO_CREACION  := USER;
          REG_SD.DT_FECHA_CREACION    := SYSDATE;
          REG_SD.VC_TERMINAL_CREACION := UPPER(SYS_CONTEXT('USERENV', 'SERVER_HOST'));

          IF intErrores = 0 THEN
            SELECT SOLICITUD_DET_SEQ.NEXTVAL
              INTO intIdSolicituDet
              FROM DUAL;

            REG_SD.INT_IDSOLICITUD_DET           := intIdSolicituDet;
            REG_SD.OBSERVACIONES                 := 'POR PROCESAR REGLAS';
            REG_SD.VC_ESTADO                     := 'REG';
            REG_SD.DEC_PORCENTAJE_COBERTURA      := 0;
            REG_SD.DEC_PORCENTAJE_COBERTURA_ORIG := 0;
            REG_SD.DEC_MONTO_COBERTURA           := 0;
            REG_SD.DEC_MONTO_COBERTURA_ORIG      := 0;

            UPDATE SOLICITUD_DETALLE_TEXTO SDT
               SET SDT.OBSERVACIONES       = 'OK',
                   SDT.INT_IDSOLICITUD_DET = intIdSolicituDet
             WHERE SDT.INT_IDSOLICITUD = REG_SDT.INT_IDSOLICITUD
               AND SDT.INT_FILA = REG_SDT.INT_FILA;
          ELSE
            REG_SD.OBSERVACIONES := vcErrores;

            UPDATE SOLICITUD_DETALLE_TEXTO SDT
               SET SDT.OBSERVACIONES = vcErrores
             WHERE SDT.INT_IDSOLICITUD = REG_SDT.INT_IDSOLICITUD
               AND SDT.INT_FILA = REG_SDT.INT_FILA;
          END IF;

          L_TAB_SD_VAL.EXTEND();
          L_TAB_SD_VAL(L_TAB_SD_VAL.LAST) := REG_SD;

        END LOOP;

        end_time := DBMS_UTILITY.get_time;
        DBMS_OUTPUT.PUT_LINE('Bulk VALIDAR 1: ' || TO_CHAR(end_time - start_time));

        Start_time := DBMS_UTILITY.get_time;
        SELECT T.*
          BULK COLLECT
          INTO L_TAB_SD0
          FROM TABLE(L_TAB_SD_VAL) T
         WHERE OBSERVACIONES = 'POR PROCESAR REGLAS';
        end_time := DBMS_UTILITY.get_time;
        DBMS_OUTPUT.PUT_LINE('Bulk select 1: ' || TO_CHAR(end_time - start_time));

        Start_time := DBMS_UTILITY.get_time;
        FORALL i in L_TAB_SD0.first .. L_TAB_SD0.last
          INSERT /*+APPEND*/ INTO SOLICITUD_DETALLE VALUES L_TAB_SD0(i);
        end_time := DBMS_UTILITY.get_time;
        DBMS_OUTPUT.PUT_LINE('Bulk Insert 1: ' || TO_CHAR(end_time - start_time));

        UPDATE SOLICITUD SR
           SET SR.INT_RECHAZADOS =
               (SELECT COUNT(1)
                  FROM SOLICITUD_DETALLE SD
                 WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
                   AND SD.OBSERVACIONES <> 'POR PROCESAR REGLAS')
         WHERE SR.INT_IDSOLICITUD = p_intIdSolicitud;

        UPDATE SOLICITUD_RESULTADOS SR
           SET SR.INT_REGISTROS_RECHAZADOS_ESTRUCTURA =
               (SELECT COUNT(1)
                  FROM SOLICITUD_DETALLE SD
                 WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
                   AND SD.OBSERVACIONES <> 'POR PROCESAR REGLAS'),
               SR.INT_REGISTROS_RECHAZADOS           =
               (SELECT COUNT(1)
                  FROM SOLICITUD_DETALLE SD
                 WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
                   AND SD.OBSERVACIONES <> 'POR PROCESAR REGLAS'),
               SR.VC_USUARIO_MODIFICACION             = USER,
               SR.DT_FECHA_MODIFICACION               = SYSDATE,
               SR.VC_TERMINAL_MODIFICACION            = SYS_CONTEXT('USERENV', 'IP_ADDRESS')
         WHERE SR.INT_IDSOLICITUD = p_intIdSolicitud
           AND SR.VC_ESTADO = 'PROCESAR_CLOB';
        COMMIT;
      END;

    END IF;

  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      ROLLBACK;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_BASE', 'I_PROCESAR_ESTRUCTURA_SOLICITUD', vcErrorStack, vcErrorBacktace, 'INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
      RAISE_APPLICATION_ERROR(-20113, 'PKG_BASE.I_PROCESAR_ESTRUCTURA_SOLICITUD:'|| vcErrorStack||'; '||vcErrorBacktace||'; INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
  END I_PROCESAR_ESTRUCTURA_SOLICITUD;

  PROCEDURE I_PROCESAR_ESTRUCTURA_REPLEGAL(p_intIdSolicitud IN SOLICITUD.INT_IDSOLICITUD%TYPE) AS
    PRAGMA AUTONOMOUS_TRANSACTION;
    intCount      NUMBER;
    intLargoFile2 NUMBER;
    L_TAB_SR0     T_TAB_SR := T_TAB_SR();
    L_TAB_SR_VAL  T_TAB_SR := T_TAB_SR();
    vcErrores     VARCHAR2(4000);
    intErrores    NUMBER;
    start_time    NUMBER;
    end_time      NUMBER;
    stRepLega     PKG_BASE.T_TAB_ESTRUCTURA;
    blValidacion  Boolean;
    intIdProducto SOLICITUD_DETALLE.INT_IDSOLICITUD_DET%TYPE;
    REG_SRLT      SOLICITUD_REPLEG_TEXTO%ROWTYPE;
    REG_SRL       SOLICITUD_REPLEG%ROWTYPE;
    REG_SRL_NULL  SOLICITUD_REPLEG%ROWTYPE;
  BEGIN

    intIdProducto := 0;

    SELECT A.INT_IDPRODUCTO
      INTO intIdProducto
      FROM SOLICITUD A
     WHERE A.INT_IDSOLICITUD = p_intIdSolicitud;

    SELECT COUNT(1)
      INTO intCount
      FROM SOLICITUD_ARCHIVOS A
     WHERE A.INT_IDSOLICITUD = p_intIdSolicitud
       AND A.VC_ESTADO = 'PR';

    IF intCount > 0 THEN
      SELECT COUNT(1)
        INTO intLargoFile2
        FROM SOLICITUD_REPLEG_TEXTO A
       WHERE A.INT_IDSOLICITUD = p_intIdSolicitud;
    END IF;

    IF intLargoFile2 > 0 THEN
      PKG_BASE.I_EXTRAER_ESTRUCTURA(intIdProducto, 'REPLEGA', stRepLega);
      BEGIN
        Start_time := DBMS_UTILITY.get_time;
        FOR CURSOR_SRLT IN (SELECT DISTINCT SRT.INT_IDSOLICITUD, SRT.INT_FILA, SRT.INT_IDSOLICITUD_DET,
                                   SRT.C01, SRT.C02, SRT.C03, SRT.C04, SRT.C05, SRT.C06,SRT.C07,SRT.C08, SDT.C02 AS C09, SDT.C01 AS C10,
                                   SRT.OBSERVACIONES
                              FROM SOLICITUD_REPLEG_TEXTO SRT
                              LEFT JOIN SOLICITUD_DETALLE_TEXTO SDT
                                ON (SDT.INT_IDSOLICITUD = SRT.INT_IDSOLICITUD AND SDT.C01 = 'RUC' AND SDT.C02 = SRT.C01)
                             WHERE SRT.INT_IDSOLICITUD = p_intIdSolicitud
                             ORDER BY SRT.INT_IDSOLICITUD, SRT.INT_FILA) LOOP
          vcErrores  := 'Errores , ' || vcEnter;
          intErrores := 0;

          REG_SRLT := CURSOR_SRLT;
          REG_SRL  := REG_SRL_NULL;

          REG_SRL.INT_IDSOLICITUD := REG_SRLT.INT_IDSOLICITUD;

          --Numero de documento
          BEGIN
            blValidacion := FALSE;
            IF TRIM(REG_SRLT.C09) IS NULL THEN
              intErrores := intErrores + 1;
              vcErrores  := vcErrores || ' en Campo 01 : ' || stRepLega(01).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C01) || ', > Archivo Representante Legal: No se encuentra el número de documento (PJ/RUC20) en la solicitud.' || vcEnter;
            ELSE
              IF SUBSTR(TRIM(REG_SRLT.C01), 1, 2) = '10' AND TRIM(REG_SRLT.C10) = 'RUC' AND TRIM(REG_SRLT.C03) <> SUBSTR(TRIM(REG_SRLT.C01), 3, 8) THEN
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 03 : ' || stRepLega(03).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C03) || ', > Archivo Representante Legal: El numero de DNI del representante legal no coincide con la persona del RUC' || vcEnter;
              END IF;
            END IF;
            IF blValidacion THEN
              REG_SRL.VC_NUMERO_DOCUMENTO := TRIM(REG_SRLT.C01);
            END IF;
          EXCEPTION
            WHEN OTHERS THEN
              intErrores := intErrores + 1;
              vcErrores  := vcErrores || 'en Campo 01 : ' || stRepLega(01).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C01) || ', > ' || SQLERRM || '.' || vcEnter;
          END;

          BEGIN
            blValidacion := FALSE;
            IF stRepLega(01).INT_REQUERIDO = 1 AND PKG_BASE.F_VALIDA_CONDICION(stRepLega(01).INT_IDCONDICION, 'RUC', TRIM(REG_SRLT.C01), intIdProducto) = 1 THEN
              IF TRIM(REG_SRLT.C01) IS NULL THEN
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 01 : ' || stRepLega(01).VC_DESCRIPCION || ', > Es obligatorio.' || vcEnter;
              ELSE
                IF PKG_BASE.F_NUMEROS(TRIM(REG_SRLT.C01)) = 1 AND LENGTH(TRIM(REG_SRLT.C01)) = 11 THEN
                  blValidacion := TRUE;
                ELSE
                  intErrores := intErrores + 1;
                  vcErrores  := vcErrores || 'en Campo 01 : ' || stRepLega(01).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C01) || ', > Deben ser RUC de 11 caracteres numericos positivos.' || vcEnter;
                END IF;
              END IF;
            ELSE
              IF ( PKG_BASE.F_NUMEROS(TRIM(REG_SRLT.C01)) = 1 AND LENGTH(TRIM(REG_SRLT.C01)) = 11 ) OR TRIM(REG_SRLT.C01) IS NULL THEN
                blValidacion := TRUE;
              ELSE
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 01 : ' || stRepLega(01).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C01) || ', > Deben ser RUC de 11 caracteres numericos positivos.' || vcEnter;
              END IF;
            END IF;
            IF blValidacion THEN
              REG_SRL.VC_NUMERO_DOCUMENTO := TRIM(REG_SRLT.C01);
            END IF;
          EXCEPTION
            WHEN OTHERS THEN
              intErrores := intErrores + 1;
              vcErrores  := vcErrores || 'en Campo 01 : ' || stRepLega(01).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C01) || ', > ' || SQLERRM || '.' || vcEnter;
          END;

          --Tipo de documento Representante Legal
          BEGIN
            blValidacion := FALSE;
            IF stRepLega(02).INT_REQUERIDO = 1 AND PKG_BASE.F_VALIDA_CONDICION(stRepLega(02).INT_IDCONDICION, 'RUC', TRIM(REG_SRLT.C01), intIdProducto) = 1 THEN
              IF TRIM(REG_SRLT.C02) IS NULL THEN
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 02 : ' || stRepLega(02).VC_DESCRIPCION || ', > Es obligatorio.' || vcEnter;
              ELSE
                IF LENGTH(TRIM(REG_SRLT.C02)) = 3 AND PKG_BASE.F_LETRAS(TRIM(REG_SRLT.C02)) = 1 THEN
                  IF TRIM(REG_SRLT.C02) IN ('DNI', 'CET') THEN
                    blValidacion := TRUE;
                  ELSE
                    intErrores := intErrores + 1;
                    vcErrores  := vcErrores || 'en Campo 02 : ' || stRepLega(02).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C02) || ', > Debe ser ''DNI'' o ''CET''.' || vcEnter;
                  END IF;
                ELSE
                  intErrores := intErrores + 1;
                  vcErrores  := vcErrores || 'en Campo 02 : ' || stRepLega(02).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C02) || ', > Debe ser ''DNI'' o ''CET''.' || vcEnter;
                END IF;
              END IF;
            ELSE
              IF (LENGTH(TRIM(REG_SRLT.C02)) = 3 AND PKG_BASE.F_LETRAS(TRIM(REG_SRLT.C02)) = 1) OR TRIM(REG_SRLT.C02) IS NULL THEN
                blValidacion := TRUE;
              ELSE
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 02 : ' || stRepLega(02).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C02) || ', > Debe ser ''DNI'' o ''CET''.' || vcEnter;
              END IF;
            END IF;
            IF blValidacion THEN
              REG_SRL.VC_TIPO_DOCUMENTO_REPLEG := TRIM(REG_SRLT.C02);
            END IF;
          EXCEPTION
            WHEN OTHERS THEN
              intErrores := intErrores + 1;
              vcErrores  := vcErrores || 'en Campo 02 : ' || stRepLega(02).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C02) || ', > ' || SQLERRM || '.' || vcEnter;
          END;

          --Numero de documento Representante Legal
          BEGIN
            blValidacion := FALSE;
            IF stRepLega(03).INT_REQUERIDO = 1 AND PKG_BASE.F_VALIDA_CONDICION(stRepLega(03).INT_IDCONDICION, 'RUC', TRIM(REG_SRLT.C01), intIdProducto) = 1 THEN
              IF TRIM(REG_SRLT.C03) IS NULL THEN
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 03 : ' || stRepLega(03).VC_DESCRIPCION || ', > Es obligatorio.' || vcEnter;
              ELSE
                IF (PKG_BASE.F_NUMEROS(TRIM(REG_SRLT.C03)) = 1 AND LENGTH(TRIM(REG_SRLT.C03)) >= 8) THEN
                  blValidacion := TRUE;
                ELSE
                  intErrores := intErrores + 1;
                  vcErrores  := vcErrores || 'en Campo 03 : ' || stRepLega(03).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C03) || ', > Deben ser caracteres numericos positivos.' || vcEnter;
                END IF;
              END IF;
            ELSE
              IF ((PKG_BASE.F_NUMEROS(TRIM(REG_SRLT.C03)) = 1 AND LENGTH(TRIM(REG_SRLT.C03)) >= 8)) OR TRIM(REG_SRLT.C03) IS NULL THEN
                blValidacion := TRUE;
              ELSE
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 03 : ' || stRepLega(03).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C03) || ', > Deben ser caracteres numericos positivos.' || vcEnter;
              END IF;
            END IF;
            IF blValidacion THEN
              REG_SRL.VC_NUMERO_DOCUMENTO_REPLEG := TRIM(REG_SRLT.C03);
            END IF;
          EXCEPTION
            WHEN OTHERS THEN
              intErrores := intErrores + 1;
              vcErrores  := vcErrores || 'en Campo 03 : ' || stRepLega(03).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C03) || ', > ' || SQLERRM || '.' || vcEnter;
          END;

          --Nombres del Representante Legal
          BEGIN
            blValidacion := FALSE;
            IF stRepLega(04).INT_REQUERIDO = 1 AND PKG_BASE.F_VALIDA_CONDICION(stRepLega(04).INT_IDCONDICION, 'RUC', TRIM(REG_SRLT.C01), intIdProducto) = 1 THEN
              IF TRIM(REG_SRLT.C04) IS NULL THEN
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 04 : ' || stRepLega(04).VC_DESCRIPCION || ', > Es obligatorio.' || vcEnter;
              ELSE
                IF LENGTH(TRIM(REG_SRLT.C04)) <= 80 THEN
                  blValidacion := TRUE;
                ELSE
                  intErrores := intErrores + 1;
                  vcErrores  := vcErrores || 'en Campo 04 : ' || stRepLega(04).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C04) || ', > Longitud excede de 80 caracteres.' || vcEnter;
                END IF;
              END IF;
            ELSE
              IF LENGTH(TRIM(REG_SRLT.C04)) <= 80 OR TRIM(REG_SRLT.C04) IS NULL THEN
                blValidacion := TRUE;
              ELSE
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 04 : ' || stRepLega(04).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C04) || ', > Longitud excede de 80 caracteres.' || vcEnter;
              END IF;
            END IF;
            IF blValidacion THEN
              REG_SRL.VC_NOMBRES_REPLEG := TRIM(REG_SRLT.C04);
            END IF;
          EXCEPTION
            WHEN OTHERS THEN
              intErrores := intErrores + 1;
              vcErrores  := vcErrores || 'en Campo 04 : ' || stRepLega(04).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C04) || ', > ' || SQLERRM || '.' || vcEnter;
          END;

          --Apellido Paterno Representante Legal
          BEGIN
            blValidacion := FALSE;
            IF stRepLega(05).INT_REQUERIDO = 1 AND PKG_BASE.F_VALIDA_CONDICION(stRepLega(05).INT_IDCONDICION, 'RUC', TRIM(REG_SRLT.C01), intIdProducto) = 1 THEN
              IF TRIM(REG_SRLT.C05) IS NULL THEN
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 05 : ' || stRepLega(05).VC_DESCRIPCION || ', > Es obligatorio.' || vcEnter;
              ELSE
                IF LENGTH(TRIM(REG_SRLT.C05)) <= 80 THEN
                  blValidacion := TRUE;
                ELSE
                  intErrores := intErrores + 1;
                  vcErrores  := vcErrores || 'en Campo 05 : ' || stRepLega(05).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C05) || ', > Longitud excede de 80 carcateres.' || vcEnter;
                END IF;
              END IF;
            ELSE
              IF LENGTH(TRIM(REG_SRLT.C05)) <= 80 OR TRIM(REG_SRLT.C05) IS NULL THEN
                blValidacion := TRUE;
              ELSE
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 05 : ' || stRepLega(05).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C05) || ', > Longitud excede de 80 carcateres.' || vcEnter;
              END IF;
            END IF;
            IF blValidacion THEN
              REG_SRL.VC_APELLIDOS_REPLEG := TRIM(REG_SRLT.C05);
            END IF;
          EXCEPTION
            WHEN OTHERS THEN
              intErrores := intErrores + 1;
              vcErrores  := vcErrores || 'en Campo 05 : ' || stRepLega(05).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C05) || ', > ' || SQLERRM || '.' || vcEnter;
          END;

          --Cargo Representante Legal
          BEGIN
            blValidacion := FALSE;
            IF stRepLega(06).INT_REQUERIDO = 1 AND PKG_BASE.F_VALIDA_CONDICION(stRepLega(06).INT_IDCONDICION, 'RUC', TRIM(REG_SRLT.C01), intIdProducto) = 1 THEN
              IF TRIM(REG_SRLT.C06) IS NULL THEN
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 06 : ' || stRepLega(06).VC_DESCRIPCION || ', > Es obligatorio.' || vcEnter;
              ELSE
                IF LENGTH(TRIM(REG_SRLT.C06)) IN (2, 3) AND PKG_BASE.F_LETRAS(TRIM(REG_SRLT.C06)) = 1 THEN
                  blValidacion := TRUE;
                ELSE
                  intErrores := intErrores + 1;
                  vcErrores  := vcErrores || 'en Campo 06 : ' || stRepLega(06).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C06) || ', > Cargo debe ser ''GE'',''JA'',''AN'',''ADM'',''TIT'',''OTR''.' || vcEnter;
                END IF;
              END IF;
            ELSE
              IF (LENGTH(TRIM(REG_SRLT.C06)) IN (2, 3) AND PKG_BASE.F_LETRAS(TRIM(REG_SRLT.C06)) = 1) OR TRIM(REG_SRLT.C06) IS NULL THEN
                blValidacion := TRUE;
              ELSE
                intErrores := intErrores + 1;
                vcErrores  := vcErrores || 'en Campo 06 : ' || stRepLega(06).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C06) || ', > Cargo debe ser ''GE'',''JA'',''AN'',''ADM'',''TIT'',''OTR''.' || vcEnter;
              END IF;
            END IF;
            IF blValidacion THEN
              REG_SRL.VC_CARGO_REPLEG := TRIM(REG_SRLT.C06);
            END IF;
          EXCEPTION
            WHEN OTHERS THEN
              intErrores := intErrores + 1;
              vcErrores  := vcErrores || 'en Campo 06 : ' || stRepLega(06).VC_DESCRIPCION || ', ' || TRIM(REG_SRLT.C06) || ', > ' || SQLERRM || '.' || vcEnter;
          END;

          PKG_PRODUCTO.I_PROCESAR_ESTRUCTURA_REPLEGAL(REG_SRL, REG_SRLT, intErrores, vcErrores);

          REG_SRL.VC_USUARIO_CREACION  := USER;
          REG_SRL.DT_FECHA_CREACION    := SYSDATE;
          REG_SRL.VC_TERMINAL_CREACION := UPPER(SYS_CONTEXT('USERENV', 'SERVER_HOST'));

          IF intErrores = 0 THEN
            REG_SRL.OBSERVACIONES := 'OK';
            UPDATE SOLICITUD_REPLEG_TEXTO SDT
               SET SDT.OBSERVACIONES = 'OK'
             WHERE SDT.INT_IDSOLICITUD = REG_SRLT.INT_IDSOLICITUD
               AND SDT.INT_FILA = REG_SRLT.INT_FILA;
          ELSE
            REG_SRL.OBSERVACIONES := vcErrores;
            UPDATE SOLICITUD_REPLEG_TEXTO SDT
               SET SDT.OBSERVACIONES = vcErrores
             WHERE SDT.INT_IDSOLICITUD = REG_SRLT.INT_IDSOLICITUD
               AND SDT.INT_FILA = REG_SRLT.INT_FILA;
          END IF;

          L_TAB_SR_VAL.EXTEND();
          L_TAB_SR_VAL(L_TAB_SR_VAL.LAST) := REG_SRL;

        END LOOP;

        end_time := DBMS_UTILITY.get_time;
        DBMS_OUTPUT.PUT_LINE('Bulk VALIDAR 2: ' || TO_CHAR(end_time - start_time));

        Start_time := DBMS_UTILITY.get_time;
        SELECT T.* BULK COLLECT INTO L_TAB_SR0
          FROM TABLE(L_TAB_SR_VAL) T
         WHERE OBSERVACIONES = 'OK';
        end_time := DBMS_UTILITY.get_time;
        DBMS_OUTPUT.PUT_LINE('Bulk select 2: ' || TO_CHAR(end_time - start_time));

        Start_time := DBMS_UTILITY.get_time;
        FORALL i in L_TAB_SR0.first .. L_TAB_SR0.last
          INSERT /*+APPEND*/ INTO SOLICITUD_REPLEG VALUES L_TAB_SR0(i);
        end_time := DBMS_UTILITY.get_time;
        DBMS_OUTPUT.PUT_LINE('Bulk Insert 2: ' || TO_CHAR(end_time - start_time));

        COMMIT;
      END;

    END IF;

  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      ROLLBACK;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_BASE', 'I_PROCESAR_ESTRUCTURA_REPLEGAL', vcErrorStack, vcErrorBacktace, 'INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
      RAISE_APPLICATION_ERROR(-20114, 'PKG_BASE.I_PROCESAR_ESTRUCTURA_REPLEGAL:'|| vcErrorStack||'; '||vcErrorBacktace||'; INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
  END I_PROCESAR_ESTRUCTURA_REPLEGAL;

PROCEDURE I_PROCESAR_RCC_TMP(p_intIdSolicitud IN SOLICITUD.INT_IDSOLICITUD%TYPE) AS
  PRAGMA AUTONOMOUS_TRANSACTION;
BEGIN
  DBMS_OUTPUT.put_line('Iniciando Procesamiento de I_PROCESAR_RCC_TMP : ' || TO_CHAR(p_intIdSolicitud) || ', FechaHora : ' || TRIM(TO_CHAR(SYSDATE, 'DD/MM/YYYY HH24:MI:SS')));

  DELETE FROM ETL_RCC_IDCLI_TMP T WHERE T.INT_IDSOLICITUD = p_intIdSolicitud;
  DELETE FROM ETL_RCC_MVCLI_TMP T WHERE T.INT_IDSOLICITUD = p_intIdSolicitud;
  DELETE FROM ETL_RCC_RSCLI_TMP T WHERE T.INT_IDSOLICITUD = p_intIdSolicitud;

  COMMIT;

  MERGE INTO ETL_RCC_IDCLI_TMP D
  USING (SELECT p_intIdSolicitud AS INT_IDSOLICITUD,
                R1.COD_DEU       AS COD_DEU,
                R1.TIP_DOC_TRIB,
                R1.COD_DOC_TRIB,
                R1.TIP_DOC_ID,
                R1.COD_DOC_ID,
                R1.TIP_PER,
                R1.TIP_EMP,
                R1.NOM_DEU,
                R1.APE_MAT,
                R1.APE_CAS,
                R1.PRI_NOM,
                R1.SEG_NOM,
                R1.APE_PAT
           FROM US_BASE.ETL_RCC_IDCLI R1
          INNER JOIN (SELECT DISTINCT SD.VC_NUMERO_DOCUMENTO AS NUMERO_DOCUMENTO
                       FROM SOLICITUD_DETALLE SD
                      WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
                        AND SD.VC_TIPO_DOCUMENTO IN ('DNI', 'RUC')
                     UNION ALL
                     SELECT DISTINCT PKG_BASE.F_CONVERTIR_DNI_A_RUC(SD.VC_NUMERO_DOCUMENTO) AS NUMERO_DOCUMENTO
                       FROM SOLICITUD_DETALLE SD
                      WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
                        AND SD.VC_TIPO_DOCUMENTO = 'DNI'
                     UNION ALL
                     SELECT DISTINCT SUBSTR(SD.VC_NUMERO_DOCUMENTO, 3, 8) AS NUMERO_DOCUMENTO
                       FROM SOLICITUD_DETALLE SD
                      WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
                        AND SD.VC_TIPO_DOCUMENTO = 'RUC'
                        AND SUBSTR(SD.VC_NUMERO_DOCUMENTO, 1, 2) = '10') DOC1
             ON (DOC1.NUMERO_DOCUMENTO = R1.COD_DOC_ID)
         UNION
         SELECT p_intIdSolicitud AS INT_IDSOLICITUD,
                R2.COD_DEU       AS COD_DEU,
                R2.TIP_DOC_TRIB,
                R2.COD_DOC_TRIB,
                R2.TIP_DOC_ID,
                R2.COD_DOC_ID,
                R2.TIP_PER,
                R2.TIP_EMP,
                R2.NOM_DEU,
                R2.APE_MAT,
                R2.APE_CAS,
                R2.PRI_NOM,
                R2.SEG_NOM,
                R2.APE_PAT
           FROM US_BASE.ETL_RCC_IDCLI R2
          INNER JOIN (SELECT DISTINCT SD.VC_NUMERO_DOCUMENTO AS NUMERO_DOCUMENTO
                       FROM SOLICITUD_DETALLE SD
                      WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
                        AND SD.VC_TIPO_DOCUMENTO IN ('DNI', 'RUC')
                     UNION ALL
                     SELECT DISTINCT PKG_BASE.F_CONVERTIR_DNI_A_RUC(SD.VC_NUMERO_DOCUMENTO) AS NUMERO_DOCUMENTO
                       FROM SOLICITUD_DETALLE SD
                      WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
                        AND SD.VC_TIPO_DOCUMENTO = 'DNI'
                     UNION ALL
                     SELECT DISTINCT SUBSTR(SD.VC_NUMERO_DOCUMENTO, 3, 8) AS NUMERO_DOCUMENTO
                       FROM SOLICITUD_DETALLE SD
                      WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
                        AND SD.VC_TIPO_DOCUMENTO = 'RUC'
                        AND SUBSTR(SD.VC_NUMERO_DOCUMENTO, 1, 2) = '10') DOC2
             ON (DOC2.NUMERO_DOCUMENTO = R2.COD_DOC_TRIB)) O
  ON (D.INT_IDSOLICITUD = O.INT_IDSOLICITUD AND D.COD_DEU = O.COD_DEU)
  WHEN NOT MATCHED THEN
    INSERT
      (INT_IDSOLICITUD,
       COD_DEU,
       TIP_DOC_TRIB,
       COD_DOC_TRIB,
       TIP_DOC_ID,
       COD_DOC_ID,
       TIP_PER,
       TIP_EMP,
       NOM_DEU,
       APE_MAT,
       APE_CAS,
       PRI_NOM,
       SEG_NOM,
       APE_PAT)
    VALUES
      (O.INT_IDSOLICITUD,
       O.COD_DEU,
       O.TIP_DOC_TRIB,
       O.COD_DOC_TRIB,
       O.TIP_DOC_ID,
       O.COD_DOC_ID,
       O.TIP_PER,
       O.TIP_EMP,
       O.NOM_DEU,
       O.APE_MAT,
       O.APE_CAS,
       O.PRI_NOM,
       O.SEG_NOM,
       O.APE_PAT)
  WHEN MATCHED THEN
    UPDATE
       SET D.TIP_DOC_TRIB = O.TIP_DOC_TRIB,
           D.COD_DOC_TRIB = O.COD_DOC_TRIB,
           D.TIP_DOC_ID   = O.TIP_DOC_ID,
           D.COD_DOC_ID   = O.COD_DOC_ID,
           D.TIP_PER      = O.TIP_PER,
           D.TIP_EMP      = O.TIP_EMP,
           D.NOM_DEU      = O.NOM_DEU,
           D.APE_MAT      = O.APE_MAT,
           D.APE_CAS      = O.APE_CAS,
           D.PRI_NOM      = O.PRI_NOM,
           D.SEG_NOM      = O.SEG_NOM,
           D.APE_PAT      = O.APE_PAT
     WHERE D.INT_IDSOLICITUD = O.INT_IDSOLICITUD
       AND D.COD_DEU = O.COD_DEU;

  DBMS_OUTPUT.put_line('Iniciando Procesamiento de I_PROCESAR_RCC_TMP : ' || TO_CHAR(p_intIdSolicitud) || ', Tabla : ETL_RCC_IDCLI_TMP, Filas Afectadas : ' || TRIM(TO_CHAR(SQL%ROWCOUNT)) || ' FechaHora : ' || TRIM(TO_CHAR(SYSDATE, 'DD/MM/YYYY HH24:MI:SS')));
  COMMIT;

  MERGE INTO ETL_RCC_MVCLI_TMP D
  USING (SELECT T.INT_IDSOLICITUD,
                R1.PERIODO,
                R1.COD_DEU,
                R1.CAN_ENTS,
                R1.CALIF_0,
                R1.CALIF_1,
                R1.CALIF_2,
                R1.CALIF_3,
                R1.CALIF_4
           FROM US_BASE.ETL_RCC_MVCLI R1
          INNER JOIN ETL_RCC_IDCLI_TMP T
             ON (T.INT_IDSOLICITUD = p_intIdSolicitud AND
                T.COD_DEU = R1.COD_DEU)
         UNION ALL
         SELECT p_intIdSolicitud AS INT_IDSOLICITUD,
                MAX(R1.PERIODO) AS PERIODO,
                '0000000000' AS COD_DEU,
                0 AS CAN_ENTS,
                0 AS CALIF_0,
                0 AS CALIF_1,
                0 AS CALIF_2,
                0 AS CALIF_3,
                0 AS CALIF_4
           FROM US_BASE.ETL_RCC_MVCLI R1) O
  ON (D.INT_IDSOLICITUD = O.INT_IDSOLICITUD AND D.COD_DEU = O.COD_DEU)
  WHEN NOT MATCHED THEN
    INSERT
      (INT_IDSOLICITUD,
       PERIODO,
       COD_DEU,
       CAN_ENTS,
       CALIF_0,
       CALIF_1,
       CALIF_2,
       CALIF_3,
       CALIF_4)
    VALUES
      (O.INT_IDSOLICITUD,
       O.PERIODO,
       O.COD_DEU,
       O.CAN_ENTS,
       O.CALIF_0,
       O.CALIF_1,
       O.CALIF_2,
       O.CALIF_3,
       O.CALIF_4)
  WHEN MATCHED THEN
    UPDATE
       SET D.CAN_ENTS = O.CAN_ENTS,
           D.CALIF_0  = O.CALIF_0,
           D.CALIF_1  = O.CALIF_1,
           D.CALIF_2  = O.CALIF_2,
           D.CALIF_3  = O.CALIF_3,
           D.CALIF_4  = O.CALIF_4
     WHERE D.INT_IDSOLICITUD = O.INT_IDSOLICITUD
       AND D.PERIODO = O.PERIODO
       AND D.COD_DEU = O.COD_DEU;

  DBMS_OUTPUT.put_line('Iniciando Procesamiento de I_PROCESAR_RCC_TMP : ' || TO_CHAR(p_intIdSolicitud) || ', Tabla : ETL_RCC_MVCLI_TMP, Filas Afectadas : ' || TRIM(TO_CHAR(SQL%ROWCOUNT)) || ' FechaHora : ' || TRIM(TO_CHAR(SYSDATE, 'DD/MM/YYYY HH24:MI:SS')));
  COMMIT;

  MERGE INTO ETL_RCC_RSCLI_TMP D
  USING (SELECT T.INT_IDSOLICITUD,
                R.PERIODO,
                R.COD_DEU,
                R.COD_EMP,
                R.CALIFICACION,
                R.SALDO_01,
                R.SALDO_11,
                R.SALDO_02,
                R.SALDO_21,
                R.SALDO_22,
                R.SALDO_23,
                R.SALDO_24,
                R.SALDO_25,
                R.SALDO_12,
                R.SALDO_03,
                R.SALDO_13,
                R.SALDO_04,
                R.SALDO_14,
                R.SALDO_05,
                R.SALDO_15,
                R.SALDO_08,
                R.SALDO_09,
                R.SALDO_10,
                R.SALDO_20,
                R.SALDO_26,
                R.SALDO_27,
                R.SALDO_28,
                R.SALDO_29,
                R.SALDO_30,
                R.SALDO_31,
                R.SALDO_32,
                R.SALDO_33,
                R.SALDO_34,
                R.SALDO_35,
                R.SALDO_36,
                R.SALDO_37,
                R.SALDO_38,
                R.SALDO_71,
                R.SALDO_72
           FROM US_BASE.ETL_RCC_RSCLI R
          INNER JOIN ETL_RCC_MVCLI_TMP T
             ON (T.INT_IDSOLICITUD = p_intIdSolicitud AND T.PERIODO = R.PERIODO AND T.COD_DEU = R.COD_DEU)) O
  ON (D.INT_IDSOLICITUD = O.INT_IDSOLICITUD AND D.PERIODO = O.PERIODO AND D.COD_DEU = O.COD_DEU AND D.COD_EMP = O.COD_EMP)
  WHEN NOT MATCHED THEN
    INSERT
      (INT_IDSOLICITUD,
       PERIODO,
       COD_DEU,
       COD_EMP,
       CALIFICACION,
       SALDO_01,
       SALDO_11,
       SALDO_02,
       SALDO_21,
       SALDO_22,
       SALDO_23,
       SALDO_24,
       SALDO_25,
       SALDO_12,
       SALDO_03,
       SALDO_13,
       SALDO_04,
       SALDO_14,
       SALDO_05,
       SALDO_15,
       SALDO_08,
       SALDO_09,
       SALDO_10,
       SALDO_20,
       SALDO_26,
       SALDO_27,
       SALDO_28,
       SALDO_29,
       SALDO_30,
       SALDO_31,
       SALDO_32,
       SALDO_33,
       SALDO_34,
       SALDO_35,
       SALDO_36,
       SALDO_37,
       SALDO_38,
       SALDO_71,
       SALDO_72)
    VALUES
      (O.INT_IDSOLICITUD,
       O.PERIODO,
       O.COD_DEU,
       O.COD_EMP,
       O.CALIFICACION,
       O.SALDO_01,
       O.SALDO_11,
       O.SALDO_02,
       O.SALDO_21,
       O.SALDO_22,
       O.SALDO_23,
       O.SALDO_24,
       O.SALDO_25,
       O.SALDO_12,
       O.SALDO_03,
       O.SALDO_13,
       O.SALDO_04,
       O.SALDO_14,
       O.SALDO_05,
       O.SALDO_15,
       O.SALDO_08,
       O.SALDO_09,
       O.SALDO_10,
       O.SALDO_20,
       O.SALDO_26,
       O.SALDO_27,
       O.SALDO_28,
       O.SALDO_29,
       O.SALDO_30,
       O.SALDO_31,
       O.SALDO_32,
       O.SALDO_33,
       O.SALDO_34,
       O.SALDO_35,
       O.SALDO_36,
       O.SALDO_37,
       O.SALDO_38,
       O.SALDO_71,
       O.SALDO_72)
  WHEN MATCHED THEN
    UPDATE
       SET D.CALIFICACION = O.CALIFICACION,
           D.SALDO_01     = O.SALDO_01,
           D.SALDO_11     = O.SALDO_11,
           D.SALDO_02     = O.SALDO_02,
           D.SALDO_21     = O.SALDO_21,
           D.SALDO_22     = O.SALDO_22,
           D.SALDO_23     = O.SALDO_23,
           D.SALDO_24     = O.SALDO_24,
           D.SALDO_25     = O.SALDO_25,
           D.SALDO_12     = O.SALDO_12,
           D.SALDO_03     = O.SALDO_03,
           D.SALDO_13     = O.SALDO_13,
           D.SALDO_04     = O.SALDO_04,
           D.SALDO_14     = O.SALDO_14,
           D.SALDO_05     = O.SALDO_05,
           D.SALDO_15     = O.SALDO_15,
           D.SALDO_08     = O.SALDO_08,
           D.SALDO_09     = O.SALDO_09,
           D.SALDO_10     = O.SALDO_10,
           D.SALDO_20     = O.SALDO_20,
           D.SALDO_26     = O.SALDO_26,
           D.SALDO_27     = O.SALDO_27,
           D.SALDO_28     = O.SALDO_28,
           D.SALDO_29     = O.SALDO_29,
           D.SALDO_30     = O.SALDO_30,
           D.SALDO_31     = O.SALDO_31,
           D.SALDO_32     = O.SALDO_32,
           D.SALDO_33     = O.SALDO_33,
           D.SALDO_34     = O.SALDO_34,
           D.SALDO_35     = O.SALDO_35,
           D.SALDO_36     = O.SALDO_36,
           D.SALDO_37     = O.SALDO_37,
           D.SALDO_38     = O.SALDO_38,
           D.SALDO_71     = O.SALDO_71,
           D.SALDO_72     = O.SALDO_72
     WHERE D.INT_IDSOLICITUD = O.INT_IDSOLICITUD
       AND D.PERIODO = O.PERIODO
       AND D.COD_DEU = O.COD_DEU
       AND D.COD_EMP = O.COD_EMP;

  DBMS_OUTPUT.put_line('Iniciando Procesamiento de I_PROCESAR_RCC_TMP : ' || TO_CHAR(p_intIdSolicitud) || ', Tabla : ETL_RCC_RSCLI_TMP, Filas Afectadas : ' || TRIM(TO_CHAR(SQL%ROWCOUNT)) || ' FechaHora : ' || TRIM(TO_CHAR(SYSDATE, 'DD/MM/YYYY HH24:MI:SS')));
  COMMIT;

  DBMS_OUTPUT.put_line('Finalizando Procesamiento de I_PROCESAR_RCC_TMP : ' || TO_CHAR(p_intIdSolicitud) || ', FechaHora : ' || TRIM(TO_CHAR(SYSDATE, 'DD/MM/YYYY HH24:MI:SS')));
EXCEPTION
  WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      ROLLBACK;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_BASE', 'I_PROCESAR_RCC_TMP', vcErrorStack, vcErrorBacktace, 'INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
      RAISE_APPLICATION_ERROR(-20114, 'PKG_BASE.I_PROCESAR_RCC_TMP:' || vcErrorStack || '; ' || vcErrorBacktace ||  '; INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
END I_PROCESAR_RCC_TMP;

  PROCEDURE I_PROCESAR_REGLAS(p_intIdSolicitud IN SOLICITUD.INT_IDSOLICITUD%TYPE) AS
    PRAGMA AUTONOMOUS_TRANSACTION;
    intCount                NUMBER;
    intCountDocConver       NUMBER;
    intCountDoc1            NUMBER;
    intCountDocConver1      NUMBER;
    intCountDoc2            NUMBER;
    intCountDocConver2      NUMBER;
    intTodos                NUMBER;
    intMatrizCob            NUMBER;
    intAgrupAcumulado       NUMBER;
    intAgrupTipoDoc         NUMBER;
    intMontoAgrupAcumulado  NUMBER;
    intMontoAgrupTipoDoc    NUMBER;
    intMontoMax             NUMBER;
    intPorcenCoberturado    NUMBER;
    intPorcenCoberturadoAct NUMBER;
    intMontoCoberurado      NUMBER;
    intMontoCoberuradoAcum  NUMBER;
    intMontoAsignado        NUMBER;
    intTasa1                NUMBER;
    intTasa2                NUMBER;
    intTasa3                NUMBER;
    intValorTasa1           NUMBER;
    intValorTasa2           NUMBER;
    intValorTasa3           NUMBER;
    intTasaAsignada         NUMBER;
    intIdSubasta            NUMBER;
    intIdSubastaDetalle     NUMBER;
    intTCEAPromedio         NUMBER;
    intFechaLimite          NUMBER;
    intTipoLimite           NUMBER;
    intTamanioEmpresa       NUMBER;
    intIntegracionRCC       NUMBER;
    intConversionTipoDoc    NUMBER;
    vcTipDocConvertido      SOLICITUD_DETALLE.VC_TIPO_DOCUMENTO%TYPE;
    vcDocConvertido         SOLICITUD_DETALLE.VC_NUMERO_DOCUMENTO%TYPE;
    intMontoPrestamo        SOLICITUD_DETALLE.DEC_MONTO_PRESTAMO%TYPE;
    intMontoPrestamoRegi    SOLICITUD_DETALLE.DEC_MONTO_PRESTAMO%TYPE;
    intMontoPrestamoAcum    SOLICITUD_DETALLE.DEC_MONTO_PRESTAMO%TYPE;
    intMontoPrestamoCobert  SOLICITUD_DETALLE.DEC_MONTO_PRESTAMO%TYPE;
    intMontoPrestamoFinal   SOLICITUD_DETALLE.DEC_MONTO_PRESTAMO%TYPE;
    vcDocRUC                VARCHAR2(4000);
    vcDocDNI                VARCHAR2(4000);
    vcErrores               VARCHAR2(32000);
    vcErroresRL             VARCHAR2(4000);
    vcAuxiliar              VARCHAR2(4000);
    intErrores              NUMBER;
    intErroresRL            NUMBER;
    stSolBene               PKG_BASE.T_TAB_ESTRUCTURA;
    stSolRepL               PKG_BASE.T_TAB_ESTRUCTURA;
    stSolCred               PKG_BASE.T_TAB_ESTRUCTURA;
    stRepLega               PKG_BASE.T_TAB_ESTRUCTURA;
    blValidacion            Boolean;
    blElegibilidad          Boolean;
    recBRP                  US_BASE.BASE_REGLA_PRODUCTO%ROWTYPE;
    intIdProducto           SOLICITUD.INT_IDPRODUCTO%TYPE;
    vcCodigo_IFI            PRODUCTO_IFI.VC_CODIGOIFI%TYPE;
    intIdIFI                SOLICITUD.INT_IDIFI%TYPE;
    dtFechaSolicitud        SOLICITUD.DT_FECHA%TYPE;
    dtFechaLimiteSubasta    SOLICITUD.DT_FECHA%TYPE;
    dtFechaSubastaCalculada SOLICITUD.DT_FECHA%TYPE;
    dtFechaVencimiCalculada SOLICITUD.DT_FECHA%TYPE;
    intCIPCPrograma         NUMBER;
    intCIPCVariacion        NUMBER;
    intMMECalculada1        NUMBER;
    intMME                  NUMBER;
    vcCodDeu                VARCHAR2(4000);
    vcCodDeuDoc             VARCHAR2(100);
    vcCodDeuDocConVer       VARCHAR2(100);
    intPeriodoMax           NUMBER;
    intValTamEmp            NUMBER;
    intIndicador            NUMBER;
    intClaPeriodo           NUMBER(10);
    vcClaCodDeu             VARCHAR2(100);
    intClaCanEnts           NUMBER(10);
    intClaCalif0            NUMBER(10);
    intClaCalif1            NUMBER(10);
    intClaCalif2            NUMBER(10);
    intClaCalif3            NUMBER(10);
    intClaCalif4            NUMBER(10);
    intClaCalifTotal        NUMBER;
    intClaTipo              NUMBER;
    intClasificadorTipo     NUMBER;
    blClasificadorHisto     BOOLEAN;
    blClasificadorValido    BOOLEAN;
    intContadorTipo1        NUMBER;
    intContadorTipo2        NUMBER;
    intContadorTipo3        NUMBER;
    IntCountPeriodo         NUMBER;
    intDeudor               NUMBER;
    intIdEstado             NUMBER;
    vcCodEstado             US_BASE.BASE_TABLA_DETALLE.VC_CODTABLA_DETALLE%TYPE;
    intRechaEstru           NUMBER;
    intRechaRegla           NUMBER;
    intRechazado            NUMBER;
    intAprobado             NUMBER;
    intValColateral         NUMBER;
    intValCodDeudor         NUMBER;
    REG_SD                  SOLICITUD_DETALLE%ROWTYPE;
    intVersionCiiu          NUMBER;
    decTotalMontoPrestamo       NUMBER(20,2);
    decTotalMontoCoberturado    NUMBER(20,2);
  BEGIN

    PKG_BASE.I_PROCESAR_RCC_TMP(p_intIdSolicitud);

    UPDATE SOLICITUD_RESULTADOS A
       SET A.VC_ESTADO                = 'PROC_REGLAS_INI',
           A.VC_USUARIO_MODIFICACION  = USER,
           A.DT_FECHA_MODIFICACION    = SYSDATE,
           A.VC_TERMINAL_MODIFICACION = SYS_CONTEXT('USERENV', 'IP_ADDRESS')
     WHERE A.INT_IDSOLICITUD = p_intIdSolicitud
       AND A.VC_ESTADO = 'PROCESAR_STRUC';
    COMMIT;

    intIdProducto := 0;

    SELECT S.INT_IDPRODUCTO, S.INT_IDIFI, S.DT_FECHA
      INTO intIdProducto, intIdIFI, dtFechaSolicitud
      FROM SOLICITUD S
     WHERE S.INT_IDSOLICITUD = p_intIdSolicitud;

    SELECT COUNT(1)
      INTO intCount
      FROM PRODUCTO_IFI P
     WHERE P.INT_IDIFI = intIdIFI;

    IF intCount > 0 THEN
      SELECT P.VC_CODIGOIFI
        INTO vcCodigo_IFI
        FROM PRODUCTO_IFI P
       WHERE P.INT_IDIFI = intIdIFI;
    END IF;


    SELECT COUNT(1)
      INTO intCount
      FROM US_BASE.BASE_REGLA_PRODUCTO B
     WHERE B.INT_IDPROD = intIdProducto;

    IF intCount > 0 THEN
      SELECT BRP.*
        INTO recBRP
        FROM US_BASE.BASE_REGLA_PRODUCTO BRP
       WHERE BRP.INT_IDPROD = intIdProducto;
    END IF;

    PKG_BASE.I_EXTRAER_ESTRUCTURA(intIdProducto, 'SOLBENE', stSolBene);
    PKG_BASE.I_EXTRAER_ESTRUCTURA(intIdProducto, 'SOLCRED', stSolCred);
    PKG_BASE.I_EXTRAER_ESTRUCTURA(intIdProducto, 'SOLREPL', stSolRepL);
    PKG_BASE.I_EXTRAER_ESTRUCTURA(intIdProducto, 'REPLEGA', stRepLega);

    PKG_PRODUCTO.I_PROCESAR_REGLAS_INICIAL(p_intIdSolicitud);


    FOR CURSOR_SD IN (SELECT SD.*
                        FROM SOLICITUD_DETALLE SD
                       WHERE INT_IDSOLICITUD = p_intIdSolicitud
                       ORDER BY INT_IDSOLICITUD_DET ASC) LOOP
      REG_SD          := CURSOR_SD;
      intErrores      := 0;
      vcErrores       := 'Errores : ' || vcEnter;
      IntCountPeriodo := 0;

      --Monto de Préstamo
      ----------------------------------------------------------------------------------------------------
      intMontoPrestamo       := 0;
      intMontoAgrupAcumulado := 0;
      intMontoAgrupTipoDoc   := 0;
      intMontoMax            := 0;
      intValTamEmp           := 0;
      intValColateral        := 0;

      SELECT COUNT(1)
        INTO intCount
        FROM US_BASE.V_BASE_PRODUCTO_CONFIG_MONTO_PRESTAMO_DATOS BPC
       WHERE BPC.INT_IDPRODUCTO = intIdProducto;


      IF intCount > 0 THEN
        SELECT BPC.CH_AGRUP_ACUMULADO,
               BPC.CH_AGRUP_TIPODOC,
               BPC.DEC_MONTO_MAX
          INTO intMontoAgrupAcumulado, intMontoAgrupTipoDoc, intMontoMax
          FROM US_BASE.V_BASE_PRODUCTO_CONFIG_MONTO_PRESTAMO_DATOS BPC
         WHERE BPC.INT_IDPRODUCTO = intIdProducto;

        IF intMontoAgrupTipoDoc = 1 THEN
          --Documento_Conversión = Obtener su tipo de documento de conversión (número de documento)
          IF REG_SD.VC_TIPO_DOCUMENTO = 'DNI' THEN
            vcTipDocConvertido := 'RUC';
            vcDocConvertido    := PKG_BASE.F_CONVERTIR_DNI_A_RUC(REG_SD.VC_NUMERO_DOCUMENTO);
          ELSIF REG_SD.VC_TIPO_DOCUMENTO = 'RUC' AND SUBSTR(REG_SD.VC_NUMERO_DOCUMENTO,1,2)='10'  THEN
            vcTipDocConvertido := 'DNI';
            vcDocConvertido := PKG_BASE.F_CONVERTIR_RUC_A_DNI(REG_SD.VC_NUMERO_DOCUMENTO);
          ELSE
            vcTipDocConvertido := REG_SD.VC_TIPO_DOCUMENTO;
            vcDocConvertido := REG_SD.VC_NUMERO_DOCUMENTO;
          END IF;

          IF intMontoAgrupAcumulado = 1 THEN
            --Monto_Prestamo= Obtener Monto_Prestamo (número de documento, Documento_Conversión)
            SELECT NVL(SUM(NVL(SD.DEC_MONTO_PRESTAMO, 0)), 0)
              INTO intMontoPrestamo
              FROM SOLICITUD_DETALLE SD
             WHERE (
                    (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO) OR
                    (SD.VC_TIPO_DOCUMENTO = vcTipDocConvertido AND SD.VC_NUMERO_DOCUMENTO = vcDocConvertido)
                    )
               AND SD.VC_ESTADO IN
                           (SELECT TABDET.VC_ADICIONAL1
                            FROM US_BASE.BASE_TABLA TAB
                            INNER JOIN US_BASE.BASE_TABLA_DETALLE TABDET ON TAB.INT_IDTABLA = TABDET.INT_IDTABLA
                            WHERE VC_CODTABLA = 'ESTSOLDETFIDEM'
                            AND TABDET.VC_ADICIONAL2 IN (SELECT T.ESTADO_CREDITO
                                                      FROM US_BASE.V_BASE_PRODUCTO_CONFIG_MONTO_PRESTAMO_ESTADO_CREDITO T
                                                     WHERE T.INT_IDPRODUCTO = intIdProducto))
               AND SD.INT_IDSOLICITUD <> p_intIdSolicitud;
            intMontoPrestamo := NVL(intMontoPrestamo,0) + NVL(REG_SD.DEC_MONTO_PRESTAMO,0);
          ELSE
            --Monto_Prestamo = Monto_Prestamo_Solicitud
            intMontoPrestamo := NVL(REG_SD.DEC_MONTO_PRESTAMO, 0);
          END IF;
        ELSE
          IF intMontoAgrupAcumulado = 1 THEN
            --Monto_Prestamo= Obtener Monto_Prestamo (numero de documento)
            SELECT NVL(SUM(NVL(SD.DEC_MONTO_PRESTAMO, 0)), 0)
              INTO intMontoPrestamo
              FROM SOLICITUD_DETALLE SD
             WHERE (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO)
               AND SD.VC_ESTADO IN
                           (SELECT TABDET.VC_ADICIONAL1
                            FROM US_BASE.BASE_TABLA TAB
                            INNER JOIN US_BASE.BASE_TABLA_DETALLE TABDET ON TAB.INT_IDTABLA = TABDET.INT_IDTABLA
                            WHERE VC_CODTABLA = 'ESTSOLDETFIDEM'
                            AND TABDET.VC_ADICIONAL2 IN (SELECT T.ESTADO_CREDITO
                                                      FROM US_BASE.V_BASE_PRODUCTO_CONFIG_MONTO_PRESTAMO_ESTADO_CREDITO T
                                                     WHERE T.INT_IDPRODUCTO = intIdProducto))
               AND SD.INT_IDSOLICITUD <> p_intIdSolicitud;
            intMontoPrestamo := NVL(intMontoPrestamo,0) + NVL(REG_SD.DEC_MONTO_PRESTAMO,0);
          ELSE
            --Monto_Prestamo = Monto_Prestamo_Solicitud
            intMontoPrestamo := NVL(REG_SD.DEC_MONTO_PRESTAMO, 0);
          END IF;
        END IF;
        IF intMontoPrestamo > intMontoMax THEN
          intErrores := intErrores + 1;
          vcErrores  := vcErrores || 'en Campo 18 : ' || stSolCred(02).VC_DESCRIPCION || ', > El Monto del préstamo ' || TRIM(TO_CHAR(intMontoPrestamo, '999,999,999,990.00')) || ' se encuentra fuera del permitido.' || vcEnter;
        END IF;
      END IF;

      ----------------------------------------------------------------------------------------------------
      -- Moneda
      SELECT COUNT(1)
        INTO intCount
        FROM US_BASE.V_BASE_PRODUCTO_CONFIG_MONEDA M
       WHERE SUBSTR(M.VC_MONEDA, 1, 3) = 'OTR'
         AND M.INT_IDPRODUCTO = intIdProducto;

      IF intCount = 0 THEN
        SELECT COUNT(1)
          INTO intCount
          FROM US_BASE.V_BASE_PRODUCTO_CONFIG_MONEDA M
         WHERE SUBSTR(M.VC_MONEDA, 1, 3) = REG_SD.VC_MONEDA
           AND M.INT_IDPRODUCTO = intIdProducto;

        IF intCount = 0 THEN
          SELECT LISTAGG('''' || M.VC_MONEDA || '''', ',')
            INTO vcAuxiliar
            FROM US_BASE.V_BASE_PRODUCTO_CONFIG_MONEDA M
           WHERE M.INT_IDPRODUCTO = intIdProducto;
          intErrores := intErrores + 1;
          vcErrores  := vcErrores || 'en Campo 17 : ' || stSolCred(01).VC_DESCRIPCION || ', ' || TRIM(REG_SD.VC_MONEDA) || ', > La moneda no es válida en la operación, debe ser ' || vcAuxiliar || '.' || vcEnter;
        END IF;
      END IF;

      PKG_PRODUCTO.I_PROCESAR_REGLAS_PRE_ELEGIBILIDAD(REG_SD, intErrores, vcErrores);
      ----------------------------------------------------------------------------------------------------
      --Elegibilidad
      ----------------------------------------------------------------------------------------------------
      blElegibilidad := TRUE;

      --Tamaño de empresa
      SELECT COUNT(1)
        INTO intCount
        FROM US_BASE.V_BASE_PRODUCTO_CONFIG_EMPRESA M
       WHERE M.INT_IDPRODUCTO = intIdProducto;

      IF intCount > 0 THEN
        SELECT M.TAMANIO_EMP, M.INTEGRACION_RCC, M.CONVERSION_TIPODOC
          INTO intTamanioEmpresa, intIntegracionRCC, intConversionTipoDoc
          FROM US_BASE.V_BASE_PRODUCTO_CONFIG_EMPRESA M
         WHERE M.INT_IDPRODUCTO = intIdProducto
           AND ROWNUM <= 1;

        SELECT COUNT(1)
          INTO intCount
          FROM US_BASE.V_BASE_PRODUCTO_CONFIG_EMPRESA M
         WHERE M.VC_TAMANO_EMPRESA = REG_SD.VC_TAMANO_EMPRESA
           AND M.INT_IDPRODUCTO = intIdProducto;

        IF intCount = 0 THEN
          SELECT LISTAGG('''' || M.VC_TAMANO_EMPRESA || '''', ',')
            INTO vcAuxiliar
            FROM US_BASE.V_BASE_PRODUCTO_CONFIG_EMPRESA M
           WHERE M.INT_IDPRODUCTO = intIdProducto;
          intErrores := intErrores + 1;
          IF intTamanioEmpresa = 1 THEN
            blElegibilidad := FALSE;
            vcErrores  := vcErrores || 'en Campo 16 : ' || stSolBene(11).VC_DESCRIPCION || ', ' || TRIM(REG_SD.VC_TAMANO_EMPRESA) || ', > El tamaño de empresa (PRODUCE) del beneficiario no cumple los requisitos, debe ser ' ||  vcAuxiliar || '.' || vcEnter;
          ELSE
            blElegibilidad := FALSE;
            vcErrores      := vcErrores || 'en Campo 16 : ' || stSolBene(11).VC_DESCRIPCION || ', ' || TRIM(REG_SD.VC_TAMANO_EMPRESA) || ', > El tamaño de empresa (SBS) del beneficiario no cumple los requisitos, debe ser ' || vcAuxiliar || '.' || vcEnter;
          END IF;
        END IF;

        IF intIntegracionRCC = 1 and intTamanioEmpresa = 2 THEN
          IF intConversionTipoDoc = 1 THEN
            IF REG_SD.VC_TIPO_DOCUMENTO = 'DNI' THEN
              vcTipDocConvertido := 'RUC';
              vcDocConvertido    := PKG_BASE.F_CONVERTIR_DNI_A_RUC(REG_SD.VC_NUMERO_DOCUMENTO);
            ELSIF REG_SD.VC_TIPO_DOCUMENTO = 'RUC' AND SUBSTR(REG_SD.VC_NUMERO_DOCUMENTO,1,2)='10'  THEN
              vcTipDocConvertido := 'DNI';
              vcDocConvertido    := PKG_BASE.F_CONVERTIR_RUC_A_DNI(REG_SD.VC_NUMERO_DOCUMENTO);
            ELSE
              vcTipDocConvertido := REG_SD.VC_TIPO_DOCUMENTO;
              vcDocConvertido    := REG_SD.VC_NUMERO_DOCUMENTO;
            END IF;
          ELSE
            vcTipDocConvertido := NULL;
            vcDocConvertido := NULL;
          END IF;

          intCount     := 0;
          intCountDoc1 := 0;
          intCountDoc2 := 0;
          SELECT COUNT(DISTINCT T.COD_DEU)
            INTO intCountDoc1
            FROM ETL_RCC_IDCLI_TMP T
           WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
             AND T.COD_DOC_ID = REG_SD.VC_NUMERO_DOCUMENTO;

          IF intCountDoc1 = 0 THEN
            SELECT COUNT(DISTINCT T.COD_DEU)
              INTO intCountDoc2
              FROM ETL_RCC_IDCLI_TMP T
             WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
               AND T.COD_DOC_TRIB = REG_SD.VC_NUMERO_DOCUMENTO;
             intCount := intCountDoc2;
          ELSE
             intCount := intCountDoc1;
          END IF;

          intCountDocConver  := 0;
          intCountDocConver1 := 0;
          intCountDocConver2 := 0;
          IF intConversionTipoDoc = 1 THEN
            IF LENGTH(vcDocConvertido) >= 8 THEN
              SELECT COUNT(DISTINCT T.COD_DEU)
                INTO intCountDocConver1
                FROM ETL_RCC_IDCLI_TMP T
               WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                 AND T.COD_DOC_ID = vcDocConvertido;

              IF intCountDocConver1 = 0 THEN
                SELECT COUNT(DISTINCT T.COD_DEU)
                  INTO intCountDocConver2
                  FROM ETL_RCC_IDCLI_TMP T
                 WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                   AND T.COD_DOC_TRIB = vcDocConvertido;
                 intCountDocConver := intCountDocConver2;
              ELSE
                 intCountDocConver := intCountDocConver1;
              END IF;
            END IF;
          END IF;

          IF intCount > 1 OR intCountDocConver > 1 THEN
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores || 'Se ha identificado un registro inconsistente en la SBS - Regla: Tamaño de empresa' || vcEnter;
          ELSE
            IF intCount > 0 OR intCountDocConver > 0 THEN

              IF intCount > 0 THEN
                vcCodDeuDoc := ' ';
                IF intCountDoc1 = 1 THEN
                  SELECT T.COD_DEU
                    INTO vcCodDeuDoc
                    FROM ETL_RCC_IDCLI_TMP T
                   WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                     AND T.COD_DOC_ID = REG_SD.VC_NUMERO_DOCUMENTO;
                ELSE
                  SELECT T.COD_DEU
                    INTO vcCodDeuDoc
                    FROM ETL_RCC_IDCLI_TMP T
                   WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                     AND T.COD_DOC_TRIB = REG_SD.VC_NUMERO_DOCUMENTO;
                END IF;
              ELSE
                vcCodDeuDoc := NULL;
              END IF;

              IF intCountDocConver > 0 THEN
                vcCodDeuDocConVer := ' ';
                IF intCountDocConver1 = 1 THEN
                  SELECT T.COD_DEU
                    INTO vcCodDeuDocConVer
                    FROM ETL_RCC_IDCLI_TMP T
                   WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                     AND T.COD_DOC_ID = vcDocConvertido;
                ELSE
                  SELECT T.COD_DEU
                    INTO vcCodDeuDocConVer
                    FROM ETL_RCC_IDCLI_TMP T
                   WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                     AND T.COD_DOC_TRIB = vcDocConvertido;
                END IF;
              ELSE
                vcCodDeuDocConVer := NULL;
              END IF;

              IF vcCodDeuDoc = vcCodDeuDocConVer THEN
                vcCodDeuDocConVer := ' ';
              END IF;

              intValCodDeudor := 0 ;
              FOR REC_DEU IN (SELECT DISTINCT T.COD_DEU AS COD_DEU, DECODE(T.COD_DEU, vcCodDeuDoc, 1, vcCodDeuDocConVer, 2, 3)
                                FROM ETL_RCC_IDCLI_TMP T
                               WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                                 AND T.COD_DEU IN (vcCodDeuDoc, vcCodDeuDocConVer)
                               ORDER BY DECODE(T.COD_DEU, vcCodDeuDoc, 1, vcCodDeuDocConVer, 2, 3) ) LOOP

                SELECT COUNT(1)
                  INTO intCount
                  FROM ETL_RCC_IDCLI_TMP T
                 WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                   AND T.COD_DEU = REC_DEU.COD_DEU;

                vcCodDeu := ' ';
                IF intCount > 0 THEN
                  SELECT NVL(TRIM(T.COD_DOC_ID), TRIM(T.COD_DOC_TRIB))
                    INTO vcCodDeu
                    FROM ETL_RCC_IDCLI_TMP T
                   WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                     AND T.COD_DEU = REC_DEU.COD_DEU
                     AND ROWNUM <=1;


                END IF;

                SELECT COUNT(1)
                  INTO intCount
                  FROM ETL_RCC_MVCLI_TMP T
                 WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                   AND T.COD_DEU = REC_DEU.COD_DEU;

                IF intCount > 0 THEN
                  SELECT MAX(T.PERIODO)
                    INTO intPeriodoMax
                    FROM ETL_RCC_RSCLI_TMP T
                    WHERE T.INT_IDSOLICITUD = p_intIdSolicitud;

                  SELECT SUM(M.INDICADOR)
                    INTO intIndicador
                    FROM US_BASE.V_BASE_PRODUCTO_CONFIG_EMPRESA M
                   WHERE M.INT_IDPRODUCTO = intIdProducto;

                  IntCountPeriodo := 0;
                  intValTamEmp    := 0;
                  vcAuxiliar      := '';
                  IF intValCodDeudor = 0 THEN
                    FOR REC_RCC IN (SELECT D.PERIODO, --: AÑO Y MES DE LA CALIFICACIÓN
                                           T.COD_DEU, --: CÓDIGO DEL DEUDOR, PARA UBICAR AL CLIENTE EVALUADO
                                           vcCodDeu AS COD_DOC_ID,
                                           SUM(NVL(SALDO_33, 0)) AS SUM_SALDO_33, --: DEUDA CORPORATIVO
                                           SUM(NVL(SALDO_34, 0)) AS SUM_SALDO_34, --: DEUDA GRAN EMPRESA
                                           SUM(NVL(SALDO_35, 0)) AS SUM_SALDO_35, --: DEUDA MEDIANA EMPRESA
                                           SUM(NVL(SALDO_36, 0)) AS SUM_SALDO_36, --: DEUDA PEQUENA EMPRESA,
                                           SUM(NVL(SALDO_28, 0)) AS SUM_SALDO_28, --: DEUDA MICROEMPRESA
                                           SUM(NVL(SALDO_31, 0)) AS SUM_SALDO_31, --: DEUDA CONSUMO REVOLVENTE
                                           SUM(NVL(SALDO_32, 0)) AS SUM_SALDO_32, --: DEUDA CONSUMO NO REVOLVENTE
                                           SUM(NVL(SALDO_29, 0)) AS SUM_SALDO_29, --: DEUDA CREDITO HIPOTECARIO
                                           SUM(NVL(SALDO_33, 0) + NVL(SALDO_34, 0) + NVL(SALDO_35, 0) + NVL(SALDO_36, 0) + NVL(SALDO_28, 0)) AS SUM_PARCIAL,
                                           SUM(NVL(SALDO_33, 0) + NVL(SALDO_34, 0) + NVL(SALDO_35, 0) + NVL(SALDO_36, 0) + NVL(SALDO_28, 0) + NVL(SALDO_31, 0) + NVL(SALDO_32, 0)) AS SUM_TOTAL
                                      FROM (SELECT TO_NUMBER(TO_CHAR(ADD_MONTHS(TO_DATE(TRIM(TO_CHAR(intPeriodoMax)), 'YYYYMM'), -LEVEL + 1), 'YYYYMM')) AS PERIODO
                                              FROM DUAL
                                            CONNECT BY LEVEL <= 6) D --Buscar COD_DEU en los 6 últimos periodos a partir del último periodo disponible
                                      LEFT JOIN ETL_RCC_RSCLI_TMP T
                                        ON (T.INT_IDSOLICITUD = p_intIdSolicitud AND T.PERIODO = D.PERIODO AND T.COD_DEU = REC_DEU.COD_DEU)
                                     GROUP BY D.PERIODO, T.COD_DEU
                                     ORDER BY D.PERIODO DESC) LOOP

                      IF REG_SD.VC_TAMANO_EMPRESA = 'MIC' THEN
                        IF REC_RCC.SUM_TOTAL <= 20000 THEN
                          blValidacion    := TRUE;
                          IntCountPeriodo := IntCountPeriodo + 1;
                        ELSE
                          blValidacion := FALSE;
                          --Si el codigo de deudor es nulo o la suma total es igual a cero
                          IF REC_RCC.COD_DEU IS NULL OR REC_RCC.SUM_TOTAL = 0 THEN
                             vcAuxiliar   := vcAuxiliar || 'Configuración : Documento: ' || REC_RCC.COD_DOC_ID || ', MIC PERIODO: ' || REC_RCC.PERIODO || ' - Deuda Total en el sistema financiero no encontrada.'|| vcEnter;
                          ELSE
                             vcAuxiliar   := vcAuxiliar || 'Configuración : Documento: ' || REC_RCC.COD_DOC_ID || ', MIC PERIODO: ' || REC_RCC.PERIODO || ' - Deuda Total en el sistema financiero (S/ ' || TRIM(TO_CHAR(REC_RCC.SUM_TOTAL, '999,990.00')) || ') es mayor al límite permitido (S/ 20,000.00).'|| vcEnter;
                          END IF;
                        END IF;
                      ELSIF REG_SD.VC_TAMANO_EMPRESA = 'PEQ' THEN
                        IF REC_RCC.SUM_TOTAL > 20000 AND REC_RCC.SUM_TOTAL <= 300000 THEN
                          blValidacion    := TRUE;
                          IntCountPeriodo := IntCountPeriodo + 1;
                        ELSE
                          blValidacion := FALSE;
                          --Si el codigo de deudor es nulo o la suma total es igual a cero
                          IF REC_RCC.COD_DEU IS NULL OR REC_RCC.SUM_TOTAL = 0 THEN
                             vcAuxiliar   := vcAuxiliar || 'Configuración : Documento: ' || REC_RCC.COD_DOC_ID || ', PEQ PERIODO: ' || REC_RCC.PERIODO || ' - Deuda Total en el sistema financiero no encontrada.'|| vcEnter;
                          ELSE
                             vcAuxiliar   := vcAuxiliar || 'Configuración : Documento: ' || REC_RCC.COD_DOC_ID || ', PEQ PERIODO: ' || REC_RCC.PERIODO || ' - Deuda Total en el sistema financiero (S/ ' || TRIM(TO_CHAR(REC_RCC.SUM_TOTAL, '999,990.00')) || ') es menor o igual al límite inferior permitido (S/ 20,000.00) y/o es mayor o igual al límite superior permitido (S/ 300,000.00).'|| vcEnter;
                          END IF;
                        END IF;
                      ELSIF REG_SD.VC_TAMANO_EMPRESA = 'MED' THEN
                        --Para Personas Naturales
                        IF (REG_SD.VC_TIPO_DOCUMENTO = 'DNI' OR (REG_SD.VC_TIPO_DOCUMENTO = 'RUC' AND (SUBSTR(REG_SD.VC_NUMERO_DOCUMENTO,1,2) IN ('10','15','17') ))) THEN
                         IF REC_RCC.SUM_PARCIAL = 0 THEN
                            blValidacion := FALSE;
                            vcAuxiliar   := vcAuxiliar || 'Configuración : Documento: ' || REC_RCC.COD_DOC_ID || ', MED PERIODO: ' || REC_RCC.PERIODO || ' - La suma de SALDO_(28,36,35,34,33) - Deuda (MICROEMPRESA, MEDIANA EMPRESA, GRAN EMPRESA, GRAN EMPRESA, CORPORATIVO) es igual a cero.'|| vcEnter;
                          ELSE
                            intValTamEmp := intValTamEmp + 1;
                          END IF;
                          IF REC_RCC.SUM_TOTAL > 300000 THEN
                            blValidacion    := TRUE;
                            IntCountPeriodo := IntCountPeriodo + 1;
                          ELSE
                            blValidacion := FALSE;
                            --Si el codigo de deudor es nulo o la suma total es igual a cero
                            IF REC_RCC.COD_DEU IS NULL OR REC_RCC.SUM_TOTAL = 0 THEN
                               vcAuxiliar   := vcAuxiliar || 'Configuración : Documento: ' || REC_RCC.COD_DOC_ID || ', MED PERIODO: ' || REC_RCC.PERIODO || ' - Deuda Total en el sistema financiero no encontrada.'|| vcEnter;
                            ELSE
                               vcAuxiliar   := vcAuxiliar || 'Configuración : Documento: ' || REC_RCC.COD_DOC_ID || ', MED PERIODO: ' || REC_RCC.PERIODO || ' - Deuda Total en el sistema financiero (S/ ' || TRIM(TO_CHAR(REC_RCC.SUM_TOTAL, '999,990.00')) || ') es menor al límite inferior permitido (S/ 300,000.00).'|| vcEnter;
                            END IF;
                          END IF;
                        --Para Personas Jurídica
                        ELSE
                          IF (REC_RCC.SUM_TOTAL + REC_RCC.SUM_SALDO_29) > 300000 THEN
                            blValidacion    := TRUE;
                            IntCountPeriodo := IntCountPeriodo + 1;
                          ELSE
                            blValidacion := FALSE;
                            --Si el codigo de deudor es nulo o la suma total es igual a cero
                            IF REC_RCC.COD_DEU IS NULL OR (REC_RCC.SUM_TOTAL + REC_RCC.SUM_SALDO_29) = 0 THEN
                               vcAuxiliar   := vcAuxiliar || 'Configuración : Documento: ' || REC_RCC.COD_DOC_ID || ', MED PERIODO: ' || REC_RCC.PERIODO || ' - Deuda Total en el sistema financiero no encontrada.'|| vcEnter;
                            ELSE
                               vcAuxiliar   := vcAuxiliar || 'Configuración : Documento: ' || REC_RCC.COD_DOC_ID || ', MED PERIODO: ' || REC_RCC.PERIODO || ' - Deuda Total en el sistema financiero (S/ ' || TRIM(TO_CHAR((REC_RCC.SUM_TOTAL + REC_RCC.SUM_SALDO_29), '999,990.00')) || ') es menor al límite inferior permitido (S/ 300,000.00).'|| vcEnter;
                            END IF;
                          END IF;
                        END IF;
                      --OTROS
                      ELSE
                        blValidacion    := TRUE;
                        IntCountPeriodo := IntCountPeriodo + 1;
                      END IF;
                    END LOOP;
                      -- Si es Mediama empresa, Se valida los 6 Meses para Persona Natural
                      IF REG_SD.VC_TAMANO_EMPRESA = 'MED' THEN
                        IF ( ( (IntCountPeriodo >= 0 AND intValTamEmp < 6) OR (IntCountPeriodo = 0 AND intValTamEmp = 6) ) AND (REG_SD.VC_TIPO_DOCUMENTO = 'DNI' OR (REG_SD.VC_TIPO_DOCUMENTO = 'RUC' AND (SUBSTR(REG_SD.VC_NUMERO_DOCUMENTO,1,2) IN ('10','15','17') ))) ) OR (IntCountPeriodo = 0 AND REG_SD.VC_TIPO_DOCUMENTO = 'RUC' AND SUBSTR(REG_SD.VC_NUMERO_DOCUMENTO,1,2) = '20' )THEN
                          intValCodDeudor := intValCodDeudor +1 ;
                          blElegibilidad := FALSE;
                          intErrores      := intErrores + 1;
                          vcErrores       := vcErrores || 'El tamaño de empresa no cumple la regla de elegibilidad, ' || vcEnter || vcAuxiliar ;
                        END IF;
                      -- para el Resto se valida al Menos un Mes
                      ELSE
                        IF IntCountPeriodo = 0 THEN -- Si todos Fallaron se muestra el Error
                          intValCodDeudor := intValCodDeudor +1 ;
                          blElegibilidad := FALSE;
                          intErrores      := intErrores + 1;
                          vcErrores       := vcErrores || 'El tamaño de empresa no cumple la regla de elegibilidad, ' || vcEnter || vcAuxiliar ;
                        END IF;
                      END IF;
                  END IF;
                --ELSE
                  --IntCountPeriodo := 1;
                END IF;
              END LOOP;
            END IF;
          END IF;
        END IF;
      END IF;

      ----------------------------------------------------------------------------------------------------
     --Listas Permitidas
      --CIIU
      ----------------------------------------------------------------------------------------------------
      SELECT M.TODOS, M.IDVERSION  --DERM -> VERSION
        INTO intTodos, intVersionCiiu
        FROM US_BASE.V_BASE_PRODUCTO_CONFIG_CIIU M
       WHERE M.INT_IDPRODUCTO = intIdProducto
         AND ROWNUM <= 1;

      IF intTodos = 0 THEN
        SELECT COUNT(1)
          INTO intCount
          FROM US_BASE.V_BASE_PRODUCTO_CONFIG_CIIU M
         WHERE M.VC_CIIU = REG_SD.VC_CIIU
           AND M.INT_IDPRODUCTO = intIdProducto;
      ELSE
        SELECT COUNT(1)
          INTO intCount
          FROM US_BASE.V_SCP_CIIU M
         WHERE M.VC_CIIU = REG_SD.VC_CIIU
         AND INT_IDVERSION = intVersionCiiu  --DERM
         ;
      END IF;

      IF intCount = 0 THEN
        intErrores := intErrores + 1;
        vcErrores  := vcErrores || 'en Campo 15 : ' || stSolBene(10).VC_DESCRIPCION || ', ' || TRIM(REG_SD.VC_CIIU) || ', > El CIIU no es válido.' || vcEnter;
      END IF;
      ----------------------------------------------------------------------------------------------------
      -- Ubigeo
      ----------------------------------------------------------------------------------------------------
      SELECT M.TODOS
        INTO intTodos
        FROM US_BASE.V_BASE_PRODUCTO_CONFIG_UBIGEO M
       WHERE M.INT_IDPRODUCTO = intIdProducto
         AND ROWNUM <= 1;

      IF intTodos = 0 THEN
        SELECT COUNT(1)
          INTO intCount
          FROM US_BASE.V_BASE_PRODUCTO_CONFIG_UBIGEO M
         WHERE M.VC_UBIGEO = REG_SD.VC_UBIGEO
           AND M.INT_IDPRODUCTO = intIdProducto;
      ELSE
        SELECT COUNT(1)
          INTO intCount
          FROM US_BASE.VM_SCP_UBIGEO M
         WHERE M.VC_UBIGEO = REG_SD.VC_UBIGEO;
      END IF;

      IF intCount = 0 THEN
        intErrores := intErrores + 1;
        vcErrores  := vcErrores || 'en Campo 08 : ' || stSolBene(08).VC_DESCRIPCION || ', ' || TRIM(REG_SD.VC_UBIGEO) || ', > El Ubigeo no es válido.' || vcEnter;
      END IF;
      ----------------------------------------------------------------------------------------------------
      --Tipo de Destino
      ----------------------------------------------------------------------------------------------------
      SELECT M.TODOS
        INTO intTodos
        FROM US_BASE.V_BASE_PRODUCTO_CONFIG_TIPODESTINO M
       WHERE M.INT_IDPRODUCTO = intIdProducto
         AND ROWNUM <= 1;

      IF intTodos = 0 THEN
        SELECT COUNT(1)
          INTO intCount
          FROM US_BASE.V_BASE_PRODUCTO_CONFIG_TIPODESTINO M
         WHERE M.VC_TIPO_DESTINO = REG_SD.VC_TIPO_DESTINO
           AND M.INT_IDPRODUCTO = intIdProducto;
      ELSE
        SELECT COUNT(1)
          INTO intCount
          FROM US_BASE.V_SCP_TIPO_DESTINO M
         WHERE M.VC_TIPO_DESTINO = REG_SD.VC_TIPO_DESTINO;
      END IF;

      IF intCount = 0 THEN
        IF intTodos = 0 THEN
          SELECT LISTAGG('''' || M.VC_TIPO_DESTINO || '''', ',')
            INTO vcAuxiliar
            FROM US_BASE.V_BASE_PRODUCTO_CONFIG_TIPODESTINO M
           WHERE M.INT_IDPRODUCTO = intIdProducto;
        ELSE
          SELECT LISTAGG('''' || M.VC_TIPO_DESTINO || '''', ',')
            INTO vcAuxiliar
            FROM US_BASE.V_SCP_TIPO_DESTINO M;
        END IF;
        blElegibilidad := FALSE;
        intErrores     := intErrores + 1;
        vcErrores      := vcErrores || 'en Campo 22 : ' || stSolCred(06).VC_DESCRIPCION || ', ' || TRIM(REG_SD.VC_TIPO_DESTINO) || ', > El Tipo de Destino no es válido.' || vcEnter;
      END IF;

      ----------------------------------------------------------------------------------------------------
      -- Tipo Colateral
      ----------------------------------------------------------------------------------------------------
      SELECT COUNT(1)
        INTO intCount
        FROM US_BASE.V_BASE_PRODUCTO_CONFIG_TIPOCOLATERAL M
       WHERE M.VC_COLATERAL_CREDITO = REG_SD.VC_COLATERAL_CREDITO
         AND M.INT_IDPRODUCTO = intIdProducto;

      IF intCount = 0 THEN
        SELECT LISTAGG('''' || M.VC_COLATERAL_CREDITO || '''', ',')
          INTO vcAuxiliar
          FROM US_BASE.V_BASE_PRODUCTO_CONFIG_TIPOCOLATERAL M
         WHERE M.INT_IDPRODUCTO = intIdProducto;
        intValColateral := intValColateral + 1;

        blElegibilidad := FALSE;
        intErrores     := intErrores + 1;
        vcErrores      := vcErrores || 'en Campo 20 : ' || stSolCred(04).VC_DESCRIPCION || ', ' || TRIM(REG_SD.VC_COLATERAL_CREDITO) || ', > El Tipo Colateral Crédito no es válido, debe ser ' || vcAuxiliar || '.' || vcEnter;
      END IF;
      
      ----------------------------------------------------------------------------------------------------
      -- Documento permitido beneficiario
      IF recBRP.CH_ES_VALIDACION_TIPO_DOCUMENTO_PERMITIDO_OTROS = 0 THEN
        --RUC Beneficiario, DNI y CET
        IF TRIM(REG_SD.VC_TIPO_DOCUMENTO) = 'RUC' THEN
          IF recBRP.CH_ES_VALIDACION_RUTBENEFICIARIO_EXITENCIA_SUNAT = 1 THEN
            SELECT PKG_BASE.F_VALIDA_RUC(TRIM(REG_SD.VC_NUMERO_DOCUMENTO))
              INTO intCount
              FROM DUAL;
            IF intCount = 0 THEN
              blElegibilidad := FALSE;
              intErrores     := intErrores + 1;
              vcErrores      := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', > El número de RUC es invalido, revisar Digito Verificador.' || vcEnter;
            ELSE
              SELECT COUNT(1)
                INTO intCount
                FROM US_BASE.ETL_RUC_PADRON T
               WHERE T.VC_RUC = TRIM(REG_SD.VC_NUMERO_DOCUMENTO)
                 AND T.INT_INDACTUAL = 1
                 AND T.VC_ESTADO = DECODE(recBRP.CH_ES_VALIDACION_RUTBENEFICIARIO_ACTIVO,0,T.VC_ESTADO, 'ACTIVO')
                 AND T.VC_COND_DOMICILIO = DECODE(recBRP.CH_ES_VALIDACION_RUTBENEFICIARIO_HABIDO,0,T.VC_COND_DOMICILIO,'HABIDO');
              IF intCount = 0 THEN
                blElegibilidad := FALSE;
                intErrores     := intErrores + 1;
                vcErrores      := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', > El número de documento no es válido o no cumple las condiciones en la información SUNAT.' || vcEnter;
              END IF;
            END IF;
          END IF;

        ELSIF TRIM(REG_SD.VC_TIPO_DOCUMENTO) = 'DNI' THEN
          IF recBRP.CH_ES_VALIDACION_RUTBENEFICIARIO_EXITENCIA_SUNAT = 1 THEN
            IF recBRP.CH_ES_VALIDACION_RUTBENEFICIARIO_CONVERSION_TIPO_DOC = 1 THEN
              vcDocConvertido    := PKG_BASE.F_CONVERTIR_DNI_A_RUC(TRIM(REG_SD.VC_NUMERO_DOCUMENTO));
              SELECT COUNT(1)
                INTO intCount
                FROM US_BASE.ETL_RUC_PADRON T
               WHERE T.VC_RUC = vcDocConvertido
                 AND T.INT_INDACTUAL = 1;
              IF intCount = 0 THEN
                blElegibilidad := FALSE;
                intErrores     := intErrores + 1;
                vcErrores      := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', > El número de documento no es válido o no cumple las condiciones en la información SUNAT.' || vcEnter;
              ELSE
                SELECT COUNT(1)
                  INTO intCount
                  FROM US_BASE.ETL_RUC_PADRON T
                 WHERE T.VC_RUC = vcDocConvertido
                   AND T.INT_INDACTUAL = 1
                   AND T.VC_ESTADO = DECODE(recBRP.CH_ES_VALIDACION_RUTBENEFICIARIO_ACTIVO,0,T.VC_ESTADO, 'ACTIVO')
                   AND T.VC_COND_DOMICILIO = DECODE(recBRP.CH_ES_VALIDACION_RUTBENEFICIARIO_HABIDO,0,T.VC_COND_DOMICILIO,'HABIDO');
                IF intCount = 0 THEN
                  blElegibilidad := FALSE;
                  intErrores     := intErrores + 1;
                  vcErrores      := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', > El número de documento no es válido o no cumple las condiciones en la información SUNAT.' || vcEnter;
                END IF;
              END IF;
            END IF;
          END IF;

        END IF;

        --Tipo de documento
        SELECT COUNT(1)
          INTO intCount
          FROM DUAL
         WHERE TRIM(REG_SD.VC_TIPO_DOCUMENTO) IN
               (SELECT D.VALOR
                  FROM (SELECT DECODE(recBRP.CH_ES_VALIDACION_TIPO_DOCUMENTO_PERMITIDO_DNI, 1, 'DNI', 'XXX') AS D1,
                               DECODE(recBRP.CH_ES_VALIDACION_TIPO_DOCUMENTO_PERMITIDO_RUC, 1, 'RUC', 'XXX') AS D2,
                               DECODE(recBRP.CH_ES_VALIDACION_TIPO_DOCUMENTO_PERMITIDO_CET, 1, 'CET', 'XXX') AS D3
                          FROM DUAL) UNPIVOT(VALOR FOR COL IN(D1, D2, D3)) D);
        IF intCount = 0 THEN
          blElegibilidad := FALSE;
          intErrores     := intErrores + 1;
          vcErrores      := vcErrores || 'en Campo 01 : ' || stSolBene(01).VC_DESCRIPCION || ', > El Tipo Documento permitido para el beneficiario no es válido, ''' || TRIM(REG_SD.VC_TIPO_DOCUMENTO) || ''' no esta permitido.' || vcEnter;
        END IF;

        --Número de documento
        IF recBRP.CH_ES_VALIDACION_TIPO_DOCUMENTO_PERMITIDO_DNI = 1 THEN
          IF recBRP.CH_ES_VALIDACION_DNI_TAMANO_CAMPO_8 = 1 THEN
            IF TRIM(REG_SD.VC_TIPO_DOCUMENTO) = 'DNI' THEN
              IF LENGTH(TRIM(REG_SD.VC_NUMERO_DOCUMENTO)) = 8 THEN
                blValidacion := TRUE;
              ELSE
                blElegibilidad := FALSE;
                intErrores     := intErrores + 1;
                vcErrores      := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', > El tamaño de ''' || TRIM(REG_SD.VC_TIPO_DOCUMENTO) || ''' es incorrecto.' || vcEnter;
              END IF;
            END IF;
          END IF;
        END IF;
        IF recBRP.CH_ES_VALIDACION_TIPO_DOCUMENTO_PERMITIDO_RUC = 1 THEN
          IF recBRP.CH_ES_VALIDACION_RUTBENEFICIARIO_TAMANO_CAMPO_11 = 1 THEN
            IF TRIM(REG_SD.VC_TIPO_DOCUMENTO) = 'RUC' THEN
              IF LENGTH(TRIM(REG_SD.VC_NUMERO_DOCUMENTO)) = 11 THEN
                blValidacion := TRUE;
              ELSE
                blElegibilidad := FALSE;
                intErrores     := intErrores + 1;
                vcErrores      := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', > El tamaño de ''' || TRIM(REG_SD.VC_TIPO_DOCUMENTO) || ''' es incorrecto.' || vcEnter;
              END IF;
            END IF;
          END IF;
        END IF;
        IF recBRP.CH_ES_VALIDACION_TIPO_DOCUMENTO_PERMITIDO_CET = 1 THEN
          IF recBRP.CH_ES_VALIDACION_CET_TAMANO_CAMPO_9 = 1 THEN
            IF TRIM(REG_SD.VC_TIPO_DOCUMENTO) = 'CET' THEN
              IF LENGTH(TRIM(REG_SD.VC_NUMERO_DOCUMENTO)) >= 9 AND LENGTH(TRIM(REG_SD.VC_NUMERO_DOCUMENTO)) <= 12 THEN
                blValidacion := TRUE;
              ELSE
                blElegibilidad := FALSE;
                intErrores     := intErrores + 1;
                vcErrores      := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', > El tamaño de ''' || TRIM(REG_SD.VC_TIPO_DOCUMENTO) || ''' es incorrecto.' || vcEnter;
              END IF;
            END IF;
          END IF;
        END IF;

      END IF;

      ----------------------------------------------------------------------------------------------------
      --Lista negra Beneficiario
      ----------------------------------------------------------------------------------------------------
      vcDocRUC := ' ';
      vcDocDNI := ' ';
      --    IF recBRP.CH_ES_VALIDACION_LISTA_NEGRA_OTROS = 0 THEN
      IF recBRP.CH_ES_VALIDACION_LISTA_NEGRA_APLICA_REPRESENTANTE_LEGAL = 0 THEN
        IF recBRP.CH_ES_VALIDACION_LISTA_NEGRA_CONVERSION_TIP_DOC = 1 THEN
          --Documento adicional = {Doc Calculado Benef}
          IF TRIM(REG_SD.VC_TIPO_DOCUMENTO) = 'DNI' THEN
            vcDocRUC := PKG_BASE.F_CONVERTIR_DNI_A_RUC(TRIM(REG_SD.VC_NUMERO_DOCUMENTO));
            vcDocDNI := TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
          ELSIF REG_SD.VC_TIPO_DOCUMENTO = 'RUC' AND SUBSTR(REG_SD.VC_NUMERO_DOCUMENTO,1,2)='10'  THEN
            vcDocRUC := ' ';
            vcDocDNI := PKG_BASE.F_CONVERTIR_RUC_A_DNI(TRIM(REG_SD.VC_NUMERO_DOCUMENTO));
          ELSE
            vcDocRUC := TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
            vcDocDNI := ' ';
          END IF;
        END IF;
      ELSE
        IF recBRP.CH_ES_VALIDACION_LISTA_NEGRA_CONVERSION_TIP_DOC = 1 THEN
          IF recBRP.CH_ES_VALIDACION_LISTA_NEGRA_CONVERSION_TIP_DOC_RL = 1 THEN
            --Documento adicional = {Doc Calculado Benef, Doc Representante Legal, Doc Calculado R.L}
            IF TRIM(REG_SD.VC_TIPO_DOCUMENTO) = 'DNI' THEN
              vcDocRUC := PKG_BASE.F_CONVERTIR_DNI_A_RUC(TRIM(REG_SD.VC_NUMERO_DOCUMENTO));
              vcDocDNI := TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
            ELSIF TRIM(REG_SD.VC_TIPO_DOCUMENTO) = 'RUC' THEN
              SELECT COUNT(1) INTO intCount
                FROM SOLICITUD_REPLEG SR
               WHERE SR.INT_IDSOLICITUD = p_intIdSolicitud
                 AND SR.VC_NUMERO_DOCUMENTO = TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
              IF intCount > 0 THEN
                SELECT LISTAGG(SR.VC_NUMERO_DOCUMENTO_REPLEG, ','),
                       LISTAGG(PKG_BASE.F_CONVERTIR_DNI_A_RUC(SR.VC_NUMERO_DOCUMENTO_REPLEG), ',')
                  INTO vcDocDNI, vcDocRUC
                  FROM SOLICITUD_REPLEG SR
                 WHERE SR.INT_IDSOLICITUD = p_intIdSolicitud
                   AND SR.VC_NUMERO_DOCUMENTO = TRIM(REG_SD.VC_NUMERO_DOCUMENTO)
                   AND SR.VC_TIPO_DOCUMENTO_REPLEG = 'DNI';
                vcDocRUC := vcDocRUC || ',' || TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
              ELSE
                vcDocRUC := TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
              END IF;
            END IF;
            IF TRIM(REG_SD.VC_TIPO_DOCUMENTO_REPLEG) = 'DNI' THEN
              vcDocRUC := vcDocRUC || ',' || PKG_BASE.F_CONVERTIR_DNI_A_RUC(TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG));
              vcDocDNI := vcDocDNI || ',' || TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG);
            ELSIF TRIM(REG_SD.VC_TIPO_DOCUMENTO_REPLEG) = 'RUC' THEN
              vcDocRUC := vcDocRUC || ',' || TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG);
              vcDocDNI := vcDocDNI || ',' || PKG_BASE.F_CONVERTIR_RUC_A_DNI(TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG));
            END IF;
          ELSE
            --Documento adicional = {Doc Calculado Benef, Doc Representante Legal}
            IF TRIM(REG_SD.VC_TIPO_DOCUMENTO) = 'RUC' THEN
              SELECT COUNT(1) INTO intCount
                FROM SOLICITUD_REPLEG SR
               WHERE SR.INT_IDSOLICITUD = p_intIdSolicitud
                 AND SR.VC_NUMERO_DOCUMENTO = TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
              IF intCount > 0 THEN
                SELECT LISTAGG(SR.VC_NUMERO_DOCUMENTO_REPLEG, ',')
                  INTO vcDocDNI
                  FROM SOLICITUD_REPLEG SR
                 WHERE SR.INT_IDSOLICITUD = p_intIdSolicitud
                   AND SR.VC_NUMERO_DOCUMENTO = TRIM(REG_SD.VC_NUMERO_DOCUMENTO)
                   AND SR.VC_TIPO_DOCUMENTO_REPLEG = 'DNI';
                vcDocRUC := vcDocRUC || ',' || TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
              ELSE
                vcDocRUC := TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
              END IF;
            END IF;
            IF TRIM(REG_SD.VC_TIPO_DOCUMENTO) = 'DNI' THEN
              vcDocRUC := vcDocRUC || ',' || PKG_BASE.F_CONVERTIR_DNI_A_RUC(TRIM(REG_SD.VC_NUMERO_DOCUMENTO));
              vcDocDNI := vcDocDNI || ',' || TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
            ELSIF TRIM(REG_SD.VC_TIPO_DOCUMENTO) = 'RUC' THEN
              vcDocRUC := vcDocRUC || ',' || TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
            END IF;
            IF TRIM(REG_SD.VC_TIPO_DOCUMENTO_REPLEG) = 'DNI' THEN
              vcDocDNI := vcDocDNI || ',' || TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG);
            ELSIF TRIM(REG_SD.VC_TIPO_DOCUMENTO_REPLEG) = 'RUC' THEN
              vcDocRUC := vcDocRUC || ',' || TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG);
            END IF;
          END IF;
        ELSE
          IF recBRP.CH_ES_VALIDACION_LISTA_NEGRA_CONVERSION_TIP_DOC_RL = 1 THEN
            --Documento adicional = { Doc Representante Legal, Doc Calculado R.L}
            IF TRIM(REG_SD.VC_TIPO_DOCUMENTO) = 'RUC' THEN
              SELECT COUNT(1) INTO intCount
                FROM SOLICITUD_REPLEG SR
               WHERE SR.INT_IDSOLICITUD = p_intIdSolicitud
                 AND SR.VC_NUMERO_DOCUMENTO = TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
              IF intCount > 0 THEN
                SELECT LISTAGG(SR.VC_NUMERO_DOCUMENTO_REPLEG, ','),
                       LISTAGG(PKG_BASE.F_CONVERTIR_DNI_A_RUC(SR.VC_NUMERO_DOCUMENTO_REPLEG), ',')
                  INTO vcDocDNI, vcDocRUC
                  FROM SOLICITUD_REPLEG SR
                 WHERE SR.INT_IDSOLICITUD = p_intIdSolicitud
                   AND SR.VC_NUMERO_DOCUMENTO = TRIM(REG_SD.VC_NUMERO_DOCUMENTO)
                   AND SR.VC_TIPO_DOCUMENTO_REPLEG = 'DNI';
                vcDocRUC := vcDocRUC || ',' || TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
              ELSE
                vcDocRUC := TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
              END IF;
            END IF;
            IF TRIM(REG_SD.VC_TIPO_DOCUMENTO_REPLEG) = 'DNI' THEN
              vcDocRUC := vcDocRUC || ',' || PKG_BASE.F_CONVERTIR_DNI_A_RUC(TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG));
              vcDocDNI := vcDocDNI || ',' || TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG);
            ELSIF TRIM(REG_SD.VC_TIPO_DOCUMENTO_REPLEG) = 'RUC' THEN
              vcDocRUC := vcDocRUC || ',' || TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG);
            END IF;
          ELSE
            --Documento adicional = { Doc Representante Legal}
            IF TRIM(REG_SD.VC_TIPO_DOCUMENTO) = 'RUC' THEN
              SELECT COUNT(1) INTO intCount
                FROM SOLICITUD_REPLEG SR
               WHERE SR.INT_IDSOLICITUD = p_intIdSolicitud
                 AND SR.VC_NUMERO_DOCUMENTO = TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
              IF intCount > 0 THEN
                SELECT LISTAGG(SR.VC_NUMERO_DOCUMENTO_REPLEG, ',')
                  INTO vcDocDNI
                  FROM SOLICITUD_REPLEG SR
                 WHERE SR.INT_IDSOLICITUD = p_intIdSolicitud
                   AND SR.VC_NUMERO_DOCUMENTO = TRIM(REG_SD.VC_NUMERO_DOCUMENTO)
                   AND SR.VC_TIPO_DOCUMENTO_REPLEG = 'DNI';
                vcDocRUC := vcDocRUC || ',' || TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
              ELSE
                vcDocRUC := TRIM(REG_SD.VC_NUMERO_DOCUMENTO);
              END IF;
            END IF;
            IF TRIM(REG_SD.VC_TIPO_DOCUMENTO_REPLEG) = 'DNI' THEN
              vcDocDNI := vcDocDNI || ',' || TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG);
            ELSIF TRIM(REG_SD.VC_TIPO_DOCUMENTO_REPLEG) = 'RUC' THEN
              vcDocRUC := vcDocRUC || ',' || TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG);
            END IF;
          END IF;
        END IF;
      END IF;
      --    END IF;

      IF recBRP.CH_ES_VALIDACION_LISTA_NEGRA_OTROS = 0 THEN

        IF recBRP.CH_ES_VALIDACION_LISTA_NEGRA_OSCE = 1 THEN

          SELECT COUNT(1)
            INTO intCount
            FROM US_BASE.ETL_LISTA_NEGRA_OSCE LNO
           WHERE (LNO.CH_FLAG_ESTADO = 'A' AND LNO.VC_CODTIPO_DOCUMENTO = 18 AND
                 LNO.VC_NRO_DOCUMENTO IN
                 (SELECT REGEXP_SUBSTR(vcDocDNI, '[^,]+', 1, LEVEL) AS DNI
                     FROM DUAL
                   CONNECT BY REGEXP_SUBSTR(vcDocDNI, '[^,]+', 1, LEVEL) IS NOT NULL))
              OR (LNO.CH_FLAG_ESTADO = 'A' AND LNO.VC_CODTIPO_DOCUMENTO = 19 AND
                 LNO.VC_NRO_DOCUMENTO IN
                 (SELECT REGEXP_SUBSTR(vcDocRUC, '[^,]+', 1, LEVEL) AS RUC
                     FROM DUAL
                   CONNECT BY REGEXP_SUBSTR(vcDocRUC, '[^,]+', 1, LEVEL) IS NOT NULL));
          IF intCount > 0 THEN
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores || 'El número de doc. beneficiario / Representante legal se encuentra en la lista negra OSCE.' || vcEnter;
          END IF;
        END IF;

        IF recBRP.CH_ES_VALIDACION_LISTA_NEGRA_PROCURADORIA = 1 OR recBRP.CH_ES_VALIDACION_LISTA_NEGRA_LEY_73031 = 1 THEN
          SELECT COUNT(1)
            INTO intCount
            FROM US_BASE.ETL_LISTA_NEGRA_PROC_LEY LNPL
           WHERE (LNPL.CH_FLAG_ESTADO = 'A' AND LNPL.INT_IDTIPO_DOCUMENTO = 18 AND  LNPL.VC_RUC IN
                 (SELECT REGEXP_SUBSTR(vcDocDNI, '[^,]+', 1, LEVEL) AS DNI
                     FROM DUAL
                   CONNECT BY REGEXP_SUBSTR(vcDocDNI, '[^,]+', 1, LEVEL) IS NOT NULL))
              OR (LNPL.CH_FLAG_ESTADO = 'A' AND LNPL.INT_IDTIPO_DOCUMENTO = 19 AND
                 LNPL.VC_RUC IN
                 (SELECT REGEXP_SUBSTR(vcDocRUC, '[^,]+', 1, LEVEL) AS RUC
                     FROM DUAL
                   CONNECT BY REGEXP_SUBSTR(vcDocRUC, '[^,]+', 1, LEVEL) IS NOT NULL));
          IF intCount > 0 THEN
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores ||'El número de doc. beneficiario / Representante legal se encuentra en la lista negra Procuradoría o Ley 73031.' ||vcEnter;
          END IF;
        END IF;
      END IF;
      ----------------------------------------------------------------------------------------------------

      --Duplicidad Beneficiario
      ----------------------------------------------------------------------------------------------------
      intMontoPrestamoRegi    := 0;
      intMontoPrestamoAcum    := 0;
      intPorcenCoberturado    := 0;
      intPorcenCoberturadoAct := 0;
      intMontoPrestamoCobert  := 0;

      --se hace la Conversion de Tipo de Documento para tenerlos en la varibles
      IF REG_SD.VC_TIPO_DOCUMENTO = 'DNI' THEN
        vcTipDocConvertido := 'RUC';
        vcDocConvertido    := PKG_BASE.F_CONVERTIR_DNI_A_RUC(REG_SD.VC_NUMERO_DOCUMENTO);
      ELSIF REG_SD.VC_TIPO_DOCUMENTO = 'RUC' AND SUBSTR(REG_SD.VC_NUMERO_DOCUMENTO,1,2)='10'  THEN
        vcTipDocConvertido := 'DNI';
        vcDocConvertido    := PKG_BASE.F_CONVERTIR_RUC_A_DNI(REG_SD.VC_NUMERO_DOCUMENTO);
      ELSE
        vcTipDocConvertido := REG_SD.VC_TIPO_DOCUMENTO;
        vcDocConvertido    := REG_SD.VC_NUMERO_DOCUMENTO;
      END IF;

      --Se puede repetir está OFF
      IF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_SE_PUEDE_REPETIR = 0 THEN
        --Se puede repetir está OFF // Conversion Tipo Doc está OFF
        IF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_CONVERSION_TIPO_DOC = 0 THEN
          intCount := 0;
            --Para la misma solicitud
            SELECT COUNT(1) INTO intCount
              FROM SOLICITUD_DETALLE SD
             WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
               AND (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO);
            IF intCount > 1 THEN
              blElegibilidad := FALSE;
              intErrores     := intErrores + 1;
              vcErrores      := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', > El número de documento ' || REG_SD.VC_NUMERO_DOCUMENTO || ' Se identifica duplicidad de beneficiario en el mismo archivo.' || vcEnter;
            END IF;
          --Para todas las solicitud con estado
          SELECT COUNT(1) INTO intCount
            FROM SOLICITUD_DETALLE SD
           WHERE (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO)
             AND SD.INT_IDSOLICITUD_DET <> REG_SD.INT_IDSOLICITUD_DET
             AND SD.VC_ESTADO IN
                 (SELECT D.VALOR
                    FROM (SELECT DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_EN_EVALUACION, 1, 'REG', 'XXX') AS D1,
                                 DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_POR_CONFIRMAR, 1, 'ELE', 'XXX') AS D2,
                                 DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_CONFIRMADO, 1, 'CON', 'XXX') AS D3,
                                 DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_COBERTURADO, 1, 'COB', 'XXX') AS D4
                            FROM DUAL) UNPIVOT(VALOR FOR COL IN(D1, D2, D3, D4)) D);
          IF intCount > 0 THEN
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', > El número de documento ' || REG_SD.VC_NUMERO_DOCUMENTO || ' ya se encuentra registrado.' || vcEnter;
          END IF;
        --Se puede repetir está OFF // Conversion Tipo Doc está ON
        ELSIF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_CONVERSION_TIPO_DOC = 1 THEN
          intCount := 4;
            --Para la misma solicitud
            SELECT COUNT(1) INTO intCount
              FROM SOLICITUD_DETALLE SD
             WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
               AND ((SD.VC_TIPO_DOCUMENTO = vcTipDocConvertido AND SD.VC_NUMERO_DOCUMENTO = vcDocConvertido) OR
                    (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO));
            IF intCount > 1 THEN
              blElegibilidad := FALSE;
              intErrores     := intErrores + 1;
              vcErrores      := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', > El número de documento ' || REG_SD.VC_NUMERO_DOCUMENTO || ' Se identifica duplicidad de beneficiario en el mismo archivo.' || vcEnter;
            END IF;
          --Para todas las solicitud con estado
          SELECT COUNT(1) INTO intCount
            FROM SOLICITUD_DETALLE SD
           WHERE ((SD.VC_TIPO_DOCUMENTO = vcTipDocConvertido AND SD.VC_NUMERO_DOCUMENTO = vcDocConvertido) OR
                  (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO))
             AND SD.INT_IDSOLICITUD_DET <> REG_SD.INT_IDSOLICITUD_DET
             AND SD.VC_ESTADO IN
                 (SELECT D.VALOR
                    FROM (SELECT DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_EN_EVALUACION, 1, 'REG', 'XXX') AS D1,
                                 DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_POR_CONFIRMAR, 1, 'ELE', 'XXX') AS D2,
                                 DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_CONFIRMADO, 1, 'CON', 'XXX') AS D3,
                                 DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_COBERTURADO, 1, 'COB', 'XXX') AS D4
                            FROM DUAL) UNPIVOT(VALOR FOR COL IN(D1, D2, D3, D4)) D);
          IF intCount > 0 THEN
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', > El número de documento ' || REG_SD.VC_NUMERO_DOCUMENTO || ' ya se encuentra registrado.' || vcEnter;
          END IF;
        END IF;
      --Se puede repetir está ON
      ELSIF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_SE_PUEDE_REPETIR = 1 THEN
        --Se puede repetir está ON // Conversion Tipo Doc está OFF
        IF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_CONVERSION_TIPO_DOC = 0 THEN
          --Se puede repetir está ON // Conversion Tipo Doc está OFF // Misma IFI esta en OFF
          IF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_MISMA_IFI = 0 THEN
            --Se puede repetir está ON // Conversion Tipo Doc está OFF // Misma IFI esta en OFF // Misma % Cobertura esta en OFF
            IF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_MISMO_COB = 0 THEN
              intCount := 8;
              /*Continuar con la Siguiente regla*/
            --Se puede repetir está ON // Conversion Tipo Doc está OFF // Misma IFI esta en OFF // Misma % Cobertura esta en ON
            ELSIF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_MISMO_COB = 1 THEN
              intCount := 9;
             SELECT COUNT(1)
                INTO intCount
                FROM SOLICITUD_DETALLE SD
               WHERE SD.INT_IDSOLICITUD <> p_intIdSolicitud
                 AND (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO)
                 AND SD.VC_ESTADO IN
                     (SELECT D.VALOR
                        FROM (SELECT DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_EN_EVALUACION, 1, 'REG', 'XXX') AS D1,
                                     DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_POR_CONFIRMAR, 1, 'ELE', 'XXX') AS D2,
                                     DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_CONFIRMADO, 1, 'CON', 'XXX') AS D3,
                                     DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_COBERTURADO, 1, 'COB', 'XXX') AS D4
                                FROM DUAL) UNPIVOT(VALOR FOR COL IN(D1, D2, D3, D4)) D);
             IF intCount > 0 THEN
               SELECT SUM(NVL(SD.DEC_MONTO_PRESTAMO, 0))
                  INTO intMontoPrestamoRegi
                  FROM SOLICITUD_DETALLE SD
                 WHERE SD.INT_IDSOLICITUD <> p_intIdSolicitud
                   AND (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO)
                   AND SD.VC_ESTADO IN
                       (SELECT D.VALOR
                          FROM (SELECT DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_EN_EVALUACION, 1, 'REG', 'XXX') AS D1,
                                       DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_POR_CONFIRMAR, 1, 'ELE', 'XXX') AS D2,
                                       DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_CONFIRMADO, 1, 'CON', 'XXX') AS D3,
                                       DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_COBERTURADO, 1, 'COB', 'XXX') AS D4
                                  FROM DUAL) UNPIVOT(VALOR FOR COL IN(D1, D2, D3, D4)) D);
                intMontoPrestamoRegi := NVL(intMontoPrestamoRegi, 0);

                SELECT SUM(NVL(SD.DEC_MONTO_PRESTAMO, 0))
                  INTO intMontoPrestamoAcum
                  FROM SOLICITUD_DETALLE SD
                 WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
                   AND (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO);

                intMontoPrestamoAcum := NVL(intMontoPrestamoAcum, 0);

                intMontoPrestamoFinal:= intMontoPrestamoRegi + intMontoPrestamoAcum;

                SELECT COUNT(1)
                  INTO intCount
                  FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
                 WHERE intMontoPrestamoFinal BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                   AND L.INT_IDPRODUCTO = intIdProducto;

                IF intCount > 0 THEN
                  SELECT L.DEC_PORCENTAJE_COB
                    INTO intPorcenCoberturado
                    FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
                   WHERE intMontoPrestamoFinal BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                     AND L.INT_IDPRODUCTO = intIdProducto
                     AND ROWNUM = 1;
                ELSE
                  blElegibilidad := FALSE;
                  intErrores     := intErrores + 1;
                  vcErrores      := vcErrores || 'No se ha identificado el % de cobertura en los intervalos definidos para el monto del préstamo final calculado ' || TRIM(TO_CHAR(intMontoPrestamoFinal, '999,999,990.00')) || ' .' || vcEnter;
                END IF;

                SELECT COUNT(1)
                  INTO intCount
                  FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
                 WHERE intMontoPrestamoRegi BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                   AND L.INT_IDPRODUCTO = intIdProducto
                   AND ROWNUM = 1;

                IF intCount > 0 THEN
                  SELECT L.DEC_PORCENTAJE_COB
                    INTO intPorcenCoberturadoAct
                    FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
                   WHERE intMontoPrestamoRegi BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                     AND L.INT_IDPRODUCTO = intIdProducto
                     AND ROWNUM = 1;
                ELSE
                  blElegibilidad := FALSE;
                  intErrores     := intErrores + 1;
                  vcErrores      := vcErrores || 'No se ha identificado el % de cobertura en los intervalos definidos para el monto del préstamo acumulado ' || TRIM(TO_CHAR(intMontoPrestamoRegi, '999,999,990.00')) || ' .' || vcEnter;
                END IF;

                IF intPorcenCoberturadoAct <> intPorcenCoberturado THEN
                  blElegibilidad := FALSE;
                  intErrores     := intErrores + 1;
                  vcErrores      := vcErrores || 'El % de cobertura debe ser el mismo para un mismo beneficiario.' || vcEnter;
                END IF;
              END IF;
            END IF;
          --Se puede repetir está ON // Conversion Tipo Doc está OFF // Misma IFI esta en ON
          ELSIF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_MISMA_IFI = 1 THEN
            -- Aplica para Misma IFI esta en ON - Bin 10 y Bin 11
            SELECT COUNT(1)
              INTO intCount
              FROM SOLICITUD_DETALLE SD
             WHERE SD.INT_IDSOLICITUD IN
                   (SELECT S.INT_IDSOLICITUD
                      FROM SOLICITUD S
                     WHERE S.INT_IDIFI <> intIdIFI)
               AND (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO)
               AND SD.VC_ESTADO IN
                   (SELECT D.VALOR
                      FROM (SELECT DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_EN_EVALUACION, 1, 'REG', 'XXX') AS D1,
                                   DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_POR_CONFIRMAR, 1, 'ELE', 'XXX') AS D2,
                                   DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_CONFIRMADO, 1, 'CON', 'XXX') AS D3,
                                   DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_COBERTURADO, 1, 'COB', 'XXX') AS D4
                              FROM DUAL) UNPIVOT(VALOR FOR COL IN(D1, D2, D3, D4)) D);
            IF intCount > 0 THEN
              blElegibilidad := FALSE;
              intErrores     := intErrores + 1;
              vcErrores      := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', > El número de documento ' || REG_SD.VC_NUMERO_DOCUMENTO || ' ya se encuentra registrado en otra IFI.' || vcEnter;
            END IF;
            --Se puede repetir está ON // Conversion Tipo Doc está OFF // Misma IFI esta en ON // Misma % Cobertura esta en OFF
            IF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_MISMO_COB = 0 THEN
              intCount := 10;
            --Se puede repetir está ON // Conversion Tipo Doc está OFF // Misma IFI esta en ON // Misma % Cobertura esta en ON
            ELSIF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_MISMO_COB = 1 THEN
              intCount := 11;
              SELECT COUNT(1)
                INTO intCount
                FROM SOLICITUD_DETALLE SD
               WHERE SD.INT_IDSOLICITUD <> p_intIdSolicitud
                 AND (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO)
                 AND SD.VC_ESTADO IN
                     (SELECT D.VALOR
                        FROM (SELECT DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_EN_EVALUACION, 1, 'REG', 'XXX') AS D1,
                                     DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_POR_CONFIRMAR, 1, 'ELE', 'XXX') AS D2,
                                     DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_CONFIRMADO, 1, 'CON', 'XXX') AS D3,
                                     DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_COBERTURADO, 1, 'COB', 'XXX') AS D4
                                FROM DUAL) UNPIVOT(VALOR FOR COL IN(D1, D2, D3, D4)) D);
              IF intCount > 0 THEN
                SELECT SUM(NVL(SD.DEC_MONTO_PRESTAMO, 0))
                  INTO intMontoPrestamoRegi
                  FROM SOLICITUD_DETALLE SD
                 WHERE SD.INT_IDSOLICITUD <> p_intIdSolicitud
                   AND (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO)
                   AND SD.VC_ESTADO IN
                       (SELECT D.VALOR
                          FROM (SELECT DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_EN_EVALUACION, 1, 'REG', 'XXX') AS D1,
                                       DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_POR_CONFIRMAR, 1, 'ELE', 'XXX') AS D2,
                                       DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_CONFIRMADO, 1, 'CON', 'XXX') AS D3,
                                       DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_COBERTURADO, 1, 'COB', 'XXX') AS D4
                                  FROM DUAL) UNPIVOT(VALOR FOR COL IN(D1, D2, D3, D4)) D);
                intMontoPrestamoRegi := NVL(intMontoPrestamoRegi, 0);

                SELECT SUM(NVL(SD.DEC_MONTO_PRESTAMO, 0))
                  INTO intMontoPrestamoAcum
                  FROM SOLICITUD_DETALLE SD
                 WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
                   AND (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO);

                intMontoPrestamoAcum  := NVL(intMontoPrestamoAcum, 0);
                intMontoPrestamoFinal := intMontoPrestamoRegi + intMontoPrestamoAcum;

                SELECT COUNT(1)
                  INTO intCount
                  FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
                 WHERE intMontoPrestamoFinal BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                   AND L.INT_IDPRODUCTO = intIdProducto;

                IF intCount > 0 THEN
                  SELECT L.DEC_PORCENTAJE_COB
                    INTO intPorcenCoberturado
                    FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
                   WHERE intMontoPrestamoFinal BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                     AND L.INT_IDPRODUCTO = intIdProducto
                     AND ROWNUM = 1;
                ELSE
                  blElegibilidad := FALSE;
                  intErrores     := intErrores + 1;
                  vcErrores      := vcErrores || 'No se ha identificado el % de cobertura en los intervalos definidos para el monto del préstamo final calculado ' || TRIM(TO_CHAR(intMontoPrestamoFinal, '999,999,990.00')) || ' .' || vcEnter;
                END IF;

                SELECT COUNT(1)
                  INTO intCount
                  FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
                 WHERE intMontoPrestamoRegi BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                   AND L.INT_IDPRODUCTO = intIdProducto
                   AND ROWNUM = 1;

                IF intCount > 0 THEN
                  SELECT L.DEC_PORCENTAJE_COB
                    INTO intPorcenCoberturadoAct
                    FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
                   WHERE intMontoPrestamoRegi BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                     AND L.INT_IDPRODUCTO = intIdProducto
                     AND ROWNUM = 1;
                ELSE
                  blElegibilidad := FALSE;
                  intErrores     := intErrores + 1;
                  vcErrores      := vcErrores || 'No se ha identificado el % de cobertura en los intervalos definidos para el monto del préstamo registrado acumulado ' || TRIM(TO_CHAR(intMontoPrestamoRegi, '999,999,990.00')) || ' .' || vcEnter;
                END IF;

                IF intPorcenCoberturadoAct <> intPorcenCoberturado THEN
                  blElegibilidad := FALSE;
                  intErrores     := intErrores + 1;
                  vcErrores      := vcErrores || 'El % de cobertura debe ser el mismo para un mismo beneficiario.' || vcEnter;
                END IF;
              END IF;
            END IF;
          END IF;
        --Se puede repetir está ON // Conversion Tipo Doc está ON
        ELSIF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_CONVERSION_TIPO_DOC = 1 THEN
          --Se puede repetir está ON // Conversion Tipo Doc está ON // Misma IFI esta en OFF
          IF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_MISMA_IFI = 0 THEN
            --Se puede repetir está ON // Conversion Tipo Doc está ON // Misma IFI esta en OFF // Misma % Cobertura esta en OFF
            IF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_MISMO_COB = 0 THEN
