              /*Continuar con la Siguiente regla*/
            --Se puede repetir está ON // Conversion Tipo Doc está ON // Misma IFI esta en OFF // Misma % Cobertura esta en ON
            ELSIF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_MISMO_COB = 1 THEN
              intCount := 13;
              SELECT COUNT(1)
                INTO intCount
                FROM SOLICITUD_DETALLE SD
               WHERE SD.INT_IDSOLICITUD <> p_intIdSolicitud
                 AND ((SD.VC_TIPO_DOCUMENTO = vcTipDocConvertido AND SD.VC_NUMERO_DOCUMENTO = vcDocConvertido) OR
                      (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO))
                 AND SD.VC_ESTADO IN
                     (SELECT D.VALOR
                        FROM (SELECT DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_EN_EVALUACION, 1, 'REG', 'XXX') AS D1,
                                     DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_POR_CONFIRMAR, 1, 'ELE', 'XXX') AS D2,
                                     DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_CONFIRMADO, 1, 'CON', 'XXX') AS D3,
                                     DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_COBERTURADO, 1, 'COB', 'XXX') AS D4
                                FROM DUAL) UNPIVOT(VALOR FOR COL IN(D1, D2, D3, D4)) D);
              IF intCount > 0 THEN
                SELECT SUM(NVL(SD.DEC_MONTO_PRESTAMO, 0))
                  INTO intMontoPrestamoRegi
                  FROM SOLICITUD_DETALLE SD
                 WHERE SD.INT_IDSOLICITUD <> p_intIdSolicitud
                   AND ((SD.VC_TIPO_DOCUMENTO = vcTipDocConvertido AND SD.VC_NUMERO_DOCUMENTO = vcDocConvertido) OR
                        (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO))
                   AND SD.VC_ESTADO IN
                       (SELECT D.VALOR
                          FROM (SELECT DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_EN_EVALUACION, 1, 'REG', 'XXX') AS D1,
                                       DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_POR_CONFIRMAR, 1, 'ELE', 'XXX') AS D2,
                                       DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_CONFIRMADO, 1, 'CON', 'XXX') AS D3,
                                       DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_COBERTURADO, 1, 'COB', 'XXX') AS D4
                                  FROM DUAL) UNPIVOT(VALOR FOR COL IN(D1, D2, D3, D4)) D);
                intMontoPrestamoRegi := NVL(intMontoPrestamoRegi, 0);

                SELECT SUM(NVL(SD.DEC_MONTO_PRESTAMO, 0))
                  INTO intMontoPrestamoAcum
                  FROM SOLICITUD_DETALLE SD
                 WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
                   AND ((SD.VC_TIPO_DOCUMENTO = vcTipDocConvertido AND SD.VC_NUMERO_DOCUMENTO = vcDocConvertido) OR
                        (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO));

                intMontoPrestamoAcum  := NVL(intMontoPrestamoAcum, 0);
                intMontoPrestamoFinal := intMontoPrestamoRegi + intMontoPrestamoAcum;

                SELECT COUNT(1)
                  INTO intCount
                  FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
                 WHERE intMontoPrestamoFinal BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                   AND L.INT_IDPRODUCTO = intIdProducto;

                IF intCount > 0 THEN
                  SELECT L.DEC_PORCENTAJE_COB
                    INTO intPorcenCoberturado
                    FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
                   WHERE intMontoPrestamoFinal BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                     AND L.INT_IDPRODUCTO = intIdProducto
                     AND ROWNUM = 1;
                ELSE
                  blElegibilidad := FALSE;
                  intErrores     := intErrores + 1;
                  vcErrores      := vcErrores || 'No se ha identificado el % de cobertura en los intervalos definidos para el monto del préstamo final calculado ' || TRIM(TO_CHAR(intMontoPrestamoFinal, '999,999,990.00')) || ' .' || vcEnter;
                END IF;

                SELECT COUNT(1)
                  INTO intCount
                  FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
                 WHERE intMontoPrestamoRegi BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                   AND L.INT_IDPRODUCTO = intIdProducto
                   AND ROWNUM = 1;

                IF intCount > 0 THEN
                  SELECT L.DEC_PORCENTAJE_COB
                    INTO intPorcenCoberturadoAct
                    FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
                   WHERE intMontoPrestamoRegi BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                     AND L.INT_IDPRODUCTO = intIdProducto
                     AND ROWNUM = 1;
                ELSE
                  blElegibilidad := FALSE;
                  intErrores     := intErrores + 1;
                  vcErrores      := vcErrores || 'No se ha identificado el % de cobertura en los intervalos definidos para el monto del préstamo registrado acumulado ' || TRIM(TO_CHAR(intMontoPrestamoRegi, '999,999,990.00')) || ' .' || vcEnter;
                END IF;

                IF intPorcenCoberturadoAct <> intPorcenCoberturado THEN
                  blElegibilidad := FALSE;
                  intErrores     := intErrores + 1;
                  vcErrores      := vcErrores || 'El % de cobertura debe ser el mismo para un mismo beneficiario.' || vcEnter;
                END IF;
              END IF;
            END IF;
          --Se puede repetir está ON // Conversion Tipo Doc está ON // Misma IFI esta en ON
          ELSIF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_MISMA_IFI = 1 THEN
           -- Aplica para Misma IFI esta en ON - Bin 14 y Bin 15
            SELECT COUNT(1)
              INTO intCount
              FROM SOLICITUD_DETALLE SD
             WHERE SD.INT_IDSOLICITUD IN
                   (SELECT S.INT_IDSOLICITUD
                      FROM SOLICITUD S
                     WHERE S.INT_IDIFI <> intIdIFI)
               AND ((SD.VC_TIPO_DOCUMENTO = vcTipDocConvertido AND SD.VC_NUMERO_DOCUMENTO = vcDocConvertido) OR
                    (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO))
               AND SD.VC_ESTADO IN
                   (SELECT D.VALOR
                      FROM (SELECT DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_EN_EVALUACION, 1, 'REG', 'XXX') AS D1,
                                   DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_POR_CONFIRMAR, 1, 'ELE', 'XXX') AS D2,
                                   DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_CONFIRMADO, 1, 'CON', 'XXX') AS D3,
                                   DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_COBERTURADO, 1, 'COB', 'XXX') AS D4
                              FROM DUAL) UNPIVOT(VALOR FOR COL IN(D1, D2, D3, D4)) D);
            IF intCount > 0 THEN
              blElegibilidad := FALSE;
              intErrores     := intErrores + 1;
              vcErrores      := vcErrores || 'en Campo 02 : ' || stSolBene(02).VC_DESCRIPCION || ', > El número de documento ' || REG_SD.VC_NUMERO_DOCUMENTO || ' ya se encuentra registrado en otra IFI.' || vcEnter;
            END IF;
            --Se puede repetir está ON // Conversion Tipo Doc está ON // Misma IFI esta en ON // Misma % Cobertura esta en OFF
            IF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_MISMO_COB = 0 THEN
              intCount := 14;
            --Se puede repetir está ON // Conversion Tipo Doc está ON // Misma IFI esta en ON // Misma % Cobertura esta en ON
            ELSIF recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_MISMO_COB = 1 THEN
              intCount := 15;
              SELECT COUNT(1)
                INTO intCount
                FROM SOLICITUD_DETALLE SD
               WHERE SD.INT_IDSOLICITUD <> p_intIdSolicitud
                 AND ((SD.VC_TIPO_DOCUMENTO = vcTipDocConvertido AND SD.VC_NUMERO_DOCUMENTO = vcDocConvertido) OR
                      (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO))
                 AND SD.VC_ESTADO IN
                     (SELECT D.VALOR
                        FROM (SELECT DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_EN_EVALUACION, 1, 'REG', 'XXX') AS D1,
                                     DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_POR_CONFIRMAR, 1, 'ELE', 'XXX') AS D2,
                                     DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_CONFIRMADO, 1, 'CON', 'XXX') AS D3,
                                     DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_COBERTURADO, 1, 'COB', 'XXX') AS D4
                                FROM DUAL) UNPIVOT(VALOR FOR COL IN(D1, D2, D3, D4)) D);
              IF intCount > 0 THEN
                SELECT SUM(NVL(SD.DEC_MONTO_PRESTAMO, 0))
                  INTO intMontoPrestamoRegi
                  FROM SOLICITUD_DETALLE SD
                 WHERE SD.INT_IDSOLICITUD <> p_intIdSolicitud
                   AND ((SD.VC_TIPO_DOCUMENTO = vcTipDocConvertido AND SD.VC_NUMERO_DOCUMENTO = vcDocConvertido) OR
                        (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO))
                   AND SD.VC_ESTADO IN
                       (SELECT D.VALOR
                          FROM (SELECT DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_EN_EVALUACION, 1, 'REG', 'XXX') AS D1,
                                       DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_POR_CONFIRMAR, 1, 'ELE', 'XXX') AS D2,
                                       DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_CONFIRMADO, 1, 'CON', 'XXX') AS D3,
                                       DECODE(recBRP.CH_ES_VALIDACION_DUPLICIDAD_BENEFICIARIO_ESTADO_COBERTURADO, 1, 'COB', 'XXX') AS D4
                                  FROM DUAL) UNPIVOT(VALOR FOR COL IN(D1, D2, D3, D4)) D);
                intMontoPrestamoRegi := NVL(intMontoPrestamoRegi, 0);

                SELECT SUM(NVL(SD.DEC_MONTO_PRESTAMO, 0))
                  INTO intMontoPrestamoAcum
                  FROM SOLICITUD_DETALLE SD
                 WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
                   AND ((SD.VC_TIPO_DOCUMENTO = vcTipDocConvertido AND SD.VC_NUMERO_DOCUMENTO = vcDocConvertido) OR
                        (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO));

                intMontoPrestamoAcum  := NVL(intMontoPrestamoAcum, 0);
                intMontoPrestamoFinal := intMontoPrestamoRegi + intMontoPrestamoAcum;

                SELECT COUNT(1)
                  INTO intCount
                  FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
                 WHERE intMontoPrestamoFinal BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                   AND L.INT_IDPRODUCTO = intIdProducto;

                IF intCount > 0 THEN
                  SELECT L.DEC_PORCENTAJE_COB
                    INTO intPorcenCoberturado
                    FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
                   WHERE intMontoPrestamoFinal BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                     AND L.INT_IDPRODUCTO = intIdProducto
                     AND ROWNUM = 1;
                ELSE
                  blElegibilidad := FALSE;
                  intErrores     := intErrores + 1;
                  vcErrores      := vcErrores || 'No se ha identificado el % de cobertura en los intervalos definidos para el monto del préstamo final calculado ' || TRIM(TO_CHAR(intMontoPrestamoFinal, '999,999,990.00')) || ' .' || vcEnter;
                END IF;

                SELECT COUNT(1)
                  INTO intCount
                  FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
                 WHERE intMontoPrestamoRegi BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                   AND L.INT_IDPRODUCTO = intIdProducto
                   AND ROWNUM = 1;

                IF intCount > 0 THEN
                  SELECT L.DEC_PORCENTAJE_COB
                    INTO intPorcenCoberturadoAct
                    FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
                   WHERE intMontoPrestamoRegi BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                     AND L.INT_IDPRODUCTO = intIdProducto
                     AND ROWNUM = 1;
                ELSE
                  blElegibilidad := FALSE;
                  intErrores     := intErrores + 1;
                  vcErrores      := vcErrores || 'No se ha identificado el % de cobertura en los intervalos definidos para el monto del préstamo registrado acumulado ' || TRIM(TO_CHAR(intMontoPrestamoRegi, '999,999,990.00')) || ' .' || vcEnter;
                END IF;

                IF intPorcenCoberturadoAct <> intPorcenCoberturado THEN
                  blElegibilidad := FALSE;
                  intErrores     := intErrores + 1;
                  vcErrores      := vcErrores || 'El % de cobertura debe ser el mismo para un mismo beneficiario.' || vcEnter;
                END IF;
              END IF;
            END IF;
          END IF;
        END IF;
      END IF;

      ----------------------------------------------------------------------------------------------------
      --Tipo de documento permitidos Representante Legal
      ----------------------------------------------------------------------------------------------------
      IF recBRP.CH_ES_VALIDACION_TIPO_DOCUMENTO_PERMITIDO_REPRESENTANTE_LEGAL_OTROS = 0 AND REG_SD.VC_TIPO_DOCUMENTO = 'RUC' THEN
        SELECT COUNT(1)
          INTO intCount
          FROM DUAL
         WHERE TRIM(REG_SD.VC_TIPO_DOCUMENTO_REPLEG) IN
               (SELECT D.VALOR
                  FROM (SELECT DECODE(recBRP.CH_ES_VALIDACION_TIPO_DOCUMENTO_PERMITIDO_REPRESENTANTE_LEGAL_DNI, 1, 'DNI', 'XXX') AS D1,
                               DECODE(recBRP.CH_ES_VALIDACION_TIPO_DOCUMENTO_PERMITIDO_REPRESENTANTE_LEGAL_RUC, 1, 'RUC', 'XXX') AS D2,
                               DECODE(recBRP.CH_ES_VALIDACION_TIPO_DOCUMENTO_PERMITIDO_REPRESENTANTE_LEGAL_CET, 1, 'CET', 'XXX') AS D3
                          FROM DUAL) UNPIVOT(VALOR FOR COL IN(D1, D2, D3)) D);
        IF intCount = 0 THEN
          blElegibilidad := FALSE;
          intErrores     := intErrores + 1;
          vcErrores      := vcErrores || 'en Campo 10 : ' || stSolRepL(01).VC_DESCRIPCION || ', > El Tipo Documento permitido para el Representante Legal no es válido, ''' || TRIM(REG_SD.VC_TIPO_DOCUMENTO_REPLEG) || ''' no esta permitido.' || vcEnter;
        END IF;

        --Número de documento RL
        IF ((TRIM(REG_SD.VC_TIPO_DOCUMENTO_REPLEG) = 'DNI' AND LENGTH(TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG)) = 8) OR
            (TRIM(REG_SD.VC_TIPO_DOCUMENTO_REPLEG) = 'RUC' AND LENGTH(TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG)) = 11) OR
            (TRIM(REG_SD.VC_TIPO_DOCUMENTO_REPLEG) = 'CET' AND (LENGTH(TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG)) >= 9 AND LENGTH(TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG)) <= 12))) THEN
          blValidacion := TRUE;
        ELSE
          blElegibilidad := FALSE;
          intErrores     := intErrores + 1;
          vcErrores      := vcErrores || 'en Campo 11 : ' || stSolRepL(02).VC_DESCRIPCION || ', > El tamaño de ''' || TRIM(REG_SD.VC_TIPO_DOCUMENTO_REPLEG) || ''' es incorrecto.' || vcEnter;
        END IF;

        SELECT COUNT(1)
          INTO intCount
          FROM SOLICITUD_REPLEG SR
         WHERE SR.INT_IDSOLICITUD = p_intIdSolicitud
           AND SR.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO;
        IF intCount > 0 THEN
          intErroresRL := 0;
          vcErroresRL  := vcEnter;
          FOR REC_SR IN (SELECT SR.INT_IDSOLICITUD,
                                SR.VC_NUMERO_DOCUMENTO,
                                SR.VC_TIPO_DOCUMENTO_REPLEG,
                                SR.VC_NUMERO_DOCUMENTO_REPLEG,
                                SR.VC_NOMBRES_REPLEG,
                                SR.VC_APELLIDOS_REPLEG,
                                SR.VC_CARGO_REPLEG
                           FROM SOLICITUD_REPLEG SR
                          WHERE SR.INT_IDSOLICITUD = p_intIdSolicitud
                            AND SR.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO) LOOP
            SELECT COUNT(1)
              INTO intCount
              FROM DUAL
             WHERE TRIM(REC_SR.VC_TIPO_DOCUMENTO_REPLEG) IN
                   (SELECT D.VALOR
                      FROM (SELECT DECODE(recBRP.CH_ES_VALIDACION_TIPO_DOCUMENTO_PERMITIDO_REPRESENTANTE_LEGAL_DNI, 1, 'DNI', 'XXX') AS D1,
                                   DECODE(recBRP.CH_ES_VALIDACION_TIPO_DOCUMENTO_PERMITIDO_REPRESENTANTE_LEGAL_RUC, 1, 'RUC', 'XXX') AS D2,
                                   DECODE(recBRP.CH_ES_VALIDACION_TIPO_DOCUMENTO_PERMITIDO_REPRESENTANTE_LEGAL_CET, 1, 'CET', 'XXX') AS D3
                              FROM DUAL) UNPIVOT(VALOR FOR COL IN(D1, D2, D3)) D);
            IF intCount = 0 THEN
              blElegibilidad := FALSE;
              intErroresRL   := intErroresRL + 1;
              vcErroresRL    := vcErroresRL || 'en Campo 02 : ' || stRepLega(02).VC_DESCRIPCION || ', > El Tipo Documento permitido para el Representante Legal no es válido, ''' || TRIM(REC_SR.VC_TIPO_DOCUMENTO_REPLEG) || ''' no esta permitido.' || vcEnter;
            END IF;

            --Número de documento RL
            IF ((TRIM(REC_SR.VC_TIPO_DOCUMENTO_REPLEG) = 'DNI' AND LENGTH(TRIM(REC_SR.VC_NUMERO_DOCUMENTO_REPLEG)) = 8) OR
               (TRIM(REC_SR.VC_TIPO_DOCUMENTO_REPLEG) = 'RUC' AND LENGTH(TRIM(REC_SR.VC_NUMERO_DOCUMENTO_REPLEG)) = 11) OR
               (TRIM(REC_SR.VC_TIPO_DOCUMENTO_REPLEG) = 'CET' AND (LENGTH(TRIM(REC_SR.VC_NUMERO_DOCUMENTO_REPLEG)) >= 9 AND LENGTH(TRIM(REC_SR.VC_NUMERO_DOCUMENTO_REPLEG)) <= 12))) THEN
              blValidacion := TRUE;
            ELSE
              blElegibilidad := FALSE;
              intErroresRL   := intErroresRL + 1;
              vcErroresRL    := vcErroresRL || 'en Campo 03 : ' || stRepLega(03).VC_DESCRIPCION || ', > El tamaño número del documento ''' || TRIM(REC_SR.VC_TIPO_DOCUMENTO_REPLEG) || ''' -> ''' || TRIM(REC_SR.VC_NUMERO_DOCUMENTO_REPLEG) || ''' es incorrecto.' || vcEnter;
            END IF;

            IF TRIM(REC_SR.VC_CARGO_REPLEG) IN ('GE', 'JA', 'AN', 'ADM', 'TIT', 'OTR') THEN
              blValidacion := TRUE;
            ELSE
              blElegibilidad := FALSE;
              intErroresRL   := intErroresRL + 1;
              vcErroresRL    := vcErroresRL || 'en Campo 06 : ' || stRepLega(06).VC_DESCRIPCION || ', ' || TRIM(REC_SR.VC_CARGO_REPLEG) || ', > Cargo debe ser ''GE'',''JA'',''AN'',''ADM'',''TIT'',''OTR''.' || vcEnter;
            END IF;

            IF intErroresRL > 0 THEN
              UPDATE SOLICITUD_REPLEG SRL
                 SET SRL.OBSERVACIONES = 'Errores ' || vcErroresRL
               WHERE SRL.INT_IDSOLICITUD = REC_SR.INT_IDSOLICITUD
                 AND SRL.VC_NUMERO_DOCUMENTO = REC_SR.VC_NUMERO_DOCUMENTO
                 AND SRL.VC_TIPO_DOCUMENTO_REPLEG = REC_SR.VC_TIPO_DOCUMENTO_REPLEG
                 AND SRL.VC_NUMERO_DOCUMENTO_REPLEG = REC_SR.VC_NUMERO_DOCUMENTO_REPLEG;
              intErrores := intErrores + intErroresRL;
              vcErrores  := vcErrores || 'Inicio en Anexo Representante Legal' || vcErroresRL || 'Fin en Anexo Representante Legal' || vcEnter;
            ELSE
              UPDATE SOLICITUD_REPLEG SRL
                 SET SRL.OBSERVACIONES = 'OK'
               WHERE SRL.INT_IDSOLICITUD = REC_SR.INT_IDSOLICITUD
                 AND SRL.VC_NUMERO_DOCUMENTO = REC_SR.VC_NUMERO_DOCUMENTO
                 AND SRL.VC_TIPO_DOCUMENTO_REPLEG = REC_SR.VC_TIPO_DOCUMENTO_REPLEG
                 AND SRL.VC_NUMERO_DOCUMENTO_REPLEG = REC_SR.VC_NUMERO_DOCUMENTO_REPLEG;
            END IF;
          END LOOP;
        END IF;
      END IF;

      --Nro de documento permitidos Representante Legal
      IF TRIM(REG_SD.VC_TIPO_DOCUMENTO) = 'RUC' AND SUBSTR(TRIM(REG_SD.VC_NUMERO_DOCUMENTO), 1, 2) = '10' THEN
        IF TRIM(REG_SD.VC_TIPO_DOCUMENTO_REPLEG) = 'DNI' THEN
          IF PKG_BASE.F_CONVERTIR_RUC_A_DNI(TRIM(REG_SD.VC_NUMERO_DOCUMENTO)) = TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG) THEN
            IF TRIM(REG_SD.VC_NUMERO_DOCUMENTO) = PKG_BASE.F_CONVERTIR_DNI_A_RUC(TRIM(REG_SD.VC_NUMERO_DOCUMENTO_REPLEG)) THEN
              blValidacion := TRUE;
            ELSE
              blElegibilidad := FALSE;
              intErrores     := intErrores + 1;
              vcErrores      := vcErrores || 'en Campo 11 : ' || stSolRepL(02).VC_DESCRIPCION || ', > El numero de DNI del representante legal no coincide con la persona del RUC ''' || TRIM(REG_SD.VC_NUMERO_DOCUMENTO) || ''', revisar Digito Verificador del RUC.' || vcEnter;
            END IF;
          ELSE
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores || 'en Campo 11 : ' || stSolRepL(02).VC_DESCRIPCION || ', > El numero de DNI del representante legal no coincide con la persona del RUC ''' || TRIM(REG_SD.VC_NUMERO_DOCUMENTO) || '''.' || vcEnter;
          END IF;
        ELSE
          blElegibilidad := FALSE;
          intErrores     := intErrores + 1;
          vcErrores      := vcErrores || 'en Campo 10 : ' || stSolRepL(01).VC_DESCRIPCION || ', > El Tipo Documento permitido para el Representante Legal no es válido, ''' || TRIM(REG_SD.VC_TIPO_DOCUMENTO_REPLEG) || '''  no esta permitido cuando el Tipo Documento del beneficiario es RUC 10.' || vcEnter;
        END IF;
      END IF;
      ----------------------------------------------------------------------------------------------------
      --Clasificador Deudor
      ----------------------------------------------------------------------------------------------------
      -- SI Clasificador Deudor esta ON
      IF recBRP.CH_ES_VALIDACION_CALIFICACION_DEUDOR_CALIFICACION = 1 THEN
        -- Si integración RCC está ON
        IF recBRP.CH_ES_VALIDACION_CALIFICACION_DEUDOR_INTEGRACION_RCC = 1 THEN

          --Si el flag Convertir por tipo Doc está ON
          IF recBRP.CH_ES_VALIDACION_CALIFICACION_DEUDOR_AGRUPA_TIPODOC = 1 THEN
            -- Si es DNI convertir a RUC
            IF REG_SD.VC_TIPO_DOCUMENTO = 'DNI' THEN
              vcDocConvertido := PKG_BASE.F_CONVERTIR_DNI_A_RUC(REG_SD.VC_NUMERO_DOCUMENTO);
            -- Si es RUC 10 convertir a DNI
            ELSIF REG_SD.VC_TIPO_DOCUMENTO = 'RUC' AND SUBSTR(REG_SD.VC_NUMERO_DOCUMENTO, 1, 2) = '10' THEN
              vcDocConvertido := PKG_BASE.F_CONVERTIR_RUC_A_DNI(REG_SD.VC_NUMERO_DOCUMENTO);
            END IF;
          --Si el flag Convertir por tipo Doc está OFF
          ELSE
            vcDocConvertido := NULL;
          END IF;

          --Buscar por número de documento
          intCount     := 0;
          intCountDoc1 := 0;
          intCountDoc2 := 0;

          SELECT COUNT(DISTINCT T.COD_DEU)
            INTO intCountDoc1
            FROM ETL_RCC_IDCLI_TMP T
           WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
             AND T.COD_DOC_ID = REG_SD.VC_NUMERO_DOCUMENTO;

          IF intCountDoc1 = 0 THEN
            SELECT COUNT(DISTINCT T.COD_DEU)
              INTO intCountDoc2
              FROM ETL_RCC_IDCLI_TMP T
             WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
               AND T.COD_DOC_TRIB = REG_SD.VC_NUMERO_DOCUMENTO;
             intCount := intCountDoc2;
          ELSE
             intCount := intCountDoc1;
          END IF;

          --Buscar por número de documento calculado Si el flag Convertir por tipo Doc está ON
          intCountDocConver  := 0;
          intCountDocConver1 := 0;
          intCountDocConver2 := 0;
          IF recBRP.CH_ES_VALIDACION_CALIFICACION_DEUDOR_AGRUPA_TIPODOC = 1 THEN
            IF LENGTH(vcDocConvertido) >= 8 THEN
              SELECT COUNT(DISTINCT T.COD_DEU)
                INTO intCountDocConver1
                FROM ETL_RCC_IDCLI_TMP T
               WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                 AND T.COD_DOC_ID = vcDocConvertido;

              IF intCountDocConver1 = 0 THEN
                SELECT COUNT(DISTINCT T.COD_DEU)
                  INTO intCountDocConver2
                  FROM ETL_RCC_IDCLI_TMP T
                 WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                   AND T.COD_DOC_TRIB = vcDocConvertido;
                 intCountDocConver := intCountDocConver2;
              ELSE
                 intCountDocConver := intCountDocConver1;
              END IF;
            END IF;
          END IF;

          --Si se obtiene más de 1 código de deudor
          IF intCount > 1 OR intCountDocConver > 1 THEN
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores || 'Se ha identificado un registro inconsistente en la SBS - Regla: Clasificador Deudor' || vcEnter;
          ELSE
            --Si código de deudor no existe
            IF intCount = 0 AND intCountDocConver = 0 THEN
              blClasificadorValido := TRUE;
              intClasificadorTipo  := 3;
            --Si se obtiene al menos 1 código de deudor
            ELSIF intCount > 0 OR intCountDocConver > 0 THEN

              IF intCount > 0 THEN
                vcCodDeuDoc := ' ';
                IF intCountDoc1 = 1 THEN
                  SELECT T.COD_DEU
                    INTO vcCodDeuDoc
                    FROM ETL_RCC_IDCLI_TMP T
                   WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                     AND T.COD_DOC_ID = REG_SD.VC_NUMERO_DOCUMENTO;
                ELSE
                  SELECT T.COD_DEU
                    INTO vcCodDeuDoc
                    FROM ETL_RCC_IDCLI_TMP T
                   WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                     AND T.COD_DOC_TRIB = REG_SD.VC_NUMERO_DOCUMENTO;
                END IF;          


              ELSE
                vcCodDeuDoc := NULL;
              END IF;

              IF intCountDocConver > 0 THEN
                vcCodDeuDocConVer := ' ';
                IF intCountDocConver1 = 1 THEN
                  SELECT T.COD_DEU
                    INTO vcCodDeuDocConVer
                    FROM ETL_RCC_IDCLI_TMP T
                   WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                     AND T.COD_DOC_ID = vcDocConvertido;
                ELSE
                  SELECT T.COD_DEU
                    INTO vcCodDeuDocConVer
                    FROM ETL_RCC_IDCLI_TMP T
                   WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                     AND T.COD_DOC_TRIB = vcDocConvertido;
                END IF;
              ELSE
                vcCodDeuDocConVer := NULL;
              END IF;

              IF vcCodDeuDoc = vcCodDeuDocConVer THEN
                vcCodDeuDocConVer := ' ';
              END IF;

              SELECT COUNT(1)
                INTO intCount
                FROM ETL_RCC_MVCLI_TMP T
               WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                 AND T.COD_DEU IN (vcCodDeuDoc, vcCodDeuDocConVer );

              --Si código de deudor no existe en RCC
              IF intCount = 0 THEN
                blClasificadorValido := TRUE;
                intClasificadorTipo  := 3;
              --Si código de deudor existe en RCC
              ELSE
                intValCodDeudor := 0;
                FOR REC_RCC_MVCLI IN (SELECT DISTINCT T.COD_DEU AS COD_DEU , DECODE(T.COD_DEU, vcCodDeuDoc, 1, vcCodDeuDocConVer, 2, 3)
                                        FROM ETL_RCC_MVCLI_TMP T
                                       WHERE T.INT_IDSOLICITUD = p_intIdSolicitud AND T.COD_DEU IN (vcCodDeuDoc, vcCodDeuDocConVer )
                                       ORDER BY DECODE(T.COD_DEU, vcCodDeuDoc, 1, vcCodDeuDocConVer, 2, 3) ) LOOP
                  intPeriodoMax    := 0;
                  intDeudor        := 0;
                  intContadorTipo1 := 0;
                  intContadorTipo2 := 0;
                  intContadorTipo3 := 0;

                  --Obtener el último periodo disponible
                  SELECT MAX(T.PERIODO)
                    INTO intPeriodoMax
                    FROM ETL_RCC_MVCLI_TMP T
                   WHERE T.INT_IDSOLICITUD = p_intIdSolicitud;

                    --Obtener calificación en el último Periodo Disponible para el codigo de deudor                    
                    SELECT Count(1)
                    INTO intCount
                    FROM ETL_RCC_MVCLI_TMP T
                    WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                    AND T.PERIODO = intPeriodoMax
                    AND T.COD_DEU = REC_RCC_MVCLI.COD_DEU;
            
                    --Si clasifica para busqueda historica si no encuentra en periodo disponible
                    blClasificadorHisto := FALSE;

                    --Si se encuentra la calificación en el Periodo Disponible
                    IF intCount > 0 THEN
                      IF intValCodDeudor = 0 THEN
                        FOR REC_RCC_MVCLIDET IN (SELECT T.PERIODO, --: AÑO Y MES DE LA CALIFICACIÓN
                                                        T.COD_DEU, --: CÓDIGO DEL DEUDOR, PARA UBICAR AL CLIENTE EVALUADO
                                                        NVL(T.CAN_ENTS, 0) AS CAN_ENTS, --: CANTIDAD DE ENTIDADES
                                                        NVL(T.CALIF_0, 0) AS CALIF_0,
                                                        NVL(T.CALIF_1, 0) AS CALIF_1,
                                                        NVL(T.CALIF_2, 0) AS CALIF_2,
                                                        NVL(T.CALIF_3, 0) AS CALIF_3,
                                                        NVL(T.CALIF_4, 0) AS CALIF_4,
                                                        DECODE(recBRP.CH_ES_VALIDACION_CALIFICACION_DEUDOR_NORMAL, 1, NVL(T.CALIF_0, 0), 0) +
                                                        DECODE(recBRP.CH_ES_VALIDACION_CALIFICACION_DEUDOR_CPP, 1, NVL(T.CALIF_1, 0), 0) +
                                                        DECODE(recBRP.CH_ES_VALIDACION_CALIFICACION_DEUDOR_DEFICIENTE, 1, NVL(T.CALIF_2, 0), 0) +
                                                        DECODE(recBRP.CH_ES_VALIDACION_CALIFICACION_DEUDOR_DUDOSO, 1, NVL(T.CALIF_3, 0), 0) +
                                                        DECODE(recBRP.CH_ES_VALIDACION_CALIFICACION_DEUDOR_PERDIDA, 1, NVL(T.CALIF_4, 0), 0) AS CALIF_TOTAL,
                                                        NVL(T.CALIF_0, 0) + NVL(T.CALIF_1, 0) + NVL(T.CALIF_2, 0) + NVL(T.CALIF_3, 0) + NVL(T.CALIF_4, 0) AS CALIF_FULL
                                                   FROM ETL_RCC_MVCLI_TMP T
                                                  WHERE T.INT_IDSOLICITUD = p_intIdSolicitud
                                                    AND T.PERIODO = intPeriodoMax
                                                    AND T.COD_DEU = REC_RCC_MVCLI.COD_DEU
                                                  ORDER BY T.PERIODO DESC) LOOP
                          intClasificadorTipo := 1;
                          intContadorTipo1 := 1;
                          --Si la calificación seleccionada o suma de calificación seleccionada es mayor igual al parámetro configurado (Sumatoria mayor igual a) en el Periodo disponible
                          IF REC_RCC_MVCLIDET.CALIF_TOTAL >= recBRP.INT_VALIDACION_CALIFICACION_DEUDOR_SUMATORIA THEN
                            blClasificadorValido := TRUE;
                          ELSE
                           IF REC_RCC_MVCLIDET.CALIF_FULL > 0 THEN
                             intValCodDeudor:= intValCodDeudor + 1;
                             blClasificadorValido := FALSE;
                             blElegibilidad := FALSE;
                             intErrores     := intErrores + 1;
                             intDeudor      := 1;
                             vcErrores      := vcErrores || 'CALIF_TOTAL  : ' || REC_RCC_MVCLIDET.CALIF_TOTAL || ' - PROD. SUMATORIA  : ' || recBRP.INT_VALIDACION_CALIFICACION_DEUDOR_SUMATORIA || ' Código Deudor  : ' || TRIM(REC_RCC_MVCLIDET.COD_DEU) || ', Periodo : ' || TRIM(TO_CHAR(REC_RCC_MVCLIDET.PERIODO)) || ', > No se ha cumplido el criterio de calificación de deudor.' || vcEnter;
                           ELSIF REC_RCC_MVCLIDET.CALIF_FULL = 0 THEN
                             intClasificadorTipo  := 3;
                             blClasificadorHisto := TRUE;
                            END IF;
                          END IF;
                          MERGE INTO SOLICITUD_DETALLE_CLASIFICACION_DEUDOR D
                          USING (SELECT REG_SD.INT_IDSOLICITUD      AS INT_IDSOLICITUD,
                                        REG_SD.INT_IDSOLICITUD_DET  AS INT_IDSOLICITUD_DET,
                                        REC_RCC_MVCLIDET.PERIODO     AS PERIODO,
                                        REC_RCC_MVCLIDET.COD_DEU     AS COD_DEU,
                                        REC_RCC_MVCLIDET.CAN_ENTS    AS CAN_ENTS,
                                        REC_RCC_MVCLIDET.CALIF_0     AS CALIF_0,
                                        REC_RCC_MVCLIDET.CALIF_1     AS CALIF_1,
                                        REC_RCC_MVCLIDET.CALIF_2     AS CALIF_2,
                                        REC_RCC_MVCLIDET.CALIF_3     AS CALIF_3,
                                        REC_RCC_MVCLIDET.CALIF_4     AS CALIF_4,
                                        REC_RCC_MVCLIDET.CALIF_TOTAL AS CALIF_TOTAL,
                                        intClasificadorTipo          AS TIPO
                                   FROM DUAL) O
                          ON (D.INT_IDSOLICITUD = O.INT_IDSOLICITUD AND D.INT_IDSOLICITUD_DET = O.INT_IDSOLICITUD_DET AND D.PERIODO = O.PERIODO AND D.COD_DEU = O.COD_DEU)
                          WHEN MATCHED THEN
                            UPDATE
                               SET D.CAN_ENTS           = O.CAN_ENTS,
                                   D.CALIF_0_NORMAL     = O.CALIF_0,
                                   D.CALIF_1_CPP        = O.CALIF_1,
                                   D.CALIF_2_DEFICIENTE = O.CALIF_2,
                                   D.CALIF_3_DUDOSO     = O.CALIF_3,
                                   D.CALIF_4_PERDIDA    = O.CALIF_4,
                                   D.CALIF_TOTAL        = O.CALIF_TOTAL,
                                   D.TIPO               = O.TIPO
                          WHEN NOT MATCHED THEN
                            INSERT
                              (INT_IDSOLICITUD,
                               INT_IDSOLICITUD_DET,
                               PERIODO,
                               COD_DEU,
                               CAN_ENTS,
                               CALIF_0_NORMAL,
                               CALIF_1_CPP,
                               CALIF_2_DEFICIENTE,
                               CALIF_3_DUDOSO,
                               CALIF_4_PERDIDA,
                               CALIF_TOTAL,
                               TIPO)
                            VALUES
                              (O.INT_IDSOLICITUD,
                               O.INT_IDSOLICITUD_DET,
                               O.PERIODO,
                               O.COD_DEU,
                               O.CAN_ENTS,
                               O.CALIF_0,
                               O.CALIF_1,
                               O.CALIF_2,
                               O.CALIF_3,
                               O.CALIF_4,
                               O.CALIF_TOTAL,
                               O.TIPO);
                          COMMIT;
                        END LOOP;
                      END IF;
                    END IF;
                    --Si no se encuentra la calificación en el Periodo Disponible, o no se calificó en el periodo Disponible
                    IF (intCount = 0 OR blClasificadorHisto = TRUE) AND intValCodDeudor = 0  THEN
                      blClasificadorValido := FALSE;
                      intClasificadorTipo  := 0;
                      --(Revisión Data Historia = ON)
                      IF recBRP.CH_ES_VALIDACION_CALIFICACION_DEUDOR_REVISION_HISTORI = 1 THEN
                        FOR REC_RCC_MVCLIDET_HIST IN (SELECT D.PERIODO, --: AÑO Y MES DE LA CALIFICACIÓN
                                                             T.COD_DEU, --: CÓDIGO DEL DEUDOR, PARA UBICAR AL CLIENTE EVALUADO
                                                             NVL(T.CAN_ENTS, 0) AS CAN_ENTS, --: CANTIDAD DE ENTIDADES
                                                             NVL(T.CALIF_0, 0) AS CALIF_0,
                                                             NVL(T.CALIF_1, 0) AS CALIF_1,
                                                             NVL(T.CALIF_2, 0) AS CALIF_2,
                                                             NVL(T.CALIF_3, 0) AS CALIF_3,
                                                             NVL(T.CALIF_4, 0) AS CALIF_4,
                                                             DECODE(recBRP.CH_ES_VALIDACION_REVISION_HISTORICA_NORMAL, 1, NVL(CALIF_0, 0), 0) +
                                                             DECODE(recBRP.CH_ES_VALIDACION_REVISION_HISTORICA_CPP, 1, NVL(CALIF_1, 0), 0) +
                                                             DECODE(recBRP.CH_ES_VALIDACION_REVISION_HISTORICA_DEFICIENTE, 1, NVL(CALIF_2, 0), 0) +
                                                             DECODE(recBRP.CH_ES_VALIDACION_REVISION_HISTORICA_DUDOSO, 1, NVL(CALIF_3, 0), 0) +
                                                             DECODE(recBRP.CH_ES_VALIDACION_REVISION_HISTORICA_PERDIDA, 1, NVL(CALIF_4, 0), 0) AS CALIF_TOTAL,
                                                             NVL(T.CALIF_0, 0) + NVL(T.CALIF_1, 0) + NVL(T.CALIF_2, 0) + NVL(T.CALIF_3, 0) + NVL(T.CALIF_4, 0) AS CALIF_FULL
                                                        FROM (SELECT TO_NUMBER(TO_CHAR(ADD_MONTHS(TO_DATE(TRIM(TO_CHAR(intPeriodoMax)), 'YYYYMM'), -LEVEL + 1), 'YYYYMM')) AS PERIODO
                                                                FROM DUAL
                                                              CONNECT BY LEVEL <= recBRP.INT_VALIDACION_REVISION_HISTORICA_MESES) D
                                                        LEFT JOIN ETL_RCC_MVCLI_TMP T
                                                          ON ( T.INT_IDSOLICITUD = p_intIdSolicitud AND T.PERIODO = D.PERIODO AND T.COD_DEU = REC_RCC_MVCLI.COD_DEU)
                                                       ORDER BY D.PERIODO DESC) LOOP
                          intClasificadorTipo := 2;
                          --Si el código deudor no existe o la suma de todas sus calificaciones es 0  o no se encuentra información
                          IF REC_RCC_MVCLIDET_HIST.COD_DEU IS NULL OR REC_RCC_MVCLIDET_HIST.CALIF_FULL = 0 THEN
                             IF NOT blClasificadorValido THEN-- Solo para la primera vez que lo encuentre
                               intClasificadorTipo := 3;
                               blClasificadorValido := TRUE; --Flag_Valido =True
                               intClaPeriodo        := REC_RCC_MVCLIDET_HIST.PERIODO;
                               vcClaCodDeu          := REC_RCC_MVCLI.COD_DEU;
                               intClaCanEnts        := REC_RCC_MVCLIDET_HIST.CAN_ENTS;
                               intClaCalif0         := REC_RCC_MVCLIDET_HIST.CALIF_0;
                               intClaCalif1         := REC_RCC_MVCLIDET_HIST.CALIF_1;
                               intClaCalif2         := REC_RCC_MVCLIDET_HIST.CALIF_2;
                               intClaCalif3         := REC_RCC_MVCLIDET_HIST.CALIF_3;
                               intClaCalif4         := REC_RCC_MVCLIDET_HIST.CALIF_4;
                               intClaCalifTotal     := REC_RCC_MVCLIDET_HIST.CALIF_TOTAL;
                               intClaTipo           := intClasificadorTipo;
                             END IF;
                           ELSE
                             IF REC_RCC_MVCLIDET_HIST.COD_DEU IS NOT NULL THEN
                               --Si la calificación seleccionada o suma de calificación seleccionada es mayor igual al parámetro
                               --configurado (Sumatoria mayor igual a de la Revisión Data Histórica)
                               IF REC_RCC_MVCLIDET_HIST.CALIF_TOTAL >= recBRP.DEC_VALIDACION_REVISION_HISTORICA_SUMATORIA THEN
                                 --Contador Tipo 2= Contador Tipo2 +1
                                 intContadorTipo2 := intContadorTipo2 + 1;
                                 intClasificadorTipo := 2;
                                 IF intContadorTipo2 = 1 THEN
                                   blClasificadorValido := TRUE; --Flag_Valido =True
                                   intClaPeriodo        := REC_RCC_MVCLIDET_HIST.PERIODO;
                                   vcClaCodDeu          := REC_RCC_MVCLIDET_HIST.COD_DEU;
                                   intClaCanEnts        := REC_RCC_MVCLIDET_HIST.CAN_ENTS;
                                   intClaCalif0         := REC_RCC_MVCLIDET_HIST.CALIF_0;
                                   intClaCalif1         := REC_RCC_MVCLIDET_HIST.CALIF_1;
                                   intClaCalif2         := REC_RCC_MVCLIDET_HIST.CALIF_2;
                                   intClaCalif3         := REC_RCC_MVCLIDET_HIST.CALIF_3;
                                   intClaCalif4         := REC_RCC_MVCLIDET_HIST.CALIF_4;
                                   intClaCalifTotal     := REC_RCC_MVCLIDET_HIST.CALIF_TOTAL;
                                   intClaTipo           := intClasificadorTipo;
                                 END IF;
                               ELSE
                                 intValCodDeudor:= intValCodDeudor + 1;
                                 blElegibilidad := FALSE;
                                 intErrores     := intErrores + 1;
                                 vcErrores      := vcErrores || 'CALIF_TOTAL  : ' || REC_RCC_MVCLIDET_HIST.CALIF_TOTAL || ' - PROD. SUMATORIA : ' || recBRP.DEC_VALIDACION_REVISION_HISTORICA_SUMATORIA || ' - Código Deudor Histórico : ' || TRIM(REC_RCC_MVCLIDET_HIST.COD_DEU) || ', Periodo : ' || TRIM(TO_CHAR(REC_RCC_MVCLIDET_HIST.PERIODO)) || ', > No se ha cumplido el criterio de calificación de deudor.' || vcEnter;
                                 blClasificadorValido := FALSE;
                                 IF REC_RCC_MVCLIDET_HIST.CALIF_FULL = 0 THEN
                                   intClasificadorTipo := 3;
                                 ELSE
                                   --Contador Tipo 2= Contador Tipo2 +1
                                   intContadorTipo2 := intContadorTipo2 + 1;
                                   intClasificadorTipo := 2;
                                 END IF;
                                 --El aplicativo guardará el periodo y todas las calificaciones.
                                 MERGE INTO SOLICITUD_DETALLE_CLASIFICACION_DEUDOR D
                                 USING (SELECT REG_SD.INT_IDSOLICITUD            AS INT_IDSOLICITUD,
                                               REG_SD.INT_IDSOLICITUD_DET        AS INT_IDSOLICITUD_DET,
                                               REC_RCC_MVCLIDET_HIST.PERIODO     AS PERIODO,
                                               REC_RCC_MVCLIDET_HIST.COD_DEU     AS COD_DEU,
                                               REC_RCC_MVCLIDET_HIST.CAN_ENTS    AS CAN_ENTS,
                                               REC_RCC_MVCLIDET_HIST.CALIF_0     AS CALIF_0,
                                               REC_RCC_MVCLIDET_HIST.CALIF_1     AS CALIF_1,
                                               REC_RCC_MVCLIDET_HIST.CALIF_2     AS CALIF_2,
                                               REC_RCC_MVCLIDET_HIST.CALIF_3     AS CALIF_3,
                                               REC_RCC_MVCLIDET_HIST.CALIF_4     AS CALIF_4,
                                               REC_RCC_MVCLIDET_HIST.CALIF_TOTAL AS CALIF_TOTAL,
                                               intClasificadorTipo               AS TIPO
                                          FROM DUAL) O
                                 ON (D.INT_IDSOLICITUD = O.INT_IDSOLICITUD AND D.INT_IDSOLICITUD_DET = O.INT_IDSOLICITUD_DET AND D.PERIODO = O.PERIODO AND D.COD_DEU = O.COD_DEU)
                                 WHEN MATCHED THEN
                                   UPDATE
                                      SET D.CAN_ENTS           = O.CAN_ENTS,
                                          D.CALIF_0_NORMAL     = O.CALIF_0,
                                          D.CALIF_1_CPP        = O.CALIF_1,
                                          D.CALIF_2_DEFICIENTE = O.CALIF_2,
                                          D.CALIF_3_DUDOSO     = O.CALIF_3,
                                          D.CALIF_4_PERDIDA    = O.CALIF_4,
                                          D.CALIF_TOTAL        = O.CALIF_TOTAL,
                                          D.TIPO               = O.TIPO
                                 WHEN NOT MATCHED THEN
                                   INSERT
                                     (INT_IDSOLICITUD,
                                      INT_IDSOLICITUD_DET,
                                      PERIODO,
                                      COD_DEU,
                                      CAN_ENTS,
                                      CALIF_0_NORMAL,
                                      CALIF_1_CPP,
                                      CALIF_2_DEFICIENTE,
                                      CALIF_3_DUDOSO,
                                      CALIF_4_PERDIDA,
                                      CALIF_TOTAL,
                                      TIPO)
                                   VALUES
                                     (O.INT_IDSOLICITUD,
                                      O.INT_IDSOLICITUD_DET,
                                      O.PERIODO,
                                      O.COD_DEU,
                                      O.CAN_ENTS,
                                      O.CALIF_0,
                                      O.CALIF_1,
                                      O.CALIF_2,
                                      O.CALIF_3,
                                      O.CALIF_4,
                                      O.CALIF_TOTAL,
                                      O.TIPO);
                                 COMMIT;
                               END IF;
                             END IF;
                           END IF;
                       END LOOP;
                        --Si Flag_Valido =True
                         IF blClasificadorValido THEN
                           --El aplicativo guardará el periodo más actualizado y todas las calificaciones
                            MERGE INTO SOLICITUD_DETALLE_CLASIFICACION_DEUDOR D
                            USING (SELECT REG_SD.INT_IDSOLICITUD     AS INT_IDSOLICITUD,
                                          REG_SD.INT_IDSOLICITUD_DET AS INT_IDSOLICITUD_DET,
                                          intClaPeriodo              AS PERIODO,
                                          vcClaCodDeu                AS COD_DEU,
                                          intClaCanEnts              AS CAN_ENTS,
                                          intClaCalif0               AS CALIF_0,
                                          intClaCalif1               AS CALIF_1,
                                          intClaCalif2               AS CALIF_2,
                                          intClaCalif3               AS CALIF_3,
                                          intClaCalif4               AS CALIF_4,
                                          intClaCalifTotal           AS CALIF_TOTAL,
                                          intClaTipo                 AS TIPO
                                     FROM DUAL) O
                            ON (D.INT_IDSOLICITUD = O.INT_IDSOLICITUD AND D.INT_IDSOLICITUD_DET = O.INT_IDSOLICITUD_DET AND D.PERIODO = O.PERIODO AND D.COD_DEU = O.COD_DEU)
                            WHEN MATCHED THEN
                              UPDATE
                                 SET D.CAN_ENTS           = O.CAN_ENTS,
                                     D.CALIF_0_NORMAL     = O.CALIF_0,
                                     D.CALIF_1_CPP        = O.CALIF_1,
                                     D.CALIF_2_DEFICIENTE = O.CALIF_2,
                                     D.CALIF_3_DUDOSO     = O.CALIF_3,
                                     D.CALIF_4_PERDIDA    = O.CALIF_4,
                                     D.CALIF_TOTAL        = O.CALIF_TOTAL,
                                     D.TIPO               = O.TIPO
                            WHEN NOT MATCHED THEN
                              INSERT
                                (INT_IDSOLICITUD,
                                 INT_IDSOLICITUD_DET,
                                 PERIODO,
                                 COD_DEU,
                                 CAN_ENTS,
                                 CALIF_0_NORMAL,
                                 CALIF_1_CPP,
                                 CALIF_2_DEFICIENTE,
                                 CALIF_3_DUDOSO,
                                 CALIF_4_PERDIDA,
                                 CALIF_TOTAL,
                                 TIPO)
                              VALUES
                                (O.INT_IDSOLICITUD,
                                 O.INT_IDSOLICITUD_DET,
                                 O.PERIODO,
                                 O.COD_DEU,
                                 O.CAN_ENTS,
                                 O.CALIF_0,
                                 O.CALIF_1,
                                 O.CALIF_2,
                                 O.CALIF_3,
                                 O.CALIF_4,
                                 O.CALIF_TOTAL,
                                 O.TIPO);
                            COMMIT;
                          END IF;
                          IF intContadorTipo2 > 0 THEN
                            intClasificadorTipo := 2;
                          ELSE
                            intClasificadorTipo := 3;
                          END IF;
                      --(Revisión Data Historia = OFF)
                      ELSE
                        blClasificadorValido := TRUE;
                        intClasificadorTipo  := 3;
                      END IF;
                    END IF;
                END LOOP;
              END IF;
            END IF;
            -- Actualizar Tipo de Clasificador
            UPDATE SOLICITUD_DETALLE SD
               SET SD.TIPO = intClasificadorTipo
             WHERE SD.INT_IDSOLICITUD = REG_SD.INT_IDSOLICITUD
               AND SD.INT_IDSOLICITUD_DET = REG_SD.INT_IDSOLICITUD_DET;
            COMMIT;
          END IF;
        -- Si integración RCC está OFF
        ELSE
           blClasificadorValido := TRUE;--BORRAR
        END IF;
      END IF;
      ----------------------------------------------------------------------------------------------------
      -- Beneficiario en otro programa
      ----------------------------------------------------------------------------------------------------
      IF recBRP.CH_ES_VALIDACION_BENEFICIARIO_OTROS_PROGRAMAS_HONRAS = 1 THEN
        IF recBRP.CH_ES_VALIDACION_BENEFICIARIO_OTROS_PROGRAMAS_CONVER_TIP_DOC = 1 THEN
          FOR REC_RCC_HONRAS IN (SELECT VP.INT_IDPROD,
                                        VP.VC_CODPROD,
                                        VP.VC_DESCRIPCION,
                                        VP.INT_CODIGO,
                                        VP.SAP_CODIGO
                                   FROM US_BASE.V_BASE_REGLA_PRODUCTO_PROGRAMA VP
                                  INNER JOIN SOLICITUD S ON (VP.INT_IDPROD = S.INT_IDPRODUCTO)
                                  WHERE S.INT_IDSOLICITUD = p_intIdSolicitud) LOOP
            SELECT COUNT(1)
              INTO intCount
              FROM SOLICITUD_HONRAS SH
             WHERE SH.INT_IDSOLICITUD = REG_SD.INT_IDSOLICITUD
               AND SH.GSART = REC_RCC_HONRAS.SAP_CODIGO
               AND (SH.TAXNUM = REG_SD.VC_NUMERO_DOCUMENTO OR
                   (SH.TAXNUM = PKG_BASE.F_CONVERTIR_DNI_A_RUC(REG_SD.VC_NUMERO_DOCUMENTO) AND REG_SD.VC_TIPO_DOCUMENTO = 'DNI') OR
                   (SH.TAXNUM = PKG_BASE.F_CONVERTIR_RUC_A_DNI(REG_SD.VC_NUMERO_DOCUMENTO) AND REG_SD.VC_TIPO_DOCUMENTO = 'RUC' AND SUBSTR(REG_SD.VC_NUMERO_DOCUMENTO, 1, 2) = '10'));

            IF intCount > 0 THEN
              blElegibilidad := FALSE;
              intErrores     := intErrores + 1;
              vcErrores      := vcErrores || 'BENEFICIARIO OTRO PROGRAMA  : ' || REG_SD.VC_NUMERO_DOCUMENTO || ' - Ya se encuentra honrado en el/los programa(s) ' || REC_RCC_HONRAS.VC_DESCRIPCION || vcEnter;
            END IF;
          END LOOP;
        ELSE
          FOR REC_RCC_HONRAS IN (SELECT VP.INT_IDPROD,
                                        VP.VC_CODPROD,
                                        VP.VC_DESCRIPCION,
                                        VP.INT_CODIGO,
                                        VP.SAP_CODIGO
                                   FROM US_BASE.V_BASE_REGLA_PRODUCTO_PROGRAMA VP
                                  INNER JOIN SOLICITUD S ON (VP.INT_IDPROD = S.INT_IDPRODUCTO)
                                  WHERE S.INT_IDSOLICITUD = p_intIdSolicitud) LOOP
            SELECT COUNT(1)
              INTO intCount
              FROM SOLICITUD_HONRAS SH
             WHERE SH.INT_IDSOLICITUD = REG_SD.INT_IDSOLICITUD
               AND SH.GSART = REC_RCC_HONRAS.SAP_CODIGO
               AND SH.TAXNUM = REG_SD.VC_NUMERO_DOCUMENTO;

            IF intCount > 0 THEN
              blElegibilidad := FALSE;
              intErrores     := intErrores + 1;
              vcErrores      := vcErrores || 'BENEFICIARIO OTRO PROGRAMA  : ' || REG_SD.VC_NUMERO_DOCUMENTO || ' - Ya se encuentra honrado en el/los programa(s) ' || REC_RCC_HONRAS.VC_DESCRIPCION || vcEnter;
            END IF;
          END LOOP;
        END IF;
      END IF;
      ----------------------------------------------------------------------------------------------------
      --Elegibilidad Subasta
      --Código Postura
      ----------------------------------------------------------------------------------------------------
      IF recBRP.CH_ES_SUBASTA_CODIGO_POSTURA_EXISTENCIA = 1 THEN
        IF recBRP.CH_ES_SUBASTA_CODIGO_POSTURA_PERTENENCIA_FI = 1 THEN
          SELECT COUNT(1)
            INTO intCount
            FROM US_BASE.V_CEN_SUBASTA_DETALLE CSD
           WHERE CSD.VC_CODIGO_POSTURA = REG_SD.VC_CODIGO_SUBASTA
             AND CSD.INT_IDSIS = intIdProducto
             AND CSD.VC_CODIGOIFI = vcCodigo_IFI
             AND CSD.CH_FLAG_ESTADO = 'A';
          IF intCount = 0 THEN
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores || 'en Campo 25 : ' || stSolCred(10).VC_DESCRIPCION || ', ' || TRIM(REG_SD.VC_CODIGO_SUBASTA) || ', > El número de subasta no corresponde.' || vcEnter;
          END IF;
        ELSE
          SELECT COUNT(1)
            INTO intCount
            FROM US_BASE.V_CEN_SUBASTA_DETALLE CSD
           WHERE CSD.VC_CODIGO_POSTURA = REG_SD.VC_CODIGO_SUBASTA
             AND CSD.INT_IDSIS = intIdProducto
             AND CSD.CH_FLAG_ESTADO = 'A';
          IF intCount = 0 THEN
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores || 'en Campo 25 : ' || stSolCred(10).VC_DESCRIPCION || ', ' || TRIM(REG_SD.VC_CODIGO_SUBASTA) || ', > El número de subasta no Existe.' || vcEnter;
          END IF;
        END IF;
      ELSE
        IF recBRP.CH_ES_SUBASTA_CODIGO_POSTURA_PERTENENCIA_FI = 1 THEN
          SELECT COUNT(1)
            INTO intCount
            FROM US_BASE.V_CEN_SUBASTA_DETALLE CSD
           WHERE CSD.VC_CODIGO_POSTURA = REG_SD.VC_CODIGO_SUBASTA
             AND CSD.INT_IDSIS = intIdProducto
             AND CSD.VC_CODIGOIFI = vcCodigo_IFI
             AND CSD.CH_FLAG_ESTADO = 'A';
          IF intCount = 0 THEN
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores || 'en Campo 25 : ' || stSolCred(10).VC_DESCRIPCION || ', ' || TRIM(REG_SD.VC_CODIGO_SUBASTA) || ', > El número de subasta no corresponde.' || vcEnter;
          END IF;
        END IF;
      END IF;
      ----------------------------------------------------------------------------------------------------
      -- Tasa Asignada Crédito
      ----------------------------------------------------------------------------------------------------
      SELECT COUNT(1)
        INTO intCount
        FROM US_BASE.V_CEN_SUBASTA_DETALLE CSD
       WHERE CSD.VC_CODIGO_POSTURA = REG_SD.VC_CODIGO_SUBASTA
         AND CSD.INT_IDSIS = intIdProducto
         AND CSD.VC_CODIGOIFI = vcCodigo_IFI
         AND CSD.CH_FLAG_ESTADO = 'A';

      IF intCount > 0 THEN
        SELECT CSD.DEC_TASA_ASIGNADA,
               CSD.INT_IDSUBASTA,
               CSD.INT_IDSUBASTA_DETALLE
          INTO intTasaAsignada, intIdSubasta, intIdSubastaDetalle
          FROM US_BASE.V_CEN_SUBASTA_DETALLE CSD
         WHERE CSD.VC_CODIGO_POSTURA = REG_SD.VC_CODIGO_SUBASTA
           AND CSD.INT_IDSIS = intIdProducto
           AND CSD.VC_CODIGOIFI = vcCodigo_IFI
           AND CSD.CH_FLAG_ESTADO = 'A';

        SELECT CS.DEC_TCEA_PROMEDIO, CS.DT_FECHALIMITE_SOL_MON_ADJ
          INTO intTCEAPromedio, dtFechaLimiteSubasta
          FROM US_BASE.V_CEN_SUBASTA CS
         WHERE CS.INT_IDSUBASTA = intIdSubasta
           AND CS.INT_IDSIS = intIdProducto
           AND CS.CH_FLAG_ESTADO = 'A';
      END IF;

      intTasa1 := TO_NUMBER(NVL(TRIM(PKG_TABLA_DETALLE.F_OBT_CODIGO_TABLADETALLE(recBRP.INT_ID_SUBASTA_TASA_CREDITO_1)), '0'));
      intTasa2 := TO_NUMBER(NVL(TRIM(PKG_TABLA_DETALLE.F_OBT_CODIGO_TABLADETALLE(recBRP.INT_ID_SUBASTA_TASA_CREDITO_2)), '0'));
      intTasa3 := TO_NUMBER(NVL(TRIM(PKG_TABLA_DETALLE.F_OBT_CODIGO_TABLADETALLE(recBRP.INT_ID_SUBASTA_TASA_CREDITO_3)), '0'));

      intValorTasa1 := TO_NUMBER(NVL(TRIM(PKG_TABLA_DETALLE.F_OBT_CODIGO_TABLADETALLE(recBRP.INT_ID_SUBASTA_TASA_TIPO_CREDITO_1)), '0'));
      intValorTasa2 := TO_NUMBER(NVL(TRIM(PKG_TABLA_DETALLE.F_OBT_CODIGO_TABLADETALLE(recBRP.INT_ID_SUBASTA_TASA_TIPO_CREDITO_2)), '0'));
      intValorTasa3 := recBRP.DEC_SUBASTA_TASA_CREDITO_VALOR;

      IF intTasa1 <> 0 AND intValorTasa1 <> 0 THEN
        IF intTasa1 = 1 THEN -- <=
          IF REG_SD.DEC_TASA_INTERES > intTasaAsignada THEN
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores || 'en Campo 19 : ' || stSolCred(03).VC_DESCRIPCION || ', > La tasa de crédito es mayor a Tasa asignada Postura.' || vcEnter;
          END IF;
        END IF;
        IF intTasa1 = 2 THEN -- >
          IF REG_SD.DEC_TASA_INTERES <= intTasaAsignada THEN
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores || 'en Campo 19 : ' || stSolCred(03).VC_DESCRIPCION || ', > La tasa de crédito es menor a Tasa asignada Postura.' || vcEnter;
          END IF;
        END IF;
      END IF;

      IF intTasa2 <> 0 AND intValorTasa2 <> 0 THEN
        IF intTasa2 = 1 THEN -- <=
          IF REG_SD.DEC_TASA_INTERES > intTCEAPromedio THEN
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores || 'en Campo 19 : ' || stSolCred(03).VC_DESCRIPCION || ', > La tasa de crédito es mayor al valor permitido.' || vcEnter;
          END IF;
        END IF;
        IF intTasa2 = 2 THEN -- >
          IF REG_SD.DEC_TASA_INTERES <= intTCEAPromedio THEN
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores || 'en Campo 19 : ' || stSolCred(03).VC_DESCRIPCION || ', > La tasa de crédito es menor al valor permitido.' || vcEnter;
          END IF;
        END IF;
      END IF;

      IF intTasa3 <> 0 AND intValorTasa3 <> 0 THEN
        /*
        IF intTasa3 = 1 THEN-- <=
          IF REG_SD.DEC_TASA_INTERES > intValorTasa3 THEN
            intErrores := intErrores + 1;
            vcErrores  := vcErrores || 'en Campo 19 : ' || stSolCred(03).VC_DESCRIPCION || ', > La tasa de crédito es mayor a Tasa asignada de credito.' || vcEnter;
          END IF;
        END IF;
        IF intTasa3 = 2 THEN-- >
          IF REG_SD.DEC_TASA_INTERES <= intValorTasa3 THEN
            intErrores := intErrores + 1;
            vcErrores  := vcErrores || 'en Campo 19 : ' || stSolCred(03).VC_DESCRIPCION || ', > La tasa de crédito es menor a Tasa asignada de credito.' || vcEnter;
          END IF;
        END IF;
        */
        IF intTasa3 = 3 THEN -- >
          IF REG_SD.DEC_TASA_INTERES < intValorTasa3 THEN
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores || 'en Campo 19 : ' || stSolCred(03).VC_DESCRIPCION || ', > La tasa de crédito debe ser mayor o igual que ' || TRIM(TO_CHAR(intValorTasa3, '990.00')) || ' .' || vcEnter;
          END IF;
        END IF;
      END IF;
      ----------------------------------------------------------------------------------------------------
      --Fecha límite Registro Crédito
      ----------------------------------------------------------------------------------------------------
      SELECT COUNT(1)
        INTO intCount
        FROM US_BASE.V_CEN_SUBASTA CS
       INNER JOIN  US_BASE.V_CEN_SUBASTA_DETALLE CSD ON (CS.INT_IDSUBASTA = CSD.INT_IDSUBASTA)
       WHERE CSD.VC_CODIGO_POSTURA = REG_SD.VC_CODIGO_SUBASTA
         AND CSD.INT_IDSIS = intIdProducto
         AND CSD.VC_CODIGOIFI = vcCodigo_IFI
         AND CSD.CH_FLAG_ESTADO = 'A';

      IF intCount > 0 THEN

      SELECT CS.DT_FECHALIMITE_SOL_MON_ADJ
        INTO dtFechaLimiteSubasta
        FROM US_BASE.V_CEN_SUBASTA CS
       INNER JOIN  US_BASE.V_CEN_SUBASTA_DETALLE CSD ON (CS.INT_IDSUBASTA = CSD.INT_IDSUBASTA)
       WHERE CSD.VC_CODIGO_POSTURA = REG_SD.VC_CODIGO_SUBASTA
         AND CSD.INT_IDSIS = intIdProducto
         AND CSD.VC_CODIGOIFI = vcCodigo_IFI
         AND CSD.CH_FLAG_ESTADO = 'A';

        intFechaLimite := TO_NUMBER(TRIM(PKG_TABLA_DETALLE.F_OBT_CODIGO_TABLADETALLE(recBRP.INT_ID_SUBASTA_FECHA_LIMITE_REGISTRO_CREDITO)));

        IF intFechaLimite = 1 THEN
          intTipoLimite := TO_NUMBER(TRIM(PKG_TABLA_DETALLE.F_OBT_CODIGO_TABLADETALLE(recBRP.INT_ID_SUBASTA_FECHA_LIMITE_REGISTRO_CREDITO_ADICIONALES)));
          IF intTipoLimite = 1 THEN
            -- Dias Calendario
            dtFechaSubastaCalculada := dtFechaLimiteSubasta + recBRP.INT_SUBASTA_FECHA_LIMITE_REGISTRO_CREDITO_DIAS;
          ELSIF intTipoLimite = 2 THEN
            IF recBRP.INT_SUBASTA_FECHA_LIMITE_REGISTRO_CREDITO_DIAS > 0 THEN
              -- Dias Habiles
              dtFechaSubastaCalculada := PKG_BASE.F_SIGUIENTE_DIA_HABIL(dtFechaLimiteSubasta,recBRP.INT_SUBASTA_FECHA_LIMITE_REGISTRO_CREDITO_DIAS);
            ELSE
              dtFechaSubastaCalculada := dtFechaLimiteSubasta;
            END IF;
          END IF;
          IF dtFechaSolicitud > dtFechaSubastaCalculada THEN
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores || 'La fecha de solicitud ha superado el plazo máximo de la subasta.' || vcEnter;
          END IF;
        END IF;
      END IF;
      ----------------------------------------------------------------------------------------------------
      --Elegibilidad Crédito

      --Plazo Máximo de Cuota
      ----------------------------------------------------------------------------------------------------      
      IF recBRP.INT_CREDITO_PLAZO_MAXIMO_CUOTA_FECHA_DESDE IS NULL OR
         recBRP.INT_CREDITO_PLAZO_MAXIMO_CUOTA_FECHA_DESDE = 0 THEN
        IF REG_SD.INT_PLAZO_OPERACION >
           recBRP.INT_CREDITO_PLAZO_MAXIMO_CUOTA_FECHA_HASTA THEN
          blElegibilidad := FALSE;
          intErrores     := intErrores + 1;
          vcErrores      := vcErrores || 'en Campo 23 : ' || stSolCred(07).VC_DESCRIPCION || ', ' || TRIM(TO_CHAR(REG_SD.INT_PLAZO_OPERACION)) || ', > El plazo máximo de cuota debe ser menor igual a ' || TO_CHAR(recBRP.INT_CREDITO_PLAZO_MAXIMO_CUOTA_FECHA_HASTA) || '.' || vcEnter;
        END IF;
      END IF;

      IF recBRP.INT_CREDITO_PLAZO_MAXIMO_CUOTA_FECHA_HASTA IS NULL OR
         recBRP.INT_CREDITO_PLAZO_MAXIMO_CUOTA_FECHA_HASTA = 0 THEN
        IF REG_SD.INT_PLAZO_OPERACION <
           recBRP.INT_CREDITO_PLAZO_MAXIMO_CUOTA_FECHA_DESDE THEN
          blElegibilidad := FALSE;
          intErrores     := intErrores + 1;
          vcErrores      := vcErrores || 'en Campo 23 : ' || stSolCred(07).VC_DESCRIPCION || ', ' || TRIM(TO_CHAR(REG_SD.INT_PLAZO_OPERACION)) || ', > El plazo máximo de cuota debe ser mayor igual a ' || TO_CHAR(recBRP.INT_CREDITO_PLAZO_MAXIMO_CUOTA_FECHA_DESDE) || '.' || vcEnter;
        END IF;
      END IF;

      IF recBRP.INT_CREDITO_PLAZO_MAXIMO_CUOTA_FECHA_DESDE > 0 AND
         recBRP.INT_CREDITO_PLAZO_MAXIMO_CUOTA_FECHA_HASTA > 0 THEN
        IF REG_SD.INT_PLAZO_OPERACION > recBRP.INT_CREDITO_PLAZO_MAXIMO_CUOTA_FECHA_HASTA OR
           REG_SD.INT_PLAZO_OPERACION < recBRP.INT_CREDITO_PLAZO_MAXIMO_CUOTA_FECHA_DESDE THEN
          blElegibilidad := FALSE;
          intErrores     := intErrores + 1;
          vcErrores      := vcErrores || 'en Campo 23 : ' || stSolCred(07).VC_DESCRIPCION || ', ' || TRIM(TO_CHAR(REG_SD.INT_PLAZO_OPERACION)) || ', > El plazo máximo de cuota no se encuentra en el intervalo permitido ' || TO_CHAR(recBRP.INT_CREDITO_PLAZO_MAXIMO_CUOTA_FECHA_DESDE) || ' - ' || TO_CHAR(recBRP.INT_CREDITO_PLAZO_MAXIMO_CUOTA_FECHA_HASTA) || '.' || vcEnter;
        END IF;
      END IF;

      ----------------------------------------------------------------------------------------------------
      -- Plazo de Gracia
      IF recBRP.INT_CREDITO_PLAZO_GRACIA_FECHA_DESDE IS NULL OR
         recBRP.INT_CREDITO_PLAZO_GRACIA_FECHA_DESDE = 0 THEN
        IF REG_SD.INT_PERIODO_GRACIA > recBRP.INT_CREDITO_PLAZO_GRACIA_FECHA_HASTA THEN
          blElegibilidad := FALSE;
          intErrores     := intErrores + 1;
          vcErrores      := vcErrores || 'en Campo 24 : ' || stSolCred(08).VC_DESCRIPCION || ', ' || TRIM(TO_CHAR(REG_SD.INT_PERIODO_GRACIA)) || ', > El plazo de gracia debe ser menor igual a ' || TO_CHAR(recBRP.INT_CREDITO_PLAZO_GRACIA_FECHA_HASTA) || '.' || vcEnter;
        END IF;
      END IF;

      IF recBRP.INT_CREDITO_PLAZO_GRACIA_FECHA_HASTA IS NULL OR
         recBRP.INT_CREDITO_PLAZO_GRACIA_FECHA_HASTA = 0 THEN
        IF REG_SD.INT_PERIODO_GRACIA < recBRP.INT_CREDITO_PLAZO_GRACIA_FECHA_DESDE THEN
          blElegibilidad := FALSE;
          intErrores     := intErrores + 1;
          vcErrores      := vcErrores || 'en Campo 24 : ' || stSolCred(08).VC_DESCRIPCION || ', ' || TRIM(TO_CHAR(REG_SD.INT_PERIODO_GRACIA)) || ', > El plazo de gracia debe ser mayor igual a ' || TO_CHAR(recBRP.INT_CREDITO_PLAZO_GRACIA_FECHA_DESDE) || '.' || vcEnter;
        END IF;
      END IF;

      IF recBRP.INT_CREDITO_PLAZO_GRACIA_FECHA_DESDE > 0 AND
         recBRP.INT_CREDITO_PLAZO_GRACIA_FECHA_HASTA > 0 THEN
        IF REG_SD.INT_PERIODO_GRACIA > recBRP.INT_CREDITO_PLAZO_GRACIA_FECHA_HASTA OR
           REG_SD.INT_PERIODO_GRACIA < recBRP.INT_CREDITO_PLAZO_GRACIA_FECHA_DESDE THEN
          blElegibilidad := FALSE;
          intErrores     := intErrores + 1;
          vcErrores      := vcErrores || 'en Campo 24 : ' || stSolCred(08).VC_DESCRIPCION || ', ' || TRIM(TO_CHAR(REG_SD.INT_PERIODO_GRACIA)) || ', > El plazo de gracia no se encuentra en el intervalo permitido ' || TO_CHAR(recBRP.INT_CREDITO_PLAZO_GRACIA_FECHA_DESDE) || ' - ' || TO_CHAR(recBRP.INT_CREDITO_PLAZO_GRACIA_FECHA_HASTA) || '.' || vcEnter;
        END IF;
      END IF;

      ----------------------------------------------------------------------------------------------------
      --Plazo Máximo Programa
      ----------------------------------------------------------------------------------------------------
      IF NOT recBRP.DT_PLAZO_MAXIMO_PROGRAMA_FECHA_REGISTRO IS NULL THEN
        intTipoLimite := TO_NUMBER(NVL(TRIM(PKG_TABLA_DETALLE.F_OBT_CODIGO_TABLADETALLE(recBRP.INT_ID_CREDITO_PLAZO_MAXIMO_PROGRAMA_ADICIONALES)), '0'));
        IF NVL(recBRP.INT_CREDITO_PLAZO_MAXIMO_PROGRAMA_DIAS, 0) > 0 THEN
          IF intTipoLimite = 1 THEN
            -- Dias Calendario
            dtFechaVencimiCalculada := recBRP.DT_PLAZO_MAXIMO_PROGRAMA_FECHA_REGISTRO + NVL(recBRP.INT_CREDITO_PLAZO_MAXIMO_PROGRAMA_DIAS, 0);
          ELSIF intTipoLimite = 2 THEN
            -- Dias Habiles
            SELECT D.FECHA_FINAL
              INTO dtFechaVencimiCalculada
              FROM (SELECT ROWNUM AS DIAS,
                           TRUNC(recBRP.DT_PLAZO_MAXIMO_PROGRAMA_FECHA_REGISTRO) + LEVEL AS FECHA_FINAL
                      FROM DUAL
                     WHERE TO_NUMBER(TO_CHAR(TRUNC(recBRP.DT_PLAZO_MAXIMO_PROGRAMA_FECHA_REGISTRO) + LEVEL, 'D')) NOT IN (1, 7)
                    CONNECT BY LEVEL <= 365) D
             WHERE D.DIAS = NVL(recBRP.INT_CREDITO_PLAZO_MAXIMO_PROGRAMA_DIAS, 0);
          END IF;
        ELSE
          dtFechaVencimiCalculada := recBRP.DT_PLAZO_MAXIMO_PROGRAMA_FECHA_REGISTRO;
        END IF;
        IF dtFechaSolicitud > dtFechaVencimiCalculada THEN
          blElegibilidad := FALSE;
          intErrores     := intErrores + 1;
          vcErrores      := vcErrores || 'La fecha de solicitud ha superado el plazo máximo del programa.' || vcEnter;
        END IF;
      END IF;
      ----------------------------------------------------------------------------------------------------
      --Monto Colateral
      ----------------------------------------------------------------------------------------------------

      IF intValColateral = 0 THEN
        IF recBRP.CH_ES_CREDITO_MONTO_COLATERAL_CODIGO_NAP = 1 THEN
          IF NVL(REG_SD.DEC_MONTO_COLATERAL, 0) <> 0 THEN
            IF recBRP.INT_CREDITO_MONTO_COLATERAL_IMPORTE > NVL(REG_SD.DEC_MONTO_COLATERAL, 0) THEN
              blElegibilidad := FALSE;
              intErrores     := intErrores + 1;
              vcErrores      := vcErrores || 'en Campo 21 : ' || stSolCred(05).VC_DESCRIPCION || ', ' || TRIM(TO_CHAR(REG_SD.DEC_MONTO_COLATERAL, '999,999,999,990.00')) || ', > El Monto Colateral debe ser mayor a ' || TRIM(TO_CHAR(recBRP.INT_CREDITO_MONTO_COLATERAL_IMPORTE, '999,999,999')) || ' .' || vcEnter;
            END IF;
          END IF;
        ELSE
          IF recBRP.INT_CREDITO_MONTO_COLATERAL_IMPORTE > NVL(REG_SD.DEC_MONTO_COLATERAL, 0) THEN
            blElegibilidad := FALSE;
            intErrores     := intErrores + 1;
            vcErrores      := vcErrores || 'en Campo 21 : ' || stSolCred(05).VC_DESCRIPCION || ', ' || TRIM(TO_CHAR(REG_SD.DEC_MONTO_COLATERAL, '999,999,999,990.00')) || ', > El Monto Colateral debe ser mayor a ' || TRIM(TO_CHAR(recBRP.INT_CREDITO_MONTO_COLATERAL_IMPORTE, '999,999,999')) || ' .' || vcEnter;
          END IF;
        END IF;

      ELSE
        blElegibilidad := FALSE;
        intErrores     := intErrores + 1;
        vcErrores      := vcErrores || 'No se validará el ' || stSolCred(05).VC_DESCRIPCION || ' (Campo 21) dado que el Tipo ' || stSolCred(04).VC_DESCRIPCION || ' (Campo 20) no es válido.' || vcEnter;
      END IF;

      IF blElegibilidad THEN
        PKG_PRODUCTO.I_PROCESAR_REGLAS_ELEGIBILIDAD(REG_SD, blElegibilidad, intErrores, vcErrores);
      END IF;
      ----------------------------------------------------------------------------------------------------
      --Cálculos Post Reglas de Elegilidad
      IF blElegibilidad THEN
        --%Cobertura
        ----------------------------------------------------------------------------------------------------
        SELECT COUNT(1)
          INTO intCount
          FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_DATOS D
         WHERE D.INT_IDPRODUCTO = intIdProducto;

        IF intCount > 0 THEN
          SELECT d.INT_IDMATRIZCOB, d.CH_AGRUP_ACUMULADO, d.CH_AGRUP_TIPODOC
            INTO intMatrizCob, intAgrupAcumulado, intAgrupTipoDoc
            FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_DATOS D
           WHERE D.INT_IDPRODUCTO = intIdProducto
             AND ROWNUM <= 1;
        END IF;

        intMontoPrestamo     := 0;
        intPorcenCoberturado := 0;
        IF intMatrizCob <> 3 THEN
          IF intMatrizCob = 1 THEN
            IF intAgrupTipoDoc = 1 THEN
              --Documento_Conversión=  Obtener su tipo de documento de conversión (número de documento)
              IF REG_SD.VC_TIPO_DOCUMENTO = 'DNI' THEN
                vcTipDocConvertido := 'RUC';
                vcDocConvertido    := PKG_BASE.F_CONVERTIR_DNI_A_RUC(REG_SD.VC_NUMERO_DOCUMENTO);
              ELSIF REG_SD.VC_TIPO_DOCUMENTO = 'RUC' AND SUBSTR(REG_SD.VC_NUMERO_DOCUMENTO,1,2) = '10'  THEN
                vcTipDocConvertido := 'DNI';
                vcDocConvertido    := PKG_BASE.F_CONVERTIR_RUC_A_DNI(REG_SD.VC_NUMERO_DOCUMENTO);
              ELSE
                vcTipDocConvertido := REG_SD.VC_TIPO_DOCUMENTO;
                vcDocConvertido    := REG_SD.VC_NUMERO_DOCUMENTO;
              END IF;
              IF intAgrupAcumulado = 1 THEN
                --Monto_Prestamo = Obtener Monto_Prestamo (numero de documento, Documento_Conversión)
                SELECT SUM(NVL(SD.DEC_MONTO_PRESTAMO, 0))
                  INTO intMontoPrestamo
                  FROM SOLICITUD_DETALLE SD
                 WHERE ((SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO) OR
                        (SD.VC_TIPO_DOCUMENTO = vcTipDocConvertido AND SD.VC_NUMERO_DOCUMENTO = vcDocConvertido))
                   AND SD.VC_ESTADO IN
                           (SELECT TABDET.VC_ADICIONAL1
                            FROM US_BASE.BASE_TABLA TAB
                            INNER JOIN US_BASE.BASE_TABLA_DETALLE TABDET ON TAB.INT_IDTABLA = TABDET.INT_IDTABLA
                            WHERE VC_CODTABLA = 'ESTSOLDETFIDEM'
                            AND TABDET.VC_ADICIONAL2 IN (SELECT T.ESTADO_CREDITO
                                                      FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_ESTADO_CREDITO T
                                                     WHERE T.INT_IDPRODUCTO = intIdProducto))
                   AND SD.INT_IDSOLICITUD <> p_intIdSolicitud;
                intMontoPrestamo := NVL(intMontoPrestamo, 0) + NVL(REG_SD.DEC_MONTO_PRESTAMO, 0);
              ELSE
                --Monto_Prestamo = Monto_Prestamo_Solicitud
                intMontoPrestamo := NVL(REG_SD.DEC_MONTO_PRESTAMO, 0);
              END IF;
            ELSE
              IF intAgrupAcumulado = 1 THEN
                --Monto_Prestamo = Obtener Monto_Prestamo (numero de documento)
                SELECT SUM(NVL(SD.DEC_MONTO_PRESTAMO, 0))
                  INTO intMontoPrestamo
                  FROM SOLICITUD_DETALLE SD
                 WHERE (SD.VC_TIPO_DOCUMENTO = REG_SD.VC_TIPO_DOCUMENTO AND SD.VC_NUMERO_DOCUMENTO = REG_SD.VC_NUMERO_DOCUMENTO)
                   AND SD.VC_ESTADO IN
                            (SELECT TABDET.VC_ADICIONAL1
                            FROM US_BASE.BASE_TABLA TAB
                            INNER JOIN US_BASE.BASE_TABLA_DETALLE TABDET ON TAB.INT_IDTABLA = TABDET.INT_IDTABLA
                            WHERE VC_CODTABLA = 'ESTSOLDETFIDEM'
                            AND TABDET.VC_ADICIONAL2 IN (SELECT T.ESTADO_CREDITO
                                                      FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_ESTADO_CREDITO T
                                                     WHERE T.INT_IDPRODUCTO = intIdProducto))
                   AND SD.INT_IDSOLICITUD <> p_intIdSolicitud;
                intMontoPrestamo := NVL(intMontoPrestamo, 0) + NVL(REG_SD.DEC_MONTO_PRESTAMO, 0);
              ELSE
                --Monto_Prestamo = Monto_Prestamo_Solicitud
                intMontoPrestamo := NVL(REG_SD.DEC_MONTO_PRESTAMO, 0);
              END IF;
            END IF;

            SELECT COUNT(1)
              INTO intCount
              FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
             WHERE intMontoPrestamo BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
               AND L.INT_IDPRODUCTO = intIdProducto;

            IF intCount > 0 THEN
              SELECT L.DEC_PORCENTAJE_COB
                INTO intPorcenCoberturado
                FROM US_BASE.V_BASE_PRODUCTO_CONFIG_COBERTURA_LISTA L
               WHERE intMontoPrestamo BETWEEN L.DEC_MONTO_DESDE AND L.DEC_MONTO_HASTA
                 AND L.INT_IDPRODUCTO = intIdProducto
                 AND ROWNUM = 1;
              UPDATE SOLICITUD_DETALLE SD
                 SET SD.DEC_PORCENTAJE_COBERTURA      = intPorcenCoberturado,
                     SD.DEC_PORCENTAJE_COBERTURA_ORIG = intPorcenCoberturado,
                     SD.DEC_MONTO_COBERTURA           = NVL(REG_SD.DEC_MONTO_PRESTAMO, 0) * intPorcenCoberturado / 100,
                     SD.DEC_MONTO_COBERTURA_ORIG      = NVL(REG_SD.DEC_MONTO_PRESTAMO, 0) * intPorcenCoberturado / 100
               WHERE SD.INT_IDSOLICITUD = REG_SD.INT_IDSOLICITUD
                 AND SD.INT_IDSOLICITUD_DET = REG_SD.INT_IDSOLICITUD_DET;
              COMMIT;
            ELSE
              intErrores := intErrores + 1;
              vcErrores  := vcErrores || 'en Campo 18 : ' || stSolCred(02).VC_DESCRIPCION || ', ' || TRIM(TO_CHAR(intMontoPrestamo, '999,999,999,990.00')) || ', > No se ha identificado el % de cobertura en los intervalos definidos para el monto del préstamo ' || TRIM(TO_CHAR(intMontoPrestamo, '999,999,990.00')) || ' .' || vcEnter;
            END IF;
          END IF;
        END IF;
        ----------------------------------------------------------------------------------------------------
        --Monto asignado por postura
        ----------------------------------------------------------------------------------------------------

        intMontoCoberurado     := 0;
        intMontoCoberuradoAcum := 0;
        intMontoAsignado       := 0;

        IF recBRP.CH_ES_SUBASTA_MONTO_ASIGNADO_POSTURA = 1 AND TO_NUMBER(NVL(TRIM(PKG_TABLA_DETALLE.F_OBT_CODIGO_TABLADETALLE(recBRP.INT_ID_SUBASTA_MONTO_ASIGNADO_POSTURA_ASIGNADO)), '0')) = 1 THEN
          SELECT SUM(NVL(SD.DEC_MONTO_COBERTURA, 0))
            INTO intMontoCoberuradoAcum
            FROM SOLICITUD_DETALLE SD
           WHERE SD.INT_IDSOLICITUD IN
                 (SELECT S.INT_IDSOLICITUD
                    FROM SOLICITUD S
                   WHERE S.INT_IDIFI = intIdIFI)
             AND SD.INT_IDSOLICITUD_DET <> REG_SD.INT_IDSOLICITUD_DET
             AND SD.VC_CODIGO_SUBASTA = REG_SD.VC_CODIGO_SUBASTA
             AND SD.VC_ESTADO IN
                 (SELECT D.VALOR
                    FROM (SELECT DECODE(recBRP.CH_ES_SUBASTA_MONTO_ASIGNADO_POSTURA_ESTADO_EN_EVALUACION, 1, 'REG', 'XXX') AS D1,
                                 DECODE(recBRP.CH_ES_SUBASTA_MONTO_ASIGNADO_POSTURA_ESTADO_POR_CONFIRMAR, 1, 'ELE', 'XXX') AS D2,
                                 DECODE(recBRP.CH_ES_SUBASTA_MONTO_ASIGNADO_POSTURA_ESTADO_CONFIRMADO, 1, 'CON', 'XXX') AS D3,
                                 DECODE(recBRP.CH_ES_SUBASTA_MONTO_ASIGNADO_POSTURA_ESTADO_COBERTURADO, 1, 'COB', 'XXX') AS D4
                            FROM DUAL) UNPIVOT(VALOR FOR COL IN(D1, D2, D3, D4)) D);

          intMontoCoberuradoAcum := NVL(intMontoCoberuradoAcum, 0);

          SELECT NVL(SD.DEC_PORCENTAJE_COBERTURA, 0) * NVL(SD.DEC_MONTO_PRESTAMO, 0) / 100
            INTO intMontoCoberurado
            FROM SOLICITUD_DETALLE SD
           WHERE SD.INT_IDSOLICITUD = REG_SD.INT_IDSOLICITUD
             AND SD.INT_IDSOLICITUD_DET = REG_SD.INT_IDSOLICITUD_DET;

          intMontoCoberurado := NVL(intMontoCoberurado, 0);

          intMontoCoberurado := NVL(intMontoCoberuradoAcum, 0) + NVL(intMontoCoberurado, 0);

          SELECT SUM(NVL(V.DEC_MONTO_ASIGNADO, 0))
            INTO intMontoAsignado
            FROM US_BASE.V_CEN_SUBASTA_DETALLE V
           WHERE V.VC_CODIGOIFI = vcCodigo_IFI
             AND V.VC_CODIGO_POSTURA = REG_SD.VC_CODIGO_SUBASTA
             AND V.CH_FLAG_ESTADO = 'A';

          intMontoAsignado := NVL(intMontoAsignado, 0);

          IF intMontoAsignado < intMontoCoberurado THEN
            UPDATE SOLICITUD_DETALLE SD
               SET SD.DEC_PORCENTAJE_COBERTURA      = 0,
                   SD.DEC_PORCENTAJE_COBERTURA_ORIG = 0,
                   SD.DEC_MONTO_COBERTURA           = 0,
                   SD.DEC_MONTO_COBERTURA_ORIG      = 0
             WHERE SD.INT_IDSOLICITUD = REG_SD.INT_IDSOLICITUD
               AND SD.INT_IDSOLICITUD_DET = REG_SD.INT_IDSOLICITUD_DET;
            COMMIT;
            intErrores := intErrores + 1;
            vcErrores  := vcErrores || 'Se ha superado el monto de postura de la subasta: ' || REG_SD.VC_CODIGO_SUBASTA ||' - Monto calculado coberturado: ' || intMontoCoberurado || ' >  Monto adjudicado: '  || intMontoAsignado || vcEnter;
          END IF;
        END IF;

        ----------------------------------------------------------------------------------------------------
        --Importe Máximo Cobertura
        ----------------------------------------------------------------------------------------------------
        intMontoCoberurado     := 0;
        intMontoCoberuradoAcum := 0;
        SELECT SUM(NVL(SD.DEC_MONTO_COBERTURA, 0))
          INTO intMontoCoberurado
          FROM SOLICITUD_DETALLE SD
         WHERE SD.INT_IDSOLICITUD = REG_SD.INT_IDSOLICITUD
           AND SD.INT_IDSOLICITUD_DET = REG_SD.INT_IDSOLICITUD_DET;

        IF intMontoCoberurado > 0 THEN
          SELECT BPCF.DEC_MONTO_EXPOSICION
            INTO intMME
            FROM US_BASE.V_BASE_PRODUCTO_CONFIG_FONDO BPCF
           WHERE BPCF.INT_IDPRODUCTO = intIdProducto;

          SELECT SUM(NVL(SD.DEC_MONTO_COBERTURA, 0))
            INTO intMontoCoberuradoAcum
            FROM SOLICITUD_DETALLE SD
           WHERE SD.VC_ESTADO IN ('CON', 'CON', 'COB')
             AND SD.INT_IDSOLICITUD IN
                 (SELECT S.INT_IDSOLICITUD
                    FROM SOLICITUD S
                   WHERE S.INT_IDSOLICITUD <> p_intIdSolicitud)
             AND SD.INT_IDSOLICITUD <> p_intIdSolicitud;

          intMontoCoberuradoAcum := NVL(intMontoCoberuradoAcum, 0) + NVL(intMontoCoberurado, 0);

          intCIPCPrograma  := TO_NUMBER(NVL(TRIM(PKG_TABLA_DETALLE.F_OBT_CODIGO_TABLADETALLE(recBRP.INT_ID_CREDITO_IMPORTE_MAXIMO_COBERTURA_TOTAL_PROGRAMA)), '0'));
          intCIPCVariacion := TO_NUMBER(NVL(TRIM(PKG_TABLA_DETALLE.F_OBT_CODIGO_TABLADETALLE(recBRP.INT_ID_CREDITO_IMPORTE_MAXIMO_COBERTURA_VARIACION)), '0'));

          IF intCIPCPrograma = 1 THEN
            IF intCIPCVariacion = 1 THEN -- +
              intMMECalculada1 := (1 + recBRP.DEC_CREDITO_IMPORTE_MAXIMO_COBERTURA_MONTO / 100) * intMME;
            ELSIF intCIPCVariacion = 2 THEN -- -
              intMMECalculada1 := (1 - recBRP.DEC_CREDITO_IMPORTE_MAXIMO_COBERTURA_MONTO / 100) * intMME;
            ELSIF intCIPCVariacion = 3 THEN -- AMBAS
              intMMECalculada1 := (1 + recBRP.DEC_CREDITO_IMPORTE_MAXIMO_COBERTURA_MONTO / 100) * intMME;
              --intMMECalculada2 := (1 - recBRP.INT_ID_CREDITO_IMPORTE_MAXIMO_COBERTURA_MONTO/100) * intMME;
            END IF;
            IF intMontoCoberuradoAcum > intMMECalculada1 THEN
              UPDATE SOLICITUD_DETALLE SD
                 SET SD.DEC_PORCENTAJE_COBERTURA      = 0,
                     SD.DEC_PORCENTAJE_COBERTURA_ORIG = 0,
                     SD.DEC_MONTO_COBERTURA           = 0,
                     SD.DEC_MONTO_COBERTURA_ORIG      = 0
               WHERE SD.INT_IDSOLICITUD = REG_SD.INT_IDSOLICITUD
                 AND SD.INT_IDSOLICITUD_DET = REG_SD.INT_IDSOLICITUD_DET;
              COMMIT;
              intErrores := intErrores + 1;
              vcErrores  := vcErrores || 'El importe total Coberturado: ' || TO_CHAR(intMontoCoberuradoAcum, '999G999G999G999D99') ||' ha superado el límite permitido MME>>>' || TO_CHAR(intMMECalculada1, '999G999G999G999D99') || vcEnter;
            END IF;
          END IF;
        END IF;
        PKG_PRODUCTO.I_PROCESAR_REGLAS_POST_ELEGIBILIDAD(REG_SD, intErrores, vcErrores);
        ----------------------------------------------------------------------------------------------------
      ELSE
        intErrores := intErrores + 1;
        vcErrores  := vcErrores || 'El registro no ha pasado las validaciones de elegilidad y no se realizaran los cálculos post reglas de elegilidad' || vcEnter;
      END IF;


      IF intErrores = 0 THEN
         vcErrores := 'OK';
      END IF;

      IF intErrores = 0 THEN
        UPDATE SOLICITUD_DETALLE SD
           SET SD.OBSERVACIONES = vcErrores, SD.VC_ESTADO = 'ELE'
         WHERE SD.INT_IDSOLICITUD = REG_SD.INT_IDSOLICITUD
           AND SD.INT_IDSOLICITUD_DET = REG_SD.INT_IDSOLICITUD_DET;
      ELSE
        UPDATE SOLICITUD_DETALLE SD
           SET SD.OBSERVACIONES = SUBSTR(vcErrores,1,4000), SD.VC_ESTADO = 'REC'
         WHERE SD.INT_IDSOLICITUD = REG_SD.INT_IDSOLICITUD
           AND SD.INT_IDSOLICITUD_DET = REG_SD.INT_IDSOLICITUD_DET;
      END IF;

      COMMIT;
      intErrores := 0;
      vcErrores  := ' ';
    END LOOP;

    PKG_PRODUCTO.I_PROCESAR_REGLAS_FINAL(p_intIdSolicitud);

    intCount := 0;
    SELECT COUNT(1)
      INTO intCount
      FROM SOLICITUD_DETALLE SD
     WHERE SD.VC_ESTADO = 'ELE'
       AND SD.INT_IDSOLICITUD = p_intIdSolicitud;

    IF intCount > 0 THEN
      SELECT D.INT_IDTABLA_DETALLE, D.VC_CODTABLA_DETALLE
        INTO intIdEstado, vcCodEstado
        FROM US_BASE.BASE_TABLA_DETALLE D
       INNER JOIN US_BASE.BASE_TABLA T
          ON (T.INT_IDTABLA = D.INT_IDTABLA AND
             T.VC_CODTABLA = 'ESTSOLFIDEM')
       WHERE D.VC_CODTABLA_DETALLE = 'APR'
         AND D.CH_FLAG_ESTADO = 'A';
    ELSE
      SELECT D.INT_IDTABLA_DETALLE, D.VC_CODTABLA_DETALLE
        INTO intIdEstado, vcCodEstado
        FROM US_BASE.BASE_TABLA_DETALLE D
       INNER JOIN US_BASE.BASE_TABLA T
          ON (T.INT_IDTABLA = D.INT_IDTABLA AND
             T.VC_CODTABLA = 'ESTSOLFIDEM')
       WHERE D.VC_CODTABLA_DETALLE = 'REC'
         AND D.CH_FLAG_ESTADO = 'A';
    END IF;

    SELECT (SELECT COUNT(1)
              FROM SOLICITUD_DETALLE_TEXTO SD
             WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
               AND SD.OBSERVACIONES <> 'OK') AS RECH_ESTRU,
           (SELECT COUNT(1)
              FROM SOLICITUD_DETALLE SD
             WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
               AND SD.OBSERVACIONES <> 'OK') AS RECH_REGLA,
           (SELECT COUNT(1)
              FROM SOLICITUD_DETALLE SD
             WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
               AND SD.OBSERVACIONES = 'OK') AS APROBADO
      INTO intRechaEstru, intRechaRegla, intAprobado
      FROM DUAL;

    intRechazado := intRechaEstru + intRechaRegla;
    
    SELECT SUM(DEC_MONTO_PRESTAMO), SUM(DEC_MONTO_COBERTURA_ORIG)
    INTO decTotalMontoPrestamo, decTotalMontoCoberturado
    FROM SOLICITUD_DETALLE SD
    WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud;

    UPDATE SOLICITUD_RESULTADOS SR
       SET SR.INT_REGISTROS_RECHAZADOS_ESTRUCTURA = intRechaEstru,
           SR.INT_REGISTROS_RECHAZADOS_REGLAS     = intRechaRegla,
           SR.INT_REGISTROS_RECHAZADOS            = intRechazado,
           SR.INT_REGISTROS_APROBADOS             = intAprobado,
           SR.VC_ESTADO                           = 'PROCESAR_REGLAS',
           SR.VC_USUARIO_MODIFICACION             = USER,
           SR.DT_FECHA_MODIFICACION               = SYSDATE,
           SR.VC_TERMINAL_MODIFICACION            = SYS_CONTEXT('USERENV', 'IP_ADDRESS')
     WHERE SR.INT_IDSOLICITUD = p_intIdSolicitud
       AND SR.VC_ESTADO = 'PROC_REGLAS_INI';

    UPDATE SOLICITUD S
       SET S.INT_IDESTADO   = intIdEstado,
           S.INT_APROBADOS  = intAprobado,
           S.INT_RECHAZADOS = intRechazado,
           S.DEC_TOTAL_MONTO_PRESTAMO = decTotalMontoPrestamo,
           S.DEC_TOTAL_COBERTURADO_INICIAL = decTotalMontoCoberturado
     WHERE S.INT_IDSOLICITUD = p_intIdSolicitud;

    DELETE FROM SOLICITUD_HONRAS SH WHERE SH.INT_IDSOLICITUD = p_intIdSolicitud;
    DELETE FROM ETL_RCC_IDCLI_TMP T WHERE T.INT_IDSOLICITUD = p_intIdSolicitud;
    DELETE FROM ETL_RCC_MVCLI_TMP T WHERE T.INT_IDSOLICITUD = p_intIdSolicitud;
    DELETE FROM ETL_RCC_RSCLI_TMP T WHERE T.INT_IDSOLICITUD = p_intIdSolicitud;

    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      ROLLBACK;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_BASE', 'I_PROCESAR_REGLAS', vcErrorStack, vcErrorBacktace, 'INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
      RAISE_APPLICATION_ERROR(-20115, 'PKG_BASE.I_PROCESAR_REGLAS:'|| vcErrorStack||'; '||vcErrorBacktace||'; INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
      ROLLBACK;
 END I_PROCESAR_REGLAS;

  PROCEDURE I_PROCESAR(p_intIdSolicitud IN SOLICITUD.INT_IDSOLICITUD%TYPE) AS
  BEGIN
    PKG_BASE.I_PROCESAR_CLOB(p_intIdSolicitud);
    PKG_BASE.I_PROCESAR_ESTRUCTURA(p_intIdSolicitud);
  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_BASE', 'I_PROCESAR', vcErrorStack, vcErrorBacktace, 'INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
      RAISE_APPLICATION_ERROR(-20116, 'PKG_BASE.I_PROCESAR:'|| vcErrorStack||'; '||vcErrorBacktace||'; INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
  END I_PROCESAR;

END PKG_BASE;


/
--------------------------------------------------------
--  DDL for Package Body PKG_EXTORNO
--------------------------------------------------------

create or replace PACKAGE BODY  "US_BASE_MODULAR"."PKG_EXTORNO" 
  AS

  PROCEDURE S_LISTAR_ALL(p_intStartIndex     IN  NUMBER,
                         p_intPageSize       IN  NUMBER,
                         p_dtFechaDesde      IN  EXTORNO.DT_FECHA_CREACION % TYPE,
                         p_dtFechaHasta      IN  EXTORNO.DT_FECHA_CREACION % TYPE,
                         p_vcCodigo          IN  SOLICITUD.VC_CODIGO % TYPE,
                         p_intSolicitudDet   IN  EXTORNO.INT_IDSOLICITUD_DET % TYPE,
                         p_vcNumeroDocumento IN  SOLICITUD_DETALLE.VC_NUMERO_DOCUMENTO % TYPE,
                         p_intIdEsf          IN  NUMBER,
                         p_curTabla          OUT SYS_REFCURSOR)
    AS
    BEGIN
      OPEN p_curTabla FOR
        SELECT 
        D.INT_ROW_NUMBER,
        D.INT_NUMERO_TOTAL_REGISTRO,
        D.INT_IDGRUPO, 
        D.VC_USUARIO_CREACION, 
        D.DT_FECHA_CREACION
        FROM (
            SELECT 
                ROW_NUMBER() OVER (ORDER BY DATA.DT_FECHA_CREACION DESC) AS INT_ROW_NUMBER,
                COUNT(1) OVER () AS INT_NUMERO_TOTAL_REGISTRO,
                INT_IDGRUPO, 
                VC_USUARIO_CREACION, 
                DT_FECHA_CREACION
            FROM (
                        SELECT T1.INT_IDGRUPO,T1.VC_USUARIO_CREACION,T1.DT_FECHA_CREACION
                        FROM(
                          SELECT E.INT_IDGRUPO, E.VC_USUARIO_CREACION, E.DT_FECHA_CREACION, E.INT_IDSOLICITUD_DET
                          FROM EXTORNO e 
                          WHERE E.CH_FLAG_ESTADO = 'A'
                          UNION ALL
                          SELECT EE.INT_IDGRUPO,EE.VC_USUARIO_CREACION,EE.DT_FECHA_CREACION, EE.INT_IDSOLICITUD_DET
                          FROM EXTORNO_ERROR ee
                          WHERE EE.CH_FLAG_ESTADO = 'A' ) T1
                        WHERE 1=1
                        AND (p_intSolicitudDet IS NULL OR p_intSolicitudDet = 0 OR T1.INT_IDSOLICITUD_DET = p_intSolicitudDet )
                        AND T1.DT_FECHA_CREACION >= NVL(p_dtFechaDesde, T1.DT_FECHA_CREACION)
                        AND T1.DT_FECHA_CREACION <= NVL(p_dtFechaHasta, T1.DT_FECHA_CREACION)
                        AND (p_vcCodigo IS NULL OR LPAD(TO_CHAR(T1.INT_IDGRUPO), 7, '0') LIKE '%' || p_vcCodigo || '%')
                        AND ( (T1.INT_IDSOLICITUD_DET IS NULL
                             AND p_vcNumeroDocumento IS NULL
                             AND (p_intIdEsf IS NULL OR p_intIdEsf = 0) ) 
                        OR (T1.INT_IDSOLICITUD_DET IS NOT NULL AND  EXISTS (SELECT 1
                                     FROM SOLICITUD_DETALLE SOLDET
                                     INNER JOIN SOLICITUD SOL ON SOLDET.INT_IDSOLICITUD = SOL.INT_IDSOLICITUD
                                     WHERE SOLDET.INT_IDSOLICITUD_DET = T1.INT_IDSOLICITUD_DET                                     
                                      AND (SOLDET.VC_NUMERO_DOCUMENTO = NVL(p_vcNumeroDocumento, SOLDET.VC_NUMERO_DOCUMENTO) OR p_vcNumeroDocumento IS NULL)                    
                                     AND (p_intIdEsf IS NULL OR p_intIdEsf = 0 OR SOL.INT_IDIFI = p_intIdEsf) )  ) )
                        GROUP BY T1.INT_IDGRUPO,T1.VC_USUARIO_CREACION,T1.DT_FECHA_CREACION  
                        ) DATA
        ) D
        WHERE INT_ROW_NUMBER BETWEEN ((P_INTSTARTINDEX) * P_INTPAGESIZE + 1) AND ((P_INTSTARTINDEX + 1) * P_INTPAGESIZE);
    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_EXTORNO', 'S_LISTAR_ALL', vcErrorStack, vcErrorBacktace);
          RAISE_APPLICATION_ERROR(-20209, 'PKG_EXTORNO.S_LISTAR_ALL:' || vcErrorStack || '; ' || vcErrorBacktace);
    END S_LISTAR_ALL;

  PROCEDURE S_LISTAR_DETALLE(p_intStartIndex IN  NUMBER,
                             p_intPageSize   IN  NUMBER,
                             p_intIdGrupo    IN  NUMBER,
                             p_curTabla      OUT SYS_REFCURSOR)
    AS
    BEGIN
      OPEN p_curTabla FOR
      SELECT D.INT_NUMERO_TOTAL_REGISTRO,
             D.INT_ROW_NUMBER,
             D.INT_IDEXTORNO,
             D.VC_TIPO_DOCUMENTO,
			 D.INT_IDSOLICITUD_DET,
             D.VC_NUMERO_DOCUMENTO,
             D.VC_RAZON_SOCIAL,
             D.DEC_MONTO_EXTORNO,
             D.DT_FECHA_CREACION,
             D.INT_IDSOLICITUD,
             D.VC_OBSERVACIONES
        FROM (SELECT COUNT(1) OVER () AS INT_NUMERO_TOTAL_REGISTRO,
                     ROW_NUMBER() OVER (ORDER BY DT_FECHA_CREACION DESC, INT_IDEXTORNO DESC) AS INT_ROW_NUMBER,
                     INT_IDEXTORNO,
                     VC_TIPO_DOCUMENTO,
					 INT_IDSOLICITUD_DET,
                     VC_NUMERO_DOCUMENTO,
                     VC_RAZON_SOCIAL,
                     DEC_MONTO_EXTORNO,
                     DT_FECHA_CREACION,
                     INT_IDSOLICITUD,
                     VC_OBSERVACIONES
            FROM (SELECT BS.INT_IDEXTORNO AS INT_IDEXTORNO,
						 DE.INT_IDSOLICITUD_DET,
                         DE.VC_TIPO_DOCUMENTO,
                         DE.VC_NUMERO_DOCUMENTO,
                         NVL(VC_RAZON_SOCIAL, DE.VC_NOMBRES || ' ' || DE.VC_APELLIDO_PATERNO || ' ' || DE.VC_APELLIDO_MATERNO) AS VC_RAZON_SOCIAL,
                         DE.DEC_MONTO_PRESTAMO AS DEC_MONTO_EXTORNO,
                         BS.DT_FECHA_CREACION,
                         DE.INT_IDSOLICITUD,
                         BS.VC_OBSERVACIONES
                FROM EXTORNO BS
                  LEFT JOIN SOLICITUD_DETALLE DE
                    ON DE.INT_IDSOLICITUD_DET = BS.INT_IDSOLICITUD_DET
                WHERE BS.INT_IDGRUPO = p_intIdGrupo
                UNION ALL
              SELECT BSE.INT_IDEXTORNO_ER AS INT_IDEXTORNO,
                     NULL AS VC_TIPO_DOCUMENTO,
					 NULL AS INT_IDSOLICITUD_DET,
                     NULL AS VC_NUMERO_DOCUMENTO,
                     NULL AS VC_RAZON_SOCIAL,
                     NULL AS DEC_MONTO_EXTORNO,
                     BSE.DT_FECHA_CREACION,
                     NULL AS INT_IDSOLICITUD,
                     BSE.VC_OBSERVACIONES
                FROM EXTORNO_ERROR BSE
                WHERE BSE.INT_IDGRUPO = p_intIdGrupo)) D
        WHERE (D.INT_ROW_NUMBER BETWEEN ((P_INTSTARTINDEX) * P_INTPAGESIZE + 1) AND (P_INTSTARTINDEX + 1) * P_INTPAGESIZE)
        ORDER BY D.DT_FECHA_CREACION;
    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_EXTORNO', 'S_LISTAR_DETALLE', vcErrorStack, vcErrorBacktace);
          RAISE_APPLICATION_ERROR(-20209, 'Error en PKG_EXTORNO.S_LISTAR_DETALLE: ' || vcErrorStack || '; ' || vcErrorBacktace);
    END S_LISTAR_DETALLE;

  PROCEDURE I_REGISTRAR_EXTORNO_MASIVO(p_extornoList IN  EXTORNO_LIST,
									   p_intIdSolicitud     OUT EXTORNO.INT_IDGRUPO%TYPE,
                                       p_vchMsg      OUT VARCHAR2)
    AS
      v_new_group NUMBER;
      v_count_doc NUMBER;
      v_estado_id VARCHAR2(10 BYTE);
	  intRegistros NUMBER;

    BEGIN
p_intIdSolicitud:= 0;
	 intRegistros :=p_extornoList.COUNT;

     IF intRegistros > IntMaxRegistros THEN
        p_vchMsg:='El n'||CHR(250 USING NCHAR_CS)||'mero de registros m'||CHR(225 USING NCHAR_CS)||'ximo permitido es de ' || IntMaxRegistros || '.';
        RETURN;
     END IF;

      -- Generar un nuevo grupo para los extornos
      v_new_group := EXTORNO_GRUPO_SEQ.NEXTVAL;

      -- Recorrer la lista de extornos
      FOR i IN (SELECT *
          FROM TABLE (p_extornoList))
      LOOP
        BEGIN
          SELECT COUNT(1)
            INTO v_count_doc
            FROM SOLICITUD_DETALLE sd
              JOIN SOLICITUD S
                ON (SD.INT_IDSOLICITUD = S.INT_IDSOLICITUD)
            WHERE SD.VC_NUMERO_DOCUMENTO = I.VC_NUMERO_DOCUMENTO
              AND SD.INT_IDSOLICITUD_DET = I.INT_IDSOLICITUD_DET;

          -- Verificar el estado del detalle de la solicitud
          IF v_count_doc > 0
          THEN
            SELECT d.VC_ESTADO
              INTO v_estado_id
              FROM SOLICITUD S
                LEFT JOIN SOLICITUD_DETALLE D
                  ON (S.INT_IDSOLICITUD = D.INT_IDSOLICITUD)
              WHERE D.INT_IDSOLICITUD_DET = I.INT_IDSOLICITUD_DET
                AND D.VC_NUMERO_DOCUMENTO = I.VC_NUMERO_DOCUMENTO;

            -- Insertar en EXTORNO independientemente de las validaciones
            INSERT INTO EXTORNO (
              INT_IDSOLICITUD_DET, CH_FLAG_ESTADO, VC_USUARIO_CREACION, DT_FECHA_CREACION, INT_IDGRUPO, VC_OBSERVACIONES
            )
            VALUES (i.INT_IDSOLICITUD_DET, 'A', i.VC_USUARIO_CREACION, SYSDATE, v_new_group, CASE WHEN v_estado_id NOT IN ('ELE') THEN 'Estado no v lido para extorno. Estado actual (' || v_estado_id || ')' ELSE 'OK' END);
          ELSE

            INSERT INTO EXTORNO_ERROR (
              INT_IDSOLICITUD_DET, CH_FLAG_ESTADO, VC_USUARIO_CREACION, DT_FECHA_CREACION, INT_IDGRUPO, VC_OBSERVACIONES
            )
            VALUES (NULL, 'A', i.VC_USUARIO_CREACION, SYSDATE, v_new_group, 'No se encontr  detalle con n mero documento: ' || i.VC_NUMERO_DOCUMENTO || ' para el id ' || i.INT_IDSOLICITUD_DET);
          END IF;

          -- Si pasa todas las validaciones, actualizar SOLICITUD_DETALLE a estado EXTORNADO
          IF v_count_doc = 1
            AND v_estado_id IN ('ELE')
          THEN
            UPDATE SOLICITUD_DETALLE sd
              SET sd.VC_ESTADO = 'EXT'
              WHERE sd.INT_IDSOLICITUD_DET = i.INT_IDSOLICITUD_DET;
          END IF;
          COMMIT;
          p_vchMsg := 'OK';
        EXCEPTION
          WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
              vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
              p_vchMsg := 'PKG_EXTORNO.I_REGISTRAR_EXTORNO_MASIVO:' || vcErrorStack || '; ' || vcErrorBacktace;
              PKG_LOG_ERROR.I_REGISTRAR('PKG_EXTORNO', 'I_REGISTRAR_EXTORNO_MASIVO', vcErrorStack, vcErrorBacktace, v_new_group);
              RAISE_APPLICATION_ERROR(-20209, 'PKG_EXTORNO.I_REGISTRAR_EXTORNO_MASIVO:' || vcErrorStack || '; ' || vcErrorBacktace);
        END;
      END LOOP;

	  p_intIdSolicitud := v_new_group;

    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          ROLLBACK;
          p_vchMsg := 'PKG_EXTORNO.I_REGISTRAR_EXTORNO_MASIVO:' || vcErrorStack || '; ' || vcErrorBacktace;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_EXTORNO', 'I_REGISTRAR_EXTORNO_MASIVO', vcErrorStack, vcErrorBacktace, v_new_group);
          RAISE_APPLICATION_ERROR(-20209, 'PKG_EXTORNO.I_REGISTRAR_EXTORNO_MASIVO:' || vcErrorStack || '; ' || vcErrorBacktace);
    END I_REGISTRAR_EXTORNO_MASIVO;

  PROCEDURE S_LISTAR_DETALLE_ALL(p_intIdGrupo IN  NUMBER,
                                 p_curTabla   OUT SYS_REFCURSOR)
    AS
    BEGIN
      OPEN p_curTabla FOR
      SELECT D.INT_NUMERO_TOTAL_REGISTRO,
             D.INT_ROW_NUMBER,
             D.INT_IDEXTORNO,
             D.VC_TIPO_DOCUMENTO,
			 D.INT_IDSOLICITUD_DET,
             D.VC_NUMERO_DOCUMENTO,
             D.VC_RAZON_SOCIAL,
             D.DEC_MONTO_EXTORNO,
             D.DT_FECHA_CREACION,
             D.INT_IDSOLICITUD,
             D.VC_OBSERVACIONES
        FROM (SELECT COUNT(1) OVER () AS INT_NUMERO_TOTAL_REGISTRO,
                     ROW_NUMBER() OVER (ORDER BY DT_FECHA_CREACION DESC, INT_IDEXTORNO DESC) AS INT_ROW_NUMBER,
                     INT_IDEXTORNO,
                     VC_TIPO_DOCUMENTO,
					 INT_IDSOLICITUD_DET,
                     VC_NUMERO_DOCUMENTO,
                     VC_RAZON_SOCIAL,
                     DEC_MONTO_EXTORNO,
                     DT_FECHA_CREACION,
                     INT_IDSOLICITUD,
                     VC_OBSERVACIONES
            FROM (SELECT BS.INT_IDEXTORNO AS INT_IDEXTORNO,
                         DE.VC_TIPO_DOCUMENTO,
						 DE.INT_IDSOLICITUD_DET,
                         DE.VC_NUMERO_DOCUMENTO,
                         NVL(VC_RAZON_SOCIAL, DE.VC_NOMBRES || ' ' || DE.VC_APELLIDO_PATERNO || ' ' || DE.VC_APELLIDO_MATERNO) AS VC_RAZON_SOCIAL,
                         DE.DEC_MONTO_PRESTAMO AS DEC_MONTO_EXTORNO,
                         BS.DT_FECHA_CREACION,
                         DE.INT_IDSOLICITUD,
                         BS.VC_OBSERVACIONES
                FROM EXTORNO BS
                  LEFT JOIN SOLICITUD_DETALLE DE
                    ON DE.INT_IDSOLICITUD_DET = BS.INT_IDSOLICITUD_DET
                WHERE BS.INT_IDGRUPO = p_intIdGrupo
                UNION ALL
              SELECT BSE.INT_IDEXTORNO_ER AS INT_IDEXTORNO,
                     NULL AS VC_TIPO_DOCUMENTO,
					 NULL AS INT_IDSOLICITUD_DET,
                     NULL AS VC_NUMERO_DOCUMENTO,
                     NULL AS VC_RAZON_SOCIAL,
                     NULL AS DEC_MONTO_EXTORNO,
                     BSE.DT_FECHA_CREACION,
                     NULL AS INT_IDSOLICITUD,
                     BSE.VC_OBSERVACIONES
                FROM EXTORNO_ERROR BSE
                WHERE BSE.INT_IDGRUPO = p_intIdGrupo)) D
        ORDER BY D.INT_ROW_NUMBER DESC;
    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_EXTORNO', 'S_LISTAR_DETALLE_ALL', vcErrorStack, vcErrorBacktace);
          RAISE_APPLICATION_ERROR(-20209, 'PKG_EXTORNO.S_LISTAR_DETALLE_ALL:' || vcErrorStack || '; ' || vcErrorBacktace);
    END S_LISTAR_DETALLE_ALL;

    PROCEDURE I_VALIDAR_COLUMNAS(
              p_nroColumnas IN NUMBER,
              p_vchMsg      OUT VARCHAR2
                                )
    AS

    BEGIN
        p_vchMsg :='OK';

        IF p_nroColumnas > IntCamposSol THEN

            p_vchMsg := 'Se ha detectado un registro con un n'|| CHR(250 USING NCHAR_CS) ||'mero de columnas diferente al esperado.';

        END IF;

    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

          p_vchMsg := 'PKG_EXTORNO.I_VALIDAR_COLUMNAS:' || vcErrorStack || '; ' || vcErrorBacktace;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_EXTORNO', 'I_VALIDAR_COLUMNAS', vcErrorStack, vcErrorBacktace, '');
          RAISE_APPLICATION_ERROR(-20209, 'PKG_EXTORNO.I_VALIDAR_COLUMNAS:' || vcErrorStack || '; ' || vcErrorBacktace);
    END I_VALIDAR_COLUMNAS;


    PROCEDURE S_LISTAR_PENDIENTE_CORREO(p_curTabla          OUT SYS_REFCURSOR)
    AS
    BEGIN
      OPEN p_curTabla FOR
      SELECT T1.INT_IDGRUPO,
      T1.VC_USUARIO_CREACION,
      SUM(T1.INT_APROBADOS) INT_APROBADOS,
      SUM(T1.INT_RECHAZADOS) INT_RECHAZADOS,
      SUM(T1.INT_NUMERO_TOTAL_REGISTRO) INT_NUMERO_TOTAL_REGISTRO 
      FROM (SELECT E.INT_IDGRUPO,
      CASE WHEN E.VC_OBSERVACIONES <> 'OK' THEN 1 ELSE 0 END AS INT_RECHAZADOS,
      CASE WHEN E.VC_OBSERVACIONES = 'OK' THEN 1 ELSE 0 END AS INT_APROBADOS,
      E.VC_USUARIO_CREACION,
      1 INT_NUMERO_TOTAL_REGISTRO
      FROM EXTORNO e
      WHERE E.CH_FLAG_ESTADO = 'A' AND E.VC_ENVIO_CORREO = 'PENDIENTE'
      UNION ALL
      SELECT EE.INT_IDGRUPO,
      1 INT_RECHAZADOS,
      0 INT_APROBADOS,
      EE.VC_USUARIO_CREACION,
      1 INT_NUMERO_TOTAL_REGISTRO
      FROM EXTORNO_ERROR ee
      WHERE EE.CH_FLAG_ESTADO= 'A' AND EE.VC_ENVIO_CORREO = 'PENDIENTE' ) T1
      GROUP BY T1.INT_IDGRUPO,T1.VC_USUARIO_CREACION
      ORDER BY T1.INT_IDGRUPO ASC ;

    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_EXTORNO', 'S_LISTAR_PENDIENTE_CORREO', vcErrorStack, vcErrorBacktace);
          RAISE_APPLICATION_ERROR(-20209, 'PKG_EXTORNO.S_LISTAR_PENDIENTE_CORREO:' || vcErrorStack || '; ' || vcErrorBacktace);
    END S_LISTAR_PENDIENTE_CORREO;


    PROCEDURE U_ACTUALIZAR_EXTORNO_RESULTADO(p_intIdGrupo IN NUMBER)
    AS
      PRAGMA AUTONOMOUS_TRANSACTION;
    BEGIN

      UPDATE EXTORNO E
        SET E.VC_ENVIO_CORREO = 'ENVIADO', E.VC_USUARIO_MODIFICACION = USER, E.DT_FECHA_MODIFICACION = SYSDATE, E.VC_TERMINAL_MODIFICACION = SYS_CONTEXT('USERENV', 'IP_ADDRESS')
        WHERE E.CH_FLAG_ESTADO= 'A' AND E.VC_ENVIO_CORREO = 'PENDIENTE';

      UPDATE EXTORNO_ERROR E
        SET E.VC_ENVIO_CORREO = 'ENVIADO', E.VC_USUARIO_MODIFICACION = USER, E.DT_FECHA_MODIFICACION = SYSDATE, E.VC_TERMINAL_MODIFICACION = SYS_CONTEXT('USERENV', 'IP_ADDRESS')
        WHERE E.CH_FLAG_ESTADO= 'A' AND E.VC_ENVIO_CORREO = 'PENDIENTE';
      COMMIT;
    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          ROLLBACK;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_EXTORNO', 'U_ACTUALIZAR_EXTORNO_RESULTADO', vcErrorStack, vcErrorBacktace, 'INT_IDGRUPO:' || TO_CHAR(p_intIdGrupo));
          RAISE_APPLICATION_ERROR(-20213, 'PKG_EXTORNO.U_ACTUALIZAR_EXTORNO_RESULTADO:' || vcErrorStack || '; ' || vcErrorBacktace || '; INT_IDGRUPO:' || TO_CHAR(p_intIdGrupo));
    END U_ACTUALIZAR_EXTORNO_RESULTADO;

END PKG_EXTORNO;




/
--------------------------------------------------------
--  DDL for Package Body PKG_LOG_ERROR
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "US_BASE_MODULAR"."PKG_LOG_ERROR" 
  AS

  PROCEDURE I_REGISTRAR(p_vcPaquete IN LOG_ERROR.VC_PAQUETE % TYPE,
                        p_vcObjeto  IN LOG_ERROR.VC_OBJETO % TYPE,
                        p_vcError   IN LOG_ERROR.VC_ERROR % TYPE,
                        p_vcTrazado IN LOG_ERROR.VC_TRAZADO % TYPE,
                        p_vcMensaje IN LOG_ERROR.VC_MENSAJE % TYPE DEFAULT NULL)
    AS
      PRAGMA AUTONOMOUS_TRANSACTION;
    BEGIN

      INSERT INTO LOG_ERROR (
        INT_IDLOG_ERROR, DT_FECHA, VC_PAQUETE, VC_OBJETO, VC_ERROR, VC_TRAZADO, VC_MENSAJE
      )
      VALUES (LOG_ERROR_SEQ.NEXTVAL, SYSDATE, p_vcPaquete, p_vcObjeto, p_vcError, p_vcTrazado, p_vcMensaje);
      COMMIT;

    EXCEPTION
      WHEN OTHERS THEN INSERT INTO LOG_ERROR (
            INT_IDLOG_ERROR, DT_FECHA, VC_PAQUETE, VC_OBJETO, VC_ERROR, VC_TRAZADO, VC_MENSAJE
          )
          VALUES (LOG_ERROR_SEQ.NEXTVAL, SYSDATE, 'PKG_LOG_ERROR', 'I_REGISTRAR', DBMS_UTILITY.FORMAT_ERROR_STACK, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, p_vcMensaje);
          COMMIT;
    END I_REGISTRAR;

END PKG_LOG_ERROR;


