  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "US_BASE_MODULAR"."PKG_PLANTILLA_CORREO" 
  AS

  PROCEDURE S_OBTENER_PLANTILLA_X_CODIGO(p_vcCodigo IN  US_BASE.BASE_PLANTILLAS_CORREO.VC_CODIGO % TYPE,
                                         p_curTabla OUT SYS_REFCURSOR)
    AS
