          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_PLANTILLA_CORREO', 'S_OBTENER_PLANTILLA_X_CODIGO', vcErrorStack, vcErrorBacktace, 'VC_CODIGO:' || TO_CHAR(p_vcCodigo));
          RAISE_APPLICATION_ERROR(-20241, 'PKG_PLANTILLA_CORREO.S_OBTENER_PLANTILLA_X_CODIGO:' || vcErrorStack || '; ' || vcErrorBacktace || 'VC_CODIGO:' || TO_CHAR(p_vcCodigo));
    END S_OBTENER_PLANTILLA_X_CODIGO;

END PKG_PLANTILLA_CORREO;


/
--------------------------------------------------------
--  DDL for Package Body PKG_PRODUCTO
--------------------------------------------------------

create or replace PACKAGE BODY     "US_BASE_MODULAR"."PKG_PRODUCTO" AS

  PROCEDURE I_INSERTAR(p_intIdIFI           IN SOLICITUD.INT_IDIFI%TYPE,
                       p_intIdProducto      IN SOLICITUD.INT_IDPRODUCTO%TYPE,
                       p_intIdMoneda        IN SOLICITUD.INT_IDMONEDA%TYPE,
                       p_intIdTipoOperacion IN SOLICITUD.INT_IDTIPO_OPERACION%TYPE,
                       p_vcUsuario          IN SOLICITUD.VC_USUARIO_CREACION%TYPE,
                       p_vcIp               IN SOLICITUD.VC_TERMINAL_CREACION%TYPE,
                       p_clFile1            IN SOLICITUD_ARCHIVOS.CL_FILE1%TYPE,
                       p_clFile2            IN SOLICITUD_ARCHIVOS.CL_FILE2%TYPE,
                       p_intIdSolicitud     OUT SOLICITUD.INT_IDSOLICITUD%TYPE,
                       p_mensaje            OUT VARCHAR2,
                       p_error              OUT VARCHAR2) AS

    PRAGMA AUTONOMOUS_TRANSACTION;
    intIdSolicitudMax SOLICITUD.INT_IDSOLICITUD%TYPE;
    vcCodigoMax       SOLICITUD.VC_CODIGO%TYPE;
    dtFechaCreacion   SOLICITUD.DT_FECHA_CREACION%TYPE;
    intCount          NUMBER;
    intLargoFile1     NUMBER;
    intLargoFile2     NUMBER;
    intCantSolicitud  NUMBER;
    intCantRepresLeg  NUMBER;
    intIdEstado       SOLICITUD.INT_IDESTADO%TYPE;
    vcNombreIfi       SOLICITUD.VC_NOMBRE_IFI%TYPE;
    intRegistros      SOLICITUD.INT_REGISTROS%TYPE;
    vcCodProducto     US_BASE.BASE_PRODUCTO_CONFIG.VC_CODIGOPRODUCTO%TYPE;
    vcError           VARCHAR2(4000);
    vcMensaje         VARCHAR2(4000);

  BEGIN

    SELECT NVL(DBMS_LOB.GETLENGTH(p_clFile1), -1),
           NVL(DBMS_LOB.GETLENGTH(p_clFile2), -1)
      INTO intLargoFile1, intLargoFile2
      FROM DUAL;

    IF intLargoFile1 <= 0 THEN
      p_intIdSolicitud := 0;
      p_mensaje        := 'El archivo de solicitudes: esta vacio';
      p_error          := 'Archivo de solicitudes: esta vacio';
      ROLLBACK;
      RETURN;
    END IF;

    BEGIN
      intCantSolicitud := TO_NUMBER(NVL(TRIM(PKG_TABLA_DETALLE.F_OBT_VALOR_TABLADETALLE('CARGAREGISTROS','SOLICITUD', 1)), '5000'));
      intCantRepresLeg := TO_NUMBER(NVL(TRIM(PKG_TABLA_DETALLE.F_OBT_VALOR_TABLADETALLE('CARGAREGISTROS', 'REPRESENTANTE',  1)), '5000'));
    EXCEPTION
      WHEN OTHERS THEN
        p_intIdSolicitud := -10;
        p_mensaje        := 'Linea: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ', Error: ' || SQLERRM;
        p_error          := 'PKG_PRODUCTO.I_INSERTAR: ' || SQLCODE || ', Linea: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        ROLLBACK;
        RETURN;
    END;

    SELECT COUNT(1)
      INTO intRegistros
      FROM TABLE (SELECT PKG_BASE.F_CLOB_A_FILAS(p_clFile1) FROM DUAL) T
     WHERE TRIM(T.COLUMN_VALUE) IS NOT NULL;

    IF intRegistros > intCantSolicitud THEN
      p_intIdSolicitud := -1;
	  p_mensaje        := 'El número de registros excede al máximo permitido de ' || TRIM(TO_CHAR(intCantSolicitud)) || ' en el archivo de solicitudes.';
      p_error          := 'Archivo de solicitudes: contiene mas de ' || TRIM(TO_CHAR(intCantSolicitud)) || ' registros.';
      ROLLBACK;
      RETURN;
    END IF;

    SELECT COUNT(1)
      INTO intRegistros
      FROM TABLE (SELECT PKG_BASE.F_CLOB_A_FILAS(p_clFile2) FROM DUAL) T
     WHERE TRIM(T.COLUMN_VALUE) IS NOT NULL;

    IF intRegistros > intCantRepresLeg THEN
      p_intIdSolicitud := -2;
	  p_mensaje        := 'El número de registros excede al máximo permitido de ' || TRIM(TO_CHAR(intCantSolicitud)) || ' en el archivo de representante legal.';
      p_error          := 'Archivo de representantes: contiene mas de ' || TRIM(TO_CHAR(intCantSolicitud)) || ' registros.';
      ROLLBACK;
      RETURN;
    END IF;

    SELECT COUNT(1)
      INTO intRegistros
      FROM (SELECT REGEXP_REPLACE(REPLACE(T.COLUMN_VALUE, '|', '| '), '^\|', ' |') AS REGISTRO
              FROM TABLE (SELECT PKG_BASE.F_CLOB_A_FILAS(p_clFile1) FROM DUAL) T
             WHERE TRIM(T.COLUMN_VALUE) IS NOT NULL) D
     WHERE PKG_BASE.F_EXPRESSION_COUNT(TRIM(D.REGISTRO), '|') <> IntCamposSol;


    IF intRegistros > 0 THEN
      BEGIN
        SELECT SUBSTR(LISTAGG('La <strong>fila ' || E.FILA || '</strong> contiene <strong>' || TRIM(TO_CHAR(NVL(PKG_BASE.F_EXPRESSION_COUNT(TRIM(E.REGISTRO), '|'), 0) + 1)) || ' columnas</strong>, pero se esperaba <strong>' || TO_CHAR(IntCamposSol + 1) || '</strong>', '</br> ') WITHIN GROUP(ORDER BY E.FILA), 1, 1000)
          INTO vcMensaje
          FROM (SELECT D.FILA, D.REGISTRO, D.DAT01
                  FROM (SELECT ROWNUM AS FILA,
                               REGEXP_REPLACE(REPLACE(T.COLUMN_VALUE, '|', '| '), '^\|', ' |') AS REGISTRO,
                               T.COLUMN_VALUE AS DAT01
                          FROM TABLE (SELECT PKG_BASE.F_CLOB_A_FILAS(p_clFile1)
                                        FROM DUAL) T
                         WHERE TRIM(T.COLUMN_VALUE) IS NOT NULL) D
                 WHERE PKG_BASE.F_EXPRESSION_COUNT(TRIM(D.REGISTRO), '|') <> IntCamposSol) E
         WHERE ROWNUM <= 3;
      EXCEPTION
        WHEN OTHERS THEN
          p_intIdSolicitud := -20;
          p_mensaje        := 'Linea: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ', Error: ' || SQLERRM;
          p_error          := 'PKG_PRODUCTO.I_INSERTAR: ' || SQLCODE || ', Linea: ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          ROLLBACK;
          RETURN;
      END;

      IF INSTR(vcMensaje, ',', -1) > 0 THEN
        vcError := SUBSTR(vcMensaje, 1, INSTR(vcMensaje, ',', -1) - 1);
      ELSE
        vcError := vcMensaje;
      END IF;

      --SELECT 'El archivo de solicitudes: ' || DECODE(intRegistros, 1, 'Existe ', 'Existen ') || TRIM(TO_CHAR(intRegistros)) || DECODE(intRegistros, 1, ' registro  ', ' registros  ') ||  UNISTR('con n\u00FAmero de columnas diferente a lo requerido.') || vcEnter || vcError
      --  INTO p_mensaje
      --  FROM DUAL;
	  SELECT DECODE(intRegistros, 1, 'Se ha detectado un registro con un n'|| CHR(250 USING NCHAR_CS) ||'mero de columnas diferente al esperado', 'Se han detectado registros con un n'|| CHR(250 USING NCHAR_CS) ||'mero de columnas diferente al esperado') 
      INTO p_mensaje
      FROM DUAL;
      
      p_mensaje := p_mensaje || '</br>' || TRIM(vcMensaje);	
      
      p_intIdSolicitud := -3;
      p_error          := vcError;
      ROLLBACK;
      RETURN;
    END IF;

    SELECT COUNT(1)
      INTO intRegistros
      FROM (SELECT REGEXP_REPLACE(REPLACE(T.COLUMN_VALUE, '|', '| '), '^\|', ' |') AS REGISTRO
              FROM TABLE (SELECT PKG_BASE.F_CLOB_A_FILAS(p_clFile2) FROM DUAL) T
             WHERE TRIM(T.COLUMN_VALUE) IS NOT NULL) D
     WHERE PKG_BASE.F_EXPRESSION_COUNT(TRIM(D.REGISTRO), '|') <> IntCamposRep;

    IF intRegistros > 0 THEN      
      SELECT SUBSTR(LISTAGG('La <strong>fila ' || E.FILA || '</strong> contiene <strong>' || TRIM(TO_CHAR(NVL(PKG_BASE.F_EXPRESSION_COUNT(TRIM(E.REGISTRO), '|'), 0) + 1)) || ' columnas</strong>, pero se esperaba <strong>' || TO_CHAR(IntCamposRep + 1) || '</strong>', '</br> ') WITHIN GROUP(ORDER BY E.FILA), 1, 1000)
        INTO vcMensaje
        FROM (SELECT D.FILA, D.REGISTRO
                FROM (SELECT ROWNUM AS FILA,
                             REGEXP_REPLACE(REPLACE(T.COLUMN_VALUE, '|', '| '), '^\|', ' |') AS REGISTRO
                        FROM TABLE (SELECT PKG_BASE.F_CLOB_A_FILAS(p_clFile2)
                                      FROM DUAL) T
                       WHERE TRIM(T.COLUMN_VALUE) IS NOT NULL) D
               WHERE PKG_BASE.F_EXPRESSION_COUNT(TRIM(D.REGISTRO), '|') <> IntCamposRep) E
       WHERE ROWNUM <= 3;

      vcError          := SUBSTR(vcMensaje, 1, INSTR(vcMensaje, ',', -1) - 1);
      p_intIdSolicitud := -4;
      --SELECT 'El archivo de representantes: ' || DECODE(intRegistros, 1, 'Existe ', 'Existen ') || TRIM(TO_CHAR(intRegistros)) || DECODE(intRegistros, 1, ' registro  ', ' registros  ') ||  UNISTR('con n\u00FAmero de columnas diferente a lo requerido.') || vcEnter || vcError
      --  INTO p_mensaje
      --  FROM DUAL;
	  SELECT DECODE(intRegistros, 1, 'Se ha detectado un registro con un n'|| CHR(250 USING NCHAR_CS) ||'mero de columnas diferente al esperado', 'Se han detectado registros con un n'|| CHR(250 USING NCHAR_CS) ||'mero de columnas diferente al esperado') 
      INTO p_mensaje
      FROM DUAL;
      
      p_mensaje := p_mensaje || '</br>' || TRIM(vcMensaje);	
      
      p_error          := 'Archivo de representantes: ' || vcError;
      ROLLBACK;
      RETURN;
    END IF;

    SELECT COUNT(1)
      INTO intCount
      FROM US_BASE.BASE_ESTRUCTURA_CONFIG B
     WHERE B.INT_IDPRODUCTO = p_intIdProducto;

    IF intCount = 0 THEN
      p_intIdSolicitud := -5;
      p_mensaje        := 'No existe Configuracion de Estructura para este producto.';
      p_error          := 'No existe Configuracion de Estructura para este producto.';
      ROLLBACK;
      RETURN;
    END IF;

    SELECT COUNT(1)
      INTO intCount
      FROM US_BASE.BASE_REGLA_PRODUCTO B
     WHERE B.INT_IDPROD = p_intIdProducto;

    IF intCount = 0 THEN
      p_intIdSolicitud := -6;
      p_mensaje        := 'No existe Configuracion de Reglas para este producto.';
      p_error          := 'No existe Configuracion de Reglas para este producto.';
      ROLLBACK;
      RETURN;
    END IF;

    SELECT COUNT(1)
      INTO intCount
      FROM US_BASE.BASE_PRODUCTO_CONFIG B
     WHERE B.INT_IDPRODUCTO = p_intIdProducto;

    IF intCount = 1 THEN
      SELECT B.VC_CODIGOPRODUCTO
        INTO vcCodProducto
        FROM US_BASE.BASE_PRODUCTO_CONFIG B
       WHERE B.INT_IDPRODUCTO = p_intIdProducto;
    ELSE
      p_intIdSolicitud := -7;
      p_mensaje        := 'No existe Configuracion de Producto para este producto.';
      p_error          := 'No existe Configuracion de Producto para este producto.';
      ROLLBACK;
      RETURN;
    END IF;

    SELECT COUNT(1)
      INTO intCount
      FROM PRODUCTO_IFI I
     WHERE I.INT_IDIFI = p_intIdIFI;

    IF intCount > 0 THEN
      SELECT I.VC_NOMBREIFI
        INTO vcNombreIfi
        FROM PRODUCTO_IFI I
       WHERE I.INT_IDIFI = p_intIdIFI
         AND ROWNUM <= 1;
    ELSE
      p_intIdSolicitud := -8;
      p_mensaje        := 'No existe Entidad del Sistema Financiero asociada a este producto.';
      p_error          := 'No existe Entidad del Sistema Financiero asociada a este producto.';
      ROLLBACK;
      RETURN;
    END IF;

    SELECT SOLICITUD_SEQ.NEXTVAL INTO intIdSolicitudMax FROM DUAL;

    SELECT 'SOL' || TRIM(TO_CHAR(intIdSolicitudMax, '00000000')), SYSDATE
      INTO vcCodigoMax, dtFechaCreacion
      FROM DUAL;

    intCount := 0;

    SELECT COUNT(1)
      INTO intCount
      FROM US_BASE.BASE_TABLA_DETALLE D
     INNER JOIN US_BASE.BASE_TABLA T
        ON (T.INT_IDTABLA = D.INT_IDTABLA AND T.VC_CODTABLA = 'ESTSOLFIDEM')
     WHERE D.VC_CODTABLA_DETALLE = 'REG'
       AND D.CH_FLAG_ESTADO = 'A';

    IF intCount > 0 THEN
      SELECT D.INT_IDTABLA_DETALLE
        INTO intIdEstado
        FROM US_BASE.BASE_TABLA_DETALLE D
       INNER JOIN US_BASE.BASE_TABLA T
          ON (T.INT_IDTABLA = D.INT_IDTABLA AND
             T.VC_CODTABLA = 'ESTSOLFIDEM')
       WHERE D.VC_CODTABLA_DETALLE = 'REG'
         AND D.CH_FLAG_ESTADO = 'A';
    END IF;

    intCount := 0;

    SELECT COUNT(1)
      INTO intCount
      FROM PRODUCTO_IFI I
     WHERE I.INT_IDIFI = p_intIdIFI;

    IF intCount > 0 THEN
      SELECT I.VC_NOMBREIFI
        INTO vcNombreIfi
        FROM PRODUCTO_IFI I
       WHERE I.INT_IDIFI = p_intIdIFI
         AND ROWNUM <= 1;
    END IF;

    INSERT INTO SOLICITUD_ARCHIVOS
      (INT_IDSOLICITUD,
       CL_FILE1,
       CL_FILE2,
       VC_ESTADO,
       VC_USUARIO_CREACION,
       DT_FECHA_CREACION,
       VC_TERMINAL_CREACION)
    values
      (intIdSolicitudMax,
       empty_clob(),
       empty_clob(),
       'RE',
       p_vcUsuario,
       dtFechaCreacion,
       p_vcIp);
    COMMIT;

    UPDATE SOLICITUD_ARCHIVOS
       SET CL_FILE1 = p_clFile1, CL_FILE2 = p_clFile2
     WHERE INT_IDSOLICITUD = intIdSolicitudMax;
    COMMIT;

    SELECT COUNT(1)
      INTO intRegistros
      FROM TABLE (SELECT PKG_BASE.F_CLOB_A_FILAS(A.CL_FILE1)
                    FROM SOLICITUD_ARCHIVOS A
                   WHERE A.INT_IDSOLICITUD = intIdSolicitudMax) T
     WHERE TRIM(T.COLUMN_VALUE) IS NOT NULL;

    INSERT INTO SOLICITUD
      (INT_IDSOLICITUD,
       INT_IDPRODUCTO,
       VC_CODIGO,
       INT_IDIFI,
       VC_NOMBRE_IFI,
       INT_REGISTROS,
       INT_APROBADOS,
       INT_RECHAZADOS,
       INT_IDESTADO,
       INT_IDTIPO_OPERACION,
       INT_IDMONEDA,
       DEC_TOTAL_COBERTURADO_INICIAL,
       DEC_TOTAL_DESEMBOLSADO,
       DT_FECHA,
       VC_USUARIO_CREACION,
       DT_FECHA_CREACION,
       VC_TERMINAL_CREACION)
    VALUES
      (intIdSolicitudMax,
       p_intIdProducto,
       vcCodigoMax,
       p_intIdIFI,
       vcNombreIfi,
       intRegistros,
       0,
       0,
       intIdEstado,
       p_intIdTipoOperacion,
       p_intIdMoneda,
       0,
       0,
       TRUNC(dtFechaCreacion),
       p_vcUsuario,
       dtFechaCreacion,
       p_vcIp);
    COMMIT;



    INSERT INTO SOLICITUD_RESULTADOS
      (INT_IDSOLICITUD,
       INT_TOTAL_REGISTROS,
       VC_ESTADO,
       INT_REGISTROS_APROBADOS,
       INT_REGISTROS_RECHAZADOS,
       INT_REGISTROS_RECHAZADOS_ESTRUCTURA,
       INT_REGISTROS_RECHAZADOS_REGLAS,
       DT_FECHA,
       VC_USUARIO_CREACION,
       DT_FECHA_CREACION,
       VC_TERMINAL_CREACION)
    VALUES
      (intIdSolicitudMax,
       intRegistros,
       'REGISTRO',
       0,
       0,
       0,
       0,
       TRUNC(dtFechaCreacion),
       p_vcUsuario,
       dtFechaCreacion,
       p_vcIp);
    COMMIT;

    p_intIdSolicitud := intIdSolicitudMax;
    p_mensaje        := vcCodigoMax;
    p_error          := ' ';

  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      ROLLBACK;
      p_intIdSolicitud := -5;
      p_mensaje        := 'PKG_ARCHIVO.I_INSERTAR---> Nro Linea Error: ' || vcErrorStack||'; '||vcErrorBacktace;
      p_error          := 'PKG_ARCHIVO.I_INSERTAR---> Nro Linea Error: ' || vcErrorStack||'; '||vcErrorBacktace;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_PRODUCTO', 'I_INSERTAR', vcErrorStack, vcErrorBacktace);
      RAISE_APPLICATION_ERROR(-20141, 'PKG_PRODUCTO.I_INSERTAR:'|| vcErrorStack||'; '||vcErrorBacktace);
  END I_INSERTAR;

  PROCEDURE I_PROCESAR(p_intIdSolicitud IN SOLICITUD.INT_IDSOLICITUD%TYPE) as
  BEGIN
    PKG_BASE.I_PROCESAR_REGLAS(p_intIdSolicitud);
  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_PRODUCTO', 'I_PROCESAR', vcErrorStack, vcErrorBacktace, 'INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
      RAISE_APPLICATION_ERROR(-20142, 'PKG_PRODUCTO.I_PROCESAR:'|| vcErrorStack||'; '||vcErrorBacktace||'; INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
  END I_PROCESAR;

