/
--------------------------------------------------------
--  DDL for Package Body PKG_PRODUCTO_IFI
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "US_BASE_MODULAR"."PKG_PRODUCTO_IFI" AS

  PROCEDURE S_OBTENER_PRODUCTO_POR_IFI(p_intIdIFI IN PRODUCTO_IFI.INT_IDIFI%TYPE,
                                       p_curTabla OUT sys_refcursor) as
  BEGIN
    OPEN p_curTabla FOR
      SELECT P.INT_IDPRODUCTO_IFI,
             P.INT_IDPRODUCTO,
             P.INT_IDIFI,
             P.DT_FECHA_ASOCIACION,
             CH_FLAG_ESTADO
        FROM PRODUCTO_IFI P
       WHERE P.INT_IDIFI = p_intIdIFI;
  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_PRODUCTO_IFI', 'S_OBTENER_PRODUCTO_POR_IFI', vcErrorStack, vcErrorBacktace, 'INT_IDIFI:' || TO_CHAR(p_intIdIFI));      
      RAISE_APPLICATION_ERROR(-20161, 'PKG_PRODUCTO_IFI.S_OBTENER_PRODUCTO_POR_IFI:'|| vcErrorStack||'; '||vcErrorBacktace||'; INT_IDIFI:' || TO_CHAR(p_intIdIFI));            
  END S_OBTENER_PRODUCTO_POR_IFI;

  PROCEDURE I_REGISTRAR_PRODUCTO_IFI(p_intIdProducto    IN PRODUCTO_IFI.INT_IDPRODUCTO%TYPE,
                                     p_intIdIFI         IN PRODUCTO_IFI.INT_IDIFI%TYPE,
                                     p_vcCodigoIFI      IN PRODUCTO_IFI.VC_CODIGOIFI%TYPE,
                                     p_vchNombreIFI     IN PRODUCTO_IFI.VC_NOMBREIFI%TYPE,
                                     p_dtFechaAsoc      IN PRODUCTO_IFI.DT_FECHA_ASOCIACION%TYPE,
                                     o_intIdProductoIFI OUT INT,
                                     o_vchMensaje       OUT VARCHAR2) AS
  BEGIN
    INSERT INTO PRODUCTO_IFI
      (INT_IDPRODUCTO,
       INT_IDIFI,
       VC_CODIGOIFI,
       VC_NOMBREIFI,
       CH_FLAG_ESTADO,
       DT_FECHA_ASOCIACION,
       VC_USUARIO_CREACION,
       DT_FECHA_CREACION,
       VC_TERMINAL_CREACION)
    VALUES
      (p_intIdProducto,
       p_intIdIFI,
       p_vcCodigoIFI,
       p_vchNombreIFI,
       'A',
       p_dtFechaAsoc,
       '',
       SYSDATE,
       '')
    RETURNING INT_IDPRODUCTO_IFI INTO o_intIdProductoIFI;
    o_vchMensaje := 'OK';
  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      o_vchMensaje := 'PKG_PRODUCTO_IFI.I_REGISTRAR_PRODUCTO_IFI---> Nro Linea Error: ' || vcErrorStack||'; '||vcErrorBacktace||'; INT_IDIFI:' || TO_CHAR(p_intIdIFI);
      PKG_LOG_ERROR.I_REGISTRAR('PKG_PRODUCTO_IFI', 'I_REGISTRAR_PRODUCTO_IFI', vcErrorStack, vcErrorBacktace, 'INT_IDIFI:' || TO_CHAR(p_intIdIFI));      
  END I_REGISTRAR_PRODUCTO_IFI;

  PROCEDURE I_REACTIVAR_PRODUCTO_IFI(p_intIdIFI    IN PRODUCTO_IFI.INT_IDIFI%TYPE,
                                     p_dtFechaAsoc IN PRODUCTO_IFI.DT_FECHA_ASOCIACION%TYPE,
                                     o_vchMensaje  OUT VARCHAR2) AS

    p_intCantidadRegistro NUMBER;
  BEGIN
    p_intCantidadRegistro := 0;

    SELECT COUNT(1)
      INTO p_intCantidadRegistro
      FROM PRODUCTO_IFI P
     WHERE P.INT_IDIFI = p_intIdIFI;

    IF p_intCantidadRegistro = 0 THEN
      --  o_intIdReglaProducto := 0;
      o_vchMensaje := 'NO EXISTE';
    ELSE
      UPDATE PRODUCTO_IFI
         SET CH_FLAG_ESTADO        = 'A',
             DT_FECHA_ASOCIACION   = p_dtFechaAsoc,
             DT_FECHA_MODIFICACION = SYSDATE
       WHERE INT_IDIFI = p_intIdIFI;

      --o_intIdReglaProducto := p_intIdReglaProducto;
      o_vchMensaje := 'OK';
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      o_vchMensaje := 'PKG_PRODUCTO_IFI.I_REACTIVAR_PRODUCTO_IFI---> Nro Linea Error: ' || vcErrorStack||'; '||vcErrorBacktace||'; INT_IDIFI:' || TO_CHAR(p_intIdIFI);    
      PKG_LOG_ERROR.I_REGISTRAR('PKG_PRODUCTO_IFI', 'I_REACTIVAR_PRODUCTO_IFI', vcErrorStack, vcErrorBacktace, 'INT_IDIFI:' || TO_CHAR(p_intIdIFI));
  END I_REACTIVAR_PRODUCTO_IFI;

  PROCEDURE S_OBTENER_IFIS(p_curResultado OUT sys_refcursor) AS
  BEGIN
    OPEN p_curResultado FOR
      SELECT  INT_IDPRODUCTO_IFI, DT_FECHA_ASOCIACION,INT_IDIFI, VC_NOMBREIFI, VC_CODIGOIFI, DT_FECHA_CREACION,COUNT(*) OVER() AS INT_NUMERO_TOTAL_REGISTRO
        FROM PRODUCTO_IFI
       WHERE CH_FLAG_ESTADO = 'A'
       ORDER BY DT_FECHA_CREACION DESC;
  EXCEPTION
    WHEN OTHERS THEN  
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_PRODUCTO_IFI', 'S_OBTENER_IFIS', vcErrorStack, vcErrorBacktace);
      RAISE_APPLICATION_ERROR(-20162, 'PKG_PRODUCTO_IFI.S_OBTENER_IFIS:'|| vcErrorStack||'; '||vcErrorBacktace);
  END S_OBTENER_IFIS;
  
  PROCEDURE S_OBTENER_IFIS_PAGINACION(p_intStartIndex IN NUMBER,
                                      p_intPageSize IN NUMBER,
                                       p_curResultado OUT sys_refcursor) AS
  BEGIN
    OPEN p_curResultado FOR
      SELECT *
        FROM (SELECT COUNT(1) OVER () AS INT_NUMERO_TOTAL_REGISTRO,
                     ROW_NUMBER() OVER (ORDER BY VC_NOMBREIFI) AS INT_ROW_NUMBER,
                     INT_IDIFI,
                     VC_NOMBREIFI,
                     VC_CODIGOIFI
            FROM PRODUCTO_IFI
            WHERE CH_FLAG_ESTADO = 'A') D
        WHERE D.INT_ROW_NUMBER BETWEEN (P_INTSTARTINDEX * P_INTPAGESIZE + 1)
          AND ((P_INTSTARTINDEX + 1) * P_INTPAGESIZE)
        ORDER BY D.INT_ROW_NUMBER;

  EXCEPTION
    WHEN OTHERS THEN  
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_PRODUCTO_IFI', 'S_OBTENER_IFIS_PAGINACION', vcErrorStack, vcErrorBacktace);
      RAISE_APPLICATION_ERROR(-20162, 'PKG_PRODUCTO_IFI.S_OBTENER_IFIS_PAGINACION:'|| vcErrorStack||'; '||vcErrorBacktace);
  END S_OBTENER_IFIS_PAGINACION;
  
END PKG_PRODUCTO_IFI;


/
--------------------------------------------------------
--  DDL for Package Body PKG_SEGURIDAD
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "US_BASE_MODULAR"."PKG_SEGURIDAD" AS

  PROCEDURE S_OBTENER_ROLES_ACCION(p_vcRol        IN US_BASE.BASE_ROL_ACCION.VC_ROL%TYPE,
                                   p_curResultado OUT sys_refcursor) AS
  BEGIN
    OPEN p_curResultado FOR
      SELECT VC_ROL, VC_MODULO, CL_ACCION
        FROM US_BASE.BASE_ROL_ACCION
       WHERE CH_FLAG_ESTADO = 'A'
         AND VC_ROL = p_vcRol;
  EXCEPTION
    WHEN OTHERS THEN
      vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
      vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      PKG_LOG_ERROR.I_REGISTRAR('PKG_SEGURIDAD', 'S_OBTENER_ROLES_ACCION', vcErrorStack, vcErrorBacktace, 'VC_ROL:' || TO_CHAR(p_vcRol));
      RAISE_APPLICATION_ERROR(-20191, 'PKG_SEGURIDAD.S_OBTENER_ROLES_ACCION:'|| vcErrorStack||'; '||vcErrorBacktace||'; VC_ROL:' || TO_CHAR(p_vcRol));      
  END S_OBTENER_ROLES_ACCION;

END PKG_SEGURIDAD;


/
--------------------------------------------------------
--  DDL for Package Body PKG_SOLICITUD
--------------------------------------------------------

create or replace PACKAGE BODY                                                                                             "PKG_SOLICITUD" 
  AS

  PROCEDURE S_LISTAR(p_intStartIndex      IN  NUMBER,
                     p_intPageSize        IN  NUMBER,
                     p_vcCodigo           IN  SOLICITUD.VC_CODIGO % TYPE,
                     p_intIdIFI           IN  SOLICITUD.INT_IDIFI % TYPE,
                     p_intIdEstado        IN  SOLICITUD.INT_IDESTADO % TYPE,
                     p_dtFechaDesde       IN  SOLICITUD.DT_FECHA % TYPE,
                     p_dtFechaHasta       IN  SOLICITUD.DT_FECHA % TYPE,
                     p_intIdTipoOperacion IN  SOLICITUD.INT_IDTIPO_OPERACION % TYPE,
                     p_vcNumeroDocumento  IN  SOLICITUD_DETALLE.VC_NUMERO_DOCUMENTO % TYPE,
					 p_intIdSolicitudDet  IN  SOLICITUD.INT_IDTIPO_OPERACION % TYPE,
                     p_intIdSolicitud     IN  SOLICITUD.INT_IDSOLICITUD % TYPE,
                     p_curTabla           OUT SYS_REFCURSOR)
    AS
    BEGIN

      OPEN p_curTabla FOR
      SELECT D.INT_NUMERO_TOTAL_REGISTRO,
             D.INT_ROW_NUMBER,
             D.INT_IDSOLICITUD,
             D.VC_CODIGO,
             D.INT_IDIFI,
             D.VC_NOMBRE_IFI,
             D.INT_REGISTROS,
             D.INT_APROBADOS,
             D.INT_RECHAZADOS,
             D.INT_IDESTADO,
             D.ESTADO_SOL,
             D.INT_IDTIPO_OPERACION,
             D.TIPO_OPE,
             D.INT_IDMONEDA,
             CASE WHEN D.VC_COD_MONEDA = 'OTROS' THEN '' ELSE TRIM(PKG_TABLA_DETALLE.F_OBT_VALOR_TABLADETALLE('MONBASE',D.VC_COD_MONEDA,'2') ) END VC_TIPO_MONEDA,
             D.MONEDA,
             D.DEC_TOTAL_COBERTURADO_INICIAL,
             D.DEC_TOTAL_DESEMBOLSADO,
             D.DEC_TOTAL_MONTO_PRESTAMO,
             D.DT_FECHA,
             D.VC_USUARIO_CREACION,
             D.DT_FECHA_CREACION,
             D.VC_TERMINAL_CREACION,
             D.VC_USUARIO_MODIFICACION,
             D.DT_FECHA_MODIFICACION,
             D.VC_TERMINAL_MODIFICACION,
             D.JSON_UI_DECORADORES
        FROM (SELECT COUNT(1) OVER () AS INT_NUMERO_TOTAL_REGISTRO,
                     ROW_NUMBER() OVER (ORDER BY BS.INT_IDSOLICITUD DESC) AS INT_ROW_NUMBER,
                     BS.INT_IDSOLICITUD,
                     BS.VC_CODIGO,
                     BS.INT_IDIFI,
                     BS.VC_NOMBRE_IFI,
                     BS.INT_REGISTROS,
                     BS.INT_APROBADOS,
                     BS.INT_RECHAZADOS,
                     BS.INT_IDESTADO,
                     PKG_TABLA_DETALLE.F_OBT_NOMBRE_TABLADETALLE(BS.INT_IDESTADO) AS ESTADO_SOL,
                     BS.INT_IDTIPO_OPERACION,
                     PKG_TABLA_DETALLE.F_OBT_NOMBRE_TABLADETALLE(BS.INT_IDTIPO_OPERACION) AS TIPO_OPE,
                     BS.INT_IDMONEDA,
                     PKG_TABLA_DETALLE.F_OBT_CODIGO_TABLADETALLE(INT_IDMONEDA) VC_COD_MONEDA,
                     PKG_TABLA_DETALLE.F_OBT_NOMBRE_TABLADETALLE(BS.INT_IDMONEDA) AS MONEDA,
                     BS.DEC_TOTAL_COBERTURADO_INICIAL,
                     BS.DEC_TOTAL_DESEMBOLSADO,
                     BS.DEC_TOTAL_MONTO_PRESTAMO,
                     BS.DT_FECHA,
                     BS.VC_USUARIO_CREACION,
                     BS.DT_FECHA_CREACION,
                     BS.VC_TERMINAL_CREACION,
                     BS.VC_USUARIO_MODIFICACION,
                     BS.DT_FECHA_MODIFICACION,
                     BS.VC_TERMINAL_MODIFICACION,
                     BS.JSON_UI_DECORADORES
            FROM SOLICITUD BS
            WHERE (p_vcCodigo IS NULL
              OR BS.VC_CODIGO LIKE '%' || p_vcCodigo || '%')
              AND BS.INT_IDIFI = NVL(DECODE(p_intIdIFI, 0, NULL, p_intIdIFI), BS.INT_IDIFI)
              AND BS.INT_IDSOLICITUD = NVL(DECODE(p_intIdSolicitud, 0, NULL, p_intIdSolicitud), BS.INT_IDSOLICITUD)
              AND BS.INT_IDESTADO = NVL(DECODE(p_intIdEstado, 0, NULL, p_intIdEstado), BS.INT_IDESTADO)
              AND BS.DT_FECHA >= NVL(p_dtFechaDesde, BS.DT_FECHA)
              AND BS.DT_FECHA <= NVL(p_dtFechaHasta, BS.DT_FECHA)
              AND BS.INT_IDTIPO_OPERACION = NVL(DECODE(p_intIdTipoOperacion, 0, NULL, p_intIdTipoOperacion), BS.INT_IDTIPO_OPERACION)
              AND (EXISTS (SELECT 1
                  FROM SOLICITUD_DETALLE BSD
                  WHERE BSD.INT_IDSOLICITUD = BS.INT_IDSOLICITUD
                    AND BSD.VC_NUMERO_DOCUMENTO = NVL(p_vcNumeroDocumento, BSD.VC_NUMERO_DOCUMENTO)                    
                    )
                    OR p_vcNumeroDocumento IS NULL)
              AND (EXISTS (SELECT 1
                  FROM SOLICITUD_DETALLE BSD
                  WHERE BSD.INT_IDSOLICITUD = BS.INT_IDSOLICITUD                    
                    AND (p_intIdSolicitudDet IS NULL OR p_intIdSolicitudDet = 0 OR BSD.INT_IDSOLICITUD_DET = p_intIdSolicitudDet)                    
                    )
                    OR p_intIdSolicitudDet IS NULL OR p_intIdSolicitudDet = 0) 
            ORDER BY BS.DT_FECHA_CREACION DESC) D
        WHERE (D.INT_ROW_NUMBER BETWEEN ((p_intStartIndex) * p_intPageSize + 1) AND (p_intStartIndex + 1) * p_intPageSize)
        ORDER BY D.INT_ROW_NUMBER;

    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD', 'S_LISTAR', vcErrorStack, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
          RAISE_APPLICATION_ERROR(-20201, 'PKG_SOLICITUD.S_LISTAR:' || vcErrorStack || '; ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
    END S_LISTAR;

  PROCEDURE D_ELIMINAR_X_NROSOLICITUD(p_vcCodigo    IN  SOLICITUD.VC_CODIGO % TYPE,
                                      out_vcMensaje OUT VARCHAR2)
    AS
      v_IDSOLICITUD NUMBER;
    BEGIN
      v_IDSOLICITUD := 0;

      SELECT INT_IDSOLICITUD
        INTO v_IDSOLICITUD
        FROM SOLICITUD
        WHERE VC_CODIGO = p_vcCodigo;

      DELETE FROM SOLICITUD_ARCHIVOS
        WHERE INT_IDSOLICITUD = v_IDSOLICITUD;

      DELETE FROM SOLICITUD_REPLEG_TEXTO
        WHERE INT_IDSOLICITUD = v_IDSOLICITUD;

      DELETE FROM SOLICITUD_DETALLE_TEXTO
        WHERE INT_IDSOLICITUD = v_IDSOLICITUD;

      DELETE FROM SOLICITUD_REPLEG
        WHERE INT_IDSOLICITUD = v_IDSOLICITUD;

      DELETE FROM SOLICITUD_DETALLE
        WHERE INT_IDSOLICITUD = v_IDSOLICITUD;

      DELETE FROM SOLICITUD_HISTORICO
        WHERE INT_IDSOLICITUD = v_IDSOLICITUD;

      DELETE FROM SOLICITUD
        WHERE INT_IDSOLICITUD = v_IDSOLICITUD;

      out_vcMensaje := 'OK';

    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          out_vcMensaje := 'PKG_SOLICITUD.D_ELIMINAR_X_NROSOLICITUD---> Nro Linea Error: ' || vcErrorStack || '; ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || '; VC_CODPROD:' || TO_CHAR(p_vcCodigo);
          PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD', 'D_ELIMINAR_X_NROSOLICITUD', vcErrorStack, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 'VC_CODIGO:' || TO_CHAR(p_vcCodigo));
    END D_ELIMINAR_X_NROSOLICITUD;

  PROCEDURE S_LISTAR_SOLICITUD_ERRORES(p_vcSolicitud IN  VARCHAR2,
                                       p_curTabla    OUT SYS_REFCURSOR)
    AS
    BEGIN

      OPEN p_curTabla FOR
      SELECT SO.INT_IDSOLICITUD,
             ER.INT_IDSOLICITUD_DET,
             SO.VC_CODIGO,
             SO.INT_IDIFI,
             SO.VC_NOMBRE_IFI,
             ER.VC_NOMBRES,
             ER.VC_TIPO_DOCUMENTO,
             ER.VC_NUMERO_DOCUMENTO,
             ER.VC_RAZON_SOCIAL,
             ER.VC_TIPO_ERROR,
             ER.INT_FILA_ARCHIVO,
             ER.VC_FILA_ARCHIVO,
             ER.OBSERVACIONES
        FROM (SELECT SDT1.INT_IDSOLICITUD,
                     SDT1.INT_IDSOLICITUD_DET,
                     SDT1.C01 AS VC_TIPO_DOCUMENTO,
                     SDT1.C02 AS VC_NUMERO_DOCUMENTO,
                     TO_CHAR(SDT1.C03) AS VC_RAZON_SOCIAL,
                     (SDT1.C04 || ' ' || SDT1.C05 || ' ' || SDT1.C06) AS VC_NOMBRES,
                     'SOLICITUD ESTRUCTURA' AS VC_TIPO_ERROR,
                     SDT1.INT_FILA AS INT_FILA_ARCHIVO,
                     'Error en fila ' || TRIM(TO_CHAR(SDT1.INT_FILA)) || ' del archivo Solicitud' AS VC_FILA_ARCHIVO,
                     SDT1.OBSERVACIONES,
                     1 AS ORDEN
            FROM SOLICITUD S
              INNER JOIN SOLICITUD_DETALLE_TEXTO SDT1
                ON (S.INT_IDSOLICITUD = SDT1.INT_IDSOLICITUD)
            WHERE SDT1.INT_IDSOLICITUD IN (SELECT TO_NUMBER(REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL)) AS SOLICITUD
                  FROM DUAL
                CONNECT BY REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL) IS NOT NULL)
              AND SDT1.INT_IDSOLICITUD_DET = 0
              AND SDT1.OBSERVACIONES <> 'OK'
            UNION ALL
          SELECT SDT2.INT_IDSOLICITUD,
                 SDT2.INT_IDSOLICITUD_DET,
                 SD.VC_TIPO_DOCUMENTO,
                 SD.VC_NUMERO_DOCUMENTO,
                 TO_CHAR(SD.VC_RAZON_SOCIAL) AS VC_RAZON_SOCIAL,
                 (SD.VC_APELLIDO_PATERNO || ' ' || SD.VC_APELLIDO_MATERNO || ' ' || SD.VC_NOMBRES) AS VC_NOMBRES,
                 'SOLICITUD REGLAS' AS VC_TIPO_ERROR,
                 SDT2.INT_FILA AS INT_FILA_ARCHIVO,
                 'Error en fila ' || TRIM(TO_CHAR(SDT2.INT_FILA)) || ' del archivo Solicitud' AS VC_FILA_ARCHIVO,
                 SD.OBSERVACIONES,
                 2 AS ORDEN
            FROM SOLICITUD_DETALLE_TEXTO SDT2
              INNER JOIN SOLICITUD_DETALLE SD
                ON (SD.INT_IDSOLICITUD_DET = SDT2.INT_IDSOLICITUD_DET
                AND SDT2.INT_IDSOLICITUD = SD.INT_IDSOLICITUD)
            WHERE SDT2.INT_IDSOLICITUD IN (SELECT TO_NUMBER(REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL)) AS SOLICITUD
                  FROM DUAL
                CONNECT BY REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL) IS NOT NULL)
              AND SDT2.INT_IDSOLICITUD_DET > 0
              AND SDT2.OBSERVACIONES = 'OK'
              AND SD.OBSERVACIONES <> 'OK'
            UNION ALL
          SELECT SRT1.INT_IDSOLICITUD,
                 SRT1.INT_IDSOLICITUD_DET,
                 SRT1.C02 AS VC_TIPO_DOCUMENTO,
                 SRT1.C03 AS VC_NUMERO_DOCUMENTO,
                 TO_CHAR(' ') AS VC_RAZON_SOCIAL,
                 SRT1.C04 || ' ' || SRT1.C05 AS VC_NOMBRES,
                 'REPRESENTANTE LEGAL ESTRUCTURA' AS VC_TIPO_ERROR,
                 SRT1.INT_FILA AS INT_FILA_ARCHIVO,
                 'Error en fila ' || TRIM(TO_CHAR(SRT1.INT_FILA)) || ' del archivo Representante Legal' AS VC_FILA_ARCHIVO,
                 SRT1.OBSERVACIONES,
                 3 AS ORDEN
            FROM SOLICITUD S
              INNER JOIN SOLICITUD_REPLEG_TEXTO SRT1
                ON (S.INT_IDSOLICITUD = SRT1.INT_IDSOLICITUD)
            WHERE SRT1.INT_IDSOLICITUD IN (SELECT TO_NUMBER(REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL)) AS SOLICITUD
                  FROM DUAL
                CONNECT BY REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL) IS NOT NULL)
              AND SRT1.INT_IDSOLICITUD_DET = 0
              AND SRT1.OBSERVACIONES <> 'OK'
            UNION ALL
          SELECT SRT2.INT_IDSOLICITUD,
                 SRT2.INT_IDSOLICITUD_DET,
                 SD.VC_TIPO_DOCUMENTO_REPLEG,
                 SD.VC_NUMERO_DOCUMENTO_REPLEG,
                 ' ' AS VC_RAZON_SOCIAL,
                 SD.VC_APELLIDOS_REPLEG || ' ' || SD.VC_NOMBRES_REPLEG AS VC_NOMBRES,
                 'REPRESENTANTE LEGAL REGLAS' AS VC_TIPO_ERROR,
                 SRT2.INT_FILA AS INT_FILA_ARCHIVO,
                 'Error en fila ' || TRIM(TO_CHAR(SRT2.INT_FILA)) || ' del archivo Representante Legal' AS VC_FILA_ARCHIVO,
                 SD.OBSERVACIONES,
                 4 AS ORDEN
            FROM SOLICITUD_REPLEG_TEXTO SRT2
              INNER JOIN SOLICITUD_REPLEG SD
                ON (SD.VC_NUMERO_DOCUMENTO_REPLEG = SRT2.C03
                AND SD.VC_TIPO_DOCUMENTO_REPLEG = SRT2.C02
                AND SRT2.INT_IDSOLICITUD = SD.INT_IDSOLICITUD)
            WHERE SRT2.INT_IDSOLICITUD IN (SELECT TO_NUMBER(REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL)) AS SOLICITUD
                  FROM DUAL
                CONNECT BY REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL) IS NOT NULL)
              AND SRT2.INT_IDSOLICITUD_DET > 0
              AND SRT2.OBSERVACIONES = 'OK'
              AND SD.OBSERVACIONES <> 'OK') ER
          INNER JOIN SOLICITUD SO
            ON (SO.INT_IDSOLICITUD = ER.INT_IDSOLICITUD)
        ORDER BY SO.INT_IDSOLICITUD,
                 ER.ORDEN,
                 ER.INT_FILA_ARCHIVO;

    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD', 'S_LISTAR_SOLICITUD_ERRORES', vcErrorStack, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 'INT_IDSOLICITUD:' || TO_CHAR(p_vcSolicitud));
          RAISE_APPLICATION_ERROR(-20202, 'PKG_SOLICITUD.S_LISTAR_SOLICITUD_ERRORES:' || vcErrorStack || '; ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || '; INT_IDSOLICITUD:' || TO_CHAR(p_vcSolicitud));
    END S_LISTAR_SOLICITUD_ERRORES;

  PROCEDURE S_LISTAR_DOCUMENTOS_X_SOLICITUD(p_intIdSolicitud IN  SOLICITUD.INT_IDSOLICITUD % TYPE,
                                            p_curTabla       OUT SYS_REFCURSOR)
    AS

      intCount            NUMBER;
      intIdProducto       NUMBER;
      intHonras           NUMBER := 0;
      intConvertirTipoDoc NUMBER := 0;
    BEGIN

      SELECT COUNT(1)
        INTO intCount
        FROM SOLICITUD S
        WHERE S.INT_IDSOLICITUD = p_intIdSolicitud;

      IF intCount > 0
      THEN
        SELECT S.INT_IDPRODUCTO
          INTO intIdProducto
          FROM SOLICITUD S
          WHERE S.INT_IDSOLICITUD = p_intIdSolicitud;

        SELECT COUNT(1)
          INTO intCount
          FROM US_BASE.BASE_REGLA_PRODUCTO B
          WHERE B.INT_IDPROD = intIdProducto;

        IF intCount > 0
        THEN
          SELECT TO_NUMBER(NVL(B.CH_ES_VALIDACION_BENEFICIARIO_OTROS_PROGRAMAS_HONRAS, '0')),
                 TO_NUMBER(NVL(B.CH_ES_VALIDACION_BENEFICIARIO_OTROS_PROGRAMAS_CONVER_TIP_DOC, '0'))
            INTO intHonras,
                 intConvertirTipoDoc
            FROM US_BASE.BASE_REGLA_PRODUCTO B
            WHERE B.INT_IDPROD = intIdProducto;
        END IF;
      END IF;

      IF intHonras = 1
      THEN
        IF intConvertirTipoDoc = 1
        THEN
          OPEN p_curTabla FOR
          SELECT DISTINCT SD.VC_NUMERO_DOCUMENTO AS NUMERO_DOCUMENTO
            FROM SOLICITUD_DETALLE SD
            WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
              AND SD.VC_TIPO_DOCUMENTO IN ('DNI', 'RUC')
            UNION ALL
          SELECT DISTINCT PKG_BASE.F_CONVERTIR_DNI_A_RUC(SD.VC_NUMERO_DOCUMENTO) AS NUMERO_DOCUMENTO
            FROM SOLICITUD_DETALLE SD
            WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
              AND SD.VC_TIPO_DOCUMENTO = 'DNI'
            UNION ALL
          SELECT DISTINCT SUBSTR(SD.VC_NUMERO_DOCUMENTO, 3, 8) AS NUMERO_DOCUMENTO
            FROM SOLICITUD_DETALLE SD
            WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
              AND SD.VC_TIPO_DOCUMENTO = 'RUC'
              AND SUBSTR(SD.VC_NUMERO_DOCUMENTO, 1, 2) = '10';
        ELSE
          OPEN p_curTabla FOR
          SELECT DISTINCT SD.VC_NUMERO_DOCUMENTO AS NUMERO_DOCUMENTO
            FROM SOLICITUD_DETALLE SD
            WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
              AND SD.VC_TIPO_DOCUMENTO IN ('DNI', 'RUC');
        END IF;
      ELSE
        OPEN p_curTabla FOR
        SELECT DISTINCT SD.VC_NUMERO_DOCUMENTO AS NUMERO_DOCUMENTO
          FROM SOLICITUD_DETALLE SD
          WHERE SD.INT_IDSOLICITUD = p_intIdSolicitud
            AND SD.VC_TIPO_DOCUMENTO IN ('DNI', 'RUC')
            AND 1 = 0;
      END IF;

    EXCEPTION
      WHEN OTHERS THEN PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD', 'S_LISTAR_DOCUMENTOS_X_SOLICITUD', vcErrorStack, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 'INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
          RAISE_APPLICATION_ERROR(-20203, 'PKG_SOLICITUD.S_LISTAR_DOCUMENTOS_X_SOLICITUD:' || vcErrorStack || '; ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || '; INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
    END S_LISTAR_DOCUMENTOS_X_SOLICITUD;

  PROCEDURE S_LISTAR_AUDITORIA_X_SOLICITUD(p_intIdSolicitud IN  SOLICITUD.INT_IDSOLICITUD % TYPE,
                                           p_intStartIndex  IN  NUMBER,
                                           p_intPageSize    IN  NUMBER,
                                           p_curTabla       OUT SYS_REFCURSOR)
    AS
    BEGIN

      OPEN p_curTabla FOR
      SELECT D.INT_NUMERO_TOTAL_REGISTRO,
             D.INT_ROW_NUMBER,
             D.VC_ESTADO_SIGUIENTE,
             D.VC_ESTADO_ANTERIORERIOR,
             D.DT_FECHA_CREACION,
             D.VC_USUARIO_CREACION,
             D.JSON_UI_DECORADORES 
        FROM (SELECT COUNT(1) OVER () AS INT_NUMERO_TOTAL_REGISTRO,
                     ROW_NUMBER() OVER (ORDER BY INT_IDSOLICITUD DESC) AS INT_ROW_NUMBER,
                     D1.VC_NOMBRE AS VC_ESTADO_SIGUIENTE,
                     D2.VC_NOMBRE AS VC_ESTADO_ANTERIORERIOR,
                     H.DT_FECHA_CREACION,
                     H.VC_USUARIO_CREACION,
                     D1.VC_ADICIONAL1 JSON_UI_DECORADORES
            FROM SOLICITUD_HISTORICO H
            LEFT JOIN US_BASE.BASE_TABLA_DETALLE D1 ON H.INT_IDESTADO = D1.INT_IDTABLA_DETALLE
            LEFT JOIN US_BASE.BASE_TABLA_DETALLE D2 ON H.INT_IDESTADO_ANT = D2.INT_IDTABLA_DETALLE
            WHERE H.INT_IDSOLICITUD = P_INTIDSOLICITUD
            ORDER BY H.INT_FILA DESC) D
        WHERE (D.INT_ROW_NUMBER BETWEEN ((P_INTSTARTINDEX) * P_INTPAGESIZE + 1) AND (P_INTSTARTINDEX + 1) * P_INTPAGESIZE);

    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD', 'S_LISTAR_AUDITORIA_X_SOLICITUD', vcErrorStack, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 'INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
          RAISE_APPLICATION_ERROR(-20204, 'PKG_SOLICITUD.S_LISTAR_AUDITORIA_X_SOLICITUD:' || vcErrorStack || '; ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || '; INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
    END S_LISTAR_AUDITORIA_X_SOLICITUD;

  PROCEDURE S_LISTAR_EXPORTAR(p_SolicitudesList IN  VARCHAR2,
                              p_curTabla        OUT SYS_REFCURSOR)
    AS

    BEGIN
      OPEN p_curTabla FOR
      SELECT D.INT_NUMERO_TOTAL_REGISTRO,
             D.INT_ROW_NUMBER,
             D.INT_IDSOLICITUD,
             D.VC_CODIGO,
             D.INT_IDIFI,
             D.VC_NOMBRE_IFI,
             D.INT_REGISTROS,
             D.INT_APROBADOS,
             D.INT_RECHAZADOS,
             D.INT_IDESTADO,
             D.ESTADO_SOL,
             D.INT_IDTIPO_OPERACION,
             D.TIPO_OPE,
             D.INT_IDMONEDA,
             D.MONEDA,
             D.DEC_TOTAL_COBERTURADO_INICIAL,
             D.DEC_TOTAL_DESEMBOLSADO,
             D.DT_FECHA,
             D.VC_USUARIO_CREACION,
             D.DT_FECHA_CREACION,
             D.VC_TERMINAL_CREACION,
             D.VC_USUARIO_MODIFICACION,
             D.DT_FECHA_MODIFICACION,
             D.VC_TERMINAL_MODIFICACION
        FROM (SELECT COUNT(1) OVER () AS INT_NUMERO_TOTAL_REGISTRO,
                     ROW_NUMBER() OVER (ORDER BY BS.INT_IDSOLICITUD DESC) AS INT_ROW_NUMBER,
                     BS.INT_IDSOLICITUD,
                     BS.VC_CODIGO,
                     BS.INT_IDIFI,
                     BS.VC_NOMBRE_IFI,
                     BS.INT_REGISTROS,
                     BS.INT_APROBADOS,
                     BS.INT_RECHAZADOS,
                     BS.INT_IDESTADO,
                     PKG_TABLA_DETALLE.F_OBT_NOMBRE_TABLADETALLE(BS.INT_IDESTADO) AS ESTADO_SOL,
                     BS.INT_IDTIPO_OPERACION,
                     PKG_TABLA_DETALLE.F_OBT_NOMBRE_TABLADETALLE(BS.INT_IDTIPO_OPERACION) AS TIPO_OPE,
                     BS.INT_IDMONEDA,
                     PKG_TABLA_DETALLE.F_OBT_NOMBRE_TABLADETALLE(BS.INT_IDMONEDA) AS MONEDA,
                     BS.DEC_TOTAL_COBERTURADO_INICIAL,
                     BS.DEC_TOTAL_DESEMBOLSADO,
                     BS.DT_FECHA,
                     BS.VC_USUARIO_CREACION,
                     BS.DT_FECHA_CREACION,
                     BS.VC_TERMINAL_CREACION,
                     BS.VC_USUARIO_MODIFICACION,
                     BS.DT_FECHA_MODIFICACION,
                     BS.VC_TERMINAL_MODIFICACION
            FROM SOLICITUD BS
            WHERE BS.INT_IDSOLICITUD IN (SELECT TO_NUMBER(REGEXP_SUBSTR(p_SolicitudesList, '[^,]+', 1, LEVEL)) AS INT_IDSOLICITUD
                  FROM DUAL
                CONNECT BY REGEXP_SUBSTR(p_SolicitudesList, '[^,]+', 1, LEVEL) IS NOT NULL)
            ORDER BY BS.DT_FECHA_CREACION DESC) D
        ORDER BY D.INT_ROW_NUMBER;

    EXCEPTION
      WHEN OTHERS THEN PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD', 'S_LISTAR_EXPORTAR', vcErrorStack, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 'INT_IDSOLICITUD:' || TO_CHAR(p_SolicitudesList));
          RAISE_APPLICATION_ERROR(-20205, 'PKG_SOLICITUD.S_LISTAR_EXPORTAR:' || vcErrorStack || '; ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || '; INT_IDSOLICITUD:' || TO_CHAR(p_SolicitudesList));
    END S_LISTAR_EXPORTAR;

  PROCEDURE S_LISTAR_DETALLE_X_SOLICITUD(p_intIdSolicitud   IN  SOLICITUD.INT_IDSOLICITUD % TYPE,
                                         p_intStartIndex    IN  NUMBER,
                                         p_intPageSize      IN  NUMBER,
                                         p_intAprobadas     IN  NUMBER,
                                         p_curTabla         OUT SYS_REFCURSOR)
    AS
    BEGIN

 OPEN p_curTabla FOR
      SELECT D.INT_NUMERO_TOTAL_REGISTRO,
             D.INT_ROW_NUMBER,
             D.INT_IDSOLICITUD_DET,
             D.VC_RAZON_SOCIAL,
             D.VC_TIPO_DOCUMENTO,
             D.VC_NUMERO_DOCUMENTO,
             D.DEC_MONTO_PRESTAMO,
             D.VC_MONEDA,
             D.DEC_MONTO_COBERTURA,
             D.DEC_PORCENTAJE_COBERTURA,
             D.VC_ESTADO,
             D.JSON_UI_DECORADORES
        FROM (SELECT 
              COUNT(1) OVER () AS INT_NUMERO_TOTAL_REGISTRO,
              ROW_NUMBER() OVER (ORDER BY INT_IDSOLICITUD DESC) AS INT_ROW_NUMBER,
              T.INT_IDSOLICITUD_DET,
             T.VC_RAZON_SOCIAL,
             T.VC_TIPO_DOCUMENTO,
             T.VC_NUMERO_DOCUMENTO,
             T.DEC_MONTO_PRESTAMO,
             T.VC_MONEDA,
             T.DEC_MONTO_COBERTURA,
             T.DEC_PORCENTAJE_COBERTURA,
             T.VC_ESTADO,
             T.JSON_UI_DECORADORES
              FROM (SELECT DET.INT_IDSOLICITUD,
                           DET.INT_IDSOLICITUD_DET,
                           /* Fuerza VARCHAR2 en la concatenación */
                           NVL(
                             CAST(DET.VC_RAZON_SOCIAL AS VARCHAR2(4000)),
                             CAST(DET.VC_NOMBRES AS VARCHAR2(400)) || ' ' ||
                             CAST(DET.VC_APELLIDO_PATERNO AS VARCHAR2(400)) || ' ' ||
                             CAST(DET.VC_APELLIDO_MATERNO AS VARCHAR2(400))
                           ) AS VC_RAZON_SOCIAL,
                           CAST(DET.VC_TIPO_DOCUMENTO    AS VARCHAR2(50))   AS VC_TIPO_DOCUMENTO,
                           CAST(DET.VC_NUMERO_DOCUMENTO  AS VARCHAR2(100))  AS VC_NUMERO_DOCUMENTO,
                           DET.DEC_MONTO_PRESTAMO,
                           CAST(DET.VC_MONEDA            AS VARCHAR2(10))   AS VC_MONEDA,
                           DET.DEC_MONTO_COBERTURA,
                           DET.DEC_PORCENTAJE_COBERTURA,                           
                           CAST(PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM', DET.VC_ESTADO, 0) AS VARCHAR2(400)) AS VC_ESTADO,                           
                           CAST(DBMS_LOB.SUBSTR(DET.JSON_UI_DECORADORES, 4000, 1) AS VARCHAR2(4000)) AS JSON_UI_DECORADORES
                    FROM SOLICITUD_DETALLE DET
                    LEFT JOIN US_BASE.V_BASE_ESTADOSSOLDET_CLASIFICADOS V ON V.COD_CORTO = DET.VC_ESTADO
                    WHERE DET.INT_IDSOLICITUD = p_intIdSolicitud
                    AND (
                          p_intAprobadas IS NULL
                       OR (p_intAprobadas = 1  AND V.GRUPO = 'A')
                       OR (p_intAprobadas <> 1 AND V.GRUPO = 'R')
                    )
                    UNION ALL 
                    SELECT  DETX.INT_IDSOLICITUD, 
                            DETX.INT_IDSOLICITUD_DET,
                             NVL(
                                 CAST(DETX.C03 AS VARCHAR2(4000)),
                                 CAST(DETX.C06 AS VARCHAR2(400)) || ' ' ||
                                 CAST(DETX.C04 AS VARCHAR2(400)) || ' ' ||
                                 CAST(DETX.C05 AS VARCHAR2(400))
                             )                                                AS VC_RAZON_SOCIAL,
                             CAST(DETX.C01 AS VARCHAR2(50))                   AS VC_TIPO_DOCUMENTO,
                             CAST(DETX.C02 AS VARCHAR2(100))                  AS VC_NUMERO_DOCUMENTO,
                             0                                                AS DEC_MONTO_PRESTAMO,
                             CAST(DETX.C17 AS VARCHAR2(10))                   AS VC_MONEDA,
                             0                                                AS DEC_MONTO_COBERTURA,
                             0                                                AS DEC_PORCENTAJE_COBERTURA,
                             CAST(PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM','REC',0) AS VARCHAR2(400)) AS VC_ESTADO,             
                            CAST(NULL AS VARCHAR2(4000))     AS JSON_UI_DECORADORES
                    FROM SOLICITUD_DETALLE_TEXTO DETX            
                    WHERE DETX.INT_IDSOLICITUD = p_intIdSolicitud
                    AND p_intAprobadas <> 1 
                    AND DETX.INT_IDSOLICITUD_DET = 0
                ) T
            ) D
        WHERE (D.INT_ROW_NUMBER BETWEEN ((p_intStartIndex) * p_intPageSize + 1) AND (p_intStartIndex + 1) * p_intPageSize)
        ORDER BY D.INT_ROW_NUMBER;

    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD', 'S_LISTAR_DETALLE_X_SOLICITUD', vcErrorStack, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 'INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
          RAISE_APPLICATION_ERROR(-20206, 'PKG_SOLICITUD.S_LISTAR_DETALLE_X_SOLICITUD:' || vcErrorStack || '; ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || '; INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
    END S_LISTAR_DETALLE_X_SOLICITUD;

  PROCEDURE S_LISTAR_SOLICITUD_DETALLADO_ERRORES(p_vcSolicitud       IN  VARCHAR2,
                                                 p_intFlagAprobados  IN  NUMBER,
                                                 p_intFlagRechazados IN  NUMBER,
                                                 p_curTabla          OUT SYS_REFCURSOR)
    AS
    BEGIN
      OPEN p_curTabla FOR
      SELECT SO.INT_IDSOLICITUD,
             ER.INT_IDSOLICITUD_DET,
             SO.VC_CODIGO,
             SO.INT_IDIFI,
             SO.VC_NOMBRE_IFI,
             ER.VC_UBIGEO,
             ER.VC_GRUPOBEN,
             ER.VC_CIIU,
             ER.VC_TIPNUMREPLEG,
             ER.VC_DIRECCION,
             ER.VC_NUMREPLEG,
             ER.VC_REPLEG,
             ER.VC_MONEDA,
             ER.VC_COLCRED,
             ER.VC_MONTOLATERAL,
             ER.VC_CARGREPLEG,
             ER.VC_TAMANIO,
             ER.VC_TIPDESTINO,
             ER.VC_MONTOPRESTAMO,
             ER.VC_TIPO_DOCUMENTO,
             ER.VC_TASAINTERES,
             ER.VC_NUMERO_DOCUMENTO,
             ER.VC_PERIODGRACIA,
             ER.VC_PLAZOOPER,
             ER.VC_ORIGENFONDOS,
             ER.VC_RAZON_SOCIAL,
             ER.VC_NOMBRES,
             ER.VC_DIRECCION,
             ER.VC_TIPO_ERROR,
             ER.INT_FILA_ARCHIVO,
             ER.VC_FILA_ARCHIVO,
             ER.VC_CODSUBASTA,
             ER.VC_ESTADO,
             ER.OBSERVACIONES,
             ER.DEC_PORCENTAJE_COBERTURA,
             ER.DEC_MONTO_COBERTURA			 
        FROM (SELECT SD00.INT_IDSOLICITUD,
                     SD00.INT_IDSOLICITUD_DET,
                     SD00.VC_TIPO_DOCUMENTO AS VC_TIPO_DOCUMENTO,
                     SD00.VC_NUMERO_DOCUMENTO AS VC_NUMERO_DOCUMENTO,
                     SD00.VC_RAZON_SOCIAL AS VC_RAZON_SOCIAL,
                     (SD00.VC_NOMBRES || SD00.VC_APELLIDO_PATERNO ||
                     SD00.VC_APELLIDO_MATERNO) AS VC_NOMBRES,
                     SD00.VC_DIRECCION AS VC_DIRECCION,
                     SD00.VC_UBIGEO AS VC_UBIGEO,
                     '' AS VC_GRUPOBEN,
                     SD00.VC_TIPO_DOCUMENTO_REPLEG AS VC_TIPNUMREPLEG,
                     '' AS VC_NUMREPLEG,
                     SD00.VC_NOMBRES_REPLEG || ' ' ||
                     SD00.VC_APELLIDOS_REPLEG AS VC_REPLEG,
                     SD00.VC_CARGO_REPLEG AS VC_CARGREPLEG,
                     SD00.VC_CIIU AS VC_CIIU,
                     SD00.VC_TAMANO_EMPRESA AS VC_TAMANIO,
                     SD00.VC_MONEDA AS VC_MONEDA,
                     '' AS VC_MONTOPRESTAMO,
                     '' AS VC_TASAINTERES,
                     SD00.VC_COLATERAL_CREDITO AS VC_COLCRED,
                     '' AS VC_MONTOLATERAL,
                     SD00.VC_TIPO_DESTINO AS VC_TIPDESTINO,
                     '' AS VC_PLAZOOPER,
                     '' AS VC_PERIODGRACIA,
                     SD00.VC_CODIGO_SUBASTA AS VC_CODSUBASTA,
                     '' AS VC_ORIGENFONDOS,
                     PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM', SD00.VC_ESTADO, 0) AS VC_ESTADO,
                     '' AS VC_TIPO_ERROR,
                     0 AS INT_FILA_ARCHIVO,
                     '' AS VC_FILA_ARCHIVO,
                     SD00.OBSERVACIONES,
                     1 AS ORDEN,
                     SD00.DEC_PORCENTAJE_COBERTURA,
                     SD00.DEC_MONTO_COBERTURA					 
            FROM SOLICITUD S00
              INNER JOIN SOLICITUD_DETALLE SD00
                ON (S00.INT_IDSOLICITUD = SD00.INT_IDSOLICITUD)
            WHERE S00.INT_IDSOLICITUD IN (SELECT TO_NUMBER(REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL)) AS SOLICITUD
                  FROM DUAL
                CONNECT BY REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL) IS NOT NULL)
              AND SD00.OBSERVACIONES = 'MIGRA'
            UNION ALL
          SELECT SD00.INT_IDSOLICITUD,
                 SDT00.INT_IDSOLICITUD_DET,
                 SDT00.C01 AS VC_TIPO_DOCUMENTO,
                 SDT00.C02 AS VC_NUMERO_DOCUMENTO,
                 SDT00.C03 AS VC_RAZON_SOCIAL,
                 (SDT00.C04 || ' ' || SDT00.C05 || ' ' || SDT00.C06) AS VC_NOMBRES,
                 SDT00.C07 AS VC_DIRECCION,
                 SDT00.C08 AS VC_UBIGEO,
                 SDT00.C09 AS VC_GRUPOBEN,
                 SDT00.C10 AS VC_TIPNUMREPLEG,
                 SDT00.C11 AS VC_NUMREPLEG,
                 SDT00.C12 || ' ' || SDT00.C13 AS VC_REPLEG,
                 SDT00.C14 AS VC_CARGREPLEG,
                 SDT00.C15 AS VC_CIIU,
                 SDT00.C16 AS VC_TAMANIO,
                 SDT00.C17 AS VC_MONEDA,
                 SDT00.C18 AS VC_MONTOPRESTAMO,
                 SDT00.C19 AS VC_TASAINTERES,
                 SDT00.C20 AS VC_COLCRED,
                 SDT00.C21 AS VC_MONTOLATERAL,
                 SDT00.C22 AS VC_TIPDESTINO,
                 SDT00.C23 AS VC_PLAZOOPER,
                 SDT00.C24 AS VC_PERIODGRACIA,
                 SDT00.C25 AS VC_CODSUBASTA,
                 SDT00.C26 AS VC_ORIGENFONDOS,
                 PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM', SD00.VC_ESTADO, 0) AS VC_ESTADO,
                 '' AS VC_TIPO_ERROR,
                 SDT00.INT_FILA AS INT_FILA_ARCHIVO,
                 '' AS VC_FILA_ARCHIVO,
                 SD00.OBSERVACIONES,
                 2 AS ORDEN,
                 SD00.DEC_PORCENTAJE_COBERTURA,
                 SD00.DEC_MONTO_COBERTURA  				 
            FROM SOLICITUD S00
              INNER JOIN SOLICITUD_DETALLE SD00
                ON (S00.INT_IDSOLICITUD = SD00.INT_IDSOLICITUD)
              INNER JOIN SOLICITUD_DETALLE_TEXTO SDT00
                ON (SD00.INT_IDSOLICITUD = SDT00.INT_IDSOLICITUD
                AND SD00.INT_IDSOLICITUD_DET = SDT00.INT_IDSOLICITUD_DET)
            WHERE S00.INT_IDSOLICITUD IN (SELECT TO_NUMBER(REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL)) AS SOLICITUD
                  FROM DUAL
                CONNECT BY REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL) IS NOT NULL)
              AND SD00.OBSERVACIONES = 'OK'
              AND p_intFlagAprobados = 1
            UNION ALL
          SELECT SDT01.INT_IDSOLICITUD,
                 SDT01.INT_IDSOLICITUD_DET,
                 SDT01.C01 AS VC_TIPO_DOCUMENTO,
                 SDT01.C02 AS VC_NUMERO_DOCUMENTO,
                 SDT01.C03 AS VC_RAZON_SOCIAL,
                 (SDT01.C04 || ' ' || SDT01.C05 || ' ' || SDT01.C06) AS VC_NOMBRES,
                 SDT01.C07 AS VC_DIRECCION,
                 SDT01.C08 AS VC_UBIGEO,
                 SDT01.C09 AS VC_GRUPOBEN,
                 SDT01.C10 AS VC_TIPNUMREPLEG,
                 SDT01.C11 AS VC_NUMREPLEG,
                 SDT01.C12 || ' ' || SDT01.C13 AS VC_REPLEG,
                 SDT01.C14 AS VC_CARGREPLEG,
                 SDT01.C15 AS VC_CIIU,
                 SDT01.C16 AS VC_TAMANIO,
                 SDT01.C17 AS VC_MONEDA,
                 SDT01.C18 AS VC_MONTOPRESTAMO,
                 SDT01.C19 AS VC_TASAINTERES,
                 SDT01.C20 AS VC_COLCRED,
                 SDT01.C21 AS VC_MONTOLATERAL,
                 SDT01.C22 AS VC_TIPDESTINO,
                 SDT01.C23 AS VC_PLAZOOPER,
                 SDT01.C24 AS VC_PERIODGRACIA,
                 SDT01.C25 AS VC_CODSUBASTA,
                 SDT01.C26 AS VC_ORIGENFONDOS,
                 PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM', SD01.VC_ESTADO, 0) AS VC_ESTADO,
                 'SOLICITUD REGLAS' AS VC_TIPO_ERROR,
                 SDT01.INT_FILA AS INT_FILA_ARCHIVO,
                 'Error en fila ' || TRIM(TO_CHAR(SDT01.INT_FILA)) || ' del archivo Solicitud' AS VC_FILA_ARCHIVO,
                 SD01.OBSERVACIONES,
                 3 AS ORDEN,
                 SD01.DEC_PORCENTAJE_COBERTURA,
                 SD01.DEC_MONTO_COBERTURA  				 
            FROM SOLICITUD S01
              INNER JOIN SOLICITUD_DETALLE SD01
                ON (S01.INT_IDSOLICITUD = SD01.INT_IDSOLICITUD)
              INNER JOIN SOLICITUD_DETALLE_TEXTO SDT01
                ON (SD01.INT_IDSOLICITUD = SDT01.INT_IDSOLICITUD
                AND SD01.INT_IDSOLICITUD_DET = SDT01.INT_IDSOLICITUD_DET)
            WHERE S01.INT_IDSOLICITUD IN (SELECT TO_NUMBER(REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL)) AS SOLICITUD
                  FROM DUAL
                CONNECT BY REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL) IS NOT NULL)
              AND SD01.OBSERVACIONES <> 'OK'
              AND p_intFlagRechazados = 1
            UNION
          SELECT SDT02.INT_IDSOLICITUD,
                 SDT02.INT_IDSOLICITUD_DET,
                 SDT02.C01 AS VC_TIPO_DOCUMENTO,
                 SDT02.C02 AS VC_NUMERO_DOCUMENTO,
                 SDT02.C03 AS VC_RAZON_SOCIAL,
                 SDT02.C04 || ' ' || SDT02.C05 || ' ' || SDT02.C06 AS VC_NOMBRES,
                 SDT02.C07 AS VC_DIRECCION,
                 SDT02.C08 AS VC_UBIGEO,
                 SDT02.C09 AS VC_GRUPOBEN,
                 SDT02.C10 AS VC_TIPNUMREPLEG,
                 SDT02.C11 AS VC_NUMREPLEG,
                 SDT02.C12 || ' ' || SDT02.C13 AS VC_REPLEG,
                 SDT02.C14 AS VC_CARGREPLEG,
                 SDT02.C15 AS VC_CIIU,
                 SDT02.C16 AS VC_TAMANIO,
                 SDT02.C17 AS VC_MONEDA,
                 SDT02.C18 AS VC_MONTOPRESTAMO,
                 SDT02.C19 AS VC_TASAINTERES,
                 SDT02.C20 AS VC_COLCRED,
                 SDT02.C21 AS VC_MONTOLATERAL,
                 SDT02.C22 AS VC_TIPDESTINO,
                 SDT02.C23 AS VC_PLAZOOPER,
                 SDT02.C24 AS VC_PERIODGRACIA,
                 SDT02.C25 AS VC_CODSUBASTA,
                 SDT02.C26 AS VC_ORIGENFONDOS,
                 PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM', 'REC', 0) AS VC_ESTADO,
                 'SOLICITUD ESTRUCTURA' AS VC_TIPO_ERROR,
                 SDT02.INT_FILA AS INT_FILA_ARCHIVO,
                 'Error en fila ' || TRIM(TO_CHAR(SDT02.INT_FILA)) || ' del archivo Solicitud' AS VC_FILA_ARCHIVO,
                 SDT02.OBSERVACIONES,
                 4 AS ORDEN,
                 CAST(NULL AS NUMBER) AS DEC_PORCENTAJE_COBERTURA,
                 CAST(NULL AS NUMBER) AS DEC_MONTO_COBERTURA                 				 
            FROM SOLICITUD S02
              INNER JOIN SOLICITUD_DETALLE_TEXTO SDT02
                ON (S02.INT_IDSOLICITUD = SDT02.INT_IDSOLICITUD)
            WHERE S02.INT_IDSOLICITUD IN (SELECT TO_NUMBER(REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL)) AS SOLICITUD
                  FROM DUAL
                CONNECT BY REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL) IS NOT NULL)
              AND SDT02.OBSERVACIONES <> 'OK'
              AND p_intFlagRechazados = 1
            ORDER BY INT_IDSOLICITUD ASC,
                     INT_FILA_ARCHIVO ASC) ER
          INNER JOIN SOLICITUD SO
            ON (SO.INT_IDSOLICITUD = ER.INT_IDSOLICITUD)
        ORDER BY SO.INT_IDSOLICITUD,
                 ER.INT_FILA_ARCHIVO;

    EXCEPTION
      WHEN OTHERS THEN PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD', 'S_LISTAR_SOLICITUD_DETALLADO_ERRORES', vcErrorStack, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
          RAISE_APPLICATION_ERROR(-20207, 'PKG_SOLICITUD.S_LISTAR_SOLICITUD_DETALLADO_ERRORES:' || vcErrorStack || '; ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
    END S_LISTAR_SOLICITUD_DETALLADO_ERRORES;

  PROCEDURE S_LISTAR_SOLICITUD_DETALLADO_ERRORES2(p_vcCodigo           IN  SOLICITUD.VC_CODIGO % TYPE,
                                                  p_intIdIFI           IN  SOLICITUD.INT_IDIFI % TYPE,
                                                  p_intIdEstado        IN  SOLICITUD.INT_IDESTADO % TYPE,
                                                  p_dtFechaDesde       IN  SOLICITUD.DT_FECHA % TYPE,
                                                  p_dtFechaHasta       IN  SOLICITUD.DT_FECHA % TYPE,
                                                  p_intIdTipoOperacion IN  SOLICITUD.INT_IDTIPO_OPERACION % TYPE,
                                                  p_vcNumeroDocumento  IN  SOLICITUD_DETALLE.VC_NUMERO_DOCUMENTO % TYPE,
                                                  p_intFlagAprobados   IN  NUMBER,
                                                  p_intFlagRechazados  IN  NUMBER,
                                                  p_curTabla           OUT SYS_REFCURSOR)
    AS
    BEGIN
      OPEN p_curTabla FOR
      SELECT SO.INT_IDSOLICITUD,
             ER.INT_IDSOLICITUD_DET,
             SO.VC_CODIGO,
             SO.INT_IDIFI,
             SO.VC_NOMBRE_IFI,
             ER.VC_UBIGEO,
             ER.VC_GRUPOBEN,
             ER.VC_CIIU,
             ER.VC_TIPNUMREPLEG,
             ER.VC_DIRECCION,
             ER.VC_NUMREPLEG,
             ER.VC_REPLEG,
             ER.VC_MONEDA,
             ER.VC_COLCRED,
             ER.VC_MONTOLATERAL,
             ER.VC_TIPDESTINO,
             ER.VC_MONTOPRESTAMO,
             ER.VC_CARGREPLEG,
             ER.VC_TIPO_DOCUMENTO,
             ER.VC_TASAINTERES,
             ER.VC_TAMANIO,
             ER.VC_NUMERO_DOCUMENTO,
             ER.VC_PERIODGRACIA,
             ER.VC_PLAZOOPER,
             ER.VC_ORIGENFONDOS,
             ER.VC_RAZON_SOCIAL,
             ER.VC_NOMBRES,
             ER.VC_DIRECCION,
             ER.VC_TIPO_ERROR,
             ER.INT_FILA_ARCHIVO,
             ER.VC_FILA_ARCHIVO,
             ER.VC_CODSUBASTA,
             ER.VC_ESTADO,
             ER.OBSERVACIONES
        FROM (SELECT SD00.INT_IDSOLICITUD,
                     SD00.INT_IDSOLICITUD_DET,
                     SD00.VC_TIPO_DOCUMENTO AS VC_TIPO_DOCUMENTO,
                     SD00.VC_NUMERO_DOCUMENTO AS VC_NUMERO_DOCUMENTO,
                     SD00.VC_RAZON_SOCIAL AS VC_RAZON_SOCIAL,
                     (SD00.VC_NOMBRES || SD00.VC_APELLIDO_PATERNO ||
                     SD00.VC_APELLIDO_MATERNO) AS VC_NOMBRES,
                     SD00.VC_DIRECCION AS VC_DIRECCION,
                     SD00.VC_UBIGEO AS VC_UBIGEO,
                     '' AS VC_GRUPOBEN,
                     SD00.VC_TIPO_DOCUMENTO_REPLEG AS VC_TIPNUMREPLEG,
                     '' AS VC_NUMREPLEG,
                     SD00.VC_NOMBRES_REPLEG || ' ' ||
                     SD00.VC_APELLIDOS_REPLEG AS VC_REPLEG,
                     SD00.VC_CARGO_REPLEG AS VC_CARGREPLEG,
                     SD00.VC_CIIU AS VC_CIIU,
                     SD00.VC_TAMANO_EMPRESA AS VC_TAMANIO,
                     SD00.VC_MONEDA AS VC_MONEDA,
                     '' AS VC_MONTOPRESTAMO,
                     '' AS VC_TASAINTERES,
                     SD00.VC_COLATERAL_CREDITO AS VC_COLCRED,
                     '' AS VC_MONTOLATERAL,
                     SD00.VC_TIPO_DESTINO AS VC_TIPDESTINO,
                     '' AS VC_PLAZOOPER,
                     '' AS VC_PERIODGRACIA,
                     SD00.VC_CODIGO_SUBASTA AS VC_CODSUBASTA,
                     '' AS VC_ORIGENFONDOS,
                     PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM', SD00.VC_ESTADO, 0) AS VC_ESTADO,
                     '' AS VC_TIPO_ERROR,
                     0 AS INT_FILA_ARCHIVO,
                     '' AS VC_FILA_ARCHIVO,
                     SD00.OBSERVACIONES,
                     1 AS ORDEN
            FROM SOLICITUD S00
              INNER JOIN SOLICITUD_DETALLE SD00
                ON (S00.INT_IDSOLICITUD = SD00.INT_IDSOLICITUD)
            WHERE (p_vcCodigo IS NULL
              OR S00.VC_CODIGO LIKE '%' || p_vcCodigo || '%')
              AND S00.INT_IDIFI = NVL(DECODE(p_intIdIFI, 0, NULL, p_intIdIFI), S00.INT_IDIFI)
              AND S00.INT_IDESTADO = NVL(DECODE(p_intIdEstado, 0, NULL, p_intIdEstado), S00.INT_IDESTADO)
              AND S00.DT_FECHA >= NVL(p_dtFechaDesde, S00.DT_FECHA)
              AND S00.DT_FECHA <= NVL(p_dtFechaHasta, S00.DT_FECHA)
              AND S00.INT_IDTIPO_OPERACION = NVL(DECODE(p_intIdTipoOperacion, 0, NULL, p_intIdTipoOperacion), S00.INT_IDTIPO_OPERACION)
              AND SD00.VC_NUMERO_DOCUMENTO = NVL(p_vcNumeroDocumento, SD00.VC_NUMERO_DOCUMENTO)
              AND SD00.OBSERVACIONES = 'MIGRA'
            UNION ALL
          SELECT SD00.INT_IDSOLICITUD,
                 SDT00.INT_IDSOLICITUD_DET,
                 SDT00.C01 AS VC_TIPO_DOCUMENTO,
                 SDT00.C02 AS VC_NUMERO_DOCUMENTO,
                 SDT00.C03 AS VC_RAZON_SOCIAL,
                 (SDT00.C04 || ' ' || SDT00.C05 || ' ' || SDT00.C06) AS VC_NOMBRES,
                 SDT00.C07 AS VC_DIRECCION,
                 SDT00.C08 AS VC_UBIGEO,
                 SDT00.C09 AS VC_GRUPOBEN,
                 SDT00.C10 AS VC_TIPNUMREPLEG,
                 SDT00.C11 AS VC_NUMREPLEG,
                 SDT00.C12 || ' ' || SDT00.C13 AS VC_REPLEG,
                 SDT00.C14 AS VC_CARGREPLEG,
                 SDT00.C15 AS VC_CIIU,
                 SDT00.C16 AS VC_TAMANIO,
                 SDT00.C17 AS VC_MONEDA,
                 SDT00.C18 AS VC_MONTOPRESTAMO,
                 SDT00.C19 AS VC_TASAINTERES,
                 SDT00.C20 AS VC_COLCRED,
                 SDT00.C21 AS VC_MONTOLATERAL,
                 SDT00.C22 AS VC_TIPDESTINO,
                 SDT00.C23 AS VC_PLAZOOPER,
                 SDT00.C24 AS VC_PERIODGRACIA,
                 SDT00.C25 AS VC_CODSUBASTA,
                 SDT00.C26 AS VC_ORIGENFONDOS,
                 PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM', SD00.VC_ESTADO, 0) AS VC_ESTADO,
                 '' AS VC_TIPO_ERROR,
                 SDT00.INT_FILA AS INT_FILA_ARCHIVO,
                 '' AS VC_FILA_ARCHIVO,
                 SD00.OBSERVACIONES,
                 2 AS ORDEN
            FROM SOLICITUD S00
              INNER JOIN SOLICITUD_DETALLE SD00
                ON (S00.INT_IDSOLICITUD = SD00.INT_IDSOLICITUD)
              INNER JOIN SOLICITUD_DETALLE_TEXTO SDT00
                ON (SD00.INT_IDSOLICITUD = SDT00.INT_IDSOLICITUD
                AND SD00.INT_IDSOLICITUD_DET = SDT00.INT_IDSOLICITUD_DET)
            WHERE (p_vcCodigo IS NULL
              OR S00.VC_CODIGO LIKE '%' || p_vcCodigo || '%')
              AND S00.INT_IDIFI = NVL(DECODE(p_intIdIFI, 0, NULL, p_intIdIFI), S00.INT_IDIFI)
              AND S00.INT_IDESTADO = NVL(DECODE(p_intIdEstado, 0, NULL, p_intIdEstado), S00.INT_IDESTADO)
              AND S00.DT_FECHA >= NVL(p_dtFechaDesde, S00.DT_FECHA)
              AND S00.DT_FECHA <= NVL(p_dtFechaHasta, S00.DT_FECHA)
              AND S00.INT_IDTIPO_OPERACION = NVL(DECODE(p_intIdTipoOperacion, 0, NULL, p_intIdTipoOperacion), S00.INT_IDTIPO_OPERACION)
              AND SD00.VC_NUMERO_DOCUMENTO = NVL(p_vcNumeroDocumento, SD00.VC_NUMERO_DOCUMENTO)
              AND SD00.OBSERVACIONES = 'OK'
              AND p_intFlagAprobados = 1
            UNION ALL
          SELECT SDT01.INT_IDSOLICITUD,
                 SDT01.INT_IDSOLICITUD_DET,
                 SDT01.C01 AS VC_TIPO_DOCUMENTO,
                 SDT01.C02 AS VC_NUMERO_DOCUMENTO,
                 SDT01.C03 AS VC_RAZON_SOCIAL,
                 (SDT01.C04 || ' ' || SDT01.C05 || ' ' || SDT01.C06) AS VC_NOMBRES,
                 SDT01.C07 AS VC_DIRECCION,
                 SDT01.C08 AS VC_UBIGEO,
                 SDT01.C09 AS VC_GRUPOBEN,
                 SDT01.C10 AS VC_TIPNUMREPLEG,
                 SDT01.C11 AS VC_NUMREPLEG,
                 SDT01.C12 || ' ' || SDT01.C13 AS VC_REPLEG,
                 SDT01.C14 AS VC_CARGREPLEG,
                 SDT01.C15 AS VC_CIIU,
                 SDT01.C16 AS VC_TAMANIO,
                 SDT01.C17 AS VC_MONEDA,
                 SDT01.C18 AS VC_MONTOPRESTAMO,
                 SDT01.C19 AS VC_TASAINTERES,
                 SDT01.C20 AS VC_COLCRED,
                 SDT01.C21 AS VC_MONTOLATERAL,
                 SDT01.C22 AS VC_TIPDESTINO,
                 SDT01.C23 AS VC_PLAZOOPER,
                 SDT01.C24 AS VC_PERIODGRACIA,
                 SDT01.C25 AS VC_CODSUBASTA,
                 SDT01.C26 AS VC_ORIGENFONDOS,
                 PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM', SD01.VC_ESTADO, 0) AS VC_ESTADO,
                 'SOLICITUD REGLAS' AS VC_TIPO_ERROR,
                 SDT01.INT_FILA AS INT_FILA_ARCHIVO,
                 'Error en fila ' || TRIM(TO_CHAR(SDT01.INT_FILA)) || ' del archivo Solicitud' AS VC_FILA_ARCHIVO,
                 SD01.OBSERVACIONES,
                 3 AS ORDEN
            FROM SOLICITUD S01
              INNER JOIN SOLICITUD_DETALLE SD01
                ON (S01.INT_IDSOLICITUD = SD01.INT_IDSOLICITUD)
              INNER JOIN SOLICITUD_DETALLE_TEXTO SDT01
                ON (SD01.INT_IDSOLICITUD = SDT01.INT_IDSOLICITUD
                AND SD01.INT_IDSOLICITUD_DET = SDT01.INT_IDSOLICITUD_DET)
            WHERE (p_vcCodigo IS NULL
              OR S01.VC_CODIGO LIKE '%' || p_vcCodigo || '%')
              AND S01.INT_IDIFI = NVL(DECODE(p_intIdIFI, 0, NULL, p_intIdIFI), S01.INT_IDIFI)
              AND S01.INT_IDESTADO = NVL(DECODE(p_intIdEstado, 0, NULL, p_intIdEstado), S01.INT_IDESTADO)
              AND S01.DT_FECHA >= NVL(p_dtFechaDesde, S01.DT_FECHA)
              AND S01.DT_FECHA <= NVL(p_dtFechaHasta, S01.DT_FECHA)
              AND S01.INT_IDTIPO_OPERACION = NVL(DECODE(p_intIdTipoOperacion, 0, NULL, p_intIdTipoOperacion), S01.INT_IDTIPO_OPERACION)
              AND SD01.VC_NUMERO_DOCUMENTO = NVL(p_vcNumeroDocumento, SD01.VC_NUMERO_DOCUMENTO)
              AND SD01.OBSERVACIONES <> 'OK'
              AND p_intFlagRechazados = 1
            UNION
          SELECT SDT02.INT_IDSOLICITUD,
                 SDT02.INT_IDSOLICITUD_DET,
                 SDT02.C01 AS VC_TIPO_DOCUMENTO,
                 SDT02.C02 AS VC_NUMERO_DOCUMENTO,
                 SDT02.C03 AS VC_RAZON_SOCIAL,
                 SDT02.C04 || ' ' || SDT02.C05 || ' ' || SDT02.C06 AS VC_NOMBRES,
                 SDT02.C07 AS VC_DIRECCION,
                 SDT02.C08 AS VC_UBIGEO,
                 SDT02.C09 AS VC_GRUPOBEN,
                 SDT02.C10 AS VC_TIPNUMREPLEG,
                 SDT02.C11 AS VC_NUMREPLEG,
                 SDT02.C12 || ' ' || SDT02.C13 AS VC_REPLEG,
                 SDT02.C14 AS VC_CARGREPLEG,
                 SDT02.C15 AS VC_CIIU,
                 SDT02.C16 AS VC_TAMANIO,
                 SDT02.C17 AS VC_MONEDA,
                 SDT02.C18 AS VC_MONTOPRESTAMO,
                 SDT02.C19 AS VC_TASAINTERES,
                 SDT02.C20 AS VC_COLCRED,
                 SDT02.C21 AS VC_MONTOLATERAL,
                 SDT02.C22 AS VC_TIPDESTINO,
                 SDT02.C23 AS VC_PLAZOOPER,
                 SDT02.C24 AS VC_PERIODGRACIA,
                 SDT02.C25 AS VC_CODSUBASTA,
                 SDT02.C26 AS VC_ORIGENFONDOS,
                 PKG_TABLA_DETALLE.F_OBT_VALOR_TABLADETALLE('ESTADOSOLIDETA', 'REC', 0) AS VC_ESTADO,
                 'SOLICITUD ESTRUCTURA' AS VC_TIPO_ERROR,
                 SDT02.INT_FILA AS INT_FILA_ARCHIVO,
                 'Error en fila ' || TRIM(TO_CHAR(SDT02.INT_FILA)) || ' del archivo Solicitud' AS VC_FILA_ARCHIVO,
                 SDT02.OBSERVACIONES,
                 4 AS ORDEN
            FROM SOLICITUD S02
              INNER JOIN SOLICITUD_DETALLE_TEXTO SDT02
                ON (S02.INT_IDSOLICITUD = SDT02.INT_IDSOLICITUD)
            WHERE (p_vcCodigo IS NULL
              OR S02.VC_CODIGO LIKE '%' || p_vcCodigo || '%')
              AND S02.INT_IDIFI = NVL(DECODE(p_intIdIFI, 0, NULL, p_intIdIFI), S02.INT_IDIFI)
              AND S02.INT_IDESTADO = NVL(DECODE(p_intIdEstado, 0, NULL, p_intIdEstado), S02.INT_IDESTADO)
              AND S02.DT_FECHA >= NVL(p_dtFechaDesde, S02.DT_FECHA)
              AND S02.DT_FECHA <= NVL(p_dtFechaHasta, S02.DT_FECHA)
              AND S02.INT_IDTIPO_OPERACION = NVL(DECODE(p_intIdTipoOperacion, 0, NULL, p_intIdTipoOperacion), S02.INT_IDTIPO_OPERACION)
              AND SDT02.C02 = NVL(p_vcNumeroDocumento, SDT02.C02)
              AND SDT02.OBSERVACIONES <> 'OK'
              AND p_intFlagRechazados = 1) ER
          INNER JOIN SOLICITUD SO
            ON (SO.INT_IDSOLICITUD = ER.INT_IDSOLICITUD)
        ORDER BY SO.INT_IDSOLICITUD,
                 ER.INT_FILA_ARCHIVO;
    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD', 'S_LISTAR_SOLICITUD_DETALLADO_ERRORES2', vcErrorStack, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
          RAISE_APPLICATION_ERROR(-20208, 'PKG_SOLICITUD.S_LISTAR_SOLICITUD_DETALLADO_ERRORES2:' || vcErrorStack || '; ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
    END S_LISTAR_SOLICITUD_DETALLADO_ERRORES2;

  PROCEDURE S_LISTAR_ALL(p_vcCodigo           IN  SOLICITUD.VC_CODIGO % TYPE,
                         p_intIdIFI           IN  SOLICITUD.INT_IDIFI % TYPE,
                         p_intIdEstado        IN  SOLICITUD.INT_IDESTADO % TYPE,
                         p_dtFechaDesde       IN  SOLICITUD.DT_FECHA % TYPE,
                         p_dtFechaHasta       IN  SOLICITUD.DT_FECHA % TYPE,
                         p_intIdTipoOperacion IN  SOLICITUD.INT_IDTIPO_OPERACION % TYPE,
                         p_vcNumeroDocumento  IN  SOLICITUD_DETALLE.VC_NUMERO_DOCUMENTO % TYPE,
                         p_curTabla           OUT SYS_REFCURSOR)
    AS
    BEGIN

      OPEN p_curTabla FOR
      SELECT D.INT_NUMERO_TOTAL_REGISTRO,
             D.INT_ROW_NUMBER,
             D.INT_IDSOLICITUD,
             D.VC_CODIGO,
             D.INT_IDIFI,
             D.VC_NOMBRE_IFI,
             D.INT_REGISTROS,
             D.INT_APROBADOS,
             D.INT_RECHAZADOS,
             D.INT_IDESTADO,
             D.ESTADO_SOL,
             D.INT_IDTIPO_OPERACION,
             D.TIPO_OPE,
             D.INT_IDMONEDA,
             D.MONEDA,
             D.DEC_TOTAL_COBERTURADO_INICIAL,
             D.DEC_TOTAL_DESEMBOLSADO,
             D.DT_FECHA,
             D.VC_USUARIO_CREACION,
             D.DT_FECHA_CREACION,
             D.VC_TERMINAL_CREACION,
             D.VC_USUARIO_MODIFICACION,
             D.DT_FECHA_MODIFICACION,
             D.VC_TERMINAL_MODIFICACION
        FROM (SELECT COUNT(1) OVER () AS INT_NUMERO_TOTAL_REGISTRO,
                     ROW_NUMBER() OVER (ORDER BY BS.INT_IDSOLICITUD DESC) AS INT_ROW_NUMBER,
                     BS.INT_IDSOLICITUD,
                     BS.VC_CODIGO,
                     BS.INT_IDIFI,
                     BS.VC_NOMBRE_IFI,
                     BS.INT_REGISTROS,
                     BS.INT_APROBADOS,
                     BS.INT_RECHAZADOS,
                     BS.INT_IDESTADO,
                     PKG_TABLA_DETALLE.F_OBT_NOMBRE_TABLADETALLE(BS.INT_IDESTADO) AS ESTADO_SOL,
                     BS.INT_IDTIPO_OPERACION,
                     PKG_TABLA_DETALLE.F_OBT_NOMBRE_TABLADETALLE(BS.INT_IDTIPO_OPERACION) AS TIPO_OPE,
                     BS.INT_IDMONEDA,
                     PKG_TABLA_DETALLE.F_OBT_NOMBRE_TABLADETALLE(BS.INT_IDMONEDA) AS MONEDA,
                     BS.DEC_TOTAL_COBERTURADO_INICIAL,
                     BS.DEC_TOTAL_DESEMBOLSADO,
                     BS.DT_FECHA,
                     BS.VC_USUARIO_CREACION,
                     BS.DT_FECHA_CREACION,
                     BS.VC_TERMINAL_CREACION,
                     BS.VC_USUARIO_MODIFICACION,
                     BS.DT_FECHA_MODIFICACION,
                     BS.VC_TERMINAL_MODIFICACION
            FROM SOLICITUD BS
            WHERE (p_vcCodigo IS NULL
              OR BS.VC_CODIGO LIKE '%' || p_vcCodigo || '%')
              AND BS.INT_IDIFI = NVL(DECODE(p_intIdIFI, 0, NULL, p_intIdIFI), BS.INT_IDIFI)
              AND BS.INT_IDESTADO = NVL(DECODE(p_intIdEstado, 0, NULL, p_intIdEstado), BS.INT_IDESTADO)
              AND BS.DT_FECHA >= NVL(p_dtFechaDesde, BS.DT_FECHA)
              AND BS.DT_FECHA <= NVL(p_dtFechaHasta, BS.DT_FECHA)
              AND BS.INT_IDTIPO_OPERACION = NVL(DECODE(p_intIdTipoOperacion, 0, NULL, p_intIdTipoOperacion), BS.INT_IDTIPO_OPERACION)
              AND (EXISTS (SELECT 1
                  FROM SOLICITUD_DETALLE BSD
                  WHERE BSD.INT_IDSOLICITUD = BS.INT_IDSOLICITUD
                    AND BSD.VC_NUMERO_DOCUMENTO = NVL(p_vcNumeroDocumento, BSD.VC_NUMERO_DOCUMENTO))
              OR p_vcNumeroDocumento IS NULL)
            ORDER BY BS.DT_FECHA_CREACION DESC) D
        ORDER BY D.INT_ROW_NUMBER;

    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD', 'S_LISTAR_ALL', vcErrorStack, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
          RAISE_APPLICATION_ERROR(-20209, 'PKG_SOLICITUD.S_LISTAR_ALL:' || vcErrorStack || '; ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
    END S_LISTAR_ALL;

	   PROCEDURE S_LISTAR_SOLICITUD_DETALLADO_EXPORTAR(p_vcCodigo           IN SOLICITUD.VC_CODIGO%TYPE,
                                                  p_intIdIFI           IN SOLICITUD.INT_IDIFI%TYPE,
                                                  p_intIdEstado        IN SOLICITUD.INT_IDESTADO%TYPE,
                                                  p_dtFechaDesde       IN SOLICITUD.DT_FECHA%TYPE,
                                                  p_dtFechaHasta       IN SOLICITUD.DT_FECHA%TYPE,
                                                  p_intIdTipoOperacion IN SOLICITUD.INT_IDTIPO_OPERACION%TYPE,
                                                  p_vcNumeroDocumento  IN SOLICITUD_DETALLE.VC_NUMERO_DOCUMENTO%TYPE,
                                                  p_intFlagAprobados   IN NUMBER,
                                                  p_intFlagRechazados  IN NUMBER,
                                                  p_curTabla           OUT SYS_REFCURSOR) AS
	  BEGIN

		OPEN p_curTabla FOR
		  SELECT COUNT(1) OVER() CONTEO4,
			T_REPLEG.INT_IDSOLICITUD,
			T_REPLEG.INT_IDSOLICITUD_DET,
			T_REPLEG.VC_CODIGO,
			T_REPLEG.INT_IDIFI,
			T_REPLEG.VC_NOMBRE_IFI,
			T_REPLEG.VC_TIPO_DOCUMENTO,
			T_REPLEG.VC_NUMERO_DOCUMENTO,
			T_REPLEG.VC_RAZON_SOCIAL,
			T_REPLEG.VC_NOMBRES,
			T_REPLEG.VC_DIRECCION,
			T_REPLEG.VC_UBIGEO,
			T_REPLEG.VC_GRUPOBEN,
			T_REPLEG.VC_TIPNUMREPLEG,
			T_REPLEG.VC_NUMREPLEG,
			T_REPLEG.VC_REPLEG,
			T_REPLEG.VC_CARGREPLEG,
			T_REPLEG.VC_CIIU,
			T_REPLEG.VC_TAMANIO,
			T_REPLEG.VC_MONEDA,
			T_REPLEG.VC_MONTOPRESTAMO,
			T_REPLEG.VC_TASAINTERES,
			T_REPLEG.VC_COLCRED,
			T_REPLEG.VC_MONTOLATERAL,
			T_REPLEG.VC_TIPDESTINO,
			T_REPLEG.VC_PLAZOOPER,
			T_REPLEG.VC_PERIODGRACIA,
			T_REPLEG.VC_CODSUBASTA,
			T_REPLEG.VC_ORIGENFONDOS,
			T_REPLEG.INT_FILA_ARCHIVO,
			CASE WHEN T_REPLEG.OBSERVACIONES <> 'OK' THEN 'Error en fila ' || TRIM(TO_CHAR(T_REPLEG.INT_FILA_ARCHIVO)) || ' del archivo Solicitud' ELSE '' END AS VC_FILA_ARCHIVO,			
			T_REPLEG.VC_ESTADO,
			T_REPLEG.VC_TIPO_ERROR,
			T_REPLEG.OBSERVACIONES,
			T_REPLEG.DEC_PORCENTAJE_COBERTURA,
            T_REPLEG.DEC_MONTO_COBERTURA
		FROM (SELECT COUNT(1) OVER() CONTEO3,
				T_DETALLE.INT_IDSOLICITUD,
				T_DETALLE.INT_IDSOLICITUD_DET,
				T_DETALLE.VC_CODIGO,
				T_DETALLE.INT_IDIFI,
				T_DETALLE.VC_NOMBRE_IFI,
				T_DETALLE.VC_TIPO_DOCUMENTO,
				T_DETALLE.VC_NUMERO_DOCUMENTO,
				T_DETALLE.VC_RAZON_SOCIAL,
				T_DETALLE.VC_NOMBRES,
				T_DETALLE.VC_DIRECCION,
				T_DETALLE.VC_UBIGEO,
				T_DETALLE.VC_GRUPOBEN,
				T_DETALLE.VC_TIPNUMREPLEG,
				T_DETALLE.VC_NUMREPLEG,
				T_DETALLE.VC_REPLEG,
				T_DETALLE.VC_CARGREPLEG,
				T_DETALLE.VC_CIIU,
				T_DETALLE.VC_TAMANIO,
				T_DETALLE.VC_MONEDA,
				T_DETALLE.VC_MONTOPRESTAMO,
				T_DETALLE.VC_TASAINTERES,
				T_DETALLE.VC_COLCRED,
				T_DETALLE.VC_MONTOLATERAL,
				T_DETALLE.VC_TIPDESTINO,
				T_DETALLE.VC_PLAZOOPER,
				T_DETALLE.VC_PERIODGRACIA,
				T_DETALLE.VC_CODSUBASTA,
				T_DETALLE.VC_ORIGENFONDOS,
				T_DETALLE.INT_FILA_ARCHIVO,				
				T_DETALLE.VC_ESTADO,
				T_DETALLE.VC_TIPO_ERROR,
				T_DETALLE.OBSERVACIONES,
				LISTAGG(CASE WHEN SRT.OBSERVACIONES <> 'OK' THEN SRT.OBSERVACIONES ELSE '' END, ' | ') WITHIN GROUP (ORDER BY SRT.OBSERVACIONES) AS OBS_REP,
				T_DETALLE.DEC_PORCENTAJE_COBERTURA,
                T_DETALLE.DEC_MONTO_COBERTURA
		FROM (SELECT COUNT(1) OVER() CONTEO2,
				T_TEXTO.INT_IDSOLICITUD,
				T_TEXTO.INT_IDSOLICITUD_DET,
				T_TEXTO.VC_CODIGO,
				T_TEXTO.INT_IDIFI,
				T_TEXTO.VC_NOMBRE_IFI,
				T_TEXTO.VC_TIPO_DOCUMENTO,
				T_TEXTO.VC_NUMERO_DOCUMENTO,
				T_TEXTO.VC_RAZON_SOCIAL,
				T_TEXTO.VC_NOMBRES,
				T_TEXTO.VC_DIRECCION,
				T_TEXTO.VC_UBIGEO,
				T_TEXTO.VC_GRUPOBEN,
				T_TEXTO.VC_TIPNUMREPLEG,
				T_TEXTO.VC_NUMREPLEG,
				T_TEXTO.VC_REPLEG,
				T_TEXTO.VC_CARGREPLEG,
				T_TEXTO.VC_CIIU,
				T_TEXTO.VC_TAMANIO,
				T_TEXTO.VC_MONEDA,
				T_TEXTO.VC_MONTOPRESTAMO,
				T_TEXTO.VC_TASAINTERES,
				T_TEXTO.VC_COLCRED,
				T_TEXTO.VC_MONTOLATERAL,
				T_TEXTO.VC_TIPDESTINO,
				T_TEXTO.VC_PLAZOOPER,
				T_TEXTO.VC_PERIODGRACIA,
				T_TEXTO.VC_CODSUBASTA,
				T_TEXTO.VC_ORIGENFONDOS,
				T_TEXTO.INT_FILA_ARCHIVO,
				--SD.Z_INT_CATEGORIA1,
				--SD.Z_INT_CATEGORIA2,
				--SD.Z_INT_CATEGORIA3,
				CASE WHEN T_TEXTO.INT_IDSOLICITUD_DET > 0 THEN PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM', SD.VC_ESTADO, 0) ELSE PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM', 'RECHAZ', 0) END AS VC_ESTADO,
				CASE WHEN T_TEXTO.OBSERVACIONES <> 'OK' THEN T_TEXTO.VC_TIPO_ERROR ELSE 
					CASE WHEN SD.OBSERVACIONES <> 'OK' THEN 'SOLICITUD REGLAS' ELSE '' 
					END 
				END AS VC_TIPO_ERROR,
				CASE WHEN T_TEXTO.OBSERVACIONES <> 'OK' THEN T_TEXTO.OBSERVACIONES ELSE 
					CASE WHEN SD.OBSERVACIONES <> 'OK' THEN SD.OBSERVACIONES ELSE SD.OBSERVACIONES 
					END 
				END AS OBSERVACIONES,
				SD.DEC_PORCENTAJE_COBERTURA,
                SD.DEC_MONTO_COBERTURA
				FROM(         SELECT COUNT(1) OVER() CONTEO1,
									 S.INT_IDSOLICITUD,
									 NVL(SDT.INT_IDSOLICITUD_DET, 0) INT_IDSOLICITUD_DET,
									 S.VC_CODIGO,
									 S.INT_IDIFI,
									 S.VC_NOMBRE_IFI,
									 SDT.C01 AS VC_TIPO_DOCUMENTO,
									 SDT.C02 AS VC_NUMERO_DOCUMENTO,
									 SDT.C03 AS VC_RAZON_SOCIAL,
									 (SDT.C04 || ' ' || SDT.C05 || ' ' || SDT.C06) AS VC_NOMBRES,
									 SDT.C07 AS VC_DIRECCION,
									 SDT.C08 AS VC_UBIGEO,
									 SDT.C09 AS VC_GRUPOBEN,
									 SDT.C10 AS VC_TIPNUMREPLEG,
									 SDT.C11 AS VC_NUMREPLEG,
									 SDT.C12 || ' ' || SDT.C13 AS VC_REPLEG,
									 SDT.C14 AS VC_CARGREPLEG,
									 SDT.C15 AS VC_CIIU,
									 SDT.C16 AS VC_TAMANIO,
									 SDT.C17 AS VC_MONEDA,
									 SDT.C18 AS VC_MONTOPRESTAMO,
									 SDT.C19 AS VC_TASAINTERES,
									 SDT.C20 AS VC_COLCRED,
									 SDT.C21 AS VC_MONTOLATERAL,
									 SDT.C22 AS VC_TIPDESTINO,
									 SDT.C23 as VC_PLAZOOPER,
									 SDT.C24 as VC_PERIODGRACIA,
									 SDT.C25 as VC_CODSUBASTA,
									 SDT.C26 AS VC_ORIGENFONDOS,
									 CASE WHEN SDT.OBSERVACIONES <> 'OK' THEN 'SOLICITUD ESTRUCTURA' ELSE '' END AS VC_TIPO_ERROR,
									 SDT.INT_FILA AS INT_FILA_ARCHIVO,
									 SDT.OBSERVACIONES
								FROM SOLICITUD S
								INNER JOIN SOLICITUD_DETALLE_TEXTO SDT ON (S.INT_IDSOLICITUD = SDT.INT_IDSOLICITUD)
								WHERE (p_vcCodigo IS NULL OR S.VC_CODIGO LIKE '%' || p_vcCodigo || '%')
								 AND S.INT_IDIFI = NVL(DECODE(p_intIdIFI, 0, NULL, p_intIdIFI), S.INT_IDIFI)
								 AND S.INT_IDESTADO = NVL(DECODE(p_intIdEstado, 0, NULL, p_intIdEstado), S.INT_IDESTADO)
								 AND S.DT_FECHA >= NVL(p_dtFechaDesde, S.DT_FECHA)
								 AND S.DT_FECHA <= NVL(p_dtFechaHasta, S.DT_FECHA)
								 AND S.INT_IDTIPO_OPERACION = NVL(DECODE(p_intIdTipoOperacion, 0, NULL, p_intIdTipoOperacion), S.INT_IDTIPO_OPERACION))T_TEXTO
				LEFT JOIN SOLICITUD_DETALLE SD ON (T_TEXTO.INT_IDSOLICITUD_DET> 0 AND T_TEXTO.INT_IDSOLICITUD = SD.INT_IDSOLICITUD AND T_TEXTO.INT_IDSOLICITUD_DET = SD.INT_IDSOLICITUD_DET))T_DETALLE
		LEFT JOIN SOLICITUD_REPLEG SRT ON (T_DETALLE.INT_IDSOLICITUD = SRT.INT_IDSOLICITUD AND T_DETALLE.VC_NUMERO_DOCUMENTO = SRT.VC_NUMERO_DOCUMENTO)
		--LEFT JOIN SOLICITUD_REPLEG_TEXTO SRT ON (T_DETALLE.INT_IDSOLICITUD = SRT.INT_IDSOLICITUD AND T_DETALLE.VC_NUMERO_DOCUMENTO = SRT.C01)
		GROUP BY T_DETALLE.INT_IDSOLICITUD,
				T_DETALLE.INT_IDSOLICITUD_DET,
				T_DETALLE.VC_CODIGO,
				T_DETALLE.INT_IDIFI,
				T_DETALLE.VC_NOMBRE_IFI,
				T_DETALLE.VC_TIPO_DOCUMENTO,
				T_DETALLE.VC_NUMERO_DOCUMENTO,
				T_DETALLE.VC_RAZON_SOCIAL,
				T_DETALLE.VC_NOMBRES,
				T_DETALLE.VC_DIRECCION,
				T_DETALLE.VC_UBIGEO,
				T_DETALLE.VC_GRUPOBEN,
				T_DETALLE.VC_TIPNUMREPLEG,
				T_DETALLE.VC_NUMREPLEG,
				T_DETALLE.VC_REPLEG,
				T_DETALLE.VC_CARGREPLEG,
				T_DETALLE.VC_CIIU,
				T_DETALLE.VC_TAMANIO,
				T_DETALLE.VC_MONEDA,
				T_DETALLE.VC_MONTOPRESTAMO,
				T_DETALLE.VC_TASAINTERES,
				T_DETALLE.VC_COLCRED,
				T_DETALLE.VC_MONTOLATERAL,
				T_DETALLE.VC_TIPDESTINO,
				T_DETALLE.VC_PLAZOOPER,
				T_DETALLE.VC_PERIODGRACIA,
				T_DETALLE.VC_CODSUBASTA,
				T_DETALLE.VC_ORIGENFONDOS,
				T_DETALLE.INT_FILA_ARCHIVO,				
				T_DETALLE.VC_ESTADO,
				T_DETALLE.VC_TIPO_ERROR,
				T_DETALLE.OBSERVACIONES, 
				T_DETALLE.DEC_PORCENTAJE_COBERTURA,
                T_DETALLE.DEC_MONTO_COBERTURA
				ORDER BY T_DETALLE.INT_IDSOLICITUD, T_DETALLE.INT_FILA_ARCHIVO) T_REPLEG
			WHERE T_REPLEG.VC_NUMERO_DOCUMENTO = NVL(p_vcNumeroDocumento, T_REPLEG.VC_NUMERO_DOCUMENTO)
				 AND (p_intFlagAprobados = 1 AND T_REPLEG.OBSERVACIONES = 'OK' OR p_intFlagRechazados = 1 AND T_REPLEG.OBSERVACIONES <> 'OK')


				 UNION ALL

				 SELECT COUNT(1) OVER() CONTEO_MIGRA,
						 SD00.INT_IDSOLICITUD,
						 SD00.INT_IDSOLICITUD_DET,
						 S00.VC_CODIGO,
						 S00.INT_IDIFI,
						 S00.VC_NOMBRE_IFI,
						 SD00.VC_TIPO_DOCUMENTO AS VC_TIPO_DOCUMENTO,
						 SD00.VC_NUMERO_DOCUMENTO AS VC_NUMERO_DOCUMENTO,
						 SD00.VC_RAZON_SOCIAL AS VC_RAZON_SOCIAL,
						 (SD00.VC_APELLIDO_PATERNO || ' ' || SD00.VC_APELLIDO_MATERNO || ' ' || SD00.VC_NOMBRES) AS VC_NOMBRES,
						 SD00.VC_DIRECCION AS VC_DIRECCION,
						 SD00.VC_UBIGEO AS VC_UBIGEO,
						 SD00.VC_GENERO AS VC_GRUPOBEN,
						 SD00.VC_TIPO_DOCUMENTO_REPLEG AS VC_TIPNUMREPLEG,
						 TO_CHAR(SD00.VC_NUMERO_DOCUMENTO_REPLEG) AS VC_NUMREPLEG,
						 (SD00.VC_NOMBRES_REPLEG || ' ' || SD00.VC_APELLIDOS_REPLEG) AS VC_REPLEG,
						 SD00.VC_CARGO_REPLEG AS VC_CARGREPLEG,
						 SD00.VC_CIIU AS VC_CIIU,
						 SD00.VC_TAMANO_EMPRESA AS VC_TAMANIO,
						 SD00.VC_MONEDA AS VC_MONEDA,
						 TO_CHAR(SD00.DEC_MONTO_PRESTAMO) AS VC_MONTOPRESTAMO,
						 TO_CHAR(SD00.DEC_TASA_INTERES) AS VC_TASAINTERES,
						 SD00.VC_COLATERAL_CREDITO AS VC_COLCRED,
						 TO_CHAR(SD00.DEC_MONTO_COLATERAL) AS VC_MONTOLATERAL,
						 SD00.VC_TIPO_DESTINO AS VC_TIPDESTINO,
						 TO_CHAR(SD00.INT_PLAZO_OPERACION) as VC_PLAZOOPER,
						 TO_CHAR(SD00.INT_PERIODO_GRACIA) as VC_PERIODGRACIA,
						 SD00.VC_CODIGO_SUBASTA as VC_CODSUBASTA,
						 TO_CHAR(SD00.INT_ORIGEN_FONDOS) AS VC_ORIGENFONDOS,
						 0 AS INT_FILA_ARCHIVO,
						 '' AS VC_FILA_ARCHIVO,
						 --SD00.Z_INT_CATEGORIA1,
						 --SD00.Z_INT_CATEGORIA2,
						 --SD00.Z_INT_CATEGORIA3,
						 PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM', SD00.VC_ESTADO, 0) AS VC_ESTADO,
						 '' AS VC_TIPO_ERROR,
						 SD00.OBSERVACIONES,
						 SD00.DEC_PORCENTAJE_COBERTURA,
                         SD00.DEC_MONTO_COBERTURA
					FROM SOLICITUD S00
				   INNER JOIN SOLICITUD_DETALLE SD00
					  ON (S00.INT_IDSOLICITUD = SD00.INT_IDSOLICITUD)
				   WHERE SD00.OBSERVACIONES = 'MIGRA'
				   AND (p_vcCodigo IS NULL OR S00.VC_CODIGO LIKE '%' || p_vcCodigo || '%')
					 AND S00.INT_IDIFI = NVL(DECODE(p_intIdIFI, 0, NULL, p_intIdIFI), S00.INT_IDIFI)
					 AND S00.INT_IDESTADO = NVL(DECODE(p_intIdEstado, 0, NULL, p_intIdEstado), S00.INT_IDESTADO)
					 AND S00.DT_FECHA >= NVL(p_dtFechaDesde, S00.DT_FECHA)
					 AND S00.DT_FECHA <= NVL(p_dtFechaHasta, S00.DT_FECHA)
					 AND S00.INT_IDTIPO_OPERACION = NVL(DECODE(p_intIdTipoOperacion, 0, NULL, p_intIdTipoOperacion), S00.INT_IDTIPO_OPERACION)
					 AND SD00.VC_NUMERO_DOCUMENTO = NVL(p_vcNumeroDocumento, SD00.VC_NUMERO_DOCUMENTO)
					 AND (p_intFlagRechazados = 1 AND SD00.VC_ESTADO = 'REC' OR p_intFlagAprobados = 1 AND SD00.VC_ESTADO <> 'REC')

				 ;       


	  EXCEPTION
		WHEN OTHERS THEN
		  vcErrorStack    := DBMS_UTILITY.FORMAT_ERROR_STACK;
		  vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
		  PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD', 'S_LISTAR_SOLICITUD_DETALLADO_EXPORTAR', vcErrorStack, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
		  RAISE_APPLICATION_ERROR(-20208, 'PKG_SOLICITUD.S_LISTAR_SOLICITUD_DETALLADO_EXPORTAR:' || vcErrorStack || '; ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
	  END S_LISTAR_SOLICITUD_DETALLADO_EXPORTAR;   


  PROCEDURE S_LISTAR_DETALLE_X_SOLICITUD_Y_IDORDOCUMENTO(p_intIdSolicitud 	IN  SOLICITUD.INT_IDSOLICITUD % TYPE,
														 p_vcIdOrDocumento 	IN  SOLICITUD_DETALLE.VC_NUMERO_DOCUMENTO % TYPE,
														 p_intStartIndex  	IN  NUMBER,
														 p_intPageSize    	IN  NUMBER,
                                                         p_intAprobadas     IN  NUMBER,
														 p_curTabla       	OUT SYS_REFCURSOR)
    AS
    BEGIN

      OPEN p_curTabla FOR
      SELECT D.INT_NUMERO_TOTAL_REGISTRO,
             D.INT_ROW_NUMBER,
             D.INT_IDSOLICITUD_DET,
             D.VC_RAZON_SOCIAL,
             D.VC_TIPO_DOCUMENTO,
             D.VC_NUMERO_DOCUMENTO,
             D.DEC_MONTO_PRESTAMO,
             D.VC_MONEDA,
             D.DEC_MONTO_COBERTURA,
             D.DEC_PORCENTAJE_COBERTURA,
             D.VC_ESTADO,
             D.JSON_UI_DECORADORES
        FROM (SELECT 
              COUNT(1) OVER () AS INT_NUMERO_TOTAL_REGISTRO,
              ROW_NUMBER() OVER (ORDER BY INT_IDSOLICITUD DESC) AS INT_ROW_NUMBER,
              T.INT_IDSOLICITUD_DET,
             T.VC_RAZON_SOCIAL,
             T.VC_TIPO_DOCUMENTO,
             T.VC_NUMERO_DOCUMENTO,
             T.DEC_MONTO_PRESTAMO,
             T.VC_MONEDA,
             T.DEC_MONTO_COBERTURA,
             T.DEC_PORCENTAJE_COBERTURA,
             T.VC_ESTADO,
             T.JSON_UI_DECORADORES
              FROM (SELECT DET.INT_IDSOLICITUD,
                           DET.INT_IDSOLICITUD_DET,
                           /* Fuerza VARCHAR2 en la concatenación */
                           NVL(
                             CAST(DET.VC_RAZON_SOCIAL AS VARCHAR2(4000)),
                             CAST(DET.VC_NOMBRES AS VARCHAR2(400)) || ' ' ||
                             CAST(DET.VC_APELLIDO_PATERNO AS VARCHAR2(400)) || ' ' ||
                             CAST(DET.VC_APELLIDO_MATERNO AS VARCHAR2(400))
                           ) AS VC_RAZON_SOCIAL,
                           CAST(DET.VC_TIPO_DOCUMENTO    AS VARCHAR2(50))   AS VC_TIPO_DOCUMENTO,
                           CAST(DET.VC_NUMERO_DOCUMENTO  AS VARCHAR2(100))  AS VC_NUMERO_DOCUMENTO,
                           DET.DEC_MONTO_PRESTAMO,
                           CAST(DET.VC_MONEDA            AS VARCHAR2(10))   AS VC_MONEDA,
                           DET.DEC_MONTO_COBERTURA,
                           DET.DEC_PORCENTAJE_COBERTURA,                           
                           CAST(PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM', DET.VC_ESTADO, 0) AS VARCHAR2(400)) AS VC_ESTADO,                           
                           CAST(DBMS_LOB.SUBSTR(DET.JSON_UI_DECORADORES, 4000, 1) AS VARCHAR2(4000)) AS JSON_UI_DECORADORES
                    FROM SOLICITUD_DETALLE DET
                    LEFT JOIN US_BASE.V_BASE_ESTADOSSOLDET_CLASIFICADOS V ON V.COD_CORTO = DET.VC_ESTADO
                    WHERE DET.INT_IDSOLICITUD = p_intIdSolicitud
                    AND (
                          p_intAprobadas IS NULL
                       OR (p_intAprobadas = 1  AND V.GRUPO = 'A')
                       OR (p_intAprobadas <> 1 AND V.GRUPO = 'R')
                    )
                    AND (p_vcIdOrDocumento IS NULL OR DET.INT_IDSOLICITUD_DET = p_vcIdOrDocumento OR DET.VC_NUMERO_DOCUMENTO = p_vcIdOrDocumento) 
                    UNION ALL 
                    SELECT  DETX.INT_IDSOLICITUD, 
                            DETX.INT_IDSOLICITUD_DET,
                             NVL(
                                 CAST(DETX.C03 AS VARCHAR2(4000)),
                                 CAST(DETX.C06 AS VARCHAR2(400)) || ' ' ||
                                 CAST(DETX.C04 AS VARCHAR2(400)) || ' ' ||
                                 CAST(DETX.C05 AS VARCHAR2(400))
                             )                                                AS VC_RAZON_SOCIAL,
                             CAST(DETX.C01 AS VARCHAR2(50))                   AS VC_TIPO_DOCUMENTO,
                             CAST(DETX.C02 AS VARCHAR2(100))                  AS VC_NUMERO_DOCUMENTO,
                             0                                                AS DEC_MONTO_PRESTAMO,
                             CAST(DETX.C17 AS VARCHAR2(10))                   AS VC_MONEDA,
                             0                                                AS DEC_MONTO_COBERTURA,
                             0                                                AS DEC_PORCENTAJE_COBERTURA,
                             CAST(PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM','REC',0) AS VARCHAR2(400)) AS VC_ESTADO,             
                             CAST(    JSON_OBJECT(
                                            'field'     VALUE 'VC_ESTADO',
                                            'textcolor' VALUE 'color-red-001',
                                            'bgcolor'   VALUE 'color-red-002'
                                            ) AS VARCHAR2(4000))     AS JSON_UI_DECORADORES
                    FROM SOLICITUD_DETALLE_TEXTO DETX            
                    WHERE DETX.INT_IDSOLICITUD = p_intIdSolicitud
                    AND p_intAprobadas <> 1 
                    AND DETX.INT_IDSOLICITUD_DET = 0
                    AND (p_vcIdOrDocumento IS NULL OR DETX.INT_IDSOLICITUD_DET = p_vcIdOrDocumento OR DETX.C02 = p_vcIdOrDocumento) 
                ) T
            ) D
        WHERE (D.INT_ROW_NUMBER BETWEEN ((p_intStartIndex) * p_intPageSize + 1) AND (p_intStartIndex + 1) * p_intPageSize)
        ORDER BY D.INT_ROW_NUMBER;


    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD', 'S_LISTAR_DETALLE_X_SOLICITUD_Y_IDORDOCUMENTO', vcErrorStack, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 'INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
          RAISE_APPLICATION_ERROR(-20206, 'PKG_SOLICITUD.S_LISTAR_DETALLE_X_SOLICITUD_Y_IDORDOCUMENTO:' || vcErrorStack || '; ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || '; INT_IDSOLICITUD:' || TO_CHAR(p_intIdSolicitud));
    END S_LISTAR_DETALLE_X_SOLICITUD_Y_IDORDOCUMENTO;      


  PROCEDURE S_LISTAR_SOLICITUD_DETALLADO_REPORTE(p_intIdSolicitud       IN  NUMBER,
                                                 p_intIndEstados         IN  NUMBER,
                                                 p_curTabla             OUT SYS_REFCURSOR)
    AS
    BEGIN
      OPEN p_curTabla FOR
		SELECT SO.INT_IDSOLICITUD,
             ER.INT_IDSOLICITUD_DET,
             SO.VC_CODIGO,
             SO.INT_IDIFI,
             SO.VC_NOMBRE_IFI,
             ER.VC_UBIGEO,
             ER.VC_GRUPOBEN,
             ER.VC_CIIU,
             ER.VC_TIPNUMREPLEG,
             ER.VC_DIRECCION,
             ER.VC_NUMREPLEG,
             ER.VC_REPLEG,
             ER.VC_MONEDA,
             ER.VC_COLCRED,
             ER.VC_MONTOLATERAL,
             ER.VC_CARGREPLEG,
             ER.VC_TAMANIO,
             ER.VC_TIPDESTINO,
             ER.VC_MONTOPRESTAMO,
             ER.VC_TIPO_DOCUMENTO,
             ER.VC_TASAINTERES,
             ER.VC_NUMERO_DOCUMENTO,
             ER.VC_PERIODGRACIA,
             ER.VC_PLAZOOPER,
             ER.VC_ORIGENFONDOS,
             ER.VC_RAZON_SOCIAL,
             ER.VC_NOMBRES,
             ER.VC_DIRECCION,
             ER.VC_TIPO_ERROR,
             ER.INT_FILA_ARCHIVO,
             ER.VC_FILA_ARCHIVO,
             ER.VC_CODSUBASTA,
             ER.VC_ESTADO,
             ER.OBSERVACIONES,
             ER.DEC_PORCENTAJE_COBERTURA,
             ER.DEC_MONTO_COBERTURA			 
        FROM (

			SELECT SD00.INT_IDSOLICITUD,
                 SDT00.INT_IDSOLICITUD_DET,
                 SDT00.C01 AS VC_TIPO_DOCUMENTO,
                 SDT00.C02 AS VC_NUMERO_DOCUMENTO,
                 SDT00.C03 AS VC_RAZON_SOCIAL,
                 (SDT00.C04 || ' ' || SDT00.C05 || ' ' || SDT00.C06) AS VC_NOMBRES,
                 SDT00.C07 AS VC_DIRECCION,
                 SDT00.C08 AS VC_UBIGEO,
                 SDT00.C09 AS VC_GRUPOBEN,
                 SDT00.C10 AS VC_TIPNUMREPLEG,
                 SDT00.C11 AS VC_NUMREPLEG,
                 SDT00.C12 || ' ' || SDT00.C13 AS VC_REPLEG,
                 SDT00.C14 AS VC_CARGREPLEG,
                 SDT00.C15 AS VC_CIIU,
                 SDT00.C16 AS VC_TAMANIO,
                 SDT00.C17 AS VC_MONEDA,
                 SDT00.C18 AS VC_MONTOPRESTAMO,
                 SDT00.C19 AS VC_TASAINTERES,
                 SDT00.C20 AS VC_COLCRED,
                 SDT00.C21 AS VC_MONTOLATERAL,
                 SDT00.C22 AS VC_TIPDESTINO,
                 SDT00.C23 AS VC_PLAZOOPER,
                 SDT00.C24 AS VC_PERIODGRACIA,
                 SDT00.C25 AS VC_CODSUBASTA,
                 SDT00.C26 AS VC_ORIGENFONDOS,
                 PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM', SD00.VC_ESTADO, 0) AS VC_ESTADO,
                 '' AS VC_TIPO_ERROR,
                 SDT00.INT_FILA AS INT_FILA_ARCHIVO,
                 '' AS VC_FILA_ARCHIVO,
                 SD00.OBSERVACIONES,
                 2 AS ORDEN,
                 SD00.DEC_PORCENTAJE_COBERTURA,
                 SD00.DEC_MONTO_COBERTURA  				 
            FROM SOLICITUD S00
            INNER JOIN SOLICITUD_DETALLE SD00 ON (S00.INT_IDSOLICITUD = SD00.INT_IDSOLICITUD)
            INNER JOIN SOLICITUD_DETALLE_TEXTO SDT00 ON (SD00.INT_IDSOLICITUD = SDT00.INT_IDSOLICITUD
													 AND SD00.INT_IDSOLICITUD_DET = SDT00.INT_IDSOLICITUD_DET)
            LEFT JOIN US_BASE.V_BASE_ESTADOSSOLDET_CLASIFICADOS V ON V.COD_CORTO = SD00.VC_ESTADO
            WHERE S00.INT_IDSOLICITUD = p_intIdSolicitud
            AND SD00.OBSERVACIONES = 'OK'
            AND (
                  p_intIndEstados IS NULL
               OR (p_intIndEstados = 1  AND V.GRUPO = 'A')
               OR (p_intIndEstados <> 1 AND V.GRUPO = 'R')
            )

            UNION ALL

			SELECT SDT01.INT_IDSOLICITUD,
                 SDT01.INT_IDSOLICITUD_DET,
                 SDT01.C01 AS VC_TIPO_DOCUMENTO,
                 SDT01.C02 AS VC_NUMERO_DOCUMENTO,
                 SDT01.C03 AS VC_RAZON_SOCIAL,
                 (SDT01.C04 || ' ' || SDT01.C05 || ' ' || SDT01.C06) AS VC_NOMBRES,
                 SDT01.C07 AS VC_DIRECCION,
                 SDT01.C08 AS VC_UBIGEO,
                 SDT01.C09 AS VC_GRUPOBEN,
                 SDT01.C10 AS VC_TIPNUMREPLEG,
                 SDT01.C11 AS VC_NUMREPLEG,
                 SDT01.C12 || ' ' || SDT01.C13 AS VC_REPLEG,
                 SDT01.C14 AS VC_CARGREPLEG,
                 SDT01.C15 AS VC_CIIU,
                 SDT01.C16 AS VC_TAMANIO,
                 SDT01.C17 AS VC_MONEDA,
                 SDT01.C18 AS VC_MONTOPRESTAMO,
                 SDT01.C19 AS VC_TASAINTERES,
                 SDT01.C20 AS VC_COLCRED,
                 SDT01.C21 AS VC_MONTOLATERAL,
                 SDT01.C22 AS VC_TIPDESTINO,
                 SDT01.C23 AS VC_PLAZOOPER,
                 SDT01.C24 AS VC_PERIODGRACIA,
                 SDT01.C25 AS VC_CODSUBASTA,
                 SDT01.C26 AS VC_ORIGENFONDOS,
                 PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM', SD01.VC_ESTADO, 0) AS VC_ESTADO,
                 'SOLICITUD REGLAS' AS VC_TIPO_ERROR,
                 SDT01.INT_FILA AS INT_FILA_ARCHIVO,
                 'Error en fila ' || TRIM(TO_CHAR(SDT01.INT_FILA)) || ' del archivo Solicitud' AS VC_FILA_ARCHIVO,
                 SD01.OBSERVACIONES,
                 3 AS ORDEN,
                 SD01.DEC_PORCENTAJE_COBERTURA,
                 SD01.DEC_MONTO_COBERTURA  				 
            FROM SOLICITUD S01
            INNER JOIN SOLICITUD_DETALLE SD01 ON (S01.INT_IDSOLICITUD = SD01.INT_IDSOLICITUD)
            INNER JOIN SOLICITUD_DETALLE_TEXTO SDT01 ON (SD01.INT_IDSOLICITUD = SDT01.INT_IDSOLICITUD
                                                         AND SD01.INT_IDSOLICITUD_DET = SDT01.INT_IDSOLICITUD_DET)
            LEFT JOIN US_BASE.V_BASE_ESTADOSSOLDET_CLASIFICADOS V ON V.COD_CORTO = SD01.VC_ESTADO
            WHERE S01.INT_IDSOLICITUD = p_intIdSolicitud
            AND SD01.OBSERVACIONES <> 'OK'
            AND (
                  p_intIndEstados IS NULL
               OR (p_intIndEstados = 1  AND V.GRUPO = 'A')
               OR (p_intIndEstados <> 1 AND V.GRUPO = 'R')
            )

            UNION

			SELECT SDT02.INT_IDSOLICITUD,
                 SDT02.INT_IDSOLICITUD_DET,
                 SDT02.C01 AS VC_TIPO_DOCUMENTO,
                 SDT02.C02 AS VC_NUMERO_DOCUMENTO,
                 SDT02.C03 AS VC_RAZON_SOCIAL,
                 SDT02.C04 || ' ' || SDT02.C05 || ' ' || SDT02.C06 AS VC_NOMBRES,
                 SDT02.C07 AS VC_DIRECCION,
                 SDT02.C08 AS VC_UBIGEO,
                 SDT02.C09 AS VC_GRUPOBEN,
                 SDT02.C10 AS VC_TIPNUMREPLEG,
                 SDT02.C11 AS VC_NUMREPLEG,
                 SDT02.C12 || ' ' || SDT02.C13 AS VC_REPLEG,
                 SDT02.C14 AS VC_CARGREPLEG,
                 SDT02.C15 AS VC_CIIU,
                 SDT02.C16 AS VC_TAMANIO,
                 SDT02.C17 AS VC_MONEDA,
                 SDT02.C18 AS VC_MONTOPRESTAMO,
                 SDT02.C19 AS VC_TASAINTERES,
                 SDT02.C20 AS VC_COLCRED,
                 SDT02.C21 AS VC_MONTOLATERAL,
                 SDT02.C22 AS VC_TIPDESTINO,
                 SDT02.C23 AS VC_PLAZOOPER,
                 SDT02.C24 AS VC_PERIODGRACIA,
                 SDT02.C25 AS VC_CODSUBASTA,
                 SDT02.C26 AS VC_ORIGENFONDOS,
                 PKG_TABLA_DETALLE.F_OBT_VALOR_ADICIONAL_TABLADETALLE('ESTSOLDETFIDEM', 'REC', 0) AS VC_ESTADO,
                 'SOLICITUD ESTRUCTURA' AS VC_TIPO_ERROR,
                 SDT02.INT_FILA AS INT_FILA_ARCHIVO,
                 'Error en fila ' || TRIM(TO_CHAR(SDT02.INT_FILA)) || ' del archivo Solicitud' AS VC_FILA_ARCHIVO,
                 SDT02.OBSERVACIONES,
                 4 AS ORDEN,
                 CAST(NULL AS NUMBER) AS DEC_PORCENTAJE_COBERTURA,
                 CAST(NULL AS NUMBER) AS DEC_MONTO_COBERTURA                 				 
            FROM SOLICITUD S02
            INNER JOIN SOLICITUD_DETALLE_TEXTO SDT02 ON (S02.INT_IDSOLICITUD = SDT02.INT_IDSOLICITUD)
            WHERE S02.INT_IDSOLICITUD = p_intIdSolicitud
            AND SDT02.OBSERVACIONES <> 'OK'
            AND (p_intIndEstados IS NULL OR (p_intIndEstados IS NOT NULL AND p_intIndEstados <> 1))
            ORDER BY INT_IDSOLICITUD ASC, INT_FILA_ARCHIVO ASC
			) ER
		INNER JOIN SOLICITUD SO ON (SO.INT_IDSOLICITUD = ER.INT_IDSOLICITUD)
		ORDER BY SO.INT_IDSOLICITUD, ER.INT_FILA_ARCHIVO;

    EXCEPTION
      WHEN OTHERS THEN PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD', 'S_LISTAR_SOLICITUD_DETALLADO_REPORTE', vcErrorStack, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
          RAISE_APPLICATION_ERROR(-20207, 'PKG_SOLICITUD.S_LISTAR_SOLICITUD_DETALLADO_REPORTE:' || vcErrorStack || '; ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
    END S_LISTAR_SOLICITUD_DETALLADO_REPORTE;

END PKG_SOLICITUD;

/
--------------------------------------------------------
--  DDL for Package Body PKG_SOLICITUD_HONRAS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "US_BASE_MODULAR"."PKG_SOLICITUD_HONRAS" 
  AS

  PROCEDURE S_LISTAR_CLASE_PRODUCTO(p_vchCodigoProducto IN  US_BASE.BASE_TABLA.VC_CODTABLA % TYPE,
                                    p_curTabla          OUT SYS_REFCURSOR)
    AS

    BEGIN
      OPEN p_curTabla FOR
      SELECT H.SAP_CODIGO AS CLASE_PRODUCTO
        FROM US_BASE.V_BASE_REGLA_PRODUCTO_PROGRAMA H
        WHERE H.VC_CODPROD = p_vchCodigoProducto
          AND H.SAP_CODIGO IS NOT NULL;
    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD_HONRAS', 'S_LISTAR_CLASE_PRODUCTO', vcErrorStack, vcErrorBacktace, 'VC_CODPROD:' || TO_CHAR(p_vchCodigoProducto));
          RAISE_APPLICATION_ERROR(-20131, 'PKG_SOLICITUD_HONRAS.S_LISTAR_CLASE_PRODUCTO:' || vcErrorStack || '; ' || vcErrorBacktace || '; VC_CODPROD:' || TO_CHAR(p_vchCodigoProducto));
    END S_LISTAR_CLASE_PRODUCTO;

  PROCEDURE I_HONRAS(p_SOLICITUD_HONRAS_LIST IN     SOLICITUD_HONRAS_LIST,
                     p_RESULTADO             IN OUT VARCHAR2)
    AS
      PRAGMA AUTONOMOUS_TRANSACTION;
    BEGIN
      IF p_SOLICITUD_HONRAS_LIST.Count > 0
      THEN
        --ACTUALIZAR TABLA SOLICITUD_HONRAS
        MERGE INTO SOLICITUD_HONRAS D
        USING (SELECT T.INT_IDSOLICITUD,
                      T.TAXNUM,
                      T.GSART
            FROM TABLE (p_SOLICITUD_HONRAS_LIST) T) O
        ON (D.INT_IDSOLICITUD = O.INT_IDSOLICITUD
          AND D.TAXNUM = O.TAXNUM
          AND D.GSART = O.GSART)
        WHEN NOT MATCHED THEN INSERT (
          INT_IDSOLICITUD, TAXNUM, GSART
        )
        VALUES (O.INT_IDSOLICITUD, O.TAXNUM, O.GSART);
        COMMIT;
      END IF;
      p_RESULTADO := 'OK';
    EXCEPTION
      WHEN OTHERS THEN p_RESULTADO := 'ER';
          vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          ROLLBACK;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD_HONRAS', 'I_HONRAS', vcErrorStack, vcErrorBacktace);
          RAISE_APPLICATION_ERROR(-20132, 'PKG_SOLICITUD_HONRAS.I_HONRAS:' || vcErrorStack || '; ' || vcErrorBacktace);
    END I_HONRAS;

END PKG_SOLICITUD_HONRAS;


