--  DDL for Package Body PKG_SOLICITUD_RESULTADO
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "US_BASE_MODULAR"."PKG_SOLICITUD_RESULTADO" 
  AS

  PROCEDURE S_LISTAR_SOLICITUD_PROCESADA(p_curTabla OUT SYS_REFCURSOR)
    AS
    BEGIN

      OPEN p_curTabla FOR
      SELECT SR.INT_IDSOLICITUD,
             S.VC_CODIGO
        FROM SOLICITUD_RESULTADOS SR
          INNER JOIN SOLICITUD S
            ON (S.INT_IDSOLICITUD = SR.INT_IDSOLICITUD)
        WHERE SR.VC_ESTADO = 'PROCESAR_STRUC'
        ORDER BY SR.INT_IDSOLICITUD;
    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD_RESULTADO', 'S_LISTAR_SOLICITUD_PROCESADA', vcErrorStack, vcErrorBacktace);
          RAISE_APPLICATION_ERROR(-20211, 'PKG_SOLICITUD_RESULTADO.S_LISTAR_SOLICITUD_PROCESADA:' || vcErrorStack || '; ' || vcErrorBacktace);
    END S_LISTAR_SOLICITUD_PROCESADA;

  PROCEDURE S_LISTAR_SOLICITUD_RESULTADO(p_curTabla OUT SYS_REFCURSOR)
    AS
    BEGIN

      OPEN p_curTabla FOR
      SELECT S.INT_IDSOLICITUD,
             S.VC_CODIGO,
             S.INT_IDPRODUCTO,
             S.INT_IDIFI,
             S.VC_NOMBRE_IFI,
             S.DT_FECHA,
             BTD.VC_NOMBRE,
             DECODE(SR.INT_TOTAL_REGISTROS,
             SR.INT_REGISTROS_APROBADOS,
             'sin observaciones',
             'con observaciones') AS VC_RESULTADO,
             S.VC_USUARIO_CREACION,
             SR.INT_TOTAL_REGISTROS,
             SR.INT_REGISTROS_APROBADOS,
             SR.INT_REGISTROS_RECHAZADOS,
             SR.INT_REGISTROS_RECHAZADOS_ESTRUCTURA,
             SR.INT_REGISTROS_RECHAZADOS_REGLAS
        FROM SOLICITUD_RESULTADOS SR
          INNER JOIN SOLICITUD S
            ON (S.INT_IDSOLICITUD = SR.INT_IDSOLICITUD)
          INNER JOIN US_BASE.BASE_TABLA_DETALLE BTD
            ON (BTD.INT_IDTABLA_DETALLE = S.INT_IDESTADO)
        WHERE SR.VC_ESTADO = 'PROCESAR_REGLAS'
        ORDER BY S.INT_IDSOLICITUD;

    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD_RESULTADO', 'S_LISTAR_SOLICITUD_RESULTADO', vcErrorStack, vcErrorBacktace);
          RAISE_APPLICATION_ERROR(-20212, 'PKG_SOLICITUD_RESULTADO.S_LISTAR_SOLICITUD_RESULTADO:' || vcErrorStack || '; ' || vcErrorBacktace);
    END S_LISTAR_SOLICITUD_RESULTADO;

  PROCEDURE U_ACTUALIZAR_SOLICITUD_RESULTADO(p_vcSolicitud IN VARCHAR2)
    AS
      PRAGMA AUTONOMOUS_TRANSACTION;
    BEGIN

      UPDATE SOLICITUD_RESULTADOS SR
        SET SR.VC_ESTADO = 'CORREO_ENVIADO', SR.VC_USUARIO_MODIFICACION = USER, SR.DT_FECHA_MODIFICACION = SYSDATE, SR.VC_TERMINAL_MODIFICACION = SYS_CONTEXT('USERENV', 'IP_ADDRESS')
        WHERE SR.INT_IDSOLICITUD IN (SELECT TO_NUMBER(REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL)) AS SOLICITUD
            FROM DUAL
          CONNECT BY REGEXP_SUBSTR(p_vcSolicitud, '[^,]+', 1, LEVEL) IS NOT NULL)
        AND SR.VC_ESTADO = 'PROCESAR_REGLAS';
      COMMIT;
    EXCEPTION
      WHEN OTHERS THEN vcErrorStack := DBMS_UTILITY.FORMAT_ERROR_STACK;
          vcErrorBacktace := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
          ROLLBACK;
          PKG_LOG_ERROR.I_REGISTRAR('PKG_SOLICITUD_RESULTADO', 'U_ACTUALIZAR_SOLICITUD_RESULTADO', vcErrorStack, vcErrorBacktace, 'INT_IDSOLICITUD:' || TO_CHAR(p_vcSolicitud));
          RAISE_APPLICATION_ERROR(-20213, 'PKG_SOLICITUD_RESULTADO.U_ACTUALIZAR_SOLICITUD_RESULTADO:' || vcErrorStack || '; ' || vcErrorBacktace || '; INT_IDSOLICITUD:' || TO_CHAR(p_vcSolicitud));
    END U_ACTUALIZAR_SOLICITUD_RESULTADO;

END PKG_SOLICITUD_RESULTADO;





