CREATE OR REPLACE TRIGGER US_BASE_MODULAR.TR_SOL_JSDECOR_BU
BEFORE INSERT OR UPDATE OF INT_IDESTADO
ON US_BASE_MODULAR.SOLICITUD
FOR EACH ROW
DECLARE
  v_json_vc  VARCHAR2(4000);
BEGIN
  -- 1) Intentar traer el JSON desde el catálogo por INT_IDESTADO = INT_IDTABLA_DETALLE
  BEGIN
    SELECT d.VC_ADICIONAL1
      INTO v_json_vc
      FROM US_BASE.BASE_TABLA t
      JOIN US_BASE.BASE_TABLA_DETALLE d
        ON d.INT_IDTABLA = t.INT_IDTABLA
     WHERE t.VC_CODTABLA = 'ESTSOLFIDEM'
       AND d.INT_IDTABLA_DETALLE = :NEW.INT_IDESTADO;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      -- 2) Fallback neutral: construir JSON vía SELECT ... INTO
      SELECT JSON_OBJECT(
               'field'     VALUE 'VC_ESTADO',
               'textcolor' VALUE 'color_primary_neutral',
               'bgcolor'   VALUE 'color_neutral'
             RETURNING VARCHAR2(4000))
        INTO v_json_vc
        FROM dual;
  END;

  -- 3) Asignar al CLOB de la fila nueva (AJUSTA el nombre de columna si usas otro)
  :NEW.JSON_UI_DECORADORES := TO_CLOB(v_json_vc);

END;

/


CREATE OR REPLACE TRIGGER US_BASE_MODULAR.TR_SOL_DET_JSDECOR_BU
BEFORE INSERT OR UPDATE OF VC_ESTADO
ON US_BASE_MODULAR.SOLICITUD_DETALLE
