CREATE OR REPLACE EDITIONABLE TRIGGER "US_BASE_MODULAR"."SOLICITUD_DETALLE_TRG_AFT_INS_UPD"
AFTER INSERT OR UPDATE ON "US_BASE_MODULAR"."SOLICITUD_DETALLE"
FOR EACH ROW
DECLARE
  v_vcModulo "US_BASE_MODULAR".HISTORIAL_CREDITO.VC_MODULO%TYPE;
  v_vcSubModulo "US_BASE_MODULAR".HISTORIAL_CREDITO.VC_SUBMODULO%TYPE;
  v_vcCodEstado1 VARCHAR2(20);
  v_vcCodEstado2 VARCHAR2(20);
  v_vcUsuarioSolicitud VARCHAR2(50);
  v_dtFecSolicitud DATE;
BEGIN
  IF NVL(:OLD.VC_ESTADO, ' ') <> NVL(:NEW.VC_ESTADO, ' ') THEN
  
	v_vcModulo := 'ADMISION';
	v_vcSubModulo := 'COBERTURA';
	v_vcCodEstado1 := TRIM(NVL(:OLD.VC_ESTADO, ' '));
	v_vcCodEstado2 := TRIM(NVL(:NEW.VC_ESTADO, ' '));
	
	BEGIN
		SELECT 
		TABDET.VC_ADICIONAL1, TABDET.VC_ADICIONAL2
		INTO v_vcModulo, v_vcSubModulo
		FROM US_BASE.BASE_TABLA TAB
		INNER JOIN US_BASE.BASE_TABLA_DETALLE TABDET ON TAB.INT_IDTABLA = TABDET.INT_IDTABLA
		WHERE VC_CODTABLA = 'RELESTHISCREMOD'
		AND TABDET.VC_CODTABLA_DETALLE = 'ADMVAL'|| v_vcCodEstado1 || v_vcCodEstado2;
	EXCEPTION 
	WHEN NO_DATA_FOUND THEN
		v_vcModulo :='XXX';
		v_vcSubModulo :='YYY';
	END;
	
	IF :NEW.VC_ESTADO = 'REG' THEN
		BEGIN
			SELECT SOL.DT_FECHA_CREACION, SOL.VC_USUARIO_CREACION
			INTO v_dtFecSolicitud, v_vcUsuarioSolicitud
			FROM "US_BASE_MODULAR".SOLICITUD SOL		
			WHERE SOL.INT_IDSOLICITUD = :NEW.INT_IDSOLICITUD
			AND PKG_TABLA_DETALLE.F_OBT_CODIGO_TABLADETALLE(SOL.INT_IDESTADO) = 'REG';
		EXCEPTION 
		WHEN NO_DATA_FOUND THEN
			v_dtFecSolicitud := SYSDATE;
			v_vcUsuarioSolicitud := :NEW.VC_USUARIO_CREACION;
		END;
	
	ELSE
		v_dtFecSolicitud := SYSDATE;
		v_vcUsuarioSolicitud := :NEW.VC_USUARIO_MODIFICACION;
	END IF;

    INSERT INTO "US_BASE_MODULAR".HISTORIAL_CREDITO
      (
       INT_SOLICITUD_DET_MODULO,
	   INT_IDCREDITO,
       VC_NUMERO_DOCUMENTO,
	   VC_MODULO,
	   VC_SUBMODULO,
       VC_ESTADO_ANTERIOR,
       VC_ESTADO,
       DT_FECHA,
       VC_USUARIO_CREACION, DT_FECHA_CREACION, VC_TERMINAL_CREACION,
       VC_USUARIO_MODIFICACION, DT_FECHA_MODIFICACION, VC_TERMINAL_MODIFICACION)
    VALUES
      (
       :NEW.INT_IDSOLICITUD_DET,
	   :NEW.INT_IDSOLICITUD_DET,
       :NEW.VC_NUMERO_DOCUMENTO,
	   v_vcModulo,
	   v_vcSubModulo,	   
       :OLD.VC_ESTADO,
       :NEW.VC_ESTADO,
       v_dtFecSolicitud,
       v_vcUsuarioSolicitud, SYSDATE, :NEW.VC_TERMINAL_CREACION,
       :NEW.VC_USUARIO_MODIFICACION, :NEW.DT_FECHA_MODIFICACION, :NEW.VC_TERMINAL_MODIFICACION);
  END IF;
END;
/
ALTER TRIGGER "US_BASE_MODULAR"."SOLICITUD_DETALLE_TRG_AFT_INS_UPD" ENABLE;



